function Get-WfxAttackTechnique {
    <# Returns name/tactic/url for ATT&CK ids (unknown ids are returned with a blank name). #>
    param([string[]]$Id)
    foreach ($t in @($Id | Where-Object { $_ })) {
        $info = $script:WfxAttack[$t]
        $base = $t -replace '\.', '/'
        [pscustomobject]@{
            Id     = $t
            Name   = if ($info) { $info[0] } else { '' }
            Tactic = if ($info) { $info[1] } else { '' }
            Url    = "https://attack.mitre.org/techniques/$base/"
        }
    }
}


# ===== Private/Core.ps1 =====
# WinForensicX — core engine: findings, scoring, redaction, logging, case management, helpers.
# Compatible with Windows PowerShell 5.1 and PowerShell 7+. Analysis helpers here are
# platform-neutral so analyzers can run (and be tested) on any OS.

$script:WfxVersion = '3.2.0'
$script:WfxSeverities = @('Info', 'Low', 'Medium', 'High', 'Critical')
$script:WfxSeverityWeight = @{ Info = 0; Low = 2; Medium = 5; High = 10; Critical = 20 }
$script:WfxConfidenceFactor = @{ Low = 0.5; Medium = 0.8; High = 1.0 }
# Categories that describe hardening / visibility rather than evidence of compromise. They are scored
# separately (Posture score) so a well-run but un-hardened host is not reported as "compromised".
$script:WfxPostureCategories = @('Posture', 'Visibility')
$script:WfxCase = $null
$script:WfxGaps = New-Object System.Collections.Generic.List[object]
$script:WfxQuiet = $false
# Every built-in regex that runs over collected (potentially attacker-controlled) text uses this timeout.
$script:WfxRegexTimeout = [TimeSpan]::FromMilliseconds(250)
$script:WfxRxCache = @{}

# ───────────────────────────── platform ─────────────────────────────
function Test-WfxWindows {
    if ($PSVersionTable.PSVersion.Major -le 5) { return $true }
    return [bool]$IsWindows
}

function Test-WfxAdmin {
    if (-not (Test-WfxWindows)) { return $false }
    try {
        $id = [Security.Principal.WindowsIdentity]::GetCurrent()
        return ([Security.Principal.WindowsPrincipal]$id).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch { return $false }
}

# ───────────────────────────── safe regex ─────────────────────────────
function Get-WfxRx {
    <# Returns a cached Regex with the global match timeout. Use for every pattern applied to collected data. #>
    param([Parameter(Mandatory)][string]$Pattern, [System.Text.RegularExpressions.RegexOptions]$Options = 'None')
    $key = "$([int]$Options)|$Pattern"
    if (-not $script:WfxRxCache.ContainsKey($key)) {
        $script:WfxRxCache[$key] = New-Object System.Text.RegularExpressions.Regex($Pattern, $Options, $script:WfxRegexTimeout)
    }
    $script:WfxRxCache[$key]
}

function Get-WfxRxMatches {
    <# All matches of a pattern; on a regex timeout returns what was found so far (never hangs). #>
    param([string]$Pattern, [AllowEmptyString()][string]$Text)
    # Emits Match objects to the pipeline (wrap the call in @() to count them).
    $list = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrEmpty($Text)) { return }
    try { foreach ($m in (Get-WfxRx $Pattern).Matches($Text)) { $list.Add($m) } }
    catch [System.Text.RegularExpressions.RegexMatchTimeoutException] { Write-Verbose "regex timeout: $Pattern" }
    $list.ToArray()
}

function Test-WfxRxMatch {
    param([string]$Pattern, [AllowEmptyString()][string]$Text)
    if ([string]::IsNullOrEmpty($Text)) { return $false }
    try { return (Get-WfxRx $Pattern).IsMatch($Text) } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] { return $false }
}

# ───────────────────────────── time ─────────────────────────────
function ConvertTo-WfxDateTime {
    <# Parses a DateTime / ISO-8601 string / legacy "/Date(ms)/" value into a UTC DateTime. $null if unparseable. #>
    param($Value)
    if ($null -eq $Value -or "$Value" -eq '') { return $null }
    if ($Value -is [datetime]) { return $Value.ToUniversalTime() }
    if ($Value -is [System.DateTimeOffset]) { return $Value.UtcDateTime }
    $s = [string]$Value
    $m = [regex]::Match($s, '^/?\\?/?Date\((-?\d+)')
    if ($m.Success) { return [DateTime]::new(1970, 1, 1, 0, 0, 0, [DateTimeKind]::Utc).AddMilliseconds([double]$m.Groups[1].Value) }
    $dto = [System.DateTimeOffset]::MinValue
    if ([System.DateTimeOffset]::TryParse($s, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::AssumeUniversal, [ref]$dto)) { return $dto.UtcDateTime }
    return $null
}

function ConvertTo-WfxUtcString {
    <# Normalizes any timestamp to an ISO-8601 UTC string ("...Z"). Collectors store ONLY this form, so bundles
       are identical across PowerShell 5.1 / 7 and re-analysis never shifts a timeline by a timezone. #>
    param($Value)
    $d = ConvertTo-WfxDateTime $Value
    if ($null -eq $d) { return $(if ($null -eq $Value) { '' } else { [string]$Value }) }
    return $d.ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [Globalization.CultureInfo]::InvariantCulture)
}

function Get-WfxUtcNow { (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [Globalization.CultureInfo]::InvariantCulture) }

# ───────────────────────────── console ─────────────────────────────
function Write-WfxConsole {
    <# Single place for interactive console output, so -Quiet and colors are consistent. #>
    param(
        [Parameter(Position = 0)][AllowEmptyString()][string]$Message = '',
        [ValidateSet('Info', 'Ok', 'Warn', 'Bad', 'Head', 'Dim', 'Plain')][string]$Kind = 'Plain',
        [switch]$NoNewline
    )
    if ($script:WfxQuiet) { return }
    $color = @{ Info = 'Cyan'; Ok = 'Green'; Warn = 'Yellow'; Bad = 'Red'; Head = 'White'; Dim = 'DarkGray'; Plain = 'Gray' }[$Kind]
    Write-Host $Message -ForegroundColor $color -NoNewline:$NoNewline
}

function Write-WfxSection {
    param([string]$Title)
    Write-WfxConsole ''
    Write-WfxConsole ("── {0} {1}" -f $Title, ('─' * [Math]::Max(3, 66 - $Title.Length))) -Kind Head
}

# ───────────────────────────── audit log & gaps ─────────────────────────────
function Write-WfxLog {
    <# Appends one JSON line to the OPEN case's audit log. Once a case is completed (manifest written) it is
       closed and nothing is ever appended again — so a later command can never invalidate its manifest. #>
    param([string]$Event, [hashtable]$Data = @{})
    $case = $script:WfxCase
    if (-not $case -or -not $case.Path -or $case.Closed) { return }
    $entry = [ordered]@{ time = (Get-WfxUtcNow); event = $Event }
    foreach ($k in $Data.Keys) { $entry[$k] = $Data[$k] }
    try {
        $line = ($entry | ConvertTo-Json -Compress -Depth 5)
        Add-Content -LiteralPath (Join-Path $case.Path 'audit.log') -Value $line -Encoding UTF8
    } catch { Write-Verbose "audit log write failed: $_" }
}

function Add-WfxGap {
    <# Records something the tool could not collect or analyze — shown in the report so absence of findings is never mistaken for absence of evidence. #>
    param([string]$Source, [string]$Reason, [string]$Fix = '')
    $script:WfxGaps.Add([pscustomobject]@{ Source = $Source; Reason = $Reason; Fix = $Fix })
    Write-WfxLog -Event 'gap' -Data @{ source = $Source; reason = $Reason }
    Write-Verbose "[$Source] gap: $Reason"
}

function Expand-WfxRecord {
    <#
    .SYNOPSIS Turns collector output into a stream of records.
    .DESCRIPTION Collectors and analyzers return their results as ONE array object (", @(...)") so that callers
    which assign them always get an array. Piped straight into Select-Object / Where-Object that single array
    object is treated as one record (one blank row). Every pipeline that consumes collector output starts with
    "Get-WfxXxx | Expand-WfxRecord | ...". Nulls are dropped; strings and dictionaries are never split.
    #>
    param([Parameter(ValueFromPipeline)]$InputObject)
    process {
        if ($null -eq $InputObject) { return }
        if ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string] -and $InputObject -isnot [System.Collections.IDictionary]) {
            foreach ($x in $InputObject) { if ($null -ne $x) { $x } }
        } else { $InputObject }
    }
}

function Get-WfxGap { , $script:WfxGaps.ToArray() }
function Clear-WfxGap { $script:WfxGaps.Clear() }

function Invoke-WfxStep {
    <# Runs one collector or analyzer step; failures become recorded gaps instead of aborting the triage. #>
    param([string]$Name, [scriptblock]$Script, $Default = @())
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try {
        $out = & $Script
        Write-WfxLog -Event 'step' -Data @{ name = $Name; ms = $sw.ElapsedMilliseconds; ok = $true }
        return $out
    } catch {
        Add-WfxGap -Source $Name -Reason $_.Exception.Message
        Write-WfxLog -Event 'step' -Data @{ name = $Name; ms = $sw.ElapsedMilliseconds; ok = $false; error = $_.Exception.Message }
        return $Default
    }
}

# ───────────────────────────── findings ─────────────────────────────
function New-WfxFinding {
    <#
    .SYNOPSIS Creates a normalized finding. Every analyzer returns these.
    .PARAMETER Id         Stable rule identifier (e.g. LOTL-CERTUTIL-DOWNLOAD). Used for dedupe, tuning and allowlists.
    .PARAMETER Entity     What the finding is about, in a stable form ("process:4412:powershell.exe", "file:C:\x.ps1").
    .PARAMETER Technique  ATT&CK ids. Anything that is not a well-formed id (T1234 / T1234.567) is dropped, so a
                          malformed or malicious custom rule pack can't inject markup into reports.
    #>
    param(
        [Parameter(Mandatory)][string]$Id,
        [Parameter(Mandatory)][string]$Title,
        [ValidateSet('Info', 'Low', 'Medium', 'High', 'Critical')][string]$Severity = 'Medium',
        [ValidateSet('Low', 'Medium', 'High')][string]$Confidence = 'Medium',
        [Parameter(Mandatory)][string]$Category,
        [string[]]$Technique = @(),
        [string]$Description = '',
        [string]$Entity = '',
        $Evidence = $null,
        [string]$Recommendation = '',
        [string]$HostName = '',
        $Time = $null,
        [string]$Source = ''
    )
    $weight = $script:WfxSeverityWeight[$Severity] * $script:WfxConfidenceFactor[$Confidence]
    $t = $null
    if ($Time) { $t = ConvertTo-WfxUtcString $Time }
    [pscustomobject]@{
        PSTypeName     = 'WinForensicX.Finding'
        Id             = $Id
        Title          = $Title
        Severity       = $Severity
        Confidence     = $Confidence
        Score          = [Math]::Round($weight, 1)
        Category       = $Category
        Technique      = @($Technique | Where-Object { $_ -and ([string]$_ -match '^T\d{4}(?:\.\d{3})?$') })
        Description    = $Description
        Entity         = $Entity
        Evidence       = $Evidence
        Recommendation = $Recommendation
        Host           = $HostName
        Time           = $t
        Source         = $Source
    }
}

function Merge-WfxFinding {
    <# Dedupes findings by Host + Id + Entity (keeps the highest-scoring one and counts repeats) and sorts by severity. #>
    param([object[]]$Finding)
    $byKey = [ordered]@{}
    foreach ($f in @($Finding | Where-Object { $_ })) {
        $key = "$($f.Host)|$($f.Id)|$($f.Entity)"
        if ($byKey.Contains($key)) {
            $prev = $byKey[$key]
            $prev | Add-Member -NotePropertyName Occurrences -NotePropertyValue ([int]$prev.Occurrences + 1) -Force
            if ($f.Score -gt $prev.Score) { $f | Add-Member -NotePropertyName Occurrences -NotePropertyValue $prev.Occurrences -Force; $byKey[$key] = $f }
        } else {
            if (-not $f.PSObject.Properties['Occurrences']) { $f | Add-Member -NotePropertyName Occurrences -NotePropertyValue 1 -Force }
            $byKey[$key] = $f
        }
    }
    $sevRank = @{ Critical = 0; High = 1; Medium = 2; Low = 3; Info = 4 }
    , @($byKey.Values | Sort-Object @{ Expression = { $sevRank[$_.Severity] } }, @{ Expression = { $_.Score }; Descending = $true }, Title)
}

function Get-WfxRiskScore {
    <#
    .SYNOPSIS Score 0–100 over a set of findings. Combines them as independent evidence: risk = 1 - Π(1 - wᵢ/40).
    One high-confidence Critical ≈ 50, two ≈ 75; many Lows can't add up to a Critical.
    Invoke-WfxAnalyze calls this twice: once over compromise indicators (Risk) and once over
    hardening/visibility findings (Posture).
    #>
    param([object[]]$Finding)
    $p = 1.0
    foreach ($f in @($Finding | Where-Object { $_ })) {
        $w = [Math]::Min(39.0, [double]$f.Score)
        $p *= (1.0 - $w / 40.0)
    }
    $score = [int][Math]::Round(100 * (1 - $p))
    $level = if ($score -ge 75) { 'Critical' } elseif ($score -ge 50) { 'High' } elseif ($score -ge 20) { 'Elevated' } else { 'Low' }
    [pscustomobject]@{ Score = $score; Level = $level }
}

function Test-WfxPostureFinding { param($Finding) return ($script:WfxPostureCategories -contains [string]$Finding.Category) }

function Get-WfxSeveritySummary {
    param([object[]]$Finding)
    $o = [ordered]@{}
    foreach ($s in 'Critical', 'High', 'Medium', 'Low', 'Info') { $o[$s] = @($Finding | Where-Object { $_.Severity -eq $s }).Count }
    [pscustomobject]$o
}

# ───────────────────────────── allowlist ─────────────────────────────
function Read-WfxAllowlist {
    <#
    .SYNOPSIS Loads an allowlist (JSON array) of known-good findings to suppress.
    Each entry: { "Id": "PERSIST-*", "Entity": "autostart:RunKey:OneDrive", "Host": "*", "Reason": "corporate standard" }.
    Id/Entity/Host accept -like wildcards; Id is required; a Reason is strongly recommended (it is shown in the report).
    #>
    param([string]$Path)
    if (-not $Path) { return , @() }
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "Allowlist not found: $Path" }
    $raw = Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json
    $entries = foreach ($e in @($raw)) {
        $id = [string](Get-WfxValue $e 'Id' '')
        if (-not $id) { continue }
        [pscustomobject]@{ Id = $id; Entity = [string](Get-WfxValue $e 'Entity' '*'); Host = [string](Get-WfxValue $e 'Host' '*'); Reason = [string](Get-WfxValue $e 'Reason' '') }
    }
    , @($entries)
}

function Split-WfxAllowlisted {
    <# Splits findings into Kept and Suppressed according to the allowlist. Suppressed findings are never
       silently dropped — they are reported separately with the matching reason. #>
    param([object[]]$Finding, [object[]]$Allowlist)
    $kept = New-Object System.Collections.Generic.List[object]
    $supp = New-Object System.Collections.Generic.List[object]
    foreach ($f in @($Finding | Where-Object { $_ })) {
        $hit = $null
        foreach ($a in @($Allowlist)) {
            if ($f.Id -like $a.Id -and [string]$f.Entity -like $a.Entity -and [string]$f.Host -like $a.Host) { $hit = $a; break }
        }
        if ($hit) {
            $supp.Add([pscustomobject]@{ Id = $f.Id; Title = $f.Title; Severity = $f.Severity; Entity = $f.Entity; Host = $f.Host; Reason = $hit.Reason; Rule = "$($hit.Id) / $($hit.Entity)" })
        } else { $kept.Add($f) }
    }
    [pscustomobject]@{ Kept = $kept.ToArray(); Suppressed = $supp.ToArray() }
}

# ───────────────────────────── text & entropy ─────────────────────────────
function Get-WfxEntropy {
    <# Shannon entropy (bits per symbol) of a string or byte array. #>
    param([Parameter(Mandatory)][AllowEmptyString()]$InputObject)
    if ($null -eq $InputObject) { return 0.0 }
    $n = 0
    if ($InputObject -is [byte[]]) {
        $counts = New-Object 'int[]' 256
        foreach ($b in $InputObject) { $counts[$b]++ }
        $n = $InputObject.Length
        if ($n -eq 0) { return 0.0 }
        $h = 0.0
        foreach ($v in $counts) { if ($v) { $p = $v / $n; $h -= $p * [Math]::Log($p, 2) } }
        return [Math]::Round($h, 3)
    }
    $counts = @{}
    foreach ($c in ([string]$InputObject).ToCharArray()) { $counts[$c] = 1 + [int]$counts[$c]; $n++ }
    if ($n -eq 0) { return 0.0 }
    $h = 0.0
    foreach ($v in $counts.Values) { $p = $v / $n; $h -= $p * [Math]::Log($p, 2) }
    [Math]::Round($h, 3)
}

function Format-WfxSecret {
    <# Shows only enough of a secret to identify it: at most 4 leading characters + length. Never the value. #>
    param([AllowEmptyString()][string]$Value)
    if ([string]::IsNullOrEmpty($Value)) { return '' }
    $keep = [Math]::Min(4, [Math]::Floor($Value.Length / 4))
    return ('{0}…[redacted, {1} chars]' -f $Value.Substring(0, $keep), $Value.Length)
}

$script:WfxSecretPatterns = @(
    @{ Name = 'Anthropic API key'; Pattern = 'sk-ant-[A-Za-z0-9_\-]{20,}' }
    @{ Name = 'OpenRouter API key'; Pattern = 'sk-or-v1-[A-Fa-f0-9]{48,}' }
    @{ Name = 'OpenAI API key'; Pattern = 'sk-(?:proj-|svcacct-|admin-)?[A-Za-z0-9_\-]{32,}' }
    @{ Name = 'Google API key'; Pattern = 'AIza[0-9A-Za-z_\-]{35}' }
    @{ Name = 'Hugging Face token'; Pattern = 'hf_[A-Za-z0-9]{30,}' }
    @{ Name = 'Groq API key'; Pattern = 'gsk_[A-Za-z0-9]{40,}' }
    @{ Name = 'xAI API key'; Pattern = 'xai-[A-Za-z0-9]{40,}' }
    @{ Name = 'Replicate token'; Pattern = 'r8_[A-Za-z0-9]{30,}' }
    @{ Name = 'AWS access key id'; Pattern = '(?:AKIA|ASIA)[0-9A-Z]{16}' }
    @{ Name = 'GitHub token'; Pattern = 'gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{60,}' }
    @{ Name = 'Slack token'; Pattern = 'xox[abprs]-[A-Za-z0-9\-]{10,}' }
    @{ Name = 'Stripe secret key'; Pattern = '[rs]k_live_[A-Za-z0-9]{20,}' }
    @{ Name = 'Azure storage key'; Pattern = 'AccountKey=[A-Za-z0-9+/=]{60,}' }
    @{ Name = 'JSON Web Token'; Pattern = 'eyJ[A-Za-z0-9_\-]{8,}\.eyJ[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}' }
    @{ Name = 'Private key block'; Pattern = '-----BEGIN (?:RSA |EC |OPENSSH |DSA |ENCRYPTED )?PRIVATE KEY-----' }
)

function Find-WfxSecret {
    <# Finds well-known secret formats in text. Returns type + redacted value + line number; never the secret. #>
    param([AllowEmptyString()][string]$Text)
    $out = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrEmpty($Text)) { return , $out.ToArray() }
    $lines = $Text -split "`r?`n"
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $seen = @{}
        foreach ($p in $script:WfxSecretPatterns) {
            foreach ($m in (Get-WfxRxMatches $p.Pattern $lines[$i])) {
                if ($seen.ContainsKey($m.Index)) { continue }   # one label per match position
                $seen[$m.Index] = $true
                $out.Add([pscustomobject]@{ Type = $p.Name; Line = $i + 1; Redacted = (Format-WfxSecret $m.Value) })
            }
        }
    }
    , $out.ToArray()
}

$script:WfxRedactRules = @(
    # key=value / "key value" credentials. The key name may be embedded in a larger identifier
    # (aws_secret_access_key, db-password, MYSQL_PWD), so allow an identifier prefix/suffix.
    , @('(?i)([A-Za-z0-9_.\-]{0,40}(?:password|passwd|pwd|secret|api[_-]?key|apikey|client[_-]?secret|access[_-]?key|token)[A-Za-z0-9_.\-]{0,20})(\s*[:=]\s*|\s+)("[^"]*"|''[^'']*''|[^\s;,&]+)', '$1$2***')
    # mysql/openssl-style concatenated password flag: -pSecret  (but not a lone -p)
    , @('(?i)(\s-p)(?!assword\b)([^\s]{2,})', '$1***')
    , @('(?i)(-(?:Password|Pass|Secret|Token|Key)\s+)("[^"]*"|''[^'']*''|\S+)', '$1***')
    , @('(?i)(/p(?:ass(?:word)?)?:)(\S+)', '$1***')
    , @('(?i)(\bnet1?(?:\.exe)?\s+user\s+[^\s/]+\s+)([^\s/][^\s]*)', '$1***')
    , @('(?i)(\bschtasks[^\n]*\s/rp\s+)(\S+)', '$1***')
    , @('(?i)(https?://[^:/\s]+:)([^@\s]+)(@)', '$1***$3')
)

$script:WfxRedactHint = '(?i)sk-|aiza|hf_|gsk_|xai-|r8_|akia|asia|gh[pousr]_|github_pat|xox|_live_|eyj|begin|pass|pwd|secret|key|token|\s-p|/p|net1?(?:\.exe)?\s+user|schtasks|://'

function Protect-WfxText {
    <# Redacts secrets and key=value credentials in free text before it is stored, displayed or reported.
       FAIL-CLOSED: if any redaction regex times out on hostile input, the text is withheld entirely. #>
    param([AllowEmptyString()][string]$Text)
    if ([string]::IsNullOrEmpty($Text)) { return $Text }
    # Cheap pre-filter: every pattern below needs one of these literals. Text without any of them is
    # returned unchanged without running ~20 regexes (this matters for large artifact sets).
    if (-not (Get-WfxRx $script:WfxRedactHint).IsMatch($Text)) { return $Text }
    $t = $Text
    try {
        foreach ($p in $script:WfxSecretPatterns) { $t = (Get-WfxRx $p.Pattern).Replace($t, [System.Text.RegularExpressions.MatchEvaluator] { param($m) Format-WfxSecret $m.Value }) }
        foreach ($r in $script:WfxRedactRules) { $t = (Get-WfxRx $r[0]).Replace($t, $r[1]) }
    } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
        return "[content withheld: redaction timed out on $($Text.Length) chars]"
    }
    return $t
}

# ───────────────────────────── encoded commands ─────────────────────────────
function ConvertFrom-WfxBase64Text {
    <# Decodes base64 to text WITHOUT executing anything. Tries UTF-16LE (PowerShell -EncodedCommand), then
       gzip/deflate-wrapped payloads, then UTF-8. Returns $null if it isn't sensibly decodable. #>
    param([string]$Base64, [int]$MaxBytes = 1048576)
    if ([string]::IsNullOrWhiteSpace($Base64)) { return $null }
    $b = ($Base64 -replace '\s', '').Trim('"', "'")
    if ($b.Length -lt 8 -or $b.Length -gt ($MaxBytes * 2)) { return $null }
    $b = $b.PadRight($b.Length + ((4 - $b.Length % 4) % 4), '=')
    try { $bytes = [Convert]::FromBase64String($b) } catch { return $null }
    $printable = { param($s) if (-not $s) { return 0 }; @($s.ToCharArray() | Where-Object { [int]$_ -ge 32 -or $_ -in "`r", "`n", "`t" }).Count / [double]$s.Length }
    # gzip (1f 8b) or raw deflate commonly wrapped inside "FromBase64String | GzipStream" stagers
    if ($bytes.Length -gt 2 -and $bytes[0] -eq 0x1f -and $bytes[1] -eq 0x8b) {
        try {
            $ms = New-Object IO.MemoryStream(, $bytes)
            $gz = New-Object IO.Compression.GzipStream($ms, [IO.Compression.CompressionMode]::Decompress)
            $sr = New-Object IO.StreamReader($gz)
            $buf = New-Object char[] $MaxBytes; $n = $sr.Read($buf, 0, $MaxBytes); $sr.Dispose()
            return ('[gzip] ' + (New-Object string($buf, 0, $n)))
        } catch {}
    }
    # UTF-16LE of ASCII text has a 0x00 in (almost) every odd byte — that is the -EncodedCommand case.
    $zeroOdd = 0; for ($i = 1; $i -lt $bytes.Length; $i += 2) { if ($bytes[$i] -eq 0) { $zeroOdd++ } }
    $u16ok = $bytes.Length -ge 4 -and ($bytes.Length % 2) -eq 0
    if ($u16ok -and $zeroOdd -ge ($bytes.Length / 2) * 0.6) {
        $u16 = [Text.Encoding]::Unicode.GetString($bytes)
        if ((& $printable $u16) -ge 0.95) { return $u16 }
    }
    $u8 = [Text.Encoding]::UTF8.GetString($bytes)
    if ((& $printable $u8) -ge 0.95) { return $u8 }
    if ($u16ok) { $u16 = [Text.Encoding]::Unicode.GetString($bytes); if ((& $printable $u16) -ge 0.95) { return $u16 } }
    return $null
}

function Get-WfxEncodedCommandPayload {
    <# Extracts and decodes the -EncodedCommand / -enc / -e argument of a PowerShell command line. Text only. #>
    param([AllowEmptyString()][string]$CommandLine)
    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return $null }
    $m = [regex]::Match($CommandLine, '(?i)(?:^|\s)[-/](?:e|ec|en|enc|enco|encod|encode|encoded|encodedc|encodedco|encodedcom|encodedcomm|encodedcomma|encodedcomman|encodedcommand)\s+["'']?([A-Za-z0-9+/=]{8,})')
    if (-not $m.Success) { return $null }
    ConvertFrom-WfxBase64Text $m.Groups[1].Value
}

# ───────────────────────────── paths & command lines ─────────────────────────────
function Get-WfxImagePath {
    <# Extracts the executable path from a command line / service ImagePath / Run value. #>
    param([AllowEmptyString()][string]$CommandLine)
    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return '' }
    $c = [Environment]::ExpandEnvironmentVariables($CommandLine.Trim())
    $c = $c -replace '^\\\?\?\\', ''
    if ($env:SystemRoot) { $c = $c -replace '^(?i)\\SystemRoot\\', "$env:SystemRoot\" }
    if ($c.StartsWith('"')) {
        $end = $c.IndexOf('"', 1)
        if ($end -gt 1) { return $c.Substring(1, $end - 1) }
    }
    $m = [regex]::Match($c, '^(.+?\.(?:exe|com|bat|cmd|ps1|vbs|js|jse|wsf|hta|scr|dll|msi|cpl|sys))(?=\s|,|$)', 'IgnoreCase')
    if ($m.Success) { return $m.Groups[1].Value }
    return ($c -split '\s+')[0]
}

function Get-WfxShortText {
    <# One-line, length-capped version of a text for tables. #>
    param([AllowEmptyString()][string]$Text, [int]$Max = 120)
    if (-not $Text) { return '' }
    $t = ($Text -replace '\s+', ' ').Trim()
    if ($t.Length -gt $Max) { return $t.Substring(0, $Max - 1) + '…' }
    return $t
}

function Get-WfxLeaf {
    param([AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrEmpty($Path)) { return '' }
    return ($Path -split '[\\/]')[-1]
}

function Test-WfxUserWritablePath {
    <# True for locations ordinary users can write to — where malware stages itself. #>
    param([AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $p = $Path.ToLowerInvariant() -replace '/', '\'
    if (Test-WfxTrustedVendorPath $p) { return $false }
    return [bool]($p -match '\\appdata\\|\\temp\\|\\tmp\\|\\downloads\\|\\desktop\\|\\documents\\|\\users\\public\\|\\programdata\\|\\windows\\temp\\|\\windows\\tasks\\|\\windows\\tracing\\|\\perflogs\\|\\\$recycle\.bin\\|\\recycler\\|\\inetpub\\temp|\\windows\\debug\\|\\spool\\drivers\\color\\|\\music\\|\\videos\\|\\pictures\\' -or
        $p -match '^[a-z]:\\[^\\]+\.(exe|dll|ps1|bat|vbs|js|hta)$')
}

function Test-WfxTrustedVendorPath {
    <# Admin-only-writable vendor locations that happen to sit under ProgramData (Defender's platform folder,
       Windows Defender ATP). These are ACL-protected, so treating them as user-writable only creates noise. #>
    param([AllowEmptyString()][string]$Path)
    if (-not $Path) { return $false }
    return [bool]($Path -match '(?i)\\programdata\\microsoft\\(?:windows defender(?: advanced threat protection)?|defender)\\(?:platform|scans)?\\?')
}

function Test-WfxSystemPath {
    param([AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    return [bool]($Path -match '(?i)^(?:[a-z]:)?\\windows\\(system32|syswow64|winsxs)\\' -or $Path -match '(?i)^\\systemroot\\system32\\')
}

function Test-WfxTrustedSignature {
    param([AllowEmptyString()][string]$Status)
    return ($Status -in @('Valid', 'Signed', 'Trusted'))
}

function Test-WfxPrivateIp {
    param([AllowEmptyString()][string]$Ip)
    if ([string]::IsNullOrWhiteSpace($Ip)) { return $true }
    $a = $Ip.Trim('[', ']')
    if ($a -match '^(?:0\.|10\.|127\.|169\.254\.|192\.168\.|172\.(?:1[6-9]|2\d|3[01])\.|100\.(?:6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.|22[4-9]\.|23\d\.|255\.)') { return $true }
    if ($a -match '(?i)^(?:::1?$|::$|fe8|fe9|fea|feb|fc|fd|ff)') { return $true }
    if ($a -match '(?i)^::ffff:(.+)$') { return (Test-WfxPrivateIp $Matches[1]) }
    return $false
}

function ConvertTo-WfxArray {
    <# PS 5.1-safe: always returns an array (handles $null and single objects). #>
    param($InputObject)
    if ($null -eq $InputObject) { return , @() }
    return , @($InputObject)
}

function ConvertTo-WfxInt {
    <# Integer from saved evidence that may be malformed ("x", "", $null, "4625 "): never throws, returns -Default. #>
    param($Value, [int]$Default = 0)
    $n = 0
    if ($null -ne $Value -and [int]::TryParse(([string]$Value).Trim(), [ref]$n)) { return $n }
    return $Default
}

function Get-WfxValue {
    <# Reads a property that may not exist without tripping strict mode. #>
    param($Object, [string]$Name, $Default = $null)
    if ($null -eq $Object) { return $Default }
    if ($Object -is [System.Collections.IDictionary]) {
        if ($Object.Contains($Name)) { return $Object[$Name] } else { return $Default }
    }
    $p = $Object.PSObject.Properties[$Name]
    if ($p) { return $p.Value }
    return $Default
}

# ───────────────────────────── tool integrity ─────────────────────────────
function Get-WfxToolIntegrity {
    <# SHA-256 of every file the tool loaded (module files or the single-file build) plus any custom rule
       packs, so a manifest records exactly which code and which rules produced a case. #>
    $files = New-Object System.Collections.Generic.List[string]
    if ($script:WfxSingleFilePath -and (Test-Path -LiteralPath $script:WfxSingleFilePath)) { $files.Add($script:WfxSingleFilePath) }
    elseif ($script:WfxModuleRoot -and (Test-Path -LiteralPath $script:WfxModuleRoot)) {
        Get-ChildItem -LiteralPath $script:WfxModuleRoot -Recurse -File -Include *.ps1, *.psm1, *.psd1, *.json -ErrorAction SilentlyContinue |
            Sort-Object FullName | ForEach-Object { $files.Add($_.FullName) }
    }
    foreach ($src in @($script:WfxRuleSources)) { if ($src -and -not $files.Contains($src)) { $files.Add($src) } }
    $entries = foreach ($f in $files) {
        try { [ordered]@{ file = (Get-WfxLeaf $f); path = $f; sha256 = (Get-FileHash -LiteralPath $f -Algorithm SHA256).Hash.ToLowerInvariant() } } catch {}
    }
    $joined = (@($entries) | ForEach-Object { "$($_.path)|$($_.sha256)" }) -join "`n"
    $sha = [Security.Cryptography.SHA256]::Create()
    $combined = -join ($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($joined)) | ForEach-Object { $_.ToString('x2') })
    [ordered]@{ version = $script:WfxVersion; combinedSha256 = $combined; files = @($entries) }
}

# ───────────────────────────── case management ─────────────────────────────
function Get-WfxDefaultOutputRoot {
    if (Test-WfxWindows) {
        $d = [Environment]::GetFolderPath('Desktop')
        if ($d) { return (Join-Path $d 'WinForensicX') }
    }
    if ($HOME) { return (Join-Path $HOME 'WinForensicX') }
    return (Join-Path (Get-Location) 'WinForensicX')
}

function New-WfxCase {
    <# Creates the case folder (outputs, raw evidence, audit log) and records who ran what, where, when, how. #>
    param([string]$OutputPath = '', [string]$Name = '', [string]$HostName = '', [string]$Mode = 'local', [hashtable]$Parameters = @{})
    if ($script:WfxCase -and -not $script:WfxCase.Closed) { Write-Verbose "Closing previous unfinished case $($script:WfxCase.Path)"; $script:WfxCase.Closed = $true }
    if (-not $HostName) { $HostName = [Environment]::MachineName }
    if (-not $OutputPath) { $OutputPath = Get-WfxDefaultOutputRoot }
    $stamp = (Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss') + 'Z'
    $safeHost = $HostName -replace '[^A-Za-z0-9._-]', '_'
    $folder = if ($Name) { ($Name -replace '[^A-Za-z0-9._-]', '_') + "_$safeHost`_$stamp" } else { "WFX_$safeHost`_$stamp" }
    $path = Join-Path $OutputPath $folder
    $n = 1; while (Test-Path -LiteralPath $path) { $path = Join-Path $OutputPath "$folder-$n"; $n++ }
    # Fail fast with one clear message: every later step writes into this folder.
    try {
        New-Item -ItemType Directory -Path (Join-Path $path 'raw') -Force -ErrorAction Stop | Out-Null
        $full = (Resolve-Path -LiteralPath $path -ErrorAction Stop).Path
    } catch {
        throw "Cannot create the case folder '$path': $($_.Exception.Message) Choose a writable output folder (menu: Settings, or -OutputPath)."
    }
    $onSystem = $false
    if ((Test-WfxWindows) -and $env:SystemDrive -and $full.StartsWith($env:SystemDrive, [StringComparison]::OrdinalIgnoreCase) -and $Mode -in @('local', 'evidence', 'monitor')) { $onSystem = $true }
    $script:WfxCase = [pscustomobject]@{
        Id           = [guid]::NewGuid().ToString()
        Name         = $Name
        Path         = $full
        Host         = $HostName
        Mode         = $Mode
        StartedUtc   = Get-WfxUtcNow
        Operator     = [Environment]::UserName
        OperatorHost = [Environment]::MachineName
        Admin        = (Test-WfxAdmin)
        PSVersion    = $PSVersionTable.PSVersion.ToString()
        PSEdition    = [string]$PSVersionTable.PSEdition
        ToolVersion  = $script:WfxVersion
        Parameters   = $Parameters
        OutputOnSystemDrive = $onSystem
        Sources      = @()
        Closed       = $false
    }
    Clear-WfxGap
    Write-WfxLog -Event 'case-start' -Data @{ case = $script:WfxCase.Id; host = $HostName; mode = $Mode; operator = $script:WfxCase.Operator; admin = $script:WfxCase.Admin; ps = $script:WfxCase.PSVersion; tool = $script:WfxVersion; parameters = $Parameters }
    if ($onSystem) {
        Write-WfxConsole 'Note: the case is being written to the system drive of the host under investigation. For evidence work prefer -OutputPath on external/network media.' -Kind Warn
        Write-WfxLog -Event 'warning' -Data @{ message = 'output written to the evidence host system drive' }
    }
    return $script:WfxCase
}

function Add-WfxCaseSource {
    <# Records an input the case was derived from (e.g. the source bundle of a re-analysis) with its SHA-256. #>
    param([string]$Path, [string]$Role = 'input')
    if (-not $script:WfxCase -or -not (Test-Path -LiteralPath $Path -PathType Leaf)) { return }
    $h = (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
    $script:WfxCase.Sources = @($script:WfxCase.Sources) + [pscustomobject]@{ role = $Role; path = $Path; sha256 = $h }
    Write-WfxLog -Event 'source' -Data @{ role = $Role; path = $Path; sha256 = $h }
}

function Save-WfxJson {
    param([Parameter(Mandatory)]$InputObject, [Parameter(Mandatory)][string]$Path, [int]$Depth = 8)
    $json = ConvertTo-Json -InputObject $InputObject -Depth $Depth
    [IO.File]::WriteAllText($Path, $json, (New-Object Text.UTF8Encoding($false)))
}

function Complete-WfxCase {
    <# Writes manifest.json — SHA-256 of every output, the tool/rule hashes, parameters and sources — then
       CLOSES the case so nothing can be appended afterwards. Returns the manifest path. #>
    $case = $script:WfxCase
    if (-not $case -or $case.Closed) { return }
    Write-WfxLog -Event 'case-end' -Data @{ case = $case.Id }
    $root = $case.Path
    $files = Get-ChildItem -LiteralPath $root -Recurse -File | Where-Object { $_.Name -ne 'manifest.json' } | Sort-Object FullName
    $entries = foreach ($f in $files) {
        [ordered]@{
            path   = $f.FullName.Substring($root.Length).TrimStart('\', '/') -replace '\\', '/'
            bytes  = $f.Length
            sha256 = (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
        }
    }
    $manifest = [ordered]@{
        schema       = 'winforensicx.manifest/2'
        case         = $case.Id
        name         = $case.Name
        host         = $case.Host
        mode         = $case.Mode
        tool         = "WinForensicX $script:WfxVersion"
        toolIntegrity = (Get-WfxToolIntegrity)
        operator     = $case.Operator
        operatorHost = $case.OperatorHost
        admin        = $case.Admin
        powershell   = "$($case.PSVersion) $($case.PSEdition)"
        parameters   = $case.Parameters
        sources      = @($case.Sources)
        started      = $case.StartedUtc
        completed    = (Get-WfxUtcNow)
        files        = @($entries)
        note         = 'Hashes prove these files are unchanged relative to this manifest. The manifest itself is not signed: record its SHA-256 out-of-band (ticket, evidence log) or sign it to make it tamper-evident.'
    }
    $mp = Join-Path $root 'manifest.json'
    Save-WfxJson -InputObject $manifest -Path $mp -Depth 8
    $case.Closed = $true
    $script:WfxCase = $null
    return $mp
}


# ===== Private/Correlate.ps1 =====
# Correlation: groups individual findings into incidents — sets of findings that share an entity (a
# file, program, account or address) and happen close together. An analyst then reads one story
# ("a document spawned PowerShell, which downloaded a tool, which was persisted and ran") instead of
# twenty separate lines. Deterministic and explainable: every link records why two findings were joined.

function Get-WfxFindingEntity {
    <# The things a finding is about, as normalised keys: file:<leaf>, user:<name>, ip:<addr>, host:<name>. #>
    param($Finding)
    $keys = New-Object System.Collections.Generic.HashSet[string]
    $ev = $Finding.Evidence
    $vals = New-Object System.Collections.Generic.List[string]
    $vals.Add([string]$Finding.Entity)
    if ($ev) {
        $pairs = if ($ev -is [System.Collections.IDictionary]) { $ev.GetEnumerator() } else { $ev.PSObject.Properties }
        foreach ($p in $pairs) {
            $n = [string]$p.Name; $v = [string]$p.Value
            if (-not $v) { continue }
            if ($n -match '(?i)^(?:user|users|actor|account|targetusername|subjectusername|accountname)$') { foreach ($u in ($v -split ',\s*')) { $u = ($u -replace '^.*\\', '').Trim().ToLowerInvariant(); if ($u -and $u -notmatch '\.[a-z0-9]{2,4}$' -and $u -notmatch '^(?:system|local service|network service|-|\$|anonymous logon|dwm-\d+|umfd-\d+)$' -and $u -notmatch '\$$') { [void]$keys.Add("user:$u") } } }
            else { $vals.Add($v) }
        }
    }
    foreach ($v in $vals) {
        foreach ($m in [regex]::Matches($v, '(?i)(?:[a-z]:|\\\\[^\\\s]+|\(volume\))?(?:\\[^\\\s"<>|]+)+\.(?:exe|dll|ps1|bat|cmd|vbs|js|hta|scr|sys|msi|lnk|iso|zip|7z|rar|txt|docx?|xlsx?)\b')) {
            $leaf = ($m.Value -split '\\')[-1].ToLowerInvariant()
            if ($leaf -notin 'cmd.exe', 'powershell.exe', 'pwsh.exe', 'conhost.exe', 'svchost.exe', 'explorer.exe', 'rundll32.exe', 'wevtutil.exe') { [void]$keys.Add("file:$leaf") }
        }
        foreach ($m in [regex]::Matches($v, '\b(?:\d{1,3}\.){3}\d{1,3}\b')) { if (-not (Test-WfxPrivateIp $m.Value) -and $m.Value -notmatch '^(?:0\.|127\.|255\.)') { [void]$keys.Add("ip:$($m.Value)") } }
    }
    , @($keys)
}

function Get-WfxIncident {
    <#
    .SYNOPSIS Groups findings into incidents. Two findings are linked when they share an entity and are at most
    -Window apart, or are both High/Critical within -Burst of each other. Returns incidents with 2+ findings
    (or a single Critical), most severe first.
    #>
    param([object[]]$Finding, [TimeSpan]$Window = ([TimeSpan]::FromHours(6)), [TimeSpan]$Burst = ([TimeSpan]::FromMinutes(20)))
    $sevRank = @{ Info = 0; Low = 1; Medium = 2; High = 3; Critical = 4 }
    $fs = @($Finding | Where-Object { $_ -and $_.Time -and -not (Test-WfxPostureFinding $_) -and $_.Severity -ne 'Info' })
    $n = $fs.Count
    if ($n -eq 0) { return , @() }
    $t = @($fs | ForEach-Object { ConvertTo-WfxDateTime $_.Time })
    $ent = @($fs | ForEach-Object { , (Get-WfxFindingEntity $_) })
    $parent = [int[]](0..($n - 1))
    $find = { param($i) while ($parent[$i] -ne $i) { $parent[$i] = $parent[$parent[$i]]; $i = $parent[$i] }; $i }
    $why = @{}
    # Entity index → findings that mention it, so linking is not quadratic over all pairs.
    $idx = @{}
    for ($i = 0; $i -lt $n; $i++) { foreach ($k in $ent[$i]) { if (-not $idx.ContainsKey($k)) { $idx[$k] = New-Object System.Collections.Generic.List[int] }; $idx[$k].Add($i) } }
    foreach ($k in $idx.Keys) {
        $list = $idx[$k]; if ($list.Count -lt 2 -or $list.Count -gt 200) { continue }
        for ($a = 0; $a -lt $list.Count; $a++) { for ($b = $a + 1; $b -lt $list.Count; $b++) {
                $i = $list[$a]; $j = $list[$b]
                if ([Math]::Abs(($t[$i] - $t[$j]).TotalSeconds) -le $Window.TotalSeconds) {
                    $ri = & $find $i; $rj = & $find $j; if ($ri -ne $rj) { $parent[$ri] = $rj; $why["$i|$j"] = "shared $k" }
                }
            } }
    }
    $order = @(0..($n - 1) | Sort-Object { $t[$_] })
    for ($a = 1; $a -lt $order.Count; $a++) {
        $i = $order[$a - 1]; $j = $order[$a]
        if ($sevRank[$fs[$i].Severity] -ge 3 -and $sevRank[$fs[$j].Severity] -ge 3 -and ($t[$j] - $t[$i]) -le $Burst) {
            $ri = & $find $i; $rj = & $find $j; if ($ri -ne $rj) { $parent[$ri] = $rj; $why["$i|$j"] = 'high-severity burst' }
        }
    }
    $groups = @{}
    for ($i = 0; $i -lt $n; $i++) { $r = & $find $i; if (-not $groups.ContainsKey($r)) { $groups[$r] = New-Object System.Collections.Generic.List[int] }; $groups[$r].Add($i) }
    $tacticOrder = @('Reconnaissance', 'Resource Development', 'Initial Access', 'Execution', 'Persistence', 'Privilege Escalation', 'Defense Evasion', 'Credential Access', 'Discovery', 'Lateral Movement', 'Collection', 'Command and Control', 'Exfiltration', 'Impact')
    $out = foreach ($g in $groups.Values) {
        $members = @($g | Sort-Object { $t[$_] })
        $maxSev = ($members | ForEach-Object { $sevRank[$fs[$_].Severity] } | Measure-Object -Maximum).Maximum
        if ($members.Count -lt 2 -and $maxSev -lt 4) { continue }
        $tactics = @($members | ForEach-Object { foreach ($tq in @($fs[$_].Technique)) { $x = Get-WfxAttackTechnique $tq; if ($x) { $x.Tactic } } } | Where-Object { $_ } | Select-Object -Unique | Sort-Object { $ix = $tacticOrder.IndexOf([string]$_); if ($ix -lt 0) { 99 } else { $ix } })
        $entCount = @{}; foreach ($m in $members) { foreach ($k in $ent[$m]) { $entCount[$k] = 1 + [int]$entCount[$k] } }
        $topEnt = @($entCount.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 6 | ForEach-Object Key)
        $sevName = @('Info', 'Low', 'Medium', 'High', 'Critical')[$maxSev]
        # Likely starting point: the earliest finding at the earliest attack stage present (delivery before
        # execution before everything else). It is a lead for where to look first, not a proven root cause.
        $entry = $null
        foreach ($stage in 'Initial Access', 'Execution') {
            $hit = @($members | Where-Object { $m = $_; @($fs[$m].Technique | ForEach-Object { $x = Get-WfxAttackTechnique $_; if ($x) { $x.Tactic } }) -contains $stage } | Select-Object -First 1)
            if ($hit) { $entry = [pscustomobject]@{ Id = $fs[$hit[0]].Id; Title = $fs[$hit[0]].Title; Entity = $fs[$hit[0]].Entity; Why = "earliest $($stage.ToLowerInvariant()) finding in the incident" }; break }
        }
        if (-not $entry) { $m0 = $members[0]; $entry = [pscustomobject]@{ Id = $fs[$m0].Id; Title = $fs[$m0].Title; Entity = $fs[$m0].Entity; Why = 'earliest finding in the incident' } }
        [pscustomobject]@{
            Severity = $sevName; Start = (ConvertTo-WfxUtcString $t[$members[0]]); End = (ConvertTo-WfxUtcString $t[$members[-1]])
            Tactics = $tactics; Entities = $topEnt; Count = $members.Count; Entry = $entry
            Score = [Math]::Round(($members | ForEach-Object { [double]$fs[$_].Score } | Measure-Object -Sum).Sum, 1)
            Findings = @($members | ForEach-Object { [pscustomobject]@{ Id = $fs[$_].Id; Title = $fs[$_].Title; Severity = $fs[$_].Severity; Time = $fs[$_].Time; Entity = $fs[$_].Entity } })
            Links = @($why.Keys | Where-Object { $p = $_ -split '\|'; [int]$p[0] -in $members } | ForEach-Object { $why[$_] } | Select-Object -Unique)
        }
    }
    $i = 0
    , @($out | Sort-Object @{ e = { $sevRank[$_.Severity] }; Descending = $true }, @{ e = { $_.Score }; Descending = $true } | ForEach-Object { $i++; $_ | Add-Member -NotePropertyName Id -NotePropertyValue ('INC-{0:D2}' -f $i) -PassThru })
}


# ===== Private/Corroborate.ps1 =====
# Corroboration: does anything else on the host independently record what a finding is about?
#
# A finding comes from one source (a running process, an event, an Amcache entry). When other, independent
# sources record the same program (Prefetch says it ran, Sysmon logged its start, a service points at it),
# the finding is far less likely to be noise, and the earliest of those records tells the analyst when the
# program first appeared, even for findings that only describe state seen at collection.
#
# Matching is by full path where both sides have one. A bare file name only matches another bare name or a
# path with that name, and never for common Windows programs (cmd.exe, rundll32.exe...), which appear
# everywhere and would corroborate anything. Every match is recorded with its source and time, so the
# report can show exactly why confidence went up.

$script:WfxCorroborateCommon = @('cmd.exe', 'powershell.exe', 'pwsh.exe', 'conhost.exe', 'svchost.exe', 'explorer.exe', 'rundll32.exe', 'regsvr32.exe',
    'wscript.exe', 'cscript.exe', 'mshta.exe', 'msiexec.exe', 'dllhost.exe', 'taskhostw.exe', 'services.exe', 'lsass.exe', 'winlogon.exe', 'csrss.exe',
    'smss.exe', 'wininit.exe', 'spoolsv.exe', 'searchindexer.exe', 'runtimebroker.exe', 'sihost.exe', 'ctfmon.exe', 'wmiprvse.exe', 'wevtutil.exe',
    'vssadmin.exe', 'net.exe', 'net1.exe', 'reg.exe', 'sc.exe', 'schtasks.exe', 'netsh.exe', 'whoami.exe', 'certutil.exe', 'bitsadmin.exe',
    'chrome.exe', 'msedge.exe', 'firefox.exe', 'notepad.exe', 'taskmgr.exe', 'mmc.exe', 'wmic.exe', 'curl.exe', 'tar.exe', 'ssh.exe')

function ConvertFrom-WfxEnvPath {
    <# Expands the machine-wide folder variables that UserAssist, Jump Lists and shortcuts store
    (%SystemRoot%\System32\x.exe), so they are compared as the real folder. Per-user variables
    (%TEMP%, %APPDATA%) are left alone because the user is not known. #>
    param([AllowEmptyString()][string]$Path)
    if (-not $Path -or $Path.IndexOf('%') -lt 0) { return $Path }
    $Path -replace '(?i)^%(?:systemroot|windir)%', 'C:\Windows' -replace '(?i)^%systemdrive%', 'C:' `
        -replace '(?i)^%programfiles\(x86\)%', 'C:\Program Files (x86)' -replace '(?i)^%programfiles%', 'C:\Program Files' `
        -replace '(?i)^%programdata%', 'C:\ProgramData' -replace '(?i)^%public%', 'C:\Users\Public'
}

function ConvertTo-WfxCorroborationKey {
    <# Normalised full-path key (no drive, lower case, env vars expanded) and leaf for a path-like value. #>
    param([string]$Value)
    $v = [string]$Value
    if (-not $v) { return $null }
    $v = $v.Trim().Trim('"')
    if ($v -match '^(?:process|file):(?:\d+:)?(.+)$') { $v = $Matches[1] }
    $v = ConvertFrom-WfxEnvPath $v
    $v = $v -replace '^\\\\\?\\', '' -replace '^\\\?\?\\', '' -replace '(?i)^\\systemroot\\', 'c:\windows\'
    $leaf = ($v -split '[\\/]')[-1].ToLowerInvariant()
    if ($leaf -notmatch '\.[a-z0-9]{2,4}$') { return $null }
    $full = if ($v -match '[\\/]') { ($v.ToLowerInvariant() -replace '/', '\' -replace '^\(volume\)', '' -replace '^[a-z]:', '') } else { '' }
    [pscustomobject]@{ Full = $full; Leaf = $leaf }
}

function Get-WfxObservation {
    <# Flattens the collected evidence into { Source; Key; Time; Detail } records, one per program sighting. #>
    param($Bundle, [object[]]$Event = @(), [object[]]$Artifact = @())
    $out = New-Object System.Collections.Generic.List[object]
    $add = {
        param([string]$Source, [string]$Path, $Time, [string]$Detail)
        $k = ConvertTo-WfxCorroborationKey $Path; if (-not $k) { return }
        $out.Add([pscustomobject]@{ Source = $Source; Key = $k; Time = $(if ($Time) { ConvertTo-WfxUtcString $Time } else { '' }); Detail = $(if ($Detail) { $Detail } else { $Path }) })
    }
    foreach ($a in $Artifact) {
        if (-not $a -or $a.Evidence -notin 'Execution', 'Presence', 'Install', 'Download', 'Detection', 'Access') { continue }
        & $add ([string]$a.Artifact) ([string]$a.Path) $a.Time ("{0}: {1}" -f $(if ($a.TimeKind) { $a.TimeKind } else { 'recorded' }), $a.Path)
    }
    foreach ($e in $Event) {
        $id = ConvertTo-WfxInt (Get-WfxValue $e 'Id' 0); $log = [string](Get-WfxValue $e 'Log' ''); $fl = Get-WfxValue $e 'Fields' $null
        if (-not $fl) { continue }
        $t = Get-WfxValue $e 'TimeCreated' (Get-WfxValue $e 'Time' '')
        $g = { param($n) [string](Get-WfxValue $fl $n '') }
        if ($log -match 'Sysmon') {
            switch ($id) {
                1 { & $add 'Sysmon 1 (process start)' (& $g 'Image') $t ("started: " + (& $g 'Image')) }
                11 { & $add 'Sysmon 11 (file created)' (& $g 'TargetFilename') $t ("created: " + (& $g 'TargetFilename')) }
                6 { & $add 'Sysmon 6 (driver loaded)' (& $g 'ImageLoaded') $t ("loaded: " + (& $g 'ImageLoaded')) }
                3 { & $add 'Sysmon 3 (network)' (& $g 'Image') $t ("connected to " + (& $g 'DestinationIp') + ':' + (& $g 'DestinationPort')) }
            }
        } elseif ($log -eq 'Security' -and $id -eq 4688) { & $add 'Security 4688 (process start)' (& $g 'NewProcessName') $t ("started: " + (& $g 'NewProcessName')) }
        elseif ($log -eq 'System' -and $id -eq 7045) { $ip = Get-WfxImagePath (& $g 'ImagePath'); & $add 'System 7045 (service installed)' $ip $t ("service " + (& $g 'ServiceName') + ': ' + (& $g 'ImagePath')) }
        elseif ($log -match 'Defender' -and $id -in 1116, 1117) { & $add 'Defender detection' (& $g 'Path') $t ((& $g 'Threat Name') + ' ' + (& $g 'Path')) }
    }
    foreach ($p in @(Get-WfxValue $Bundle 'Process' @())) { & $add 'Running process' ([string](Get-WfxValue $p 'Path' '')) (Get-WfxValue $p 'CreateTime' (Get-WfxValue $p 'StartTime' '')) ("PID " + (Get-WfxValue $p 'Pid' '') + ': ' + (Get-WfxValue $p 'Path' '')) }
    foreach ($p in @(Get-WfxValue $Bundle 'Persistence' @())) {
        $path = [string](Get-WfxValue $p 'Path' ''); if (-not $path) { $path = Get-WfxImagePath ([string](Get-WfxValue $p 'Command' '')) }
        & $add ('Autostart (' + [string](Get-WfxValue $p 'Kind' 'entry') + ')') $path $null ([string](Get-WfxValue $p 'Location' $path))
    }
    foreach ($a in @(Get-WfxValue $Bundle 'Activity' @())) {
        if ([string]$a.Category -notmatch 'File|Execution|Software|Service|Driver') { continue }
        & $add ('Change (' + [string]$a.Source + ')') ([string]$a.Target) $a.Time ("{0}: {1}" -f $a.Action, $a.Target)
    }
    , $out.ToArray()
}

function Get-WfxFindingFileKey {
    <# The programs / files a finding is about, as corroboration keys. #>
    param($Finding)
    $keys = New-Object System.Collections.Generic.List[object]
    $ev = $Finding.Evidence
    $vals = New-Object System.Collections.Generic.List[string]
    if ($ev) {
        foreach ($n in 'Path', 'Image', 'NewProcessName', 'TargetFilename', 'File', 'Driver', 'ImageLoaded', 'Target', 'Process') {
            $v = Get-WfxValue $ev $n ''; if ($v -is [string] -and $v) { $vals.Add($v) }
        }
    }
    if ($Finding.Entity -match '^(?:process|file):') { $vals.Add([string]$Finding.Entity) }
    foreach ($v in $vals) {
        $k = ConvertTo-WfxCorroborationKey $v
        if ($k -and -not @($keys | Where-Object { $_.Leaf -eq $k.Leaf -and ($_.Full -eq $k.Full -or -not $k.Full) }).Count) { $keys.Add($k) }
    }
    # Prefer full paths: drop bare names that a full path already covers.
    $full = @($keys | Where-Object Full)
    , @($full + @($keys | Where-Object { -not $_.Full -and $_.Leaf -notin @($full | ForEach-Object Leaf) }))
}

function Add-WfxCorroboration {
    <#
    .SYNOPSIS Adds Corroboration (independent sources that record the same program) to each finding and raises
    confidence one level when two or more independent sources agree. Returns the findings.
    #>
    param([object[]]$Finding, $Bundle, [object[]]$Event = @(), [object[]]$Artifact = @())
    $obs = @(Get-WfxObservation -Bundle $Bundle -Event $Event -Artifact $Artifact | Expand-WfxRecord)
    $byFull = @{}; $byLeaf = @{}
    foreach ($o in $obs) {
        if ($o.Key.Full) { if (-not $byFull.ContainsKey($o.Key.Full)) { $byFull[$o.Key.Full] = New-Object System.Collections.Generic.List[object] }; $byFull[$o.Key.Full].Add($o) }
        if (-not $byLeaf.ContainsKey($o.Key.Leaf)) { $byLeaf[$o.Key.Leaf] = New-Object System.Collections.Generic.List[object] }; $byLeaf[$o.Key.Leaf].Add($o)
    }
    $up = @{ Low = 'Medium'; Medium = 'High' }
    foreach ($f in $Finding) {
        if (-not $f -or (Test-WfxPostureFinding $f) -or $f.Severity -eq 'Info') { continue }
        $own = New-Object System.Collections.Generic.HashSet[string]
        $src = [string]$f.Source
        if ($src -eq 'process') { [void]$own.Add('Running process') }
        if ($src -eq 'persistence') { foreach ($o in $obs) { if ($o.Source -like 'Autostart*') { [void]$own.Add($o.Source) } } }
        if ($src -match '^activity:(.+)$') { [void]$own.Add("Change ($($Matches[1]))") }
        if ($src -match '^evt:') { foreach ($o in $obs) { if ($o.Source -match '^(?:Sysmon|Security|System|Defender)') { [void]$own.Add($o.Source) } } }
        $ev = $f.Evidence
        foreach ($n in 'SeenIn', 'Artifact') { $sv = [string](Get-WfxValue $ev $n ''); foreach ($s in ($sv -split ',\s*')) { if ($s) { [void]$own.Add($s) } } }
        $hits = @{}
        foreach ($k in @(Get-WfxFindingFileKey $f | Expand-WfxRecord)) {
            # Full path: same full path, or a source that records only the name (Prefetch, Defender) when the name is distinctive.
            # Bare name: any record of that name, again only when distinctive.
            $distinct = $k.Leaf -notin $script:WfxCorroborateCommon -and $k.Leaf.Length -ge 6 -and $byLeaf.ContainsKey($k.Leaf)
            $cand = @()
            if ($k.Full -and $byFull.ContainsKey($k.Full)) { $cand += $byFull[$k.Full].ToArray() }
            if ($distinct) { $cand += @($byLeaf[$k.Leaf].ToArray() | Where-Object { -not $k.Full -or -not $_.Key.Full }) }
            # Common Windows programs appear everywhere; for them only a record within minutes of the finding counts.
            $common = $k.Leaf -in $script:WfxCorroborateCommon
            $ft = if ($f.Time) { ConvertTo-WfxDateTime $f.Time } else { $null }
            foreach ($o in $cand) {
                if ($own.Contains($o.Source)) { continue }
                if ($common -and -not ($ft -and $o.Time -and [Math]::Abs(((ConvertTo-WfxDateTime $o.Time) - $ft).TotalMinutes) -le 10)) { continue }
                if (-not $hits.ContainsKey($o.Source)) { $hits[$o.Source] = [pscustomobject]@{ Source = $o.Source; First = $o.Time; Last = $o.Time; Detail = $o.Detail; Count = 0 } }
                $h = $hits[$o.Source]; $h.Count++
                if ($o.Time -and (-not $h.First -or $o.Time -lt $h.First)) { $h.First = $o.Time }
                if ($o.Time -and (-not $h.Last -or $o.Time -gt $h.Last)) { $h.Last = $o.Time }
            }
        }
        if (-not $hits.Count) { continue }
        $list = @($hits.Values | Sort-Object @{ e = { if ($_.First) { $_.First } else { '9999' } } } | Select-Object -First 8)
        $f | Add-Member -NotePropertyName Corroboration -NotePropertyValue $list -Force
        if ($list.Count -ge 2 -and $up.ContainsKey([string]$f.Confidence)) {
            $old = $f.Confidence; $f.Confidence = $up[$old]
            $f.Score = [Math]::Round($script:WfxSeverityWeight[$f.Severity] * $script:WfxConfidenceFactor[$f.Confidence], 1)
            $f | Add-Member -NotePropertyName ConfidenceNote -NotePropertyValue ("Confidence raised from {0} to {1}: {2} independent sources record the same program ({3})." -f $old, $f.Confidence, $list.Count, (@($list | ForEach-Object Source) -join ', ')) -Force
        }
    }
    , @($Finding)
}


# ===== Private/Ese.ps1 =====
# Extensible Storage Engine (ESE / "JET Blue") database reader, from the documented on-disk format: pages,
# page tags, B+ trees, the MSysObjects catalog, the record format (fixed, variable and tagged columns), long
# values and the 7-bit and XPRESS compression ESE uses for small values. Read-only, plain PowerShell; it is
# used for SRUM (SRUDB.dat), and works on any ESE file copied off a system.

function Open-WfxEse {
    <# Opens an ESE database copy. Returns { B; PageSize; Small; Tables (name -> table) }. #>
    param([string]$Path = '', [byte[]]$Bytes = $null)
    # Assigned directly (never returned through the pipeline, which would unroll the array into boxed bytes).
    [byte[]]$b = $Bytes
    if (-not $b) {
        $fs = [IO.File]::Open($Path, 'Open', 'Read', 'ReadWrite, Delete')
        try {
            if ($fs.Length -gt 2GB) { throw 'ESE database larger than 2 GB.' }
            $b = New-Object byte[] $fs.Length; $o = 0
            while ($o -lt $b.Length) { $k = $fs.Read($b, $o, $b.Length - $o); if ($k -le 0) { break }; $o += $k }
        } finally { $fs.Dispose() }
    }
    if ($b.Length -lt 4096 -or [BitConverter]::ToUInt32($b, 4) -ne 0x89ABCDEFL) { throw 'Not an ESE database (no 0x89ABCDEF signature).' }
    $ps = [int][BitConverter]::ToUInt32($b, 236)
    if ($ps -notin 2048, 4096, 8192, 16384, 32768) { throw "Unsupported ESE page size: $ps" }
    $db = [pscustomobject]@{ B = $b; PageSize = $ps; Small = ($ps -le 8192); Pages = [int][Math]::Floor($b.Length / $ps) - 1; Tables = @{}; State = [BitConverter]::ToUInt32($b, 52) }
    Read-WfxEseCatalog $db
    $db
}

function Get-WfxEsePage {
    <# Page header and tag reader for page $Pgno. Returns $null if the page is outside the file. #>
    param($Db, [long]$Pgno)
    if ($Pgno -lt 1 -or $Pgno -gt $Db.Pages) { return $null }
    $base = ($Pgno + 1) * $Db.PageSize
    $b = $Db.B
    $hdr = if ($Db.Small) { 40 } else { 80 }
    $state = [BitConverter]::ToUInt16($b, $base + 34)
    [pscustomobject]@{
        Num = $Pgno; Base = $base; Data = $base + $hdr; Prev = [BitConverter]::ToUInt32($b, $base + 16); Next = [BitConverter]::ToUInt32($b, $base + 20)
        Flags = [BitConverter]::ToUInt32($b, $base + 36); TagCount = ($state -band 0x0FFF); Reserved = [Math]::Max(1, ($state -shr 12))
    }
}

function Get-WfxEseTag {
    <# Tag $I of $Page: { Off (absolute); Size; Flags (1 version, 2 deleted, 4 compressed key) }. #>
    param($Db, $Page, [int]$I)
    $b = $Db.B
    $t = $Page.Base + $Db.PageSize - 4 * ($I + 1)
    $cb = [BitConverter]::ToUInt16($b, $t); $ib = [BitConverter]::ToUInt16($b, $t + 2)
    if ($Db.Small) { $size = $cb -band 0x1FFF; $off = $ib -band 0x1FFF; $fl = $ib -shr 13 }
    else { $size = $cb -band 0x7FFF; $off = $ib -band 0x7FFF; $fl = 0 }
    $abs = $Page.Data + $off
    if ($abs + $size -gt $Page.Base + $Db.PageSize) { return $null }
    if (-not $Db.Small -and $size -ge 2) { $fl = $b[$abs + 1] -shr 5 }
    [pscustomobject]@{ Off = $abs; Size = $size; Flags = $fl }
}

function Get-WfxEseNode {
    <# Node (key + data) from tag $I. Keys can share a prefix with the page's tag 0 ("compressed" key). #>
    param($Db, $Page, [int]$I, [byte[]]$Prefix)
    $t = Get-WfxEseTag $Db $Page $I
    if (-not $t -or $t.Size -lt 2) { return $null }
    $b = $Db.B; $o = $t.Off; $end = $t.Off + $t.Size
    $pre = 0
    if ($t.Flags -band 4) { $pre = [BitConverter]::ToUInt16($b, $o) -band 0x1FFF; $o += 2 }
    if ($o + 2 -gt $end) { return $null }
    $ks = [BitConverter]::ToUInt16($b, $o) -band 0x1FFF; $o += 2
    if ($o + $ks -gt $end) { return $null }
    $key = New-Object byte[] ($pre + $ks)
    if ($pre) { [Array]::Copy($Prefix, 0, $key, 0, [Math]::Min($pre, $Prefix.Length)) }
    [Array]::Copy($b, $o, $key, $pre, $ks); $o += $ks
    [pscustomobject]@{ Key = $key; Off = $o; Len = ($end - $o); Deleted = [bool]($t.Flags -band 2) }
}

function Get-WfxEseLeaf {
    <# Every live leaf node of the B+ tree rooted at $Root, in key order. #>
    param($Db, [long]$Root)
    $out = New-Object System.Collections.Generic.List[object]
    $seen = New-Object System.Collections.Generic.HashSet[long]
    $stack = New-Object System.Collections.Generic.Stack[long]
    $stack.Push($Root)
    while ($stack.Count) {
        $pg = $stack.Pop()
        if (-not $seen.Add($pg) -or $seen.Count -gt 2000000) { continue }
        $p = Get-WfxEsePage $Db $pg; if (-not $p) { continue }
        $prefix = [byte[]]@()
        $t0 = Get-WfxEseTag $Db $p 0
        if ($t0 -and $t0.Size) { $prefix = New-Object byte[] $t0.Size; [Array]::Copy($Db.B, $t0.Off, $prefix, 0, $t0.Size) }
        $leaf = [bool]($p.Flags -band 2)
        $children = New-Object System.Collections.Generic.List[long]
        for ($i = $p.Reserved; $i -lt $p.TagCount; $i++) {
            $n = Get-WfxEseNode $Db $p $i $prefix
            if (-not $n) { continue }
            if ($leaf) { if (-not $n.Deleted) { $out.Add($n) } }
            elseif ($n.Len -ge 4) { $children.Add([BitConverter]::ToUInt32($Db.B, $n.Off)) }
        }
        for ($i = $children.Count - 1; $i -ge 0; $i--) { $stack.Push($children[$i]) }   # keep key order
    }
    , $out.ToArray()
}

$script:WfxEseFixedSize = @{ 1 = 1; 2 = 1; 3 = 2; 4 = 4; 5 = 8; 6 = 4; 7 = 8; 8 = 8; 14 = 4; 15 = 8; 16 = 16; 17 = 2 }

function Read-WfxEseCatalog {
    <# Reads MSysObjects (root page 4): tables, their columns and long-value trees. #>
    param($Db)
    $cat = [pscustomobject]@{ Name = 'MSysObjects'; Root = 4; Columns = @{}; Fixed = @{}; Lv = 0 }
    $defs = @(@(1, 'ObjidTable', 4), @(2, 'Type', 3), @(3, 'Id', 4), @(4, 'ColtypOrPgnoFDP', 4), @(5, 'SpaceUsage', 4), @(6, 'Flags', 4), @(7, 'PagesOrLocale', 4), @(8, 'RootFlag', 1), @(9, 'RecordOffset', 3), @(10, 'LCMapFlags', 4), @(11, 'KeyMost', 17), @(12, 'LVChunkMax', 4))
    $off = 0
    foreach ($d in $defs) { $sz = $script:WfxEseFixedSize[$d[2]]; $cat.Columns[$d[0]] = [pscustomobject]@{ Id = $d[0]; Name = $d[1]; Type = $d[2]; Size = $sz; Offset = $off; Codepage = 0 }; $off += $sz }
    $cat.Columns[128] = [pscustomobject]@{ Id = 128; Name = 'Name'; Type = 10; Size = 0; Offset = 0; Codepage = 1252 }
    $cur = $null
    foreach ($n in (Get-WfxEseLeaf $Db 4)) {
        $r = ConvertFrom-WfxEseRecord $Db $cat $n
        if (-not $r -or $null -eq $r.Type) { continue }
        switch ([int]$r.Type) {
            1 { $cur = [pscustomobject]@{ Name = [string]$r.Name; Root = [long]$r.ColtypOrPgnoFDP; Columns = @{}; Lv = 0; LvCache = $null; NextFixed = 0 }; $Db.Tables[$cur.Name] = $cur }
            2 {
                if (-not $cur) { break }
                $type = [int]$r.ColtypOrPgnoFDP; $id = [int]$r.Id
                $size = if ($r.SpaceUsage) { [int]$r.SpaceUsage } elseif ($script:WfxEseFixedSize.ContainsKey($type)) { $script:WfxEseFixedSize[$type] } else { 0 }
                $col = [pscustomobject]@{ Id = $id; Name = [string]$r.Name; Type = $type; Size = $size; Offset = 0; Codepage = [int]$r.PagesOrLocale }
                if ($id -le 127) { $col.Offset = $cur.NextFixed; $cur.NextFixed += $size }
                $cur.Columns[$id] = $col
            }
            4 { if ($cur) { $cur.Lv = [long]$r.ColtypOrPgnoFDP } }
        }
    }
}

function ConvertFrom-WfxEseValue {
    <# Typed value from raw column bytes. #>
    param([byte[]]$V, $Col)
    if ($null -eq $V) { return $null }
    $n = $V.Length
    switch ($Col.Type) {
        1 { if ($n) { return [bool]($V[0] -ne 0) } }
        2 { if ($n) { return $V[0] } }
        3 { if ($n -ge 2) { return [BitConverter]::ToInt16($V, 0) } }
        4 { if ($n -ge 4) { return [BitConverter]::ToInt32($V, 0) } }
        5 { if ($n -ge 8) { return [BitConverter]::ToInt64($V, 0) } }
        6 { if ($n -ge 4) { return [BitConverter]::ToSingle($V, 0) } }
        7 { if ($n -ge 8) { return [BitConverter]::ToDouble($V, 0) } }
        8 { if ($n -ge 8) { $d = [BitConverter]::ToDouble($V, 0); if ($d -gt -657435 -and $d -lt 2958466) { return [DateTime]::SpecifyKind([DateTime]::FromOADate($d), 'Utc') } ; return $null } }
        { $_ -in 10, 12 } { if ($Col.Codepage -eq 1200) { return [Text.Encoding]::Unicode.GetString($V, 0, $n - ($n % 2)).TrimEnd([char]0) } else { return [Text.Encoding]::GetEncoding(1252).GetString($V).TrimEnd([char]0) } }
        14 { if ($n -ge 4) { return [BitConverter]::ToUInt32($V, 0) } }
        15 { if ($n -ge 8) { return [BitConverter]::ToInt64($V, 0) } }
        16 { if ($n -ge 16) { $g = New-Object byte[] 16; [Array]::Copy($V, $g, 16); return [guid]::new($g) } }
        17 { if ($n -ge 2) { return [BitConverter]::ToUInt16($V, 0) } }
        default { return , $V }
    }
    $null
}

function Expand-WfxEseCompressed {
    <# ESE value compression: first byte >> 3 = scheme (1 = 7-bit ASCII, 2 = 7-bit UTF-16, 3 = XPRESS). #>
    param([byte[]]$V)
    if (-not $V -or $V.Length -lt 2) { return , $V }
    $scheme = $V[0] -shr 3
    if ($scheme -eq 1 -or $scheme -eq 2) {
        $wide = $scheme -eq 2
        $out = New-Object System.Collections.Generic.List[byte]
        $val = 0; $shift = 0
        for ($i = 1; $i -lt $V.Length; $i++) {
            $val = $val -bor ([int]$V[$i] -shl $shift)
            $out.Add([byte]($val -band 0x7F)); if ($wide) { $out.Add(0) }
            $val = $val -shr 7; $shift++
            if ($shift -eq 7) { $out.Add([byte]($val -band 0x7F)); if ($wide) { $out.Add(0) }; $val = $val -shr 7; $shift = 0 }
        }
        # Padding in the last byte can decode to one extra NUL character; text never contains NULs, so drop it.
        $unit = if ($wide) { 2 } else { 1 }
        while ($out.Count -ge $unit -and $out[$out.Count - 1] -eq 0 -and $out[$out.Count - $unit] -eq 0) { $out.RemoveRange($out.Count - $unit, $unit) }
        return , $out.ToArray()
    }
    if ($scheme -eq 3 -and $V.Length -ge 3) { return , (Expand-WfxXpress -Src $V -Start 3) }
    , $V
}

function Expand-WfxXpress {
    <# Plain LZ77 "LZXPRESS" decompression ([MS-XCA] 2.3). #>
    param([byte[]]$Src, [int]$Start = 0, [int]$Max = 16777216)
    $dst = New-Object System.Collections.Generic.List[byte]
    $i = $Start; $n = $Src.Length; $flags = 0; $count = 0; $half = -1
    while ($i -lt $n -and $dst.Count -lt $Max) {
        if ($count -eq 0) { if ($i + 4 -gt $n) { break }; $flags = [BitConverter]::ToUInt32($Src, $i); $i += 4; $count = 32 }
        $count--
        if (-not ($flags -band ([uint32]1 -shl $count))) { $dst.Add($Src[$i]); $i++; continue }
        if ($i -ge $n) { break }
        if ($i + 2 -gt $n) { break }
        $m = [BitConverter]::ToUInt16($Src, $i); $i += 2
        $len = $m -band 7; $off = ($m -shr 3) + 1
        if ($len -eq 7) {
            if ($half -lt 0) { if ($i -ge $n) { break }; $len = $Src[$i] -band 0x0F; $half = $i; $i++ }
            else { $len = $Src[$half] -shr 4; $half = -1 }
            if ($len -eq 15) {
                if ($i -ge $n) { break }
                $len = $Src[$i]; $i++
                if ($len -eq 255) { if ($i + 2 -gt $n) { break }; $len = [BitConverter]::ToUInt16($Src, $i); $i += 2; if ($len -eq 0) { if ($i + 4 -gt $n) { break }; $len = [BitConverter]::ToUInt32($Src, $i); $i += 4 }; if ($len -lt 22) { break }; $len -= 22 }
                $len += 15
            }
            $len += 7
        }
        $len += 3
        if ($off -gt $dst.Count) { break }
        $from = $dst.Count - $off
        for ($k = 0; $k -lt $len; $k++) { $dst.Add($dst[$from + $k]) }
    }
    , $dst.ToArray()
}

function Get-WfxEseLongValue {
    <# Assembles a long value (stored in the table's separate LV tree) from its 4-byte id. #>
    param($Db, $Table, [byte[]]$Id)
    if (-not $Table.Lv -or $Id.Length -lt 4) { return $null }
    if (-not $Table.LvCache) {
        $cache = @{}
        foreach ($n in (Get-WfxEseLeaf $Db $Table.Lv)) {
            if ($n.Key.Length -lt 4) { continue }
            $lid = [BitConverter]::ToString($n.Key, 0, 4)
            if (-not $cache.ContainsKey($lid)) { $cache[$lid] = [pscustomobject]@{ Size = -1; Chunks = New-Object System.Collections.Generic.List[object] } }
            if ($n.Key.Length -eq 4) { if ($n.Len -ge 8) { $cache[$lid].Size = [BitConverter]::ToUInt32($Db.B, $n.Off + 4) } }
            elseif ($n.Key.Length -ge 8) {
                $o = ([long]$n.Key[4] -shl 24) -bor ([long]$n.Key[5] -shl 16) -bor ([long]$n.Key[6] -shl 8) -bor [long]$n.Key[7]
                $d = New-Object byte[] $n.Len; [Array]::Copy($Db.B, $n.Off, $d, 0, $n.Len)
                $cache[$lid].Chunks.Add([pscustomobject]@{ Offset = $o; Data = $d })
            }
        }
        $Table.LvCache = $cache
    }
    $rid = [byte[]]@($Id[3], $Id[2], $Id[1], $Id[0])
    $k = [BitConverter]::ToString($rid)
    if (-not $Table.LvCache.ContainsKey($k)) { return $null }
    $lv = $Table.LvCache[$k]
    $chunks = @($lv.Chunks | Sort-Object Offset)
    $out = New-Object System.Collections.Generic.List[byte]
    for ($i = 0; $i -lt $chunks.Count; $i++) {
        $next = if ($i + 1 -lt $chunks.Count) { $chunks[$i + 1].Offset } elseif ($lv.Size -ge 0) { $lv.Size } else { $chunks[$i].Offset + $chunks[$i].Data.Length }
        $d = $chunks[$i].Data
        if ($d.Length -ne ($next - $chunks[$i].Offset)) { $d = Expand-WfxEseCompressed $d }    # a chunk shorter than its span is compressed
        $out.AddRange([byte[]]$d)
    }
    , $out.ToArray()
}

function ConvertFrom-WfxEseRecord {
    <# Decodes one leaf node as a record of $Table. Returns a hashtable column-name -> value. $Want (column-id -> 1) limits decoding to those columns. #>
    param($Db, $Table, $Node, [hashtable]$Want = $null)
    $b = $Db.B; $o = $Node.Off; $len = $Node.Len
    if ($len -lt 4) { return $null }
    $lastFixed = $b[$o]; $lastVar = $b[$o + 1]; $varOff = [BitConverter]::ToUInt16($b, $o + 2)
    if ($varOff -gt $len) { return $null }
    $rec = @{}
    $bitmap = $varOff - [int][Math]::Floor(($lastFixed + 7) / 8)
    foreach ($c in $Table.Columns.Values) {
        if ($c.Id -gt 127 -or $c.Id -gt $lastFixed -or ($Want -and -not $Want.ContainsKey($c.Id))) { continue }
        $bi = $c.Id - 1
        if ($bitmap + [Math]::Floor($bi / 8) -lt $len -and ($b[$o + $bitmap + [Math]::Floor($bi / 8)] -band (1 -shl ($bi % 8)))) { continue }
        $s = 4 + $c.Offset
        if ($s + $c.Size -gt $len -or $c.Size -le 0) { continue }
        $v = New-Object byte[] $c.Size; [Array]::Copy($b, $o + $s, $v, 0, $c.Size)
        $rec[$c.Name] = ConvertFrom-WfxEseValue $v $c
    }
    $nVar = $lastVar - 127
    $varData = $varOff + 2 * [Math]::Max(0, $nVar)
    $tagStart = $varData
    if ($nVar -gt 0 -and $varData -le $len) {
        $prev = 0
        for ($i = 0; $i -lt $nVar; $i++) {
            $e = [BitConverter]::ToUInt16($b, $o + $varOff + 2 * $i)
            $end = $e -band 0x7FFF
            $id = 128 + $i
            if (-not ($e -band 0x8000) -and $Table.Columns.ContainsKey($id) -and (-not $Want -or $Want.ContainsKey($id)) -and $varData + $end -le $len -and $end -ge $prev) {
                $v = New-Object byte[] ($end - $prev); [Array]::Copy($b, $o + $varData + $prev, $v, 0, $end - $prev)
                $rec[$Table.Columns[$id].Name] = ConvertFrom-WfxEseValue $v $Table.Columns[$id]
            }
            $prev = $end
        }
        $tagStart = $varData + $prev
    }
    # Tagged columns: an array of (column id, offset) pairs, then the data.
    if ($tagStart + 4 -le $len) {
        $first = [BitConverter]::ToUInt16($b, $o + $tagStart + 2)
        $cnt = [int][Math]::Floor(($(if ($Db.Small) { $first -band 0x1FFF } else { $first -band 0x7FFF })) / 4)
        $fields = for ($i = 0; $i -lt $cnt -and $tagStart + 4 * $i + 4 -le $len; $i++) {
            $tid = [BitConverter]::ToUInt16($b, $o + $tagStart + 4 * $i); $raw = [BitConverter]::ToUInt16($b, $o + $tagStart + 4 * $i + 2)
            if ($Db.Small) { [pscustomobject]@{ Id = $tid; Off = ($raw -band 0x1FFF); Ext = [bool]($raw -band 0x4000); Null = [bool]($raw -band 0x2000) } }
            else { [pscustomobject]@{ Id = $tid; Off = ($raw -band 0x7FFF); Ext = $true; Null = $false } }
        }
        $fields = @($fields)
        for ($i = 0; $i -lt $fields.Count; $i++) {
            $f = $fields[$i]
            if (-not $Table.Columns.ContainsKey([int]$f.Id) -or $f.Null -or ($Want -and -not $Want.ContainsKey([int]$f.Id))) { continue }
            $col = $Table.Columns[[int]$f.Id]
            $s = $tagStart + $f.Off; $e = if ($i + 1 -lt $fields.Count) { $tagStart + $fields[$i + 1].Off } else { $len }
            if ($s -ge $e -or $e -gt $len) { continue }
            $flags = 0
            if ($f.Ext) { $flags = $b[$o + $s]; $s++ }
            if (-not $Db.Small -and ($flags -band 0x20)) { continue }
            $v = New-Object byte[] ($e - $s); [Array]::Copy($b, $o + $s, $v, 0, $e - $s)
            if ($flags -band 0x08) {
                # multi-value: keep the first value
                if ($flags -band 0x10) { if ($v.Length -gt 1) { $l1 = [Math]::Min($v[0], $v.Length - 1); $t = New-Object byte[] $l1; [Array]::Copy($v, 1, $t, 0, $l1); $v = $t } }
                elseif ($v.Length -ge 2) { $f1 = [BitConverter]::ToUInt16($v, 0) -band 0x7FFF; $e1 = if ($f1 -ge 4) { [BitConverter]::ToUInt16($v, 2) -band 0x7FFF } else { $v.Length }; if ($f1 -le $e1 -and $e1 -le $v.Length) { $t = New-Object byte[] ($e1 - $f1); [Array]::Copy($v, $f1, $t, 0, $e1 - $f1); $v = $t } }
            }
            if ($flags -band 0x04) { $v = Get-WfxEseLongValue $Db $Table $v }
            elseif ($flags -band 0x02) { $v = Expand-WfxEseCompressed $v }
            if ($null -ne $v) { $rec[$col.Name] = ConvertFrom-WfxEseValue ([byte[]]$v) $col }
        }
    }
    $rec
}

function Get-WfxEseTable {
    <# All records of a table, as hashtables. -Column limits decoding to the named columns (faster on big tables). #>
    param($Db, [string]$Name, [int]$Max = 2000000, [string[]]$Column = @())
    if (-not $Db.Tables.ContainsKey($Name)) { return }
    $t = $Db.Tables[$Name]; $k = 0
    $want = $null
    if ($Column.Count) { $want = @{}; foreach ($c in $t.Columns.Values) { if ($Column -contains $c.Name) { $want[[int]$c.Id] = 1 } } }
    foreach ($n in (Get-WfxEseLeaf $Db $t.Root)) {
        if (++$k -gt $Max) { break }
        $r = ConvertFrom-WfxEseRecord $Db $t $n $want
        if ($r) { $r }
    }
}


# ===== Private/Flag.ps1 =====
# Row verdicts for Explore views: every row of a flaggable view gets Flag / Why / Technique columns.
#
# Design rules (these views are read by people who will act on them):
#   * Analyzer-backed views run the SAME analyzers as triage, so a view and a triage report never disagree.
#   * A flag always says why, in plain words, and names the ATT&CK technique when there is one.
#   * The triage allowlist ($env:WFX_ALLOWLIST) suppresses the same things here.
#   * A flag is a lead to investigate, not a verdict of compromise. Severity follows the analyzers' scale.

$script:WfxFlagRank = @{ 'CRITICAL' = 5; 'HIGH' = 4; 'MEDIUM' = 3; 'LOW' = 2; 'INFO' = 1; '' = 0 }
$script:WfxFlagColumns = @('Flag', 'Why', 'Technique', 'Rule')   # Rule = triage rule id(s), usable in the allowlist

function Get-WfxSessionAllowlist {
    <# The allowlist that triage uses: the menu setting (Settings › Allowlist file) if set, else $env:WFX_ALLOWLIST.
       Cached per path, so changing the setting takes effect on the next view. #>
    $path = ''
    if ((Test-Path variable:script:WfxMenu) -and $script:WfxMenu -and $script:WfxMenu.Allowlist) { $path = [string]$script:WfxMenu.Allowlist }
    elseif ($env:WFX_ALLOWLIST) { $path = $env:WFX_ALLOWLIST }
    if ($null -ne $script:WfxSessionAllow -and $script:WfxSessionAllowPath -eq $path) { return , $script:WfxSessionAllow }
    $a = @()       # Read-WfxAllowlist already returns an array; wrapping it in @() would nest it
    if ($path) {
        if (Test-Path -LiteralPath $path) {
            try { $a = Read-WfxAllowlist -Path $path } catch { Add-WfxGap -Source 'allowlist' -Reason "Allowlist $path could not be read: $($_.Exception.Message)" }
        } else { Add-WfxGap -Source 'allowlist' -Reason "Allowlist file not found: $path" }
    }
    $script:WfxSessionAllow = $a
    $script:WfxSessionAllowPath = $path
    , $a
}

function Add-WfxVerdict {
    <#
    .SYNOPSIS Adds one reason to a row's verdict. The row keeps the highest severity; reasons and techniques accumulate.
    .PARAMETER Severity Critical | High | Medium | Low | Info
    #>
    param([Parameter(Mandatory)]$InputObject, [Parameter(Mandatory)][string]$Severity, [Parameter(Mandatory)][string]$Why, [string[]]$Technique = @(), [string]$Rule = '')
    $sev = $Severity.ToUpperInvariant()
    if (-not $script:WfxFlagRank.ContainsKey($sev) -or $sev -eq '') { throw "Invalid severity '$Severity'" }
    foreach ($c in $script:WfxFlagColumns) { if (-not $InputObject.PSObject.Properties[$c]) { $InputObject | Add-Member -NotePropertyName $c -NotePropertyValue '' } }
    if ($script:WfxFlagRank[$sev] -gt $script:WfxFlagRank[[string]$InputObject.Flag]) { $InputObject.Flag = $sev }
    $whys = @(([string]$InputObject.Why) -split ' \| ' | Where-Object { $_ })
    if ($whys -notcontains $Why) { $InputObject.Why = (@($whys) + $Why) -join ' | ' }
    $tech = @(([string]$InputObject.Technique) -split ', ' | Where-Object { $_ }) + @($Technique | Where-Object { $_ -match '^T\d{4}(?:\.\d{3})?$' })
    $InputObject.Technique = (@($tech | Select-Object -Unique) -join ', ')
    if ($Rule) { $rules = @(([string]$InputObject.Rule) -split ', ' | Where-Object { $_ }); if ($rules -notcontains $Rule) { $InputObject.Rule = (@($rules) + $Rule) -join ', ' } }
}

function Add-WfxFindingVerdict {
    <# Applies analyzer findings to a row (after the allowlist). #>
    param($InputObject, [object[]]$Finding)
    foreach ($f in $Finding) { Add-WfxVerdict -InputObject $InputObject -Severity $f.Severity -Why $f.Title -Technique @($f.Technique) -Rule $f.Id }
}

function Add-WfxFlag {
    <#
    .SYNOPSIS Pipeline step: runs the triage analyzer for a record type over ALL piped records (so cross-record
    rules like parent/child still work) and attaches Flag / Why / Technique to the records the findings are about.
    .PARAMETER Kind Process | Network | Dns | Autostart | Activity | Artifact
    .PARAMETER DnsMap  IP → names, for network records (connections to tunnels / AI APIs).
    #>
    param(
        [Parameter(Mandatory, Position = 0)][ValidateSet('Process', 'Network', 'Dns', 'Autostart', 'Activity', 'Artifact')][string]$Kind,
        [Parameter(ValueFromPipeline)]$InputObject,
        [hashtable]$DnsMap = @{}
    )
    begin { $all = New-Object System.Collections.Generic.List[object] }
    process { if ($null -ne $InputObject) { $all.Add($InputObject) } }
    end {
        $recs = $all.ToArray()
        foreach ($r in $recs) { foreach ($c in $script:WfxFlagColumns) { if (-not $r.PSObject.Properties[$c]) { $r | Add-Member -NotePropertyName $c -NotePropertyValue '' } } }
        if (-not $recs.Count) { return }
        $findings = @()
        try {
            $findings = switch ($Kind) {
                'Process' { Invoke-WfxProcessAnalyzer -Process $recs }
                'Network' { Invoke-WfxNetworkAnalyzer -Connection $recs -DnsMap $DnsMap }
                'Dns' { Invoke-WfxDnsAnalyzer -DnsEntry $recs }
                'Autostart' { Invoke-WfxPersistenceAnalyzer -Autostart $recs }
                'Activity' { Invoke-WfxActivityAnalyzer -Activity $recs }
                'Artifact' { Invoke-WfxArtifactAnalyzer -Artifacts $recs }
            }
            $findings = @($findings | Expand-WfxRecord)
            $allow = Get-WfxSessionAllowlist
            if (@($allow).Count) { $findings = @((Split-WfxAllowlisted -Finding $findings -Allowlist $allow).Kept) }
        } catch {
            Add-WfxGap -Source "flags:$Kind" -Reason "Suspicious-activity checks could not run: $($_.Exception.Message)" -Fix 'Rows are shown unflagged; run a full triage for the complete analysis.'
            $findings = @()
        }
        # Index findings by the key each record type can be matched on.
        $by = @{}
        $add = { param($k, $f) if (-not $by.ContainsKey($k)) { $by[$k] = New-Object System.Collections.Generic.List[object] }; $by[$k].Add($f) }
        foreach ($f in $findings) {
            $e = [string]$f.Entity
            switch ($Kind) {
                'Process' { if ($e -match '^process:(\d+):') { & $add "pid:$($Matches[1])" $f } }
                'Network' {
                    if ($e -match '^listen:(\d+):') { & $add "listen:$($Matches[1]):$($f.Evidence.Pid)" $f }
                    elseif ($e -match '^conn:(.+):(\d+)$' -and $f.Id -ne 'AI-API-NONBROWSER') { & $add "conn:$($Matches[1]):$($Matches[2])" $f }
                    else { & $add "pid:$($f.Evidence.Pid)" $f }
                }
                'Dns' { if ($e -match '^dns:(.+)$') { & $add "dns:$($Matches[1])" $f } }
                'Autostart' { if ($e -match '^autostart:') { & $add $e.ToLowerInvariant() $f } }
                'Artifact' {
                    $ev = $f.Evidence
                    if ($ev -and $ev.Path) { & $add ('art:' + (ConvertTo-WfxArtifactKey $ev.Path)) $f }
                    if ($ev -and $ev.Source -and $e -match '^shortcut:') { & $add ('src:' + ([string]$ev.Source).ToLowerInvariant()) $f }
                }
                'Activity' {
                    $ev = $f.Evidence
                    # Keyed by action + target (not time): the analyzer dedupes repeats, but every matching row is flagged.
                    if ($f.Source -eq 'activity:burst') { Add-WfxViewPattern -Severity $f.Severity -Text $f.Title -Technique @($f.Technique) }
                    elseif ($ev -and $ev.Action) { & $add ("act:{0}|{1}" -f $ev.Action, [string]$ev.Target) $f }   # Target may be empty (e.g. Defender 5001)
                }
            }
        }
        foreach ($r in $recs) {
            $keys = switch ($Kind) {
                'Process' { "pid:$($r.Pid)" }
                'Network' {
                    if ([string]$r.State -match '^Listen') { "listen:$($r.LocalPort):$($r.Pid)" }
                    else { "conn:$($r.RemoteAddress):$($r.RemotePort)"; "pid:$($r.Pid)" }
                }
                'Dns' { 'dns:' + ([string]$r.Name).Trim('.').ToLowerInvariant() }
                'Autostart' { ("autostart:{0}:{1}" -f $r.Kind, $r.Name).ToLowerInvariant() }
                'Activity' { "act:{0}|{1}" -f $r.Action, [string]$r.Target }
                'Artifact' { 'art:' + (ConvertTo-WfxArtifactKey $r.Path); if ($r.Source) { 'src:' + ([string]$r.Source).ToLowerInvariant() } }
            }
            foreach ($k in @($keys)) { if ($by.ContainsKey($k)) { Add-WfxFindingVerdict -InputObject $r -Finding $by[$k].ToArray() } }
        }
        $recs
    }
}

function ConvertTo-WfxArtifactKey {
    <# Path key that ignores case and the drive / volume prefix, so C:\x, c:\x and (volume)\x match. #>
    param([AllowEmptyString()][string]$Path)
    ([string]$Path).ToLowerInvariant() -replace '^\(volume\)', '' -replace '^[a-z]:', ''
}

function Add-WfxViewPattern {
    <# A finding about many rows at once (e.g. 400 deletions in 10 minutes). Shown above the table. #>
    param([string]$Severity, [string]$Text, [string[]]$Technique = @())
    if ($null -eq $script:WfxViewPatterns) { $script:WfxViewPatterns = New-Object System.Collections.Generic.List[object] }
    $script:WfxViewPatterns.Add([pscustomobject]@{ Severity = $Severity.ToUpperInvariant(); Text = $Text; Technique = (@($Technique) -join ', ') })
}

function Clear-WfxViewPattern { $script:WfxViewPatterns = New-Object System.Collections.Generic.List[object] }
function Get-WfxViewPattern { if ($null -eq $script:WfxViewPatterns) { return } ; $script:WfxViewPatterns.ToArray() }

function Add-WfxCommandVerdict {
    <#
    .SYNOPSIS Flags a row whose command line / script text matches the living-off-the-land rule pack, or whose
    executable sits in a user-writable location. Run on the FULL text, before it is shortened for display.
    .PARAMETER Context  Where the command was found ("scheduled task", "PowerShell history" …) — used in the reason.
    #>
    param([Parameter(Mandatory)]$InputObject, [AllowEmptyString()][string]$Text, [string]$Context = '', [switch]$CheckImagePath)
    if ([string]::IsNullOrWhiteSpace($Text)) { return }
    $suffix = if ($Context) { " ($Context)" } else { '' }
    try {
        foreach ($r in (Test-WfxCommandLine -CommandLine $Text)) { Add-WfxVerdict -InputObject $InputObject -Severity $r.severity -Why "$($r.title)$suffix" -Technique @(Get-WfxValue $r 'technique' @()) -Rule $r.id }
    } catch { Add-WfxGap -Source 'flags:command' -Reason "Command-line rules unavailable: $($_.Exception.Message)" }
    if ($CheckImagePath) {
        $img = Get-WfxImagePath $Text
        if ($img -and (Test-WfxUserWritablePath $img)) { Add-WfxVerdict -InputObject $InputObject -Severity 'Medium' -Why "Runs a program from a user-writable folder$suffix" -Technique @('T1036.005') }
    }
}

function Test-WfxNameInList {
    <# Executable-name match against a rule-pack list (case-insensitive, with or without .exe). #>
    param([AllowEmptyString()][string]$Name, [object[]]$List)
    if ([string]::IsNullOrWhiteSpace($Name)) { return $false }
    $n = (Get-WfxLeaf $Name).Trim().ToLowerInvariant(); $nb = $n -replace '\.exe$', ''
    foreach ($x in $List) {
        $l = ([string]$x).Trim().ToLowerInvariant()
        if (-not $l -or $l -match '[\\/]') { continue }
        if ($l -eq $n -or ($l -replace '\.exe$', '') -eq $nb) { return $true }
    }
    $false
}

function Complete-WfxFlagRow {
    <# Ensures Flag / Why / Technique exist on every row and puts them first, so flagged and clean rows line up. #>
    param([Parameter(ValueFromPipeline)]$InputObject)
    process {
        if ($null -eq $InputObject -or $InputObject -is [string] -or $InputObject -is [System.ValueType]) { return $InputObject }
        foreach ($c in $script:WfxFlagColumns) { if (-not $InputObject.PSObject.Properties[$c]) { $InputObject | Add-Member -NotePropertyName $c -NotePropertyValue '' } }
        $o = [ordered]@{ Flag = $InputObject.Flag; Why = $InputObject.Why; Technique = $InputObject.Technique; Rule = $InputObject.Rule }
        foreach ($p in $InputObject.PSObject.Properties) { if ($script:WfxFlagColumns -notcontains $p.Name -and -not $p.Name.StartsWith('_')) { $o[$p.Name] = $p.Value } }
        [pscustomobject]$o
    }
}

function Get-WfxFlagSummary {
    <# "2 HIGH · 1 MEDIUM" for a set of rows ('' when nothing is flagged). #>
    param([object[]]$Rows)
    $g = @($Rows | Where-Object { $_ -and $_.PSObject.Properties['Flag'] -and $_.Flag -and $_.Flag -ne 'INFO' } | Group-Object Flag | Sort-Object { -$script:WfxFlagRank[$_.Name] })
    (@($g | ForEach-Object { "$($_.Count) $($_.Name)" }) -join ' · ')
}


# ===== Private/Fleet.ps1 =====
# Per-host summaries saved in result.json so many cases can be compared without reloading raw evidence:
#  * Programs  - every program path seen (processes, autostarts, execution artifacts, process-start events),
#                for "seen on one host only" (rarity) across a fleet.
#  * Logons    - remote logons into the host and connections / credential use out of it, for drawing
#                movement between hosts.
#  * Addresses - the host's own IP addresses, so other hosts' logon records can be matched to it.

function ConvertTo-WfxProgramKey {
    <# Path key that is stable across machines: no drive, user name or version folders, lower case. #>
    param([string]$Path)
    $p = ([string]$Path).Trim().Trim('"').ToLowerInvariant()
    if (-not $p) { return '' }
    $p = $p -replace '^\\\\\?\\', '' -replace '^\\device\\harddiskvolume\d+', '' -replace '^\(volume\)', '' -replace '^[a-z]:', '' -replace '/', '\'
    $p = $p -replace '^%systemroot%', '\windows' -replace '^%windir%', '\windows' -replace '^%programfiles%', '\program files' -replace '^\\systemroot\\', '\windows\'
    $p = $p -replace '\\users\\[^\\]+\\', '\users\*\' -replace '\\(?:\d+\.){1,3}\d+(?:[-_.][^\\]*)?\\', '\*\' -replace '\\\{[0-9a-f-]{36}\}\\', '\{guid}\'
    $p
}

function Get-WfxProgramSummary {
    <# Distinct programs seen on the host: { Key; Path; Sources; Last }. #>
    param($Bundle, [object[]]$Event = @(), [object[]]$Artifact = @(), [int]$Max = 20000)
    $map = @{}
    $add = {
        param([string]$Path, [string]$Source, $Time)
        if (-not $Path -or $Path -notmatch '(?i)\.(?:exe|dll|sys|scr|com|ps1|bat|cmd|vbs|js|hta|msi)$') { return }
        $k = ConvertTo-WfxProgramKey $Path; if (-not $k) { return }
        if (-not $map.ContainsKey($k)) { if ($map.Count -ge $Max) { return }; $map[$k] = [pscustomobject]@{ Key = $k; Path = $Path; Sources = New-Object System.Collections.Generic.List[string]; Last = '' } }
        $m = $map[$k]
        if (-not $m.Sources.Contains($Source)) { $m.Sources.Add($Source) }
        $t = if ($Time) { ConvertTo-WfxUtcString $Time } else { '' }
        if ($t -and $t -gt $m.Last) { $m.Last = $t }
    }
    foreach ($p in @(Get-WfxValue $Bundle 'Process' @())) { & $add ([string](Get-WfxValue $p 'Path' '')) 'Process' (Get-WfxValue $p 'CreateTime' $null) }
    foreach ($p in @(Get-WfxValue $Bundle 'Persistence' @())) { $pp = [string](Get-WfxValue $p 'Path' ''); if (-not $pp) { $pp = Get-WfxImagePath ([string](Get-WfxValue $p 'Command' '')) }; & $add $pp 'Autostart' $null }
    foreach ($a in $Artifact) { if ($a -and $a.Evidence -in 'Execution', 'Install', 'Presence') { & $add ([string]$a.Path) ([string]$a.Artifact) $a.Time } }
    foreach ($e in $Event) {
        $id = ConvertTo-WfxInt (Get-WfxValue $e 'Id' 0); $fl = Get-WfxValue $e 'Fields' $null; if (-not $fl -or $fl -is [string]) { continue }
        if ($id -eq 1 -and [string](Get-WfxValue $e 'Log' '') -match 'Sysmon') { & $add ([string](Get-WfxValue $fl 'Image' '')) 'Sysmon 1' (Get-WfxValue $e 'TimeCreated' $null) }
        elseif ($id -eq 4688) { & $add ([string](Get-WfxValue $fl 'NewProcessName' '')) 'Security 4688' (Get-WfxValue $e 'TimeCreated' $null) }
    }
    , @($map.Values | Sort-Object Key | ForEach-Object { [pscustomobject]@{ Key = $_.Key; Path = $_.Path; Sources = ($_.Sources -join ', '); Last = $_.Last } })
}

function Get-WfxLogonSummary {
    <#
    Remote access into and out of the host, aggregated: { Direction (In/Out); Kind; Peer; PeerName; Account;
    Detail; Count; First; Last }. In: 4624 network (3) and remote-desktop (10) logons from another machine.
    Out: 4648 logons with explicit credentials to another server, Sysmon 3 connections to SMB, RDP, WinRM, RPC.
    #>
    param([object[]]$Event = @(), [int]$Max = 2000)
    $agg = @{}
    $add = {
        param($Dir, $Kind, $Peer, $PeerName, $Account, $Detail, $Time)
        $Peer = ([string]$Peer).Trim(); $PeerName = ([string]$PeerName).Trim()
        if ((-not $Peer -or $Peer -in '-', '::1', '127.0.0.1', '0.0.0.0', 'localhost') -and (-not $PeerName -or $PeerName -eq '-')) { return }
        if ($Peer -in '-', '::1', '127.0.0.1', '0.0.0.0') { $Peer = '' }
        $k = "$Dir|$Kind|$($Peer.ToLowerInvariant())|$($PeerName.ToLowerInvariant())|$(([string]$Account).ToLowerInvariant())|$Detail"
        if (-not $agg.ContainsKey($k)) { if ($agg.Count -ge $Max) { return }; $agg[$k] = [pscustomobject]@{ Direction = $Dir; Kind = $Kind; Peer = $Peer; PeerName = $PeerName; Account = [string]$Account; Detail = $Detail; Count = 0; First = ''; Last = '' } }
        $g = $agg[$k]; $g.Count++
        $t = ConvertTo-WfxUtcString $Time
        if ($t) { if (-not $g.First -or $t -lt $g.First) { $g.First = $t }; if ($t -gt $g.Last) { $g.Last = $t } }
    }
    foreach ($e in $Event) {
        if (-not $e) { continue }
        $id = ConvertTo-WfxInt (Get-WfxValue $e 'Id' 0); $log = [string](Get-WfxValue $e 'Log' ''); $fl = Get-WfxValue $e 'Fields' $null
        if (-not $fl -or $fl -is [string]) { continue }
        $g = { param($n) [string](Get-WfxValue $fl $n '') }
        $t = Get-WfxValue $e 'TimeCreated' $null
        if ($log -eq 'Security' -and $id -eq 4624) {
            $lt = & $g 'LogonType'
            if ($lt -notin '3', '10') { continue }
            $user = & $g 'TargetUserName'
            if (-not $user -or $user -match '\$$' -or $user -match '^(?:ANONYMOUS LOGON|SYSTEM|LOCAL SERVICE|NETWORK SERVICE|DWM-\d+|UMFD-\d+)$') { continue }
            $dom = & $g 'TargetDomainName'; $acct = if ($dom -and $dom -ne '-') { "$dom\$user" } else { $user }
            & $add 'In' $(if ($lt -eq '10') { 'Remote desktop logon' } else { 'Network logon' }) (& $g 'IpAddress') (& $g 'WorkstationName') $acct "type $lt" $t
        } elseif ($log -eq 'Security' -and $id -eq 4648) {
            $srv = & $g 'TargetServerName'
            if (-not $srv -or $srv -in 'localhost', '-') { continue }
            $acct = & $g 'TargetUserName'; $dom = & $g 'TargetDomainName'; if ($dom -and $dom -ne '-') { $acct = "$dom\$acct" }
            & $add 'Out' 'Explicit credentials' '' $srv $acct (& $g 'ProcessName') $t
        } elseif ($log -match 'Sysmon' -and $id -eq 3) {
            $port = & $g 'DestinationPort'
            $svc = @{ '445' = 'SMB'; '3389' = 'Remote desktop'; '5985' = 'WinRM'; '5986' = 'WinRM'; '135' = 'RPC'; '22' = 'SSH' }[$port]
            if (-not $svc -or (& $g 'Initiated') -match '(?i)^false$') { continue }
            & $add 'Out' "$svc connection" (& $g 'DestinationIp') (& $g 'DestinationHostname') (& $g 'User') ((& $g 'Image') -replace '^.*\\', '') $t
        }
    }
    , @($agg.Values | Sort-Object First)
}

function Get-WfxHostAddress {
    <# The host's own addresses: from host info, else the local side of its connections. #>
    param($Bundle)
    $set = New-Object System.Collections.Generic.HashSet[string]
    $h = Get-WfxValue $Bundle 'Host' $null
    foreach ($a in @(Get-WfxValue $h 'Addresses' @())) { if ($a) { [void]$set.Add([string]$a) } }
    foreach ($c in @(Get-WfxValue $Bundle 'Network' @())) {
        $la = [string](Get-WfxValue $c 'LocalAddress' '')
        if ($la -and $la -notmatch '^(?:0\.0\.0\.0|127\.|::|::1|fe80:|0:0:)' -and $la -ne '::') { [void]$set.Add($la) }
    }
    , @($set | Sort-Object)
}


# ===== Private/Help.ps1 =====
# Single source of truth for user-facing help: commands, examples, limitations, safety.
# Rendered to the terminal by Show-WfxHelp and to HTML by New-WfxGuide, so the two never drift.

function Get-WfxHelpModel {
    [pscustomobject]@{
        Version  = $script:WfxVersion
        Tagline  = 'Read-only DFIR toolkit for Windows. Start it from an administrator PowerShell window with .\Start-WinForensicX.ps1, then use the menu: Investigate, Explore, Hunt & analyze, Cases.'
        Commands = @(
            [pscustomobject]@{ Name = 'Invoke-WfxTriage'; Summary = 'Collects, analyzes, scores and writes the case report. The main command.'
                Params = @('[-FileScan] [-ExposureScan] [-OutputPath <external media>] [-AllowlistPath <json>] [-SigmaPath <rules>] [-YaraRules <rules>]', '-ComputerName <hosts> [-Credential <cred>]  (remote, WinRM)', '-ArtifactPath <folder>  (collected evidence: hives, Amcache, Jump Lists, .lnk, browsers, SRUM, $MFT, .evtx)', '-EvtxPath <path>  (offline event logs only; nothing collected locally)', '-InputPath <case>  (re-analyze saved evidence)')
                Examples = @('Invoke-WfxTriage', 'Invoke-WfxTriage -FileScan -ExposureScan', 'Invoke-WfxTriage -ArtifactPath D:\kape\C -CaseName ctf-01', 'Invoke-WfxTriage -SigmaPath D:\sigma\rules\windows -YaraRules D:\yara', 'Invoke-WfxTriage -ComputerName srv01,srv02 -Credential (Get-Credential)', 'Invoke-WfxTriage -EvtxPath D:\evidence\Security.evtx', 'Invoke-WfxTriage -InputPath C:\cases\WFX_host_20260101-000000Z') }
            [pscustomobject]@{ Name = 'Invoke-WfxAnalyze'; Summary = 'Run all analyzers over a collected bundle (object, bundle.json, or case folder). OS-neutral.'
                Params = @('-Bundle <path|object>'); Examples = @('Invoke-WfxAnalyze -Bundle .\WFX_host\raw\bundle.json') }
            [pscustomobject]@{ Name = 'Start-WfxMonitor'; Summary = 'Live baseline, then alert on new suspicious processes / connections / beacons.'
                Params = @('[-Interval <sec>] [-Duration <sec>] [-MinSeverity <sev>]'); Examples = @('Start-WfxMonitor -Interval 5 -Duration 300') }
            [pscustomobject]@{ Name = 'Invoke-WfxHunt'; Summary = 'Sweep a host, saved case or evidence folder for IOCs (MD5/SHA-1/SHA-256, exact IPs, domains+subdomains, strings): event logs, artifacts (Amcache SHA-1 finds deleted programs), downloads.'
                Params = @('-Ioc <list> | -IocFile <txt> [-InputPath <case> | -ArtifactPath <folder>] [-FileScan] [-HashProcesses]'); Examples = @("Invoke-WfxHunt -Ioc 'evil.example','203.0.113.7' -FileScan", 'Invoke-WfxHunt -IocFile .\iocs.txt -InputPath .\WFX_host_case', 'Invoke-WfxHunt -IocFile .\iocs.txt -ArtifactPath D:\kape\C') }
            [pscustomobject]@{ Name = 'Get-WfxArtifact'; Summary = 'Parse execution and user-activity artifacts, live or from collected files: Amcache, ShimCache, Prefetch, BAM, UserAssist, PCA, ShellBags, Jump Lists, .lnk, RunMRU, typed paths, searches, browser downloads, Defender logs, SRUM, $MFT (collected). -Flag adds the triage verdict.'
                Params = @('[-Path <folder|file>] [-Artifact <types>] [-Flag]'); Examples = @('Get-WfxArtifact -Path D:\kape\C -Flag | Where-Object Flag', 'Get-WfxArtifact -Path .\Amcache.hve | Where-Object Sha1 -eq <sha1>', "Get-WfxArtifact -Artifact JumpList,Shortcut | Where-Object { `$_.Extra.DriveType -eq 'Removable' }") }
            [pscustomobject]@{ Name = 'Get-WfxActivity'; Summary = 'What changed recently: registry writes in persistence/security keys, software & driver installs, services, tasks, accounts, firewall/Defender/audit changes, executions (Prefetch/BAM/UserAssist), connection history, deletions; -Journal adds the NTFS change journal.'
                Params = @('[-Days <n>] [-Journal]'); Examples = @('Get-WfxActivity -Days 2', "Get-WfxActivity -Days 1 -Journal | Where-Object Category -eq 'File'") }
            [pscustomobject]@{ Name = 'New-WfxFileBaseline / Compare-WfxFileBaseline'; Summary = 'File-integrity baseline: hash folders now, later list added, deleted, content-changed and timestamp-only files.'
                Params = @('-Path <folders> [-OutputPath <json>]', '-Baseline <json>'); Examples = @('New-WfxFileBaseline -Path C:\inetpub\wwwroot -OutputPath E:\bl\web.json', 'Compare-WfxFileBaseline -Baseline E:\bl\web.json') }
            [pscustomobject]@{ Name = 'Get-WfxInsight'; Summary = '57 live read-only views, each suspicious row flagged with severity, reason and ATT&CK technique: system, updates, software, users, groups, sessions, USB, processes, process tree, ports, connections, DNS, routes, proxy, Wi-Fi, firewall, autostarts, services, tasks, WMI, logons, failed logons, RDP, account changes, Defender, downloads, Prefetch, recent files, PS history, posture.'
                Params = @('-List', '<topic> [-Days <n>]'); Examples = @('Get-WfxInsight -List', 'Get-WfxInsight logons -Days 3 | Format-Table', "Get-WfxInsight listeners | Where-Object Exposure -eq 'all interfaces'") }
            [pscustomobject]@{ Name = 'Save-WfxInsight'; Summary = 'Export every live view to a hashed inventory case: inventory.html + one CSV per view.'
                Params = @('[-Topic <list>] [-OutputPath <folder>]'); Examples = @('Save-WfxInsight -OutputPath E:\cases') }
            [pscustomobject]@{ Name = 'Test-WfxCase'; Summary = 'Verify a case against its manifest: changed, missing or added files.'
                Params = @('-Path <case> [-ExpectedManifestSha256 <hash>]'); Examples = @('Test-WfxCase -Path E:\cases\WFX_PC01_20261103-101500Z') }
            [pscustomobject]@{ Name = 'Get-WfxFileTriage'; Summary = 'What is this file? Hashes, true type vs extension, entropy, MOTW download URL, ADS, signature, PE facts, strings + IOCs. Never executes.'
                Params = @('-Path <files> [-Strings] [-MaxReadMB <n>]'); Examples = @('Get-WfxFileTriage .\sample.bin -Strings | Format-List', 'Get-ChildItem .\Downloads -File | Get-WfxFileTriage | Where-Object ExtensionMismatch') }
            [pscustomobject]@{ Name = 'ConvertFrom-WfxEncodedCommand'; Summary = 'Decode -EncodedCommand / Base64 / gzip / nested FromBase64String payloads (decode only).'
                Params = @('<command line or base64>'); Examples = @("ConvertFrom-WfxEncodedCommand 'powershell -enc VwByAGkAdABlAC0ATwB1AHQAcAB1AHQAIAAnAGgAaQAnAA=='") }
            [pscustomobject]@{ Name = 'Export-WfxTimeline'; Summary = 'UTC super-timeline of a case (processes, connections, events, files, findings) to CSV/JSON.'
                Params = @('-InputPath <case> [-Format Csv|Json] [-From <utc>] [-To <utc>]'); Examples = @('Export-WfxTimeline -InputPath .\WFX_host_case') }
            [pscustomobject]@{ Name = 'Compare-WfxCase'; Summary = 'Diff two cases: new processes, autostarts, services, listeners, DNS, exposure, findings.'
                Params = @('-Baseline <case> -Current <case> [-OutputPath <csv|json>]'); Examples = @('Compare-WfxCase -Baseline .\golden -Current .\today') }
            [pscustomobject]@{ Name = 'Export-WfxCase'; Summary = 'Export a case for other tools: Timesketch CSV, ECS JSON lines (Elastic, Splunk, Sentinel), STIX 2.1 (MISP, OpenCTI), indicator CSV. Written next to the case.'
                Params = @('-InputPath <case> [-Format Timesketch|Ecs|Stix|Indicators|All] [-OutputPath <folder>]'); Examples = @('Export-WfxCase -InputPath .\WFX_host_case', 'Export-WfxCase -InputPath .\case -Format Stix') }
            [pscustomobject]@{ Name = 'New-WfxFleetReport'; Summary = 'One page for many hosts: risk per host, patient zero and spread, indicators and findings shared between hosts, ATT&CK stages per host.'
                Params = @('-Path <folder of cases> [-OutputPath <html>]'); Examples = @('New-WfxFleetReport -Path E:\ir-cases') }
            [pscustomobject]@{ Name = 'Save-WfxEvidence'; Summary = 'Collect a hashed, read-only evidence bundle now; analyze later with -InputPath.'
                Params = @('[-FileScan] [-ExposureScan]'); Examples = @('Save-WfxEvidence -FileScan -ExposureScan') }
            [pscustomobject]@{ Name = 'Show-WfxMenu'; Summary = 'Interactive menu over everything above.'
                Params = @(); Examples = @('Show-WfxMenu') }
            [pscustomobject]@{ Name = 'Show-WfxHelp'; Summary = 'This help. Add -Html to open the full guide in a browser.'
                Params = @('[-Html]'); Examples = @('Show-WfxHelp', 'Show-WfxHelp -Html') }
        )
        Outputs  = @(
            'report.html   - self-contained triage report (open in any browser, offline)',
            'result.json   - findings + risk + ATT&CK coverage + gaps (machine-readable)',
            'findings.csv  - flat triage view for a spreadsheet / SIEM import',
            'raw/bundle.json - the normalized collected data (re-analyzable with -InputPath)',
            'audit.log     - every step the tool took, with timings (JSON lines)',
            'manifest.json - SHA-256 of every output + tool/rule hashes + parameters, written last; the case is then closed',
            'hunt.json / hunt.csv - IOC hits (Invoke-WfxHunt)',
            '<case>-timesketch.csv / -ecs.ndjson / -stix.json / -indicators.csv - Export-WfxCase, written next to the case'
        )
        Safety   = @(
            'Read-only: it changes no settings and executes nothing it finds. It sends no network traffic of its own (remote mode uses WinRM you initiate; -ExposureScan reads the domain SYSVOL share).',
            'Its only writes are its own case folder (default Desktop\WinForensicX) — use -OutputPath on external media for evidence work. Reading files can update NTFS last-access times.',
            'PowerShell 7 itself (not WinForensicX) sends anonymous start-up telemetry to Microsoft unless POWERSHELL_TELEMETRY_OPTOUT=1 is set; set it for evidence work, or use Windows PowerShell 5.1, which does not.',
            'Credential exposure is AUDITED, never extracted: it reports THAT a secret is exposed with the value redacted to type + length.',
            'No LSASS dumping, no SAM/NTDS hash parsing, no DPAPI/browser decryption, no exfiltration.',
            'Command lines, event messages and file contents are secret-scrubbed at collection time, so the raw bundle is safe to keep and ship.'
        )
        Limits   = @(
            'Findings are LEADS for an analyst, not verdicts. A finding means "look here," not "this host is compromised."',
            'Read findings alongside the collection gaps: with no process auditing and no Sysmon, "nothing found" mostly means "nothing could be seen" - the report says so.',
            'It is a TRIAGE tool, not a forensic imager. It does not acquire disk/memory images or carve deleted files.',
            'Detections are heuristic: expect some false positives and false negatives. Tune with custom rule packs ($env:WFX_RULES) and an allowlist (-AllowlistPath / $env:WFX_ALLOWLIST).',
            'Two scores: Compromise risk (evidence of attacker activity) and Posture (hardening/visibility gaps). A clean but un-hardened host scores low risk, high posture.',
            'Only loaded user registry hives (logged-on users) are inspected; event collection is capped per query and caps are reported as gaps.',
            'Administrator rights are recommended; without them some data is unavailable (recorded as gaps). Remote mode needs WinRM enabled on the target.',
            'It will not extract, decrypt, or dump secrets - that is a deliberate boundary, not a missing feature.',
            'The manifest is not signed: record its SHA-256 (printed at the end of each run) out-of-band to make the case tamper-evident.',
            'Artifacts: Amcache.hve is locked on a running system (collect it with a raw-copy tool and use -ArtifactPath); dirty hives are repaired from .LOG1/.LOG2 only when the logs continue the hive; browser rows still in the -wal file and compressed Prefetch contents are not read (Prefetch gives name and times); SRUDB.dat is usually locked live (collect it); $MFT is read from collected files only, and deleted SRUM records are skipped.',
            'Sigma: rules run only on the event logs and IDs the tool collects (rules can add Security/System IDs they need); aggregations and correlation rules are skipped and counted as a gap. YARA needs a yara executable you provide.'
        )
        Requires = 'Windows PowerShell 5.1 or PowerShell 7+. No external modules. Live collection needs Windows; analysis, re-analysis, hunting in saved cases, timelines, diffs and file triage also run on Linux/macOS (PowerShell 7).'
    }
}


# ===== Private/Hive.ps1 =====
# Read-only parser for offline Windows registry hive files (regf): SYSTEM, SOFTWARE, NTUSER.DAT,
# UsrClass.dat, Amcache.hve. Pure byte parsing of a copy held in memory: the file is opened for reading
# with sharing, never loaded into the live registry (no "reg load"), and nothing in it is executed.
#
# Limits: transaction logs (.LOG1/.LOG2) are not replayed, so a "dirty" hive copied from a running system
# can lack the most recent writes; deleted (unallocated) keys are not recovered. Both are reported.

function Open-WfxHive {
    <#
    .SYNOPSIS Opens a regf hive file (or bytes) and returns a handle for Get-WfxHiveKey / Get-WfxHiveValue.
    Returns $null if the data is not a registry hive.
    #>
    param([string]$Path, [byte[]]$Bytes, [switch]$NoLogs)
    if (-not $Bytes) {
        try {
            $fs = New-Object IO.FileStream($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
            try { $Bytes = New-Object byte[] $fs.Length; $n = 0; while ($n -lt $Bytes.Length) { $r = $fs.Read($Bytes, $n, $Bytes.Length - $n); if ($r -le 0) { break }; $n += $r } } finally { $fs.Dispose() }
        } catch { Write-Verbose "hive open failed: $Path : $($_.Exception.Message)"; return $null }
    }
    if ($Bytes.Length -lt 0x2000 -or [Text.Encoding]::ASCII.GetString($Bytes, 0, 4) -ne 'regf') { return $null }
    $seq1 = [BitConverter]::ToUInt32($Bytes, 4); $seq2 = [BitConverter]::ToUInt32($Bytes, 8)
    $replayed = 0
    if ($seq1 -ne $seq2 -and $Path -and -not $NoLogs) {
        # Dirty hive: replay the transaction logs that sit next to it (NAME.LOG1 / NAME.LOG2), if any.
        $dir = Split-Path -Parent $Path; $leaf = Split-Path -Leaf $Path
        $logs = @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -match ('^' + [regex]::Escape($leaf) + '\.LOG[12]$') } | ForEach-Object FullName)
        if ($logs.Count) { $r = Invoke-WfxHiveLogReplay -Bytes $Bytes -LogPath $logs; $Bytes = $r.Bytes; $replayed = $r.Entries }
        $seq1 = [BitConverter]::ToUInt32($Bytes, 4); $seq2 = [BitConverter]::ToUInt32($Bytes, 8)
    }
    $root = [BitConverter]::ToUInt32($Bytes, 0x24)
    $h = [pscustomobject]@{ Path = $Path; B = $Bytes; Root = [int]$root; Dirty = ($seq1 -ne $seq2); Replayed = $replayed
        LastWrite = (ConvertFrom-WfxFileTime ([BitConverter]::ToInt64($Bytes, 0x0C))) }
    $h
}

function Invoke-WfxHiveLogReplay {
    <#
    .SYNOPSIS Applies new-format (Windows 8.1+, "HvLE") transaction-log entries to an in-memory copy of a
    dirty hive, so writes Windows had not yet flushed into the hive file are not missed. Entries are applied
    in sequence-number order starting at the hive's last complete write; a gap in the sequence stops the
    replay. The original files are never modified. Old-format ("DIRT") logs are not supported.
    #>
    param([byte[]]$Bytes, [string[]]$LogPath)
    $out = New-Object byte[] $Bytes.Length; [Array]::Copy($Bytes, $out, $Bytes.Length)
    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($lp in $LogPath) {
        try { $L = [IO.File]::ReadAllBytes($lp) } catch { continue }
        if ($L.Length -lt 1024 -or [Text.Encoding]::ASCII.GetString($L, 0, 4) -ne 'regf') { continue }
        $p = 512
        while ($p + 40 -le $L.Length -and [Text.Encoding]::ASCII.GetString($L, $p, 4) -eq 'HvLE') {
            $size = [BitConverter]::ToUInt32($L, $p + 4); if ($size -lt 40 -or $p + $size -gt $L.Length) { break }
            $entries.Add([pscustomobject]@{ Seq = [BitConverter]::ToUInt32($L, $p + 12); BinSize = [BitConverter]::ToUInt32($L, $p + 16); Count = [BitConverter]::ToUInt32($L, $p + 20); Data = $L; Offset = $p })
            $p += $size
        }
    }
    $expected = [BitConverter]::ToUInt32($out, 8)          # secondary sequence = last complete write
    $applied = 0
    foreach ($e in @($entries | Sort-Object Seq)) {
        if ($e.Seq -lt $expected) { continue }
        if ($e.Seq -ne $expected) { break }
        $need = 0x1000 + [long]$e.BinSize
        if ($need -gt $out.Length -and $need -lt 2GB) { $bigger = New-Object byte[] $need; [Array]::Copy($out, $bigger, $out.Length); $out = $bigger }
        $ref = $e.Offset + 40; $data = $ref + 8 * $e.Count
        for ($i = 0; $i -lt $e.Count; $i++) {
            $po = [BitConverter]::ToUInt32($e.Data, $ref + 8 * $i); $ps = [BitConverter]::ToUInt32($e.Data, $ref + 8 * $i + 4)
            $dst = 0x1000 + [long]$po
            if ($dst + $ps -le $out.Length -and $data + $ps -le $e.Data.Length) { [Array]::Copy($e.Data, $data, $out, $dst, $ps) }
            $data += $ps
        }
        $expected++; $applied++
    }
    if ($applied) {
        [Array]::Copy([BitConverter]::GetBytes([uint32]$expected), 0, $out, 4, 4); [Array]::Copy([BitConverter]::GetBytes([uint32]$expected), 0, $out, 8, 4)
    }
    [pscustomobject]@{ Bytes = $out; Entries = $applied }
}

function ConvertFrom-WfxFileTime {
    param([long]$Value)
    if ($Value -le 0 -or $Value -gt 2650467743999999999) { return $null }   # 0 or after year 9999
    try { [DateTime]::FromFileTimeUtc($Value) } catch { $null }
}

function Get-WfxHiveCell {
    # Absolute offset of a cell's data (after its 4-byte size), or -1 when the offset is out of range.
    param($Hive, [long]$Offset)
    if ($Offset -lt 0 -or $Offset -eq 0xFFFFFFFFL) { return -1 }
    $abs = 0x1000 + $Offset + 4
    if ($abs + 4 -gt $Hive.B.Length) { return -1 }
    $abs
}

function Get-WfxHiveNode {
    <# Parses the nk (key) cell at a hive offset. #>
    param($Hive, [long]$Offset)
    $b = $Hive.B; $o = Get-WfxHiveCell $Hive $Offset
    if ($o -lt 0 -or $o + 0x4C -gt $b.Length -or $b[$o] -ne 0x6E -or $b[$o + 1] -ne 0x6B) { return $null }   # 'nk'
    $flags = [BitConverter]::ToUInt16($b, $o + 2)
    $nl = [BitConverter]::ToUInt16($b, $o + 0x48)
    if ($o + 0x4C + $nl -gt $b.Length) { return $null }
    $name = if ($flags -band 0x20) { [Text.Encoding]::GetEncoding(28591).GetString($b, $o + 0x4C, $nl) } else { [Text.Encoding]::Unicode.GetString($b, $o + 0x4C, $nl) }
    [pscustomobject]@{
        Offset     = $Offset
        Name       = $name
        LastWrite  = ConvertFrom-WfxFileTime ([BitConverter]::ToInt64($b, $o + 4))
        SubCount   = [BitConverter]::ToUInt32($b, $o + 0x14)
        SubList    = [BitConverter]::ToUInt32($b, $o + 0x1C)
        ValueCount = [BitConverter]::ToUInt32($b, $o + 0x24)
        ValueList  = [BitConverter]::ToUInt32($b, $o + 0x28)
    }
}

function Get-WfxHiveSubkeyOffsets {
    param($Hive, [long]$ListOffset, [int]$Depth = 0)
    $b = $Hive.B; $o = Get-WfxHiveCell $Hive $ListOffset
    if ($o -lt 0 -or $Depth -gt 4 -or $o + 4 -gt $b.Length) { return }
    $sig = [Text.Encoding]::ASCII.GetString($b, $o, 2); $n = [BitConverter]::ToUInt16($b, $o + 2)
    switch ($sig) {
        { $_ -in 'lf', 'lh' } { for ($i = 0; $i -lt $n -and $o + 4 + $i * 8 + 4 -le $b.Length; $i++) { [BitConverter]::ToUInt32($b, $o + 4 + $i * 8) } }
        'li' { for ($i = 0; $i -lt $n -and $o + 4 + $i * 4 + 4 -le $b.Length; $i++) { [BitConverter]::ToUInt32($b, $o + 4 + $i * 4) } }
        'ri' { for ($i = 0; $i -lt $n -and $o + 4 + $i * 4 + 4 -le $b.Length; $i++) { Get-WfxHiveSubkeyOffsets $Hive ([BitConverter]::ToUInt32($b, $o + 4 + $i * 4)) ($Depth + 1) } }
    }
}

function Get-WfxHiveSubkey {
    <# Child keys of a node (nk objects). #>
    param($Hive, $Node)
    if (-not $Node -or $Node.SubCount -eq 0) { return }
    foreach ($off in @(Get-WfxHiveSubkeyOffsets $Hive $Node.SubList)) { $k = Get-WfxHiveNode $Hive $off; if ($k) { $k } }
}

function Get-WfxHiveKey {
    <#
    .SYNOPSIS Returns the key node at a backslash path below the hive root (case-insensitive), or $null.
    "" or "\" returns the root. A first segment that names the root key itself is skipped.
    #>
    param($Hive, [string]$KeyPath = '')
    $node = Get-WfxHiveNode $Hive $Hive.Root
    if (-not $node) { return $null }
    foreach ($part in @($KeyPath -split '\\' | Where-Object { $_ })) {
        $next = $null
        foreach ($k in @(Get-WfxHiveSubkey $Hive $node)) { if ($k.Name -ieq $part) { $next = $k; break } }
        if (-not $next) { return $null }
        $node = $next
    }
    $node
}

function Get-WfxHiveValue {
    <#
    .SYNOPSIS Values of a key node: Name, Type (REG_*), Data (string / string[] / int / long / byte[]).
    .PARAMETER Name Return only this value ('' or '(default)' for the default value).
    #>
    param($Hive, $Node, [string]$Name)
    if (-not $Node -or $Node.ValueCount -eq 0) { return }
    $b = $Hive.B; $lo = Get-WfxHiveCell $Hive $Node.ValueList
    if ($lo -lt 0) { return }
    $want = if ($PSBoundParameters.ContainsKey('Name')) { if ($Name -eq '(default)') { '' } else { $Name } } else { $null }
    for ($i = 0; $i -lt $Node.ValueCount -and $lo + $i * 4 + 4 -le $b.Length; $i++) {
        $vo = Get-WfxHiveCell $Hive ([BitConverter]::ToUInt32($b, $lo + $i * 4))
        if ($vo -lt 0 -or $vo + 0x14 -gt $b.Length -or $b[$vo] -ne 0x76 -or $b[$vo + 1] -ne 0x6B) { continue }   # 'vk'
        $nl = [BitConverter]::ToUInt16($b, $vo + 2); $vflags = [BitConverter]::ToUInt16($b, $vo + 0x10)
        if ($vo + 0x14 + $nl -gt $b.Length) { continue }
        $vname = if ($nl -eq 0) { '' } elseif ($vflags -band 1) { [Text.Encoding]::GetEncoding(28591).GetString($b, $vo + 0x14, $nl) } else { [Text.Encoding]::Unicode.GetString($b, $vo + 0x14, $nl) }
        if ($null -ne $want -and $vname -ine $want) { continue }
        $size = [BitConverter]::ToUInt32($b, $vo + 4); $doff = [BitConverter]::ToUInt32($b, $vo + 8); $type = [BitConverter]::ToUInt32($b, $vo + 0xC)
        $raw = Get-WfxHiveData $Hive $size $doff
        [pscustomobject]@{ Name = $vname; Type = (ConvertTo-WfxRegTypeName $type); Data = (ConvertFrom-WfxRegData $type $raw) }
        if ($null -ne $want) { return }
    }
}

function Get-WfxHiveData {
    param($Hive, [uint32]$Size, [uint32]$Offset)
    $b = $Hive.B
    if ($Size -band 0x80000000L) {                       # data stored inside the offset field (<= 4 bytes)
        $len = [int]($Size -band 0x7FFFFFFF); if ($len -gt 4) { $len = 4 }
        $out = New-Object byte[] $len; [Array]::Copy([BitConverter]::GetBytes($Offset), 0, $out, 0, $len)
        return , $out
    }
    if ($Size -eq 0) { return , ([byte[]]@()) }
    $o = Get-WfxHiveCell $Hive $Offset
    if ($o -lt 0) { return , ([byte[]]@()) }
    if ($Size -gt 16344 -and $o + 8 -le $b.Length -and $b[$o] -eq 0x64 -and $b[$o + 1] -eq 0x62) {   # 'db' big data
        $segs = [BitConverter]::ToUInt16($b, $o + 2); $lst = Get-WfxHiveCell $Hive ([BitConverter]::ToUInt32($b, $o + 4))
        $ms = New-Object IO.MemoryStream
        for ($i = 0; $i -lt $segs -and $lst -ge 0 -and $lst + $i * 4 + 4 -le $b.Length; $i++) {
            $so = Get-WfxHiveCell $Hive ([BitConverter]::ToUInt32($b, $lst + $i * 4)); if ($so -lt 0) { break }
            $take = [Math]::Min(16344, [int]$Size - [int]$ms.Length); if ($take -le 0) { break }
            $take = [Math]::Min($take, $b.Length - $so); $ms.Write($b, $so, $take)
        }
        return , $ms.ToArray()
    }
    $len = [Math]::Min([int]$Size, $b.Length - $o)
    $out = New-Object byte[] $len; [Array]::Copy($b, $o, $out, 0, $len)
    , $out
}

function ConvertTo-WfxRegTypeName {
    param([uint32]$Type)
    switch ($Type) { 0 { 'REG_NONE' } 1 { 'REG_SZ' } 2 { 'REG_EXPAND_SZ' } 3 { 'REG_BINARY' } 4 { 'REG_DWORD' } 5 { 'REG_DWORD_BIG_ENDIAN' } 7 { 'REG_MULTI_SZ' } 11 { 'REG_QWORD' } default { "REG_$Type" } }
}

function ConvertFrom-WfxRegData {
    param([uint32]$Type, $Raw)
    $r = [byte[]]@($Raw)
    switch ($Type) {
        { $_ -in 1, 2 } { return ([Text.Encoding]::Unicode.GetString($r, 0, $r.Length - ($r.Length % 2))).TrimEnd([char]0) }
        7 { return , @(([Text.Encoding]::Unicode.GetString($r, 0, $r.Length - ($r.Length % 2))) -split "`0" | Where-Object { $_ }) }
        4 { if ($r.Length -ge 4) { return [BitConverter]::ToUInt32($r, 0) } else { return $null } }
        11 { if ($r.Length -ge 8) { return [BitConverter]::ToUInt64($r, 0) } else { return $null } }
        default { return , $r }
    }
}

function Get-WfxHiveTree {
    <# Walks keys below a node breadth-first (bounded) and emits @{ Path; Node }. #>
    param($Hive, $Node, [string]$Prefix = '', [int]$MaxKeys = 200000)
    $q = New-Object System.Collections.Generic.Queue[object]; $q.Enqueue(@($Node, $Prefix)); $n = 0
    while ($q.Count -and $n -lt $MaxKeys) {
        $item = $q.Dequeue(); $n++
        [pscustomobject]@{ Path = $item[1]; Node = $item[0] }
        foreach ($k in @(Get-WfxHiveSubkey $Hive $item[0])) { $q.Enqueue(@($k, $(if ($item[1]) { "$($item[1])\$($k.Name)" } else { $k.Name }))) }
    }
}

function Get-WfxHiveKind {
    <# Identifies a hive by its contents: SYSTEM, SOFTWARE, NTUSER, USRCLASS, AMCACHE, SAM, SECURITY or UNKNOWN. #>
    param($Hive)
    $top = @(Get-WfxHiveSubkey $Hive (Get-WfxHiveNode $Hive $Hive.Root) | ForEach-Object Name)
    if ($top -contains 'Select' -and ($top -match '^ControlSet00\d$')) { return 'SYSTEM' }
    if ($top -contains 'Root' -and ((Get-WfxHiveKey $Hive 'Root\InventoryApplicationFile') -or (Get-WfxHiveKey $Hive 'Root\File'))) { return 'AMCACHE' }
    if ($top -contains 'Local Settings') { return 'USRCLASS' }
    if ($top -contains 'Microsoft' -and $top -contains 'Classes' -and $top -contains 'Policies' -and -not ($top -contains 'Environment')) { return 'SOFTWARE' }
    if ($top -contains 'Software' -and ($top -contains 'Environment' -or $top -contains 'Control Panel')) { return 'NTUSER' }
    if ($top -contains 'SAM') { return 'SAM' }
    if ($top -contains 'Policy') { return 'SECURITY' }
    'UNKNOWN'
}


# ===== Private/Indicators.ps1 =====
# Indicator extraction from findings (the same rules the case report uses), shared by the STIX export,
# the fleet report and the console. Only attacker-related findings are used; private addresses, local
# names and Windows system binaries are left out so the list is something you could act on.

function Get-WfxIndicator {
    <#
    .SYNOPSIS Extracts indicators (IPv4, domain, URL, MD5 / SHA-1 / SHA-256) from findings' evidence.
    Returns { Type; Value; Severity; Findings (ids); FirstSeen }.
    #>
    param([object[]]$Finding)
    $rank = @{ Critical = 0; High = 1; Medium = 2; Low = 3; Info = 4 }
    $fileExt = '^(?:exe|dll|sys|ps1|psm1|bat|cmd|vbs|vbe|js|jse|wsf|hta|lnk|scr|msi|iso|img|zip|rar|7z|txt|log|xml|json|csv|html?|docx?|docm|xlsx?|xlsm|pptx?|pdf|dat|tmp|ini|cfg|config|dmp|evtx|etl|pf|db|sqlite|jpg|png|gif|cpl|ocx|mui|cab|reg|bak|old|lockd|locked|encrypted|crypt|enc|key|pem|pfx|kdbx|vhdx?|one|jar|sct|aspx?|php|jsp|dit|blf|regtrans-ms|hve|library-ms|automaticdestinations-ms|customdestinations-ms)$'
    $map = [ordered]@{}
    $add = {
        param($Type, $Value, $F)
        $v = ([string]$Value).TrimEnd(')', ',', '.', ';', "'", '"', ']')
        if (-not $v -or $v.Length -gt 400) { return }
        $k = "$Type|$($v.ToLowerInvariant())"
        if (-not $map.Contains($k)) { $map[$k] = [pscustomobject]@{ Type = $Type; Value = $v; Severity = $F.Severity; Findings = New-Object System.Collections.Generic.List[string]; FirstSeen = $F.Time } }
        $x = $map[$k]
        if (-not $x.Findings.Contains($F.Id)) { $x.Findings.Add($F.Id) }
        if ($rank[[string]$F.Severity] -lt $rank[[string]$x.Severity]) { $x.Severity = $F.Severity }
        if ($F.Time -and (-not $x.FirstSeen -or [string]$F.Time -lt [string]$x.FirstSeen)) { $x.FirstSeen = $F.Time }
    }
    foreach ($f in @($Finding | Where-Object { $_ -and -not (Test-WfxPostureFinding $_) -and $_.Id -notlike 'HUNT-*' })) {
        $texts = New-Object System.Collections.Generic.List[string]
        $texts.Add([string]$f.Entity)
        $ev = $f.Evidence
        if ($ev) {
            $pairs = if ($ev -is [System.Collections.IDictionary]) { $ev.GetEnumerator() } else { $ev.PSObject.Properties }
            foreach ($p in $pairs) { $v = $p.Value; $texts.Add($(if ($v -is [string] -or $v -is [System.ValueType]) { [string]$v } else { try { $v | ConvertTo-Json -Compress -Depth 4 } catch { [string]$v } })) }
        }
        foreach ($s in $texts) {
            if (-not $s) { continue }
            foreach ($m in [regex]::Matches($s, '(?i)\b(?:hxxps?|https?|ftp)://[^\s"''<>]+')) {
                $u = $m.Value -replace '^hxxp', 'http'; $uh = ''; try { $uh = ([uri]$u).Host } catch { }
                if ($uh -match '(?i)(?:^|\.)(?:invalid|example|test|localhost|local)$|^localhost$' -or ($uh -match '^\d' -and (Test-WfxPrivateIp $uh))) { continue }
                & $add 'url' $u $f
            }
            foreach ($m in [regex]::Matches($s, '\b(?:\d{1,3}\.){3}\d{1,3}\b')) { $ip = $m.Value; if (@($ip.Split('.') | Where-Object { [int]$_ -gt 255 }).Count) { continue }; if (-not (Test-WfxPrivateIp $ip) -and $ip -notmatch '^(?:0\.|127\.|255\.|22[4-9]\.|23\d\.)') { & $add 'ipv4' $ip $f } }
            foreach ($m in [regex]::Matches($s, '(?i)(?<![a-f0-9])(?:[a-f0-9]{64}|[a-f0-9]{40}|[a-f0-9]{32})(?![a-f0-9])')) { $h = $m.Value.ToLowerInvariant(); & $add $(switch ($h.Length) { 64 { 'sha256' } 40 { 'sha1' } default { 'md5' } }) $h $f }
            $noUrl = [regex]::Replace($s, '(?i)\b(?:hxxps?|https?|ftp)://[^\s"''<>]+', ' ')
            foreach ($m in [regex]::Matches($noUrl, '(?i)(?<![/\\:@\w.-])(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}\b(?![!\w-])')) {
                $d = $m.Value.ToLowerInvariant(); $tld = ($d -split '\.')[-1]
                if ($tld -match $fileExt -or $d -match '^(?:system|microsoft|io|net|ws|mshtml|scrobj|comsvcs|wscript|shell32|kernel32)\.' -or $d -match '\.(?:local|lan|internal|corp|home|localdomain|arpa|invalid|example)$' -or $d -match '^(?:[^.]+\.)?(?:example\.(?:com|org|net))$') { continue }
                & $add 'domain' $d $f
            }
        }
    }
    foreach ($x in $map.Values) { $x | Add-Member -NotePropertyName FindingIds -NotePropertyValue (@($x.Findings) -join ', ') -PassThru }
}

function New-WfxUuidV5 {
    <# Deterministic UUID (version 5, SHA-1) so re-exporting a case gives the same STIX ids. #>
    param([string]$Name, [guid]$Namespace = '00abedb4-aa42-466c-9c01-fed23315a9b7')
    $ns = $Namespace.ToByteArray()
    # .NET stores the first three GUID fields little-endian; RFC 4122 hashing wants network order.
    [Array]::Reverse($ns, 0, 4); [Array]::Reverse($ns, 4, 2); [Array]::Reverse($ns, 6, 2)
    $bytes = $ns + [Text.Encoding]::UTF8.GetBytes($Name)
    $h = [Security.Cryptography.SHA1]::Create().ComputeHash([byte[]]$bytes)
    $u = $h[0..15]
    $u[6] = ($u[6] -band 0x0F) -bor 0x50; $u[8] = ($u[8] -band 0x3F) -bor 0x80
    $hex = -join ($u | ForEach-Object { '{0:x2}' -f $_ })
    '{0}-{1}-{2}-{3}-{4}' -f $hex.Substring(0, 8), $hex.Substring(8, 4), $hex.Substring(12, 4), $hex.Substring(16, 4), $hex.Substring(20, 12)
}


# ===== Private/Lineage.ps1 =====
# Process trees: rebuilds "who started whom" from Sysmon 1 (process GUIDs), Security 4688 (process IDs and
# times) and the live process list, and attaches the ancestry of each process finding.
#
# Process IDs are reused by Windows, so a parent is only accepted when it was started before its child and
# is the most recent process with that ID at that moment. Sysmon's process GUIDs are unique and are used
# when present. Each step records where it came from, so the chain in the report can be checked.

function ConvertFrom-WfxPidValue {
    <# 4688 writes process IDs as hex (0x1a2c); Sysmon and the process list as decimal. #>
    param($Value)
    $s = ([string]$Value).Trim()
    if (-not $s) { return $null }
    if ($s -match '^0x([0-9a-fA-F]+)$') { return [long][Convert]::ToInt64($Matches[1], 16) }
    if ($s -match '^\d+$') { return [long]$s }
    $null
}

function New-WfxProcessGraph {
    <# Builds an index of process starts. Returns { Nodes (List); ByGuid; ByPid (pid -> nodes sorted by start) }. #>
    param([object[]]$Event = @(), [object[]]$Process = @())
    $nodes = New-Object System.Collections.Generic.List[object]
    $byGuid = @{}; $byPid = @{}; $byLeaf = @{}; $byPidAny = @{}
    $add = {
        param($n)
        $nodes.Add($n)
        if ($n.Guid) { $byGuid[$n.Guid] = $n }
        $lf = if ($n.Image) { ($n.Image -split '\\')[-1].ToLowerInvariant() } else { '' }
        $n | Add-Member -NotePropertyName Leaf -NotePropertyValue $lf
        if ($lf) { if (-not $byLeaf.ContainsKey($lf)) { $byLeaf[$lf] = New-Object System.Collections.Generic.List[object] }; $byLeaf[$lf].Add($n) }
        if ($null -ne $n.Pid) { if (-not $byPidAny.ContainsKey($n.Pid)) { $byPidAny[$n.Pid] = New-Object System.Collections.Generic.List[object] }; $byPidAny[$n.Pid].Add($n) }
        if ($null -ne $n.Pid) { $k = "$($n.Computer)|$($n.Pid)"; if (-not $byPid.ContainsKey($k)) { $byPid[$k] = New-Object System.Collections.Generic.List[object] }; $byPid[$k].Add($n) }
    }
    foreach ($e in $Event) {
        if (-not $e) { continue }
        $id = ConvertTo-WfxInt (Get-WfxValue $e 'Id' 0); $log = [string](Get-WfxValue $e 'Log' '')
        $fl = Get-WfxValue $e 'Fields' $null; if (-not $fl -or $fl -is [string]) { continue }
        $g = { param($n) [string](Get-WfxValue $fl $n '') }
        $comp = [string](Get-WfxValue $e 'Computer' '')
        $t = ConvertTo-WfxDateTime (Get-WfxValue $e 'TimeCreated' $null)
        if ($log -match 'Sysmon' -and $id -eq 1) {
            $ut = & $g 'UtcTime'; if ($ut) { $tt = ConvertTo-WfxDateTime ($ut -replace ' ', 'T' -replace '(\.\d+)?$', '$1Z'); if ($tt) { $t = $tt } }
            & $add ([pscustomobject]@{ Source = 'Sysmon 1'; Computer = $comp; Time = $t; Guid = (& $g 'ProcessGuid'); ParentGuid = (& $g 'ParentProcessGuid')
                    Pid = (ConvertFrom-WfxPidValue (& $g 'ProcessId')); Ppid = (ConvertFrom-WfxPidValue (& $g 'ParentProcessId')); Image = (& $g 'Image'); CommandLine = (& $g 'CommandLine')
                    User = (& $g 'User'); ParentImage = (& $g 'ParentImage'); ParentCommandLine = (& $g 'ParentCommandLine') })
        } elseif ($log -eq 'Security' -and $id -eq 4688) {
            $user = & $g 'SubjectUserName'; $dom = & $g 'SubjectDomainName'; if ($dom -and $user -and $user -notmatch '\$$') { $user = "$dom\$user" }
            & $add ([pscustomobject]@{ Source = 'Security 4688'; Computer = $comp; Time = $t; Guid = ''; ParentGuid = ''
                    Pid = (ConvertFrom-WfxPidValue (& $g 'NewProcessId')); Ppid = (ConvertFrom-WfxPidValue (& $g 'ProcessId')); Image = (& $g 'NewProcessName'); CommandLine = (& $g 'CommandLine')
                    User = $user; ParentImage = (& $g 'ParentProcessName'); ParentCommandLine = '' })
        }
    }
    foreach ($p in $Process) {
        if (-not $p) { continue }
        $pid0 = ConvertFrom-WfxPidValue (Get-WfxValue $p 'Pid' ''); if ($null -eq $pid0) { continue }
        & $add ([pscustomobject]@{ Source = 'Process list'; Computer = ''; Time = (ConvertTo-WfxDateTime (Get-WfxValue $p 'CreateTime' $null)); Guid = ''; ParentGuid = ''
                Pid = $pid0; Ppid = (ConvertFrom-WfxPidValue (Get-WfxValue $p 'Ppid' '')); Image = [string](Get-WfxValue $p 'Path' (Get-WfxValue $p 'Name' '')); CommandLine = [string](Get-WfxValue $p 'CommandLine' '')
                User = [string](Get-WfxValue $p 'User' (Get-WfxValue $p 'Owner' '')); ParentImage = [string](Get-WfxValue $p 'ParentPath' (Get-WfxValue $p 'ParentName' '')); ParentCommandLine = [string](Get-WfxValue $p 'ParentCommandLine' '') })
    }
    foreach ($k in @($byPid.Keys)) { $byPid[$k] = @($byPid[$k] | Sort-Object { if ($_.Time) { $_.Time } else { [datetime]::MinValue } }) }
    [pscustomobject]@{ Nodes = $nodes; ByGuid = $byGuid; ByPid = $byPid; ByLeaf = $byLeaf; ByPidAny = $byPidAny }
}

function Get-WfxProcessParent {
    <# The node that started $Node, or $null. Same source family only, so a 4688 child never borrows a Sysmon parent with a reused ID. #>
    param($Graph, $Node)
    if ($Node.ParentGuid -and $Graph.ByGuid.ContainsKey($Node.ParentGuid)) { return $Graph.ByGuid[$Node.ParentGuid] }
    if ($null -eq $Node.Ppid) { return $null }
    $k = "$($Node.Computer)|$($Node.Ppid)"
    if (-not $Graph.ByPid.ContainsKey($k)) { return $null }
    $best = $null
    foreach ($c in $Graph.ByPid[$k]) {
        if ($c.Source -ne $Node.Source -or [object]::ReferenceEquals($c, $Node)) { continue }
        # Started before the child (a few seconds of clock slack), most recent such process wins.
        if ($Node.Time -and $c.Time -and $c.Time -gt $Node.Time.AddSeconds(2)) { continue }
        if ($Node.Time -and $c.Time -and ($Node.Time - $c.Time).TotalDays -gt 60) { continue }
        $best = $c
    }
    $best
}

function Get-WfxProcessLineage {
    <# Ancestry of $Node, oldest first, ending with $Node. Adds the parent named by the child's own record when the parent's start was not collected. #>
    param($Graph, $Node, [int]$Max = 12)
    $chain = New-Object System.Collections.Generic.List[object]
    $seen = New-Object System.Collections.Generic.HashSet[object]
    $cur = $Node
    while ($cur -and $chain.Count -lt $Max -and $seen.Add($cur)) {
        $chain.Insert(0, $cur)
        $par = Get-WfxProcessParent -Graph $Graph -Node $cur
        if (-not $par) {
            if ($cur.ParentImage) { $chain.Insert(0, [pscustomobject]@{ Source = "$($cur.Source) (parent named by child)"; Computer = $cur.Computer; Time = $null; Guid = ''; ParentGuid = ''; Pid = $cur.Ppid; Ppid = $null; Image = $cur.ParentImage; CommandLine = $cur.ParentCommandLine; User = ''; ParentImage = ''; ParentCommandLine = '' }) }
            break
        }
        $cur = $par
    }
    , $chain.ToArray()
}

function Find-WfxProcessNode {
    <# The process start a finding is about: by Sysmon GUID, by PID (+ path), or by image path and time. #>
    param($Graph, $Finding)
    $ev = $Finding.Evidence; if (-not $ev) { return $null }
    $gv = { param($n) $v = Get-WfxValue $ev $n ''; if ($v -is [string] -or $v -is [System.ValueType]) { [string]$v } else { '' } }
    $guid = & $gv 'ProcessGuid'
    if ($guid -and $Graph.ByGuid.ContainsKey($guid)) { return $Graph.ByGuid[$guid] }
    $img = & $gv 'Image'; if (-not $img) { $img = & $gv 'NewProcessName' }; if (-not $img) { $img = & $gv 'Path' }
    $t = ConvertTo-WfxDateTime $(if (& $gv 'Time') { & $gv 'Time' } else { $Finding.Time })
    $pidv = ConvertFrom-WfxPidValue (& $gv 'Pid')
    $leaf = if ($img) { ($img -split '\\')[-1].ToLowerInvariant() } else { '' }
    $near = { param($a, $b) $a -and $b -and [Math]::Abs(($a - $b).TotalSeconds) -le 5 }
    $rank = @{ 'Sysmon 1' = 0; 'Security 4688' = 1; 'Process list' = 2 }
    if ($null -ne $pidv) {
        # A process seen running: the process list entry is the process itself. Prefer an event for the same
        # start (same ID, same program, same start time) because it carries the history further back.
        if (-not $Graph.ByPidAny.ContainsKey($pidv)) { return $null }
        $same = @($Graph.ByPidAny[$pidv] | Where-Object { -not $leaf -or -not $_.Leaf -or $_.Leaf -eq $leaf })
        $live = @($same | Where-Object Source -eq 'Process list' | Select-Object -First 1)
        $anchor = if ($live) { $live[0].Time } else { $t }
        $events = @($same | Where-Object { $_.Source -ne 'Process list' -and (& $near $_.Time $anchor) } | Sort-Object { $rank[$_.Source] })
        if ($events) { return $events[0] }
        if ($live) { return $live[0] }
        return $null
    }
    if (-not $leaf -or -not $t -or -not $Graph.ByLeaf.ContainsKey($leaf)) { return $null }
    $cands = @($Graph.ByLeaf[$leaf] | Where-Object { & $near $_.Time $t })
    if (-not $cands.Count) { return $null }
    @($cands | Sort-Object { $rank[$_.Source] }, { [Math]::Abs(($_.Time - $t).TotalSeconds) })[0]
}

function Add-WfxProcessLineage {
    <# Adds Lineage (oldest ancestor first) to findings about a process start, when at least a parent is known. #>
    param([object[]]$Finding, [object[]]$Event = @(), [object[]]$Process = @())
    $graph = New-WfxProcessGraph -Event $Event -Process $Process
    if (-not $graph.Nodes.Count) { return , @($Finding) }
    foreach ($f in $Finding) {
        if (-not $f -or (Test-WfxPostureFinding $f)) { continue }
        $node = Find-WfxProcessNode -Graph $graph -Finding $f
        if (-not $node) { continue }
        $chain = Get-WfxProcessLineage -Graph $graph -Node $node      # returns one wrapped array
        $chain = @($chain)
        if ($chain.Count -lt 2) { continue }
        $f | Add-Member -NotePropertyName Lineage -NotePropertyValue @($chain | ForEach-Object {
                [pscustomobject]@{ Time = $(if ($_.Time) { ConvertTo-WfxUtcString $_.Time } else { '' }); Image = $_.Image; CommandLine = (Protect-WfxText $(if ($_.CommandLine.Length -gt 1000) { $_.CommandLine.Substring(0, 1000) + ' …' } else { $_.CommandLine })); Pid = $_.Pid; User = $_.User; Source = $_.Source }
            }) -Force
    }
    , @($Finding)
}


# ===== Private/Lnk.ps1 =====
# Read-only Windows shortcut (.lnk) parser, per [MS-SHLLINK]. Pure byte parsing: no COM object,
# no shell API, nothing is executed or resolved — the file is only read.
#
# Besides the target, a shortcut records evidence an investigator wants: the command-line arguments
# (malicious .lnk lures hide PowerShell here), the window mode (hidden / minimised), the volume serial
# and label and drive type of the target (USB evidence), the network share, and in the tracker block the
# NetBIOS name and MAC address of the machine the shortcut was created on.

$script:WfxDriveType = @{ 0 = 'Unknown'; 1 = 'No root'; 2 = 'Removable'; 3 = 'Fixed'; 4 = 'Network'; 5 = 'CD-ROM'; 6 = 'RAM disk' }

function Get-WfxLnkInfo {
    <#
    .SYNOPSIS Parses a .lnk file (path) or its bytes. Returns $null if the data is not a valid shell link.
    Output: Target, Arguments, WorkingDir, RelativePath, Description, IconLocation, ShowCommand,
    Created / Accessed / Written (the TARGET's times, UTC), Size, Attributes, DriveType, DriveSerial,
    VolumeLabel, NetName, MachineId, MacAddress, Length (bytes the shortcut occupies).
    #>
    param([string]$Path, [byte[]]$Bytes)
    if (-not $Bytes) {
        if (-not $Path) { return $null }
        try { $Bytes = [System.IO.File]::ReadAllBytes($Path) } catch { return $null }
    }
    $b = $Bytes
    if ($b.Length -lt 0x4C -or [BitConverter]::ToUInt32($b, 0) -ne 0x4C) { return $null }
    if ([BitConverter]::ToString($b, 4, 16) -ne '01-14-02-00-00-00-00-00-C0-00-00-00-00-00-00-46') { return $null }
    $flags = [BitConverter]::ToUInt32($b, 0x14)
    $ft = { param($o) $v = [BitConverter]::ToInt64($b, $o); if ($v -le 0) { return $null }; try { [DateTime]::FromFileTimeUtc($v) } catch { $null } }
    $r = [ordered]@{
        Target = ''; Arguments = ''; WorkingDir = ''; RelativePath = ''; Description = ''; IconLocation = ''
        ShowCommand = switch ([BitConverter]::ToUInt32($b, 0x3C)) { 3 { 'Maximized' } 7 { 'Minimized' } default { 'Normal' } }
        Created = & $ft 0x1C; Accessed = & $ft 0x24; Written = & $ft 0x2C; Size = [BitConverter]::ToUInt32($b, 0x34)
        Attributes = [BitConverter]::ToUInt32($b, 0x18)
        DriveType = ''; DriveSerial = ''; VolumeLabel = ''; NetName = ''; MachineId = ''; MacAddress = ''; IdListPath = ''; EnvTarget = ''; Length = 0
    }
    $pos = 0x4C
    try {
        if ($flags -band 0x1) {                                   # LinkTargetIDList
            $idl = [BitConverter]::ToUInt16($b, $pos)
            if ($pos + 2 + $idl -le $b.Length) {
                $items = New-Object byte[] $idl; [Array]::Copy($b, $pos + 2, $items, 0, $idl)
                if (Get-Command ConvertFrom-WfxIdList -ErrorAction SilentlyContinue) {
                    $p = ''; foreach ($it in @(ConvertFrom-WfxIdList $items)) { $p = Join-WfxShellPath $p $it }; $r.IdListPath = $p
                }
            }
            $pos += 2 + $idl
        }
        if (($flags -band 0x2) -and $pos + 0x1C -le $b.Length) {  # LinkInfo
            $li = $pos
            $liSize = [BitConverter]::ToUInt32($b, $li); $hdr = [BitConverter]::ToUInt32($b, $li + 4); $liFlags = [BitConverter]::ToUInt32($b, $li + 8)
            $suffix = ''
            if ($hdr -ge 0x24 -and $li + 0x24 -le $b.Length) { $so = [BitConverter]::ToUInt32($b, $li + 32); if ($so) { $suffix = Read-WfxLnkString $b ($li + $so) $true } }
            if (-not $suffix) { $so = [BitConverter]::ToUInt32($b, $li + 24); if ($so) { $suffix = Read-WfxLnkString $b ($li + $so) $false } }
            if ($liFlags -band 0x1) {                             # VolumeID + LocalBasePath
                $vo = $li + [BitConverter]::ToUInt32($b, $li + 12)
                if ($vo + 16 -le $b.Length) {
                    $r.DriveType = $script:WfxDriveType[[int][BitConverter]::ToUInt32($b, $vo + 4)]
                    $r.DriveSerial = '{0:X8}' -f [BitConverter]::ToUInt32($b, $vo + 8)
                    $lo = [BitConverter]::ToUInt32($b, $vo + 12)
                    $r.VolumeLabel = if ($lo -eq 0x14 -and $vo + 20 -le $b.Length) { Read-WfxLnkString $b ($vo + [BitConverter]::ToUInt32($b, $vo + 16)) $true } else { Read-WfxLnkString $b ($vo + $lo) $false }
                }
                $base = ''
                if ($hdr -ge 0x24) { $uo = [BitConverter]::ToUInt32($b, $li + 28); if ($uo) { $base = Read-WfxLnkString $b ($li + $uo) $true } }
                if (-not $base) { $base = Read-WfxLnkString $b ($li + [BitConverter]::ToUInt32($b, $li + 16)) $false }
                $r.Target = if ($suffix) { $base.TrimEnd('\') + '\' + $suffix } else { $base }
            }
            if ($liFlags -band 0x2) {                             # CommonNetworkRelativeLink
                $cn = $li + [BitConverter]::ToUInt32($b, $li + 20)
                if ($cn + 0x14 -le $b.Length) {
                    $nno = [BitConverter]::ToUInt32($b, $cn + 8)
                    $net = if ($nno -gt 0x14 -and $cn + 0x1C -le $b.Length) { Read-WfxLnkString $b ($cn + [BitConverter]::ToUInt32($b, $cn + 20)) $true } else { Read-WfxLnkString $b ($cn + $nno) $false }
                    $r.NetName = $net
                    if (-not $r.Target) { $r.Target = if ($suffix) { $net.TrimEnd('\') + '\' + $suffix } else { $net } }
                    if (-not $r.DriveType) { $r.DriveType = 'Network' }
                }
            }
            $pos = $li + $liSize
        }
        $unicode = [bool]($flags -band 0x80)
        foreach ($f in @(@(0x4, 'Description'), @(0x8, 'RelativePath'), @(0x10, 'WorkingDir'), @(0x20, 'Arguments'), @(0x40, 'IconLocation'))) {
            if (-not ($flags -band $f[0])) { continue }
            if ($pos + 2 -gt $b.Length) { break }
            $n = [BitConverter]::ToUInt16($b, $pos); $pos += 2
            $len = if ($unicode) { $n * 2 } else { $n }
            if ($pos + $len -gt $b.Length) { break }
            $r[$f[1]] = if ($unicode) { [Text.Encoding]::Unicode.GetString($b, $pos, $len) } else { [Text.Encoding]::GetEncoding(28591).GetString($b, $pos, $len) }
            $pos += $len
        }
        while ($pos + 8 -le $b.Length) {                          # ExtraData blocks
            $bs = [BitConverter]::ToUInt32($b, $pos); if ($bs -lt 8 -or $pos + $bs -gt $b.Length) { if ($bs -lt 4) { $pos += 4 }; break }
            $sig = [BitConverter]::ToUInt32($b, $pos + 4)
            if ($sig -eq 0xA0000003L -and $bs -ge 0x60) {        # TrackerDataBlock
                $r.MachineId = (Read-WfxLnkString $b ($pos + 16) $false)
                if ($r.MachineId.Length -gt 16) { $r.MachineId = $r.MachineId.Substring(0, 16) }
                $droid = New-Object byte[] 16; [Array]::Copy($b, $pos + 48, $droid, 0, 16)
                if (($droid[7] -shr 4) -eq 1) { $r.MacAddress = (($droid[10..15] | ForEach-Object { '{0:x2}' -f $_ }) -join ':') }   # UUID v1 node = MAC
            } elseif ($sig -eq 0xA0000001L -and $bs -ge 0x314) {   # EnvironmentVariableDataBlock
                $r.EnvTarget = Read-WfxLnkString $b ($pos + 268) $true
                if (-not $r.EnvTarget) { $r.EnvTarget = Read-WfxLnkString $b ($pos + 8) $false }
            }
            $pos += $bs
        }
        $r.Length = [Math]::Min($b.Length, $pos + 4)
    } catch { $r.Length = $b.Length }
    if (-not $r.Target) { $r.Target = if ($r.EnvTarget) { $r.EnvTarget } elseif ($r.IdListPath) { $r.IdListPath } else { $r.RelativePath } }
    [pscustomobject]$r
}

function Read-WfxLnkString {
    <# Reads a NUL-terminated ANSI or UTF-16 string from a byte array, bounded by the array length. #>
    param([byte[]]$Bytes, [long]$Offset, [bool]$Unicode)
    if ($Offset -lt 0 -or $Offset -ge $Bytes.Length) { return '' }
    $end = [int]$Offset
    if ($Unicode) {
        while ($end + 1 -lt $Bytes.Length -and ($Bytes[$end] -ne 0 -or $Bytes[$end + 1] -ne 0)) { $end += 2 }
        return [Text.Encoding]::Unicode.GetString($Bytes, [int]$Offset, $end - [int]$Offset)
    }
    while ($end -lt $Bytes.Length -and $Bytes[$end] -ne 0) { $end++ }
    return [Text.Encoding]::GetEncoding(28591).GetString($Bytes, [int]$Offset, $end - [int]$Offset)
}


# ===== Private/Mft.ps1 =====
# NTFS Master File Table ($MFT) parser, from the published on-disk format (FILE records, update-sequence
# fixups, resident and non-resident attributes). Read-only: it parses a copied $MFT file (KAPE, Velociraptor,
# FTK Imager export) and never touches a live volume.
#
# Each file record carries two sets of timestamps: $STANDARD_INFORMATION, which any program can rewrite
# with one API call, and $FILE_NAME, which only the kernel updates. Comparing them is the classic way to
# spot timestomping: a creation time in $STANDARD_INFORMATION earlier than the one in $FILE_NAME, or times
# with no fraction of a second, which Windows itself practically never writes.


function ConvertFrom-WfxFileTimeTicks {
    param([long]$Ticks)
    if ($Ticks -le 0 -or $Ticks -gt 2650467743999999999L) { return $null }
    try { [DateTime]::FromFileTimeUtc($Ticks) } catch { $null }
}

function Read-WfxMftRecord {
    <#
    .SYNOPSIS Parses one FILE record (already read into $Buf at $Off, $Size bytes). Applies the fixups in place.
    Returns $null for an empty / corrupt record.
    #>
    param([byte[]]$Buf, [int]$Off, [int]$Size, [long]$Number)
    if ($Off + 48 -gt $Buf.Length) { return $null }
    if ([BitConverter]::ToUInt32($Buf, $Off) -ne 0x454C4946) { return $null }       # 'FILE'
    $usaOff = [BitConverter]::ToUInt16($Buf, $Off + 4); $usaCnt = [BitConverter]::ToUInt16($Buf, $Off + 6)
    if ($usaCnt -lt 2 -or $usaOff + 2 * $usaCnt -gt $Size -or ($usaCnt - 1) * 512 -gt $Size) { return $null }
    $usn = [BitConverter]::ToUInt16($Buf, $Off + $usaOff)
    # Each sector ends with the update sequence number; the real two bytes are kept in the array and put
    # back here. Some exports (ntfscat, some imagers) already put them back. A sector that shows neither
    # was torn (partly written, common for deleted records): it is left as is and the record is marked Torn;
    # the attribute bounds checks below keep a damaged record from being misread.
    $torn = $false
    for ($i = 1; $i -lt $usaCnt; $i++) {
        $p = $Off + $i * 512 - 2; $v = [BitConverter]::ToUInt16($Buf, $p); $real = [BitConverter]::ToUInt16($Buf, $Off + $usaOff + 2 * $i)
        if ($v -eq $usn) { $Buf[$p] = $Buf[$Off + $usaOff + 2 * $i]; $Buf[$p + 1] = $Buf[$Off + $usaOff + 2 * $i + 1] }
        elseif ($v -ne $real) { $torn = $true }
    }
    $flags = [BitConverter]::ToUInt16($Buf, $Off + 22)
    $base = [long]([BitConverter]::ToUInt64($Buf, $Off + 32) -band 0xFFFFFFFFFFFFL)
    $r = [ordered]@{ Number = $Number; Seq = [BitConverter]::ToUInt16($Buf, $Off + 16); InUse = [bool]($flags -band 1); IsDir = [bool]($flags -band 2); Base = $base
        SI = $null; FN = $null; FnRank = -1; Size = $null; Ads = $null; Zone = $null; Torn = $torn }
    $a = $Off + [BitConverter]::ToUInt16($Buf, $Off + 20)
    # The 'bytes in use' header field can be stale in deleted records, so walk to the end marker instead.
    $end = $Off + $Size
    $guard = 0
    while ($a + 16 -le $end -and $guard++ -lt 64) {
        $type = [BitConverter]::ToUInt32($Buf, $a)
        if ($type -eq 0xFFFFFFFFL) { break }
        $len = [long][BitConverter]::ToUInt32($Buf, $a + 4)
        if ($len -lt 16 -or $a + $len -gt $end) { break }
        $nonRes = $Buf[$a + 8]; $nameLen = $Buf[$a + 9]; $nameOff = [BitConverter]::ToUInt16($Buf, $a + 10)
        $cLen = 0; $c = 0
        if (-not $nonRes) {
            $cLen = [long][BitConverter]::ToUInt32($Buf, $a + 16); $c = $a + [BitConverter]::ToUInt16($Buf, $a + 20)
            if ($c + $cLen -gt $a + $len) { $a += $len; continue }
        }
        switch ($type) {
            0x10 {
                if (-not $nonRes -and $cLen -ge 32) {
                    $r.SI = @([BitConverter]::ToInt64($Buf, $c), [BitConverter]::ToInt64($Buf, $c + 8), [BitConverter]::ToInt64($Buf, $c + 16), [BitConverter]::ToInt64($Buf, $c + 24))
                }
            }
            0x30 {
                if (-not $nonRes -and $cLen -ge 66) {
                    $nl = $Buf[$c + 64]; $ns = $Buf[$c + 65]
                    if ($c + 66 + 2 * $nl -le $c + $cLen) {
                        # Prefer the Win32 long name over the DOS 8.3 alias; POSIX names are fine too.
                        $rank = switch ($ns) { 1 { 3 } 3 { 3 } 0 { 2 } default { 1 } }
                        if ($rank -gt $r.FnRank) {
                            $pref = [BitConverter]::ToUInt64($Buf, $c)
                            $r.FN = [ordered]@{ Parent = [long]($pref -band 0xFFFFFFFFFFFFL); ParentSeq = [int]($pref -shr 48)
                                Times = @([BitConverter]::ToInt64($Buf, $c + 8), [BitConverter]::ToInt64($Buf, $c + 16), [BitConverter]::ToInt64($Buf, $c + 24), [BitConverter]::ToInt64($Buf, $c + 32))
                                Name = [Text.Encoding]::Unicode.GetString($Buf, $c + 66, 2 * $nl) }
                            $r.FnRank = $rank
                        }
                    }
                }
            }
            0x80 {
                $aname = if ($nameLen -and $a + $nameOff + 2 * $nameLen -le $a + $len) { [Text.Encoding]::Unicode.GetString($Buf, $a + $nameOff, 2 * $nameLen) } else { '' }
                if (-not $aname) {
                    if ($nonRes) { if ($len -ge 56) { $r.Size = [BitConverter]::ToInt64($Buf, $a + 48) } } else { $r.Size = [long]$cLen }
                } else {
                    $r.Ads = if ($r.Ads) { @($r.Ads) + $aname } else { @($aname) }
                    if ($aname -eq 'Zone.Identifier' -and -not $nonRes -and $cLen -gt 0) { $r.Zone = [Text.Encoding]::UTF8.GetString($Buf, $c, [Math]::Min($cLen, 1024)) }
                }
            }
        }
        $a += $len
    }
    [pscustomobject]$r
}

function Read-WfxMft {
    <#
    .SYNOPSIS Parses a $MFT file (path or bytes) into one object per file: Number, Seq, InUse, IsDir, Path, Name,
    Size, SI* and FN* times (UTC), Ads, Zone (Zone.Identifier text), Torn. Extension records are merged.
    .DESCRIPTION Two passes, so memory stays small on multi-gigabyte $MFTs: the first keeps only folders (to
    build paths), the second streams the records and emits those that pass -Where.
    .PARAMETER Where       Optional filter run on each entry; only entries for which it returns true are output.
    .PARAMETER Prefilter   Optional cheaper filter run on the raw record (Name via .FN.Name, .SI / .FN.Times ticks,
                           .Ads, .Zone, .IsDir) before its path and output object are built.
    .PARAMETER MaxRecords  Safety cap (default 8 million records, about 8 GB of $MFT).
    #>
    param([string]$Path = '', [byte[]]$Bytes = $null, [scriptblock]$Where = $null, [scriptblock]$Prefilter = $null, [long]$MaxRecords = 8000000)
    $open = { if ($Bytes) { New-Object IO.MemoryStream (, $Bytes) } else { [IO.File]::Open($Path, 'Open', 'Read', 'ReadWrite, Delete') } }
    $s0 = & $open
    try {
        $head = New-Object byte[] 64
        if ($s0.Read($head, 0, 64) -lt 48 -or [BitConverter]::ToUInt32($head, 0) -ne 0x454C4946) { throw 'Not an NTFS $MFT (no FILE record at the start).' }
    } finally { $s0.Dispose() }
    $size = [long][BitConverter]::ToUInt32($head, 28)
    if ($size -notin 1024, 2048, 4096) { $size = 1024 }
    # Runs $Body for every parsed record, in order.
    $walk = {
        param([scriptblock]$Body)
        $st = & $open
        try {
            $chunk = 2048; $buf = New-Object byte[] ($size * $chunk); $n = 0L
            while ($n -lt $MaxRecords) {
                $got = 0
                while ($got -lt $buf.Length) { $k = $st.Read($buf, $got, $buf.Length - $got); if ($k -le 0) { break }; $got += $k }
                if ($got -lt $size) { break }
                $cnt = [int][Math]::Floor($got / $size)
                for ($i = 0; $i -lt $cnt; $i++) { $r = Read-WfxMftRecord -Buf $buf -Off ($i * $size) -Size $size -Number ($n + $i); if ($r) { & $Body $r } }
                $n += $cnt
                if ($got -lt $buf.Length) { break }
            }
        } finally { $st.Dispose() }
    }
    # Pass 1: folders (for paths) and extension records (attributes that did not fit in their base record).
    $dirs = New-Object 'System.Collections.Generic.Dictionary[long,object]'
    $ext = @{}
    & $walk {
        param($r)
        if ($r.Base -and $r.Base -ne $r.Number) { if (-not $ext.ContainsKey($r.Base)) { $ext[$r.Base] = New-Object System.Collections.Generic.List[object] }; $ext[$r.Base].Add($r); return }
        if ($r.IsDir) { $dirs[$r.Number] = $r }
    }
    $merge = {
        param($b)
        if (-not $ext.ContainsKey($b.Number)) { return }
        foreach ($x in $ext[$b.Number]) {
            if ($x.FN -and $x.FnRank -gt $b.FnRank) { $b.FN = $x.FN; $b.FnRank = $x.FnRank }
            if ($null -eq $b.Size -and $null -ne $x.Size) { $b.Size = $x.Size }
            if (-not $b.SI -and $x.SI) { $b.SI = $x.SI }
            if ($x.Ads) { $b.Ads = @(@($b.Ads) + @($x.Ads) | Where-Object { $_ } | Select-Object -Unique) }
            if (-not $b.Zone -and $x.Zone) { $b.Zone = $x.Zone }
        }
    }
    foreach ($d in @($dirs.Values)) { & $merge $d }
    # Folder paths, following parent references. A parent must still be that folder: a directory whose
    # sequence number matches the reference (one higher is accepted for a deleted folder, since deleting a
    # record increments it); otherwise the entry is placed under [Orphaned].
    $dpath = New-Object 'System.Collections.Generic.Dictionary[long,string]'
    $parentOk = {
        param($child)
        $par = $child.FN.Parent
        if ($par -eq 5) { return $true }
        if (-not $dirs.ContainsKey($par)) { return $false }
        $pr = $dirs[$par]; $ps = $child.FN.ParentSeq
        (-not $ps) -or $pr.Seq -eq $ps -or (-not $pr.InUse -and $pr.Seq -eq (($ps + 1) -band 0xFFFF))
    }
    $dirPath = {
        param([long]$Num)
        if ($Num -eq 5) { return '' }
        $stack = New-Object System.Collections.Generic.List[long]
        $cur = $Num; $prefix = $null
        while ($null -eq $prefix) {
            if ($cur -eq 5) { $prefix = ''; break }
            if ($dpath.ContainsKey($cur)) { $prefix = $dpath[$cur]; break }
            if (-not $dirs.ContainsKey($cur) -or -not $dirs[$cur].FN -or $stack.Count -gt 255 -or $stack.Contains($cur)) { $prefix = '\[Orphaned]'; break }
            $stack.Add($cur)
            if (-not (& $parentOk $dirs[$cur])) { $prefix = '\[Orphaned]'; break }
            $cur = $dirs[$cur].FN.Parent
        }
        $p = $prefix
        for ($j = $stack.Count - 1; $j -ge 0; $j--) { $p = $p + '\' + $dirs[$stack[$j]].FN.Name; $dpath[$stack[$j]] = $p }
        $p
    }
    # Pass 2: every base record, with its path, through the filter.
    & $walk {
        param($r)
        if ($r.Base -and $r.Base -ne $r.Number) { return }
        $b = if ($r.IsDir -and $dirs.ContainsKey($r.Number)) { $dirs[$r.Number] } else { & $merge $r; $r }
        if (-not $b.FN) { return }
        if ($Prefilter -and -not (& $Prefilter $b)) { return }
        $full = if ($b.Number -eq 5) { '' } elseif ($b.IsDir -and $dirs.ContainsKey($b.Number)) { & $dirPath $b.Number }
        elseif (& $parentOk $b) { (& $dirPath $b.FN.Parent) + '\' + $b.FN.Name } else { '\[Orphaned]\' + $b.FN.Name }
        # Inline FILETIME conversion (a function call per timestamp costs more than the parse itself).
        $si = @($null, $null, $null, $null); $fn = @($null, $null, $null, $null)
        for ($j = 0; $j -lt 4; $j++) {
            if ($b.SI) { $x = $b.SI[$j]; if ($x -gt 0 -and $x -lt 2650467743999999999L) { $si[$j] = [DateTime]::FromFileTimeUtc($x) } }
            $x = $b.FN.Times[$j]; if ($x -gt 0 -and $x -lt 2650467743999999999L) { $fn[$j] = [DateTime]::FromFileTimeUtc($x) }
        }
        $e = [pscustomobject]@{
            Number = $b.Number; Seq = $b.Seq; InUse = $b.InUse; IsDir = $b.IsDir; Name = $b.FN.Name; Path = $full; ParentNumber = $b.FN.Parent; Size = $b.Size
            SICreated = $si[0]; SIModified = $si[1]; SIChanged = $si[2]; SIAccessed = $si[3]
            FNCreated = $fn[0]; FNModified = $fn[1]; FNChanged = $fn[2]; FNAccessed = $fn[3]
            SITicks = @($b.SI); FNTicks = @($b.FN.Times); Ads = $(if ($b.Ads) { @($b.Ads) } else { @() }); Zone = $b.Zone; Torn = $b.Torn
        }
        if (-not $Where -or (& $Where $e)) { $e }
    }
}

function Test-WfxMftTimestomp {
    <#
    .SYNOPSIS Timestomp indicators for one parsed $MFT entry. Returns $null or { Score; Reasons }.
      * SI created earlier than FN created (by more than a second): the creation time was set back.
      * SI created and modified are whole seconds while FN has fractions: written by a tool, not by Windows.
    #>
    param($Entry)
    if (-not $Entry -or -not $Entry.SICreated -or -not $Entry.FNCreated) { return $null }
    $reasons = New-Object System.Collections.Generic.List[string]; $score = 0
    if (($Entry.FNCreated - $Entry.SICreated).TotalSeconds -gt 1) {
        $score += 2; $reasons.Add("created time in `$STANDARD_INFORMATION ($(ConvertTo-WfxUtcString $Entry.SICreated)) is earlier than in `$FILE_NAME ($(ConvertTo-WfxUtcString $Entry.FNCreated))")
    }
    $si = @($Entry.SITicks); $fn = @($Entry.FNTicks)
    if ($si.Count -ge 2 -and $fn.Count -ge 1 -and $si[0] -gt 0 -and ($si[0] % 10000000) -eq 0 -and ($si[1] % 10000000) -eq 0 -and ($fn[0] % 10000000) -ne 0) {
        $score += 1; $reasons.Add('created and modified times in $STANDARD_INFORMATION have no fraction of a second, unlike $FILE_NAME')
    }
    if (-not $score) { return $null }
    [pscustomobject]@{ Score = $score; Reasons = @($reasons) }
}


# ===== Private/Rules.ps1 =====
# Rule packs: JSON files in Rules/ (or embedded in the single-file build), plus optional
# custom packs from a folder (Set-WfxRulePath / $env:WFX_RULES). Regexes are compiled once, with a
# match timeout so a badly written (or malicious) community rule can never hang a triage. Every rule is
# validated when it is loaded; an invalid rule is skipped and recorded as a gap, never trusted.

# $PSScriptRoot is empty when this file is evaluated from a string (remote bootstrap) — guard it.
$script:WfxRuleRoot = if ($PSScriptRoot) { Join-Path (Split-Path -Parent $PSScriptRoot) 'Rules' } else { '' }
$script:WfxEmbeddedRules = @{}          # filled by the single-file build
$script:WfxRuleCache = @{}
$script:WfxRuleSources = New-Object System.Collections.Generic.List[string]
$script:WfxCustomRulePath = $env:WFX_RULES
$script:WfxRequiredPacks = @('lotl', 'events', 'ai', 'threats', 'dns')

function Set-WfxRulePath {
    <# Adds a folder of custom rule packs (files named <pack>.<anything>.json, e.g. lotl.mycompany.json). #>
    param([string]$Path)
    $script:WfxCustomRulePath = $Path
    $script:WfxRuleCache = @{}
}

function New-WfxRegex {
    param([string]$Pattern)
    if ([string]::IsNullOrEmpty($Pattern)) { return $null }
    return New-Object System.Text.RegularExpressions.Regex($Pattern, [System.Text.RegularExpressions.RegexOptions]::None, $script:WfxRegexTimeout)
}

function Test-WfxRegex {
    <# Regex match that treats a timeout as "no match" instead of throwing. #>
    param($Regex, [AllowEmptyString()][string]$Text)
    if ($null -eq $Regex -or [string]::IsNullOrEmpty($Text)) { return $false }
    try { return $Regex.IsMatch($Text) } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] { return $false }
}

function Read-WfxRuleJson {
    param([string]$Name)
    $docs = New-Object System.Collections.Generic.List[object]
    if ($script:WfxEmbeddedRules.ContainsKey($Name)) {
        $docs.Add(($script:WfxEmbeddedRules[$Name] | ConvertFrom-Json))
    } elseif ($script:WfxRuleRoot) {
        $file = Join-Path $script:WfxRuleRoot "$Name.json"
        if (Test-Path -LiteralPath $file) { $docs.Add((Get-Content -LiteralPath $file -Raw -Encoding UTF8 | ConvertFrom-Json)) }
    }
    if ($script:WfxCustomRulePath -and (Test-Path -LiteralPath $script:WfxCustomRulePath)) {
        foreach ($f in Get-ChildItem -LiteralPath $script:WfxCustomRulePath -Filter "$Name.*.json" -File) {
            try {
                $docs.Add((Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8 | ConvertFrom-Json))
                if (-not $script:WfxRuleSources.Contains($f.FullName)) { $script:WfxRuleSources.Add($f.FullName) }
            } catch { Add-WfxGap -Source "rules:$($f.Name)" -Reason "custom rule pack could not be parsed: $($_.Exception.Message)" }
        }
    }
    return , $docs.ToArray()
}

function Test-WfxRuleDefinition {
    <# Validates one rule object. Returns '' when valid, otherwise the reason it was rejected. #>
    param($Rule)
    $id = [string](Get-WfxValue $Rule 'id' '')
    if ($id -notmatch '^[A-Za-z0-9][A-Za-z0-9_.\-]{1,80}$') { return "invalid id '$id'" }
    if ([string](Get-WfxValue $Rule 'severity' 'Medium') -notin $script:WfxSeverities) { return "invalid severity" }
    if ([string](Get-WfxValue $Rule 'confidence' 'Medium') -notin @('Low', 'Medium', 'High')) { return "invalid confidence" }
    foreach ($t in @(Get-WfxValue $Rule 'technique' @())) { if ([string]$t -notmatch '^T\d{4}(?:\.\d{3})?$') { return "invalid ATT&CK technique '$t'" } }
    return ''
}

function Get-WfxRulePack {
    <#
    .SYNOPSIS Returns a rule pack as an object; list-like packs get compiled regexes attached.
    .DESCRIPTION Packs: lotl (command-line rules), events (event-log rules), ai (AI services/runtimes),
    threats (RMM, tunnels, offensive tools, named pipes, drivers), dns (TLDs and services).
    Throws a clear, actionable error if a built-in pack is missing (e.g. quarantined or deleted).
    #>
    param([Parameter(Mandatory)][string]$Name)
    if ($script:WfxRuleCache.ContainsKey($Name)) { return $script:WfxRuleCache[$Name] }
    $docs = Read-WfxRuleJson -Name $Name
    if ($docs.Count -eq 0) {
        throw "Rule pack '$Name' not found (expected $Name.json in '$script:WfxRuleRoot'). If antivirus quarantined it, restore it from the release archive; detections that depend on it are skipped."
    }
    $pack = $docs[0]
    if ($pack.PSObject.Properties['rules']) {
        $all = New-Object System.Collections.Generic.List[object]
        $ids = @{}
        foreach ($d in $docs) {
            foreach ($r in @($d.rules)) {
                $why = Test-WfxRuleDefinition $r
                if ($why) { Add-WfxGap -Source "rules:$Name" -Reason "rule rejected: $why"; continue }
                if ($ids.ContainsKey($r.id)) { continue }   # first definition wins
                try {
                    $r | Add-Member -NotePropertyName rx -NotePropertyValue (New-WfxRegex (Get-WfxValue $r 'pattern' '')) -Force
                    $ex = Get-WfxValue $r 'exclude'
                    $r | Add-Member -NotePropertyName rxExclude -NotePropertyValue (New-WfxRegex $ex) -Force
                    $imgs = @(Get-WfxValue $r 'images' @()) | ForEach-Object { ([string]$_).ToLowerInvariant() }
                    $r | Add-Member -NotePropertyName imageSet -NotePropertyValue @($imgs) -Force
                    $ids[$r.id] = $true
                    $all.Add($r)
                } catch {
                    Add-WfxGap -Source "rules:$Name" -Reason "rule $($r.id) has an invalid pattern: $($_.Exception.Message)"
                }
            }
        }
        $pack | Add-Member -NotePropertyName rules -NotePropertyValue $all.ToArray() -Force
    }
    $script:WfxRuleCache[$Name] = $pack
    return $pack
}

function Test-WfxRulePackSet {
    <# Checks that every built-in pack loads. Returns the names of packs that are missing/broken. #>
    $bad = foreach ($n in $script:WfxRequiredPacks) { try { $null = Get-WfxRulePack -Name $n } catch { $n } }
    $bad
}

function ConvertTo-WfxCanonicalCommand {
    <#
    .SYNOPSIS The command line as the shell will actually run it, for rule matching only (evidence keeps the original).
    .DESCRIPTION Undoes common, cheap obfuscation: en/em dashes and minus signs used as parameter prefixes (PowerShell
    accepts them), cmd caret escapes (p^o^w^e^r^s^h^e^l^l), empty-quote splitting (p""owershell), and "/switch"
    spellings of "-switch" for tools that accept both (certutil, regsvr32, msiexec ...).
    #>
    param([AllowEmptyString()][string]$CommandLine)
    if ([string]::IsNullOrEmpty($CommandLine)) { return $CommandLine }
    $c = $CommandLine -replace '[\u2013\u2014\u2015\u2212]', '-'
    $c = $c -replace '\^', ''
    $c = $c -replace '(?<=\w)""(?=\w)', ''
    $c = $c -replace '(?<=\s)/(?=[A-Za-z][\w:-]*)', '-'
    return $c
}

function Test-WfxCommandLine {
    <#
    .SYNOPSIS Runs the command-line rule pack against one command line. Returns matching rules.
    .PARAMETER Image  Executable name or path; restricts image-specific rules. Inferred from the command line if omitted.
    #>
    param([AllowEmptyString()][string]$CommandLine, [string]$Image = '')
    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return @() }
    if (-not $Image) { $Image = Get-WfxImagePath $CommandLine }
    $leaf = (Get-WfxLeaf $Image).ToLowerInvariant()
    if ($leaf -and $leaf -notmatch '\.') { $leaf += '.exe' }
    $pack = Get-WfxRulePack -Name 'lotl'
    # Match the text as written and as it will run (de-obfuscated); report each rule once.
    $texts = @($CommandLine)
    $canon = ConvertTo-WfxCanonicalCommand $CommandLine
    if ($canon -ne $CommandLine) { $texts += $canon }
    $seen = @{}
    foreach ($CommandLine in $texts) {
    foreach ($r in $pack.rules) {
        if ($seen.ContainsKey($r.id)) { continue }
        if ($r.imageSet.Count -gt 0 -and $r.imageSet -notcontains $leaf) {
            # Image-specific rule: still applies when the binary is invoked through cmd/powershell in the same line.
            $named = $false
            foreach ($i in $r.imageSet) { if (Test-WfxRxMatch ('(?i)(?:^|[\\/\s"''(;&|])' + [regex]::Escape(($i -replace '\.exe$', '')) + '(?:\.exe)?(?=[\s"'']|$)') $CommandLine) { $named = $true; break } }
            if (-not $named) { continue }
        }
        if (-not (Test-WfxRegex $r.rx $CommandLine)) { continue }
        if ($r.rxExclude -and (Test-WfxRegex $r.rxExclude $CommandLine)) { continue }
        $seen[$r.id] = $true
        $r
    }
    }
}


# ===== Private/Sigma.ps1 =====
# Sigma rule support: load community / in-house Sigma rules (YAML) and evaluate them against the Windows
# events the tool collects. Read-only and offline: rules are parsed as data, never executed.
#
# Supported: logsource product windows with the categories and services in $script:WfxSigmaSource;
# selections (maps, lists of maps, keyword lists); modifiers contains, startswith, endswith, all, re (with
# i / m / s), windash, cidr, base64offset, fieldref, exists, cased; conditions with and / or / not,
# parentheses, "1 of x*", "all of x*", "1 of them", "all of them".
# Not supported (the rule is skipped and listed as a gap): aggregations ("| count() by ...") and
# correlation rules. Events are matched only if the tool collected them (see $script:WfxEventQuery).

# Which collected events each Sigma logsource maps to, and how 4688 fields map to Sigma (Sysmon) names.
$script:WfxSigmaSource = @{
    'category:process_creation'     = @{ Logs = @('Microsoft-Windows-Sysmon/Operational', 'Security'); Ids = @(1, 4688) }
    'category:network_connection'   = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(3) }
    'category:image_load'           = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(7) }
    'category:create_remote_thread' = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(8) }
    'category:process_access'       = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(10) }
    'category:file_event'           = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(11) }
    'category:registry_add'         = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(12) }
    'category:registry_delete'      = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(12) }
    'category:registry_set'         = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(13) }
    'category:registry_event'       = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(12, 13, 14) }
    'category:dns_query'            = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(22) }
    'category:file_delete'          = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @(23, 26) }
    'category:ps_script'            = @{ Logs = @('Microsoft-Windows-PowerShell/Operational'); Ids = @(4104) }
    'service:security'              = @{ Logs = @('Security'); Ids = @() }
    'service:system'                = @{ Logs = @('System'); Ids = @() }
    'service:sysmon'                = @{ Logs = @('Microsoft-Windows-Sysmon/Operational'); Ids = @() }
    'service:windefend'             = @{ Logs = @('Microsoft-Windows-Windows Defender/Operational'); Ids = @() }
    'service:powershell'            = @{ Logs = @('Microsoft-Windows-PowerShell/Operational'); Ids = @() }
    'service:taskscheduler'         = @{ Logs = @('Microsoft-Windows-TaskScheduler/Operational'); Ids = @() }
    'service:terminalservices-localsessionmanager' = @{ Logs = @('Microsoft-Windows-TerminalServices-LocalSessionManager/Operational'); Ids = @() }
}
$script:WfxSigma4688Map = @{ Image = 'NewProcessName'; ParentImage = 'ParentProcessName'; User = 'SubjectUserName'; ProcessId = 'NewProcessId'; ParentProcessId = 'ProcessId'; IntegrityLevel = 'MandatoryLabel' }

# ───────────────────────────── minimal YAML (the subset Sigma uses) ─────────────────────────────
function ConvertFrom-WfxYaml {
    <# Parses one YAML document (block maps, block lists, flow lists, quoted / block scalars) into
       ordered dictionaries, arrays and strings. Not a general YAML parser: anchors, tags and complex
       keys are not supported. #>
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Text)
    $lines = New-Object System.Collections.Generic.List[object]
    $raw = $Text -split "`r?`n"
    for ($i = 0; $i -lt $raw.Count; $i++) {
        $l = $raw[$i]
        if ($l -match '^\s*(#.*)?$') { continue }
        $ind = $l.Length - $l.TrimStart(' ').Length
        $lines.Add([pscustomobject]@{ I = $ind; T = (Remove-WfxYamlComment $l.Trim()); N = $i; Raw = $l })
    }
    $script:WfxYamlRaw = $raw
    $pos = [ref]0
    if (-not $lines.Count) { return $null }
    ConvertFrom-WfxYamlBlock $lines $pos $lines[0].I
}

function Remove-WfxYamlComment {
    param([string]$S)
    $q = $null
    for ($i = 0; $i -lt $S.Length; $i++) {
        $c = $S[$i]
        if ($q) { if ($c -eq $q) { $q = $null } ; continue }
        if ($c -eq "'" -or $c -eq '"') { if ($i -eq 0 -or $S[$i - 1] -match '[\s:\[,{-]') { $q = $c } ; continue }
        if ($c -eq '#' -and ($i -eq 0 -or $S[$i - 1] -eq ' ')) { return $S.Substring(0, $i).TrimEnd() }
    }
    $S
}

function ConvertFrom-WfxYamlScalar {
    param([string]$V)
    $v = $V.Trim()
    if ($v -eq '' -or $v -eq '~' -or $v -eq 'null') { return $null }
    if ($v.StartsWith("'") -and $v.EndsWith("'") -and $v.Length -ge 2) { return $v.Substring(1, $v.Length - 2).Replace("''", "'") }
    if ($v.StartsWith('"') -and $v.EndsWith('"') -and $v.Length -ge 2) { return ($v.Substring(1, $v.Length - 2) -replace '\\"', '"' -replace '\\\\', '\') }
    if ($v.StartsWith('[') -and $v.EndsWith(']')) {
        $inner = $v.Substring(1, $v.Length - 2); $items = @(); $cur = ''; $q = $null
        foreach ($c in $inner.ToCharArray()) {
            if ($q) { $cur += $c; if ($c -eq $q) { $q = $null }; continue }
            if ($c -eq "'" -or $c -eq '"') { $q = $c; $cur += $c; continue }
            if ($c -eq ',') { $items += , (ConvertFrom-WfxYamlScalar $cur); $cur = ''; continue }
            $cur += $c
        }
        if ($cur.Trim()) { $items += , (ConvertFrom-WfxYamlScalar $cur) }
        return , $items
    }
    $v
}

function ConvertFrom-WfxYamlBlock {
    param($Lines, [ref]$Pos, [int]$Indent)
    if ($Pos.Value -ge $Lines.Count) { return $null }
    $first = $Lines[$Pos.Value]
    if ($first.T.StartsWith('- ') -or $first.T -eq '-') {
        $list = New-Object System.Collections.Generic.List[object]
        while ($Pos.Value -lt $Lines.Count) {
            $ln = $Lines[$Pos.Value]
            if ($ln.I -lt $Indent -or -not ($ln.T.StartsWith('- ') -or $ln.T -eq '-')) { break }
            if ($ln.I -gt $Indent) { $Pos.Value++; continue }
            $rest = if ($ln.T -eq '-') { '' } else { $ln.T.Substring(2).Trim() }
            if ($rest -eq '') {
                $Pos.Value++
                if ($Pos.Value -lt $Lines.Count -and $Lines[$Pos.Value].I -gt $Indent) { $list.Add((ConvertFrom-WfxYamlBlock $Lines $Pos $Lines[$Pos.Value].I)) } else { $list.Add($null) }
            } elseif ($rest -match '^([^''"\s][^:]*?|''[^'']*''|"[^"]*"):(\s|$)') {
                # "- key: value" starts a map item; its other keys are indented under the first key.
                $childIndent = $ln.I + 2
                $Lines[$Pos.Value] = [pscustomobject]@{ I = $childIndent; T = $rest; N = $ln.N; Raw = $ln.Raw }
                $list.Add((ConvertFrom-WfxYamlBlock $Lines $Pos $childIndent))
            } else { $list.Add((ConvertFrom-WfxYamlScalar $rest)); $Pos.Value++ }
        }
        return , $list.ToArray()
    }
    $map = [ordered]@{}
    while ($Pos.Value -lt $Lines.Count) {
        $ln = $Lines[$Pos.Value]
        if ($ln.I -lt $Indent) { break }
        if ($ln.I -gt $Indent) { $Pos.Value++; continue }
        $m = [regex]::Match($ln.T, '^(''[^'']*''|"[^"]*"|[^:]+?)\s*:(?:\s+(.*))?$')
        if (-not $m.Success) { $Pos.Value++; continue }
        $key = ConvertFrom-WfxYamlScalar $m.Groups[1].Value
        $val = $m.Groups[2].Value
        $Pos.Value++
        if ($val -match '^[|>][+-]?$') {
            $buf = New-Object System.Collections.Generic.List[string]; $bi = -1
            while ($Pos.Value -lt $Lines.Count -and $Lines[$Pos.Value].I -gt $Indent) {
                $r = $Lines[$Pos.Value].Raw; if ($bi -lt 0) { $bi = $Lines[$Pos.Value].I }
                $buf.Add($(if ($r.Length -ge $bi) { $r.Substring($bi) } else { $r.Trim() })); $Pos.Value++
            }
            $map[$key] = if ($val.StartsWith('>')) { ($buf -join ' ') } else { ($buf -join "`n") }
        } elseif ($val -eq '') {
            if ($Pos.Value -lt $Lines.Count -and ($Lines[$Pos.Value].I -gt $Indent -or ($Lines[$Pos.Value].I -eq $Indent -and $Lines[$Pos.Value].T.StartsWith('-')))) {
                $map[$key] = ConvertFrom-WfxYamlBlock $Lines $Pos $Lines[$Pos.Value].I
            } else { $map[$key] = $null }
        } else { $map[$key] = ConvertFrom-WfxYamlScalar $val }
    }
    $map
}

# ───────────────────────────── loading rules ─────────────────────────────
function Import-WfxSigmaRule {
    <#
    .SYNOPSIS Loads Sigma rules (*.yml / *.yaml) from a folder or file and compiles the ones that can run on
    collected Windows events. Returns compiled rules; unsupported or broken rules are recorded as one gap.
    #>
    param([Parameter(Mandatory)][string[]]$Path, [int]$Max = 5000)
    $files = foreach ($p in $Path) {
        if (Test-Path -LiteralPath $p -PathType Container) { Get-ChildItem -LiteralPath $p -Recurse -File -Include *.yml, *.yaml -ErrorAction SilentlyContinue }
        elseif (Test-Path -LiteralPath $p) { Get-Item -LiteralPath $p }
    }
    $out = New-Object System.Collections.Generic.List[object]; $skipped = @{}
    foreach ($f in @($files | Select-Object -First $Max)) {
        $text = try { [IO.File]::ReadAllText($f.FullName) } catch { ''; continue }
        foreach ($doc in ($text -split '(?m)^---\s*$')) {
            if (-not $doc.Trim()) { continue }
            try { $y = ConvertFrom-WfxYaml $doc } catch { $skipped['parse error'] = 1 + [int]$skipped['parse error']; continue }
            if (-not ($y -is [System.Collections.IDictionary]) -or -not $y['detection']) { continue }
            $r = ConvertTo-WfxSigmaRule $y $f.FullName
            if ($r -is [string]) { $skipped[$r] = 1 + [int]$skipped[$r] } elseif ($r) { $out.Add($r) }
        }
    }
    if ($skipped.Count) {
        Add-WfxGap -Source 'sigma' -Reason ("{0} rule(s) loaded; skipped: {1}." -f $out.Count, ((@($skipped.GetEnumerator() | Sort-Object Value -Descending | ForEach-Object { "$($_.Value) $($_.Key)" })) -join ', ')) -Fix 'Skipped rules need data or features this tool does not collect (other products, aggregations).'
    }
    , $out.ToArray()
}

function ConvertTo-WfxSigmaRule {
    # Compiles one parsed Sigma document. Returns the rule, or a short reason string when it cannot run.
    param($Y, [string]$File)
    $ls = $Y['logsource']; if (-not $ls) { return 'no logsource' }
    if ($ls['product'] -and [string]$ls['product'] -ne 'windows') { return 'not Windows' }
    $src = if ($ls['category']) { $script:WfxSigmaSource["category:$($ls['category'])"] } elseif ($ls['service']) { $script:WfxSigmaSource["service:$($ls['service'])"] } else { $null }
    if (-not $src) { return "logsource not collected ($(if ($ls['category']) { $ls['category'] } else { $ls['service'] }))" }
    if ($Y['status'] -in 'deprecated', 'unsupported') { return 'deprecated' }
    $det = $Y['detection']
    $cond = $det['condition']; if ($cond -is [array]) { $cond = '(' + ((@($cond) | ForEach-Object { "($_)" }) -join ' or ') + ')' }
    $cond = [string]$cond
    if (-not $cond -or $cond -match '\|') { return 'aggregation / correlation' }
    $sel = [ordered]@{}
    foreach ($k in $det.Keys) {
        if ($k -in 'condition', 'timeframe') { continue }
        $c = ConvertTo-WfxSigmaSelection $det[$k]
        if ($c -is [string]) { return $c }
        $sel[$k] = $c
    }
    $tree = try { ConvertTo-WfxSigmaCondition $cond @($sel.Keys) } catch { return 'condition syntax' }
    $level = switch ([string]$Y['level']) { 'critical' { 'Critical' } 'high' { 'High' } 'medium' { 'Medium' } 'low' { 'Low' } default { 'Info' } }
    $tech = @(@($Y['tags']) | ForEach-Object { [string]$_ } | Where-Object { $_ -match '^attack\.t\d{4}(?:\.\d{3})?$' } | ForEach-Object { $_.Substring(7).ToUpperInvariant() })
    $pre = Get-WfxSigmaPrefilter $sel $tree
    [pscustomobject]@{
        Pre = $pre
        Id = [string]$Y['id']; Title = [string]$Y['title']; Description = [string]$Y['description']; Level = $level; Technique = $tech
        Author = [string]$Y['author']; FalsePositives = @(@($Y['falsepositives']) | Where-Object { $_ } | ForEach-Object { [string]$_ })
        References = @(@($Y['references']) | Select-Object -First 3 | ForEach-Object { [string]$_ })
        Logs = $src.Logs; Ids = $src.Ids; Category = [string]$ls['category']; File = $File; Selections = $sel; Tree = $tree
    }
}

function Get-WfxSigmaPrefilter {
    <#
    Builds one regex of literal fragments such that an event can only match the rule if its text contains at
    least one of them, so most rules are skipped with a single regex test. Derived from the condition:
    AND keeps the stronger side, OR / "1 of" unions both sides, NOT gives no constraint. Returns $null when no
    sound filter exists (regex / null / exists / field-reference / CIDR tests, or purely negative logic).
    #>
    param($Sel, $Tree)
    # A literal set is $null (no constraint) or a string array. Stronger = longer shortest literal, then fewer.
    $better = { param($a, $b) if ($null -eq $a) { return $b }; if ($null -eq $b) { return $a }
        $ma = ($a | Measure-Object Length -Minimum).Minimum; $mb = ($b | Measure-Object Length -Minimum).Minimum
        if ($ma -ne $mb) { if ($ma -gt $mb) { return $a } else { return $b } }; if ($a.Count -le $b.Count) { $a } else { $b } }
    $union = { param($a, $b) if ($null -eq $a -or $null -eq $b) { return $null }; , @(@($a) + @($b) | Select-Object -Unique) }
    $testLits = { param($tt)
        if ($null -ne $tt.Exists -or 'fieldref' -in $tt.Mods -or 'cidr' -in $tt.Mods -or 're' -in $tt.Mods -or $tt.Field -in 'EventID', 'Provider_Name', 'Channel') { return $null }
        $l = @(foreach ($v in $tt.Values) {
                if ($null -eq $v) { return $null }
                $chunks = @(([string]$v -replace '\\([*?])', '$1') -split '[*?]' | ForEach-Object { $_.TrimStart('-', '/') } | Where-Object { $_.Length -ge 2 })
                if (-not $chunks.Count) { return $null }
                ([string]@($chunks | Sort-Object Length -Descending)[0]).ToLowerInvariant()
            })
        if ($tt.All) { return , @($l | Sort-Object Length -Descending | Select-Object -First 1) }
        , $l
    }
    $selLits = { param($name)
        $acc = @(); $first = $true
        foreach ($tests in $Sel[$name]) {
            $g = $null; foreach ($tt in $tests) { $g = & $better $g (& $testLits $tt) }
            if ($null -eq $g) { return $null }
            $acc = if ($first) { $g } else { & $union $acc $g }; $first = $false
        }
        , $acc
    }
    $walk = $null
    $walk = { param($n)
        switch ($n.Op) {
            'sel' { return (& $selLits $n.Name) }
            'not' { return $null }
            'and' { return (& $better (& $walk $n.A) (& $walk $n.B)) }
            'or' { return (& $union (& $walk $n.A) (& $walk $n.B)) }
            'of' {
                $acc = $null; $first = $true
                foreach ($s in $n.Sel) { $x = & $selLits $s; if ($n.Q -eq 'all') { $acc = & $better $acc $x } else { $acc = if ($first) { $x } else { & $union $acc $x } }; $first = $false; if ($n.Q -ne 'all' -and $null -eq $acc) { return $null } }
                return $acc
            }
        }
        $null
    }
    $lits = & $walk $Tree
    if ($null -eq $lits -or -not @($lits).Count) { return $null }
    Get-WfxRx ('(?:' + ((@($lits) | ForEach-Object { [regex]::Escape($_) }) -join '|') + ')') ([Text.RegularExpressions.RegexOptions]'IgnoreCase, CultureInvariant, Compiled')
}

function ConvertTo-WfxSigmaSelection {
    # Selection → list of alternative "AND-groups"; each group is a list of field tests. Keyword lists become
    # a single 'keywords' test.
    param($S)
    $items = if ($S -is [System.Collections.IDictionary]) { , @($S) } else { @($S) }
    if (-not @($items | Where-Object { $_ -is [System.Collections.IDictionary] }).Count) {
        return , @(, @([pscustomobject]@{ Field = '*'; Mods = @('contains'); Values = @($items | ForEach-Object { [string]$_ }); All = $false; Exists = $null }))
    }
    $alts = New-Object System.Collections.Generic.List[object]
    foreach ($m in $items) {
        if ($m -isnot [System.Collections.IDictionary]) { return 'mixed selection' }
        $tests = New-Object System.Collections.Generic.List[object]
        foreach ($k in $m.Keys) {
            $parts = ([string]$k) -split '\|'; $field = $parts[0]; $mods = @($parts | Select-Object -Skip 1)
            foreach ($md in $mods) { if ($md -notin 'contains', 'startswith', 'endswith', 'all', 're', 'i', 'm', 's', 'windash', 'cidr', 'base64offset', 'base64', 'fieldref', 'exists', 'cased') { return "modifier $md" } }
            [object[]]$vals = @($m[$k])                      # @($null) is a one-element array: "field: null"
            if ($null -eq $m[$k]) { $vals = [object[]]@($null) }
            if ('base64offset' -in $mods -or 'base64' -in $mods) {
                $vals = [object[]]@(foreach ($v in $vals) { ConvertTo-WfxBase64Variant -Value ([string]$v) -Offsets:('base64offset' -in $mods) })
                $mods = @($mods | Where-Object { $_ -notin 'base64offset', 'base64' }); if ('contains' -notin $mods) { $mods += 'contains' }
            }
            $exists = if ('exists' -in $mods) { [string]$vals[0] -match '^(?i)true$' } else { $null }
            $rx = $null
            if ($null -eq $exists -and 'fieldref' -notin $mods -and 'cidr' -notin $mods) { $rx = New-Object object[] $vals.Count; for ($q = 0; $q -lt $vals.Count; $q++) { $rx[$q] = New-WfxSigmaRegex $vals[$q] $mods } }
            # Any-of tests whose values are all plain patterns collapse into one regex: one match call per test.
            $any = $null
            if ($rx -and 'all' -notin $mods -and $vals -notcontains $null -and @($rx | Where-Object { $null -eq $_ }).Count -eq 0) {
                $o = $rx[0].Options; if (@($rx | Where-Object { $_.Options -ne $o }).Count -eq 0) { $any = Get-WfxRx ('(?:' + ((@($rx) | ForEach-Object { $_.ToString() }) -join ')|(?:') + ')') ($o -bor [Text.RegularExpressions.RegexOptions]::CultureInvariant) }
            }
            $tests.Add([pscustomobject]@{ Field = $field; Mods = $mods; Values = $vals; All = ('all' -in $mods); Exists = $exists; Rx = $rx; Any = $any })
        }
        $alts.Add($tests.ToArray())
    }
    , $alts.ToArray()
}

function ConvertTo-WfxBase64Variant {
    # The base64 forms of a string at byte offsets 0/1/2, without the unstable edge characters (Sigma base64offset).
    param([string]$Value, [switch]$Offsets)
    $b = [Text.Encoding]::UTF8.GetBytes($Value)
    if (-not $Offsets) { return [Convert]::ToBase64String($b).TrimEnd('=') }
    $start = @(0, 2, 3); $endCut = @(0, 3, 2)
    for ($i = 0; $i -lt 3; $i++) {
        $pad = New-Object byte[] ($i + $b.Length); [Array]::Copy($b, 0, $pad, $i, $b.Length)
        $e = [Convert]::ToBase64String($pad)
        $cutEnd = $endCut[($b.Length + $i) % 3]
        $s = $e.Substring($start[$i]); if ($cutEnd) { $s = $s.Substring(0, [Math]::Max(0, $s.Length - $cutEnd)) }
        $s.TrimEnd('=')
    }
}

function ConvertTo-WfxSigmaCondition {
    # Parses a Sigma condition into a small tree: @{Op='and'|'or'|'not'|'sel'|'of'; ...}.
    param([string]$Text, [string[]]$Names)
    $tokens = @([regex]::Matches($Text, '\(|\)|[^\s()]+') | ForEach-Object Value)
    $i = [ref]0
    $parseOr = $null; $parseAnd = $null; $parseNot = $null; $parseAtom = $null
    $parseAtom = {
        if ($i.Value -ge $tokens.Count) { throw 'unexpected end' }
        $t = $tokens[$i.Value]
        if ($t -eq '(') { $i.Value++; $n = & $parseOr; if ($tokens[$i.Value] -ne ')') { throw 'missing )' }; $i.Value++; return $n }
        if ($t -match '^(?:1|all|any)$' -and $i.Value + 2 -lt $tokens.Count + 1 -and $tokens[$i.Value + 1] -eq 'of') {
            $q = if ($t -eq 'all') { 'all' } else { 'any' }; $pat = $tokens[$i.Value + 2]; $i.Value += 3
            $sel = if ($pat -eq 'them') { @($Names | Where-Object { $_ -notlike '_*' }) } else { @($Names | Where-Object { $_ -like $pat }) }
            return @{ Op = 'of'; Q = $q; Sel = $sel }
        }
        if ($Names -notcontains $t) { throw "unknown selection $t" }
        $i.Value++; return @{ Op = 'sel'; Name = $t }
    }
    $parseNot = { if ($tokens[$i.Value] -eq 'not') { $i.Value++; return @{ Op = 'not'; A = (& $parseNot) } }; & $parseAtom }
    $parseAnd = { $l = & $parseNot; while ($i.Value -lt $tokens.Count -and $tokens[$i.Value] -eq 'and') { $i.Value++; $l = @{ Op = 'and'; A = $l; B = (& $parseNot) } }; $l }
    $parseOr = { $l = & $parseAnd; while ($i.Value -lt $tokens.Count -and $tokens[$i.Value] -eq 'or') { $i.Value++; $l = @{ Op = 'or'; A = $l; B = (& $parseAnd) } }; $l }
    $tree = & $parseOr
    if ($i.Value -ne $tokens.Count) { throw 'trailing tokens' }
    $tree
}

# ───────────────────────────── evaluation ─────────────────────────────
function Get-WfxSigmaField {
    param($Event, [hashtable]$Fields, [string]$Name)
    switch ($Name) {
        'EventID' { return [string]$Event.Id }
        'Provider_Name' { return [string]$Event.Provider }
        'Channel' { return [string]$Event.Log }
        'Computer' { return [string]$Event.Computer }
    }
    if ($Fields.ContainsKey($Name)) { return [string]$Fields[$Name] }
    if ($Event.Id -eq 4688 -and $script:WfxSigma4688Map[$Name] -and $Fields.ContainsKey($script:WfxSigma4688Map[$Name])) { return [string]$Fields[$script:WfxSigma4688Map[$Name]] }
    if ($Name -eq 'ParentCommandLine' -or $Name -eq 'OriginalFileName') { return $null }
    $null
}

function New-WfxSigmaRegex {
    # One compiled regex per Sigma value (all variants joined), built when the rule is loaded.
    param($Want, [string[]]$Mods)
    if ($null -eq $Want) { return $null }
    $w = [string]$Want
    if ('re' -in $Mods) {
        $o = [Text.RegularExpressions.RegexOptions]::None
        if ('i' -in $Mods) { $o = $o -bor [Text.RegularExpressions.RegexOptions]::IgnoreCase }
        if ('m' -in $Mods) { $o = $o -bor [Text.RegularExpressions.RegexOptions]::Multiline }
        if ('s' -in $Mods) { $o = $o -bor [Text.RegularExpressions.RegexOptions]::Singleline }
        try { return (Get-WfxRx $w $o) } catch { return (Get-WfxRx '(?!)') }
    }
    $variants = @($w)
    if ('windash' -in $Mods) { $variants = @(foreach ($d in '-', '/', [string][char]0x2013, [string][char]0x2014, [string][char]0x2015) { $w -replace '(?<=^|\s)-', $d }) | Select-Object -Unique }
    $alts = foreach ($v in $variants) {
        $rx = ''; for ($k = 0; $k -lt $v.Length; $k++) {
            $c = $v[$k]
            if ($c -eq '\' -and $k + 1 -lt $v.Length -and $v[$k + 1] -in '*', '?', '\') { $rx += [regex]::Escape([string]$v[$k + 1]); $k++ }
            elseif ($c -eq '*') { $rx += '.*' } elseif ($c -eq '?') { $rx += '.' } else { $rx += [regex]::Escape([string]$c) }
        }
        $rx
    }
    $body = '(?:' + ($alts -join '|') + ')'
    $rx = if ('contains' -in $Mods) { $body } elseif ('startswith' -in $Mods) { "^$body" } elseif ('endswith' -in $Mods) { "$body`$" } else { "^$body`$" }
    $opt = if ('cased' -in $Mods) { [Text.RegularExpressions.RegexOptions]::Singleline } else { [Text.RegularExpressions.RegexOptions]'IgnoreCase, Singleline' }
    Get-WfxRx $rx $opt
}

function Test-WfxSigmaValue {
    param([AllowNull()][string]$Have, $Want, [string[]]$Mods, [hashtable]$Fields, $Rx = $null)
    if ($null -eq $Want) { return [string]::IsNullOrEmpty($Have) }
    if ($null -eq $Have) { return $false }
    if ($Rx) { try { return $Rx.IsMatch($Have) } catch { return $false } }
    $w = [string]$Want
    if ('fieldref' -in $Mods) { $w = [string]$Fields[$w] }
    $cs = 'cased' -in $Mods
    if ('re' -in $Mods) {
        $o = [Text.RegularExpressions.RegexOptions]::None
        if ('i' -in $Mods) { $o = $o -bor [Text.RegularExpressions.RegexOptions]::IgnoreCase }
        if ('m' -in $Mods) { $o = $o -bor [Text.RegularExpressions.RegexOptions]::Multiline }
        if ('s' -in $Mods) { $o = $o -bor [Text.RegularExpressions.RegexOptions]::Singleline }
        try { return (Get-WfxRx $w $o).IsMatch($Have) } catch { return $false }
    }
    if ('cidr' -in $Mods) { return (Test-WfxCidr -Address $Have -Cidr $w) }
    $variants = @($w)
    if ('windash' -in $Mods) { $variants = @(foreach ($d in '-', '/', [string][char]0x2013, [string][char]0x2014, [string][char]0x2015) { $w -replace '(?<=^|\s)-', $d }) | Select-Object -Unique }
    foreach ($v in $variants) {
        # Sigma wildcards: * and ? (escaped with backslash). Build a regex once per value.
        $rx = ''; for ($k = 0; $k -lt $v.Length; $k++) {
            $c = $v[$k]
            if ($c -eq '\' -and $k + 1 -lt $v.Length -and $v[$k + 1] -in '*', '?', '\') { $rx += [regex]::Escape([string]$v[$k + 1]); $k++ }
            elseif ($c -eq '*') { $rx += '.*' } elseif ($c -eq '?') { $rx += '.' } else { $rx += [regex]::Escape([string]$c) }
        }
        if ('contains' -in $Mods) { $rx = ".*$rx.*" } elseif ('startswith' -in $Mods) { $rx = "$rx.*" } elseif ('endswith' -in $Mods) { $rx = ".*$rx" }
        $opt = if ($cs) { [Text.RegularExpressions.RegexOptions]::Singleline } else { [Text.RegularExpressions.RegexOptions]'IgnoreCase, Singleline' }
        if ((Get-WfxRx "^(?:$rx)$" $opt).IsMatch($Have)) { return $true }
    }
    $false
}

function Test-WfxCidr {
    param([string]$Address, [string]$Cidr)
    $p = $Cidr -split '/'; $ip = $null; $net = $null
    if (-not [Net.IPAddress]::TryParse($Address.Trim('[', ']'), [ref]$ip) -or -not [Net.IPAddress]::TryParse($p[0], [ref]$net)) { return $false }
    $a = $ip.GetAddressBytes(); $n = $net.GetAddressBytes(); if ($a.Length -ne $n.Length) { return $false }
    $bits = if ($p.Count -gt 1) { [int]$p[1] } else { $a.Length * 8 }
    for ($k = 0; $k -lt $a.Length; $k++) {
        $take = [Math]::Max(0, [Math]::Min(8, $bits - 8 * $k)); if ($take -eq 0) { break }
        $mask = (0xFF -shl (8 - $take)) -band 0xFF
        if (($a[$k] -band $mask) -ne ($n[$k] -band $mask)) { return $false }
    }
    $true
}

function Test-WfxSigmaSelection {
    param($Alts, $Event, [hashtable]$Fields)
    foreach ($tests in $Alts) {
        $ok = $true
        foreach ($t in $tests) {
            if ($t.Field -eq '*') {
                $hay = ([string]$Event.Message) + "`n" + ((@($Fields.Values) | ForEach-Object { [string]$_ }) -join "`n")
                $ok = [bool]@($t.Values | Where-Object { $hay.IndexOf([string]$_, [StringComparison]::OrdinalIgnoreCase) -ge 0 }).Count
            } else {
                $have = Get-WfxSigmaField $Event $Fields $t.Field
                if ($t.Any) { $ok = ($null -ne $have) -and $t.Any.IsMatch($have) }
                elseif ($null -ne $t.Exists) { $ok = ($t.Exists -eq ($null -ne $have)) }
                elseif ($t.All) { for ($k = 0; $k -lt $t.Values.Count; $k++) { if (-not (Test-WfxSigmaValue $have $t.Values[$k] $t.Mods $Fields $(if ($t.Rx) { $t.Rx[$k] }))) { $ok = $false; break } } }
                else { $ok = $false; for ($k = 0; $k -lt $t.Values.Count; $k++) { if (Test-WfxSigmaValue $have $t.Values[$k] $t.Mods $Fields $(if ($t.Rx) { $t.Rx[$k] })) { $ok = $true; break } } }
            }
            if (-not $ok) { break }
        }
        if ($ok) { return $true }
    }
    $false
}

function Test-WfxSigmaTree {
    param($Node, $Rule, $Event, [hashtable]$Fields, [hashtable]$Memo)
    switch ($Node.Op) {
        'sel' { if (-not $Memo.ContainsKey($Node.Name)) { $Memo[$Node.Name] = Test-WfxSigmaSelection $Rule.Selections[$Node.Name] $Event $Fields }; return $Memo[$Node.Name] }
        'not' { return -not (Test-WfxSigmaTree $Node.A $Rule $Event $Fields $Memo) }
        'and' { return ((Test-WfxSigmaTree $Node.A $Rule $Event $Fields $Memo) -and (Test-WfxSigmaTree $Node.B $Rule $Event $Fields $Memo)) }
        'or' { return ((Test-WfxSigmaTree $Node.A $Rule $Event $Fields $Memo) -or (Test-WfxSigmaTree $Node.B $Rule $Event $Fields $Memo)) }
        'of' {
            foreach ($s in $Node.Sel) {
                $r = Test-WfxSigmaTree @{ Op = 'sel'; Name = $s } $Rule $Event $Fields $Memo
                if ($Node.Q -eq 'any' -and $r) { return $true }
                if ($Node.Q -eq 'all' -and -not $r) { return $false }
            }
            return ($Node.Q -eq 'all' -and @($Node.Sel).Count -gt 0)
        }
    }
    $false
}

function Invoke-WfxSigmaAnalyzer {
    <# Runs compiled Sigma rules over collected events. At most -MaxPerRule findings per rule. #>
    param([object[]]$Event, [object[]]$Rule, [string]$HostName = '', [int]$MaxPerRule = 25)
    $findings = New-Object System.Collections.Generic.List[object]
    $events = @($Event | Where-Object { $_ })
    if (-not $events.Count -or -not @($Rule).Count) { return , $findings.ToArray() }
    # Prepare each event once: field table, searchable text, and a signature so identical events
    # (the same command line run 500 times) are evaluated once per rule.
    $prep = foreach ($e in $events) {
        $f = @{}; $fl = $e.Fields
        if ($fl -is [System.Collections.IDictionary]) { foreach ($k in $fl.Keys) { $f[$k] = $fl[$k] } } elseif ($fl) { foreach ($p in $fl.PSObject.Properties) { $f[$p.Name] = $p.Value } }
        $vals = @($f.Keys | Sort-Object | Where-Object { $_ -notmatch '(?i)ProcessId$|ProcessGuid$|^UtcTime$|^RecordId$|LogonId$|^SequenceNumber$|^EventRecordID$|^TimeCreated$' } | ForEach-Object { "$_=$($f[$_])" })
        [pscustomobject]@{ E = $e; F = $f; Text = (([string]$e.Message) + "`n" + (($f.Values | ForEach-Object { [string]$_ }) -join "`n")); Sig = "$($e.Log)|$($e.Id)|$($vals -join '|')"; Log = [string]$e.Log; Id = [int]$e.Id }
    }
    $uniq = [ordered]@{}
    foreach ($pe in $prep) { if ($uniq.Contains($pe.Sig)) { $uniq[$pe.Sig].N++ } else { $pe | Add-Member -NotePropertyName N -NotePropertyValue 1; $uniq[$pe.Sig] = $pe } }
    $byLog = @{}; foreach ($pe in $uniq.Values) { if (-not $byLog.ContainsKey($pe.Log)) { $byLog[$pe.Log] = New-Object System.Collections.Generic.List[object] }; $byLog[$pe.Log].Add($pe) }
    foreach ($r in $Rule) {
        $hits = 0
        $cands = foreach ($lg in $r.Logs) { if ($byLog[$lg]) { $byLog[$lg] } }
        foreach ($pe in $cands) {
            if ($r.Ids.Count -and $r.Ids -notcontains $pe.Id) { continue }
            if ($r.Pre -and -not $r.Pre.IsMatch($pe.Text)) { continue }
            if (-not (Test-WfxSigmaTree $r.Tree $r $pe.E $pe.F @{})) { continue }
            $e = $pe.E; $f = $pe.F
            $hits++
            $what = @('CommandLine', 'ScriptBlockText', 'TargetObject', 'TargetFilename', 'QueryName', 'ImageLoaded', 'DestinationIp', 'ServiceName', 'TargetUserName') | Where-Object { $f[$_] } | Select-Object -First 1
            $img = [string](Get-WfxSigmaField $e $f 'Image')
            $ev = [ordered]@{ Event = "$($e.Log) $($e.Id) record $($e.RecordId)"; Time = $e.TimeCreated; Image = $img; SameEvents = $pe.N }
            if ($what) { $ev[$what] = Get-WfxShortText ([string]$f[$what]) 600 }
            $ev['Rule'] = "$($r.Title) [$($r.Id)]"; $ev['RuleFile'] = (Split-Path -Leaf $r.File)
            $findings.Add((New-WfxFinding -Id ('SIGMA-' + $(if ($r.Id) { $r.Id.Substring(0, [Math]::Min(8, $r.Id.Length)) } else { 'RULE' })) -Title "Sigma: $($r.Title)" -Severity $r.Level -Confidence 'Medium' -Category 'Sigma' `
                        -Technique $r.Technique -Description ("{0}{1}" -f $r.Description, $(if ($r.Author) { " (Sigma rule by $($r.Author).)" })) `
                        -Recommendation $(if ($r.FalsePositives.Count) { "Known false positives: $($r.FalsePositives -join '; '). Check the event against these before acting." } else { 'Review the event in context.' }) `
                        -Entity ("sigma:{0}:{1}" -f $r.Id, $(if ($img) { $img.ToLowerInvariant() } else { $e.RecordId })) -HostName $HostName -Time $e.TimeCreated -Source "sigma:$(Split-Path -Leaf $r.File)" -Evidence $ev))
            if ($hits -ge $MaxPerRule) { break }
        }
    }
    , $findings.ToArray()
}

function Get-WfxSigmaRuleSet {
    <# Loads (once per session and path list) the Sigma rules in -Path. #>
    param([string[]]$Path)
    $key = (@($Path) -join '|')
    if ($script:WfxSigmaCache -and $script:WfxSigmaCache.Key -eq $key) { return , $script:WfxSigmaCache.Rules }
    $rules = Import-WfxSigmaRule -Path $Path
    $script:WfxSigmaCache = @{ Key = $key; Rules = $rules }
    , $rules
}

function Set-WfxSigmaEventQuery {
    <#
    .SYNOPSIS Makes event collection also read the logs / event IDs the loaded Sigma rules need (for example
    Security 4662 or 5145), so the rules have data to run on. Extra queries are capped like the built-in ones.
    #>
    param([object[]]$Rule)
    $have = @{}; foreach ($q in $script:WfxEventQuery) { foreach ($i in $q.Ids) { $have["$($q.Log)|$i"] = $true } }
    $want = @{}
    foreach ($r in @($Rule)) {
        $ids = @($r.Ids)
        if (-not $ids.Count) {
            $ids = @(foreach ($s in $r.Selections.Values) { foreach ($g in $s) { foreach ($tt in $g) { if ($tt.Field -eq 'EventID') { foreach ($v in $tt.Values) { $n = 0; if ([int]::TryParse([string]$v, [ref]$n)) { $n } } } } } })
        }
        foreach ($lg in $r.Logs) { foreach ($i in $ids) { if (-not $have["$lg|$i"]) { if (-not $want.ContainsKey($lg)) { $want[$lg] = New-Object System.Collections.Generic.HashSet[int] }; [void]$want[$lg].Add($i) } } }
    }
    $script:WfxSigmaEventQuery = @(foreach ($lg in $want.Keys) {
            $all = @($want[$lg] | Sort-Object)
            for ($k = 0; $k -lt $all.Count; $k += 20) { @{ Log = $lg; Ids = @($all[$k..([Math]::Min($k + 20, $all.Count) - 1)]); Max = 3000; Msg = $false } }
        })
    @($script:WfxSigmaEventQuery).Count
}


# ===== Private/Sqlite.ps1 =====
# Minimal read-only SQLite reader: walks table b-trees in a database file held in memory and returns rows.
# Used for browser download history (Chromium "History", Firefox "places.sqlite"). The database is copied
# into memory with read sharing, so the browser keeps running; no SQLite library is loaded or executed.
#
# Limits: rows still in the write-ahead log (History-wal) are not read; freed pages are not carved.

function Read-WfxSqliteVarint {
    param([byte[]]$B, [int]$O)
    [long]$v = 0
    for ($i = 0; $i -lt 9; $i++) {
        if ($O + $i -ge $B.Length) { break }
        $c = $B[$O + $i]
        if ($i -eq 8) { $v = ($v -shl 8) -bor $c; return @($v, 9) }
        $v = ($v -shl 7) -bor ($c -band 0x7F)
        if (-not ($c -band 0x80)) { return @($v, ($i + 1)) }
    }
    @($v, 9)
}

function Read-WfxBigEndian {
    param([byte[]]$B, [int]$O, [int]$N)
    [long]$v = 0; for ($i = 0; $i -lt $N; $i++) { $v = ($v -shl 8) -bor $B[$O + $i] }
    if ($N -lt 8 -and $N -gt 0 -and ($B[$O] -band 0x80)) { $v -= ([long]1 -shl (8 * $N)) }   # sign-extend
    $v
}

function Open-WfxSqlite {
    <# Returns a database handle, or $null when the bytes are not an SQLite 3 database. #>
    param([string]$Path, [byte[]]$Bytes)
    if (-not $Bytes) {
        try {
            $fs = New-Object IO.FileStream($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
            try { $Bytes = New-Object byte[] $fs.Length; $n = 0; while ($n -lt $Bytes.Length) { $r = $fs.Read($Bytes, $n, $Bytes.Length - $n); if ($r -le 0) { break }; $n += $r } } finally { $fs.Dispose() }
        } catch { Write-Verbose "sqlite open failed: $Path : $($_.Exception.Message)"; return $null }
    }
    if ($Bytes.Length -lt 512 -or [Text.Encoding]::ASCII.GetString($Bytes, 0, 15) -ne 'SQLite format 3') { return $null }
    $ps = ([int]$Bytes[16] -shl 8) -bor $Bytes[17]; if ($ps -eq 1) { $ps = 65536 }
    $enc = [int](Read-WfxBigEndian $Bytes 56 4)
    [pscustomobject]@{ B = $Bytes; PageSize = $ps; Usable = $ps - $Bytes[20]; Encoding = $(if ($enc -eq 2) { [Text.Encoding]::Unicode } elseif ($enc -eq 3) { [Text.Encoding]::BigEndianUnicode } else { [Text.Encoding]::UTF8 }) }
}

function Get-WfxSqlitePayload {
    # Full record payload of a leaf cell, following overflow pages.
    param($Sdb, [int]$O, [long]$P)
    $b = $Sdb.B; $U = $Sdb.Usable; $X = $U - 35
    if ($P -le $X) { $out = New-Object byte[] $P; [Array]::Copy($b, $O, $out, 0, [Math]::Min($P, $b.Length - $O)); return , $out }
    $M = [int][Math]::Floor((($U - 12) * 32 / 255)) - 23
    $K = $M + (($P - $M) % ($U - 4)); $local = if ($K -le $X) { $K } else { $M }
    $ms = New-Object IO.MemoryStream; $ms.Write($b, $O, [Math]::Min($local, $b.Length - $O))
    $next = [long](Read-WfxBigEndian $b ($O + $local) 4) -band 0xFFFFFFFFL; $guard = 0
    while ($next -gt 0 -and $ms.Length -lt $P -and $guard++ -lt 100000) {
        $po = ($next - 1) * $Sdb.PageSize; if ($po + 4 -gt $b.Length) { break }
        $take = [int][Math]::Min($U - 4, $P - $ms.Length); $take = [Math]::Min($take, $b.Length - $po - 4)
        $ms.Write($b, [int]$po + 4, $take)
        $next = [long](Read-WfxBigEndian $b ([int]$po) 4) -band 0xFFFFFFFFL
    }
    , $ms.ToArray()
}

function ConvertFrom-WfxSqliteRecord {
    param($Sdb, [byte[]]$R)
    $h = Read-WfxSqliteVarint $R 0; $hdrLen = [int]$h[0]; $p = [int]$h[1]
    $types = New-Object System.Collections.Generic.List[long]
    while ($p -lt $hdrLen -and $p -lt $R.Length) { $v = Read-WfxSqliteVarint $R $p; $types.Add($v[0]); $p += $v[1] }
    $d = $hdrLen; $vals = New-Object System.Collections.Generic.List[object]
    foreach ($t in $types) {
        $val = $null; $n = 0
        switch ($t) {
            0 { } 8 { $val = 0 } 9 { $val = 1 }
            1 { $n = 1 } 2 { $n = 2 } 3 { $n = 3 } 4 { $n = 4 } 5 { $n = 6 } 6 { $n = 8 }
            7 { $n = 8 }
            default { $n = if ($t -ge 12) { [int][Math]::Floor(($t - 12) / 2) } else { 0 } }
        }
        if ($n -gt 0 -and $d + $n -le $R.Length) {
            if ($t -ge 1 -and $t -le 6) { $val = Read-WfxBigEndian $R $d $n }
            elseif ($t -eq 7) { $tmp = New-Object byte[] 8; [Array]::Copy($R, $d, $tmp, 0, 8); [Array]::Reverse($tmp); $val = [BitConverter]::ToDouble($tmp, 0) }
            elseif ($t -ge 13 -and ($t % 2) -eq 1) { $val = $Sdb.Encoding.GetString($R, $d, $n) }
            else { $tmp = New-Object byte[] $n; [Array]::Copy($R, $d, $tmp, 0, $n); $val = $tmp }
        } elseif ($t -ge 13 -and ($t % 2) -eq 1) { $val = '' }
        $vals.Add($val); $d += $n
    }
    , $vals.ToArray()
}

function Get-WfxSqliteRows {
    <# Every (rowid, values[]) of the table b-tree rooted at a page. Bounded against cycles. #>
    param($Sdb, [long]$RootPage, [int]$Max = 200000)
    $b = $Sdb.B; $out = New-Object System.Collections.Generic.List[object]
    $stack = New-Object System.Collections.Generic.Stack[long]; $stack.Push($RootPage); $visited = @{}
    while ($stack.Count -and $out.Count -lt $Max) {
        $pg = $stack.Pop(); if ($visited.ContainsKey($pg) -or $pg -lt 1) { continue }; $visited[$pg] = $true
        $base = ($pg - 1) * $Sdb.PageSize; $h = if ($pg -eq 1) { $base + 100 } else { $base }
        if ($h + 8 -gt $b.Length) { continue }
        $type = $b[$h]; $cells = [int](Read-WfxBigEndian $b ($h + 3) 2) -band 0xFFFF
        if ($type -eq 0x05) {
            $hl = 12; $stack.Push(([long](Read-WfxBigEndian $b ($h + 8) 4) -band 0xFFFFFFFFL))
            for ($i = $cells - 1; $i -ge 0; $i--) { $co = $base + ((Read-WfxBigEndian $b ($h + $hl + 2 * $i) 2) -band 0xFFFF); if ($co + 4 -le $b.Length) { $stack.Push(([long](Read-WfxBigEndian $b ([int]$co) 4) -band 0xFFFFFFFFL)) } }
        } elseif ($type -eq 0x0D) {
            for ($i = 0; $i -lt $cells; $i++) {
                $co = [int]($base + ((Read-WfxBigEndian $b ($h + 8 + 2 * $i) 2) -band 0xFFFF)); if ($co -ge $b.Length) { continue }
                $ps = Read-WfxSqliteVarint $b $co; $rid = Read-WfxSqliteVarint $b ($co + $ps[1])
                $payload = Get-WfxSqlitePayload $Sdb ($co + $ps[1] + $rid[1]) $ps[0]
                $out.Add([pscustomobject]@{ RowId = $rid[0]; Values = (ConvertFrom-WfxSqliteRecord $Sdb $payload) })
            }
        }
    }
    , $out.ToArray()
}

function Find-WfxSqliteRow {
    <# One row of a table b-tree by rowid (B-tree descent, so a large table is not scanned). Returns values[] or $null. #>
    param($Sdb, [long]$RootPage, [long]$RowId)
    $b = $Sdb.B; $pg = $RootPage; $guard = 0
    while ($pg -ge 1 -and $guard++ -lt 64) {
        $base = ($pg - 1) * $Sdb.PageSize; $h = if ($pg -eq 1) { $base + 100 } else { $base }
        if ($h + 8 -gt $b.Length) { return $null }
        $type = $b[$h]; $cells = [int](Read-WfxBigEndian $b ($h + 3) 2) -band 0xFFFF
        if ($type -eq 0x05) {
            $next = [long](Read-WfxBigEndian $b ($h + 8) 4) -band 0xFFFFFFFFL
            for ($i = 0; $i -lt $cells; $i++) {
                $co = [int]($base + ((Read-WfxBigEndian $b ($h + 12 + 2 * $i) 2) -band 0xFFFF))
                $key = (Read-WfxSqliteVarint $b ($co + 4))[0]
                if ($RowId -le $key) { $next = [long](Read-WfxBigEndian $b $co 4) -band 0xFFFFFFFFL; break }
            }
            $pg = $next
        } elseif ($type -eq 0x0D) {
            for ($i = 0; $i -lt $cells; $i++) {
                $co = [int]($base + ((Read-WfxBigEndian $b ($h + 8 + 2 * $i) 2) -band 0xFFFF))
                $ps = Read-WfxSqliteVarint $b $co; $rid = Read-WfxSqliteVarint $b ($co + $ps[1])
                if ($rid[0] -eq $RowId) { return , (ConvertFrom-WfxSqliteRecord $Sdb (Get-WfxSqlitePayload $Sdb ($co + $ps[1] + $rid[1]) $ps[0])) }
            }
            return $null
        } else { return $null }
    }
    $null
}

function Get-WfxSqliteSchema {
    <# Root page and column names (INTEGER PRIMARY KEY index) of a table, from sqlite_master. #>
    param($Sdb, [string]$Table)
    $def = Get-WfxSqliteRows $Sdb 1 | Expand-WfxRecord | Where-Object { $_.Values[0] -eq 'table' -and $_.Values[1] -ieq $Table } | Select-Object -First 1
    if (-not $def) { return $null }
    $sql = [string]$def.Values[4]
    $body = $sql.Substring($sql.IndexOf('(') + 1); $body = $body.Substring(0, $body.LastIndexOf(')'))
    $cols = New-Object System.Collections.Generic.List[string]; $depth = 0; $cur = ''
    foreach ($ch in $body.ToCharArray()) { if ($ch -eq '(') { $depth++ } elseif ($ch -eq ')') { $depth-- }; if ($ch -eq ',' -and $depth -eq 0) { $cols.Add($cur); $cur = '' } else { $cur += $ch } }
    if ($cur) { $cols.Add($cur) }
    $names = @(); $pk = -1
    foreach ($c in $cols) {
        $c = $c.Trim(); if ($c -match '^(?i)(?:PRIMARY|UNIQUE|CHECK|FOREIGN|CONSTRAINT)\b') { continue }
        $nm = ($c -split '\s+')[0].Trim('"', '`', '[', ']')
        if ($c -match '(?i)\bINTEGER\s+PRIMARY\s+KEY\b') { $pk = $names.Count }
        $names += $nm
    }
    [pscustomobject]@{ Root = [long]$def.Values[3]; Names = $names; Pk = $pk }
}

function Get-WfxSqliteTable {
    <# Rows of a named table as objects with column names (INTEGER PRIMARY KEY columns take the rowid). #>
    param($Sdb, [Parameter(Mandatory)][string]$Table, [int]$Max = 200000)
    $sc = Get-WfxSqliteSchema $Sdb $Table
    if (-not $sc) { return }
    $names = $sc.Names; $pk = $sc.Pk
    foreach ($row in (Get-WfxSqliteRows $Sdb $sc.Root $Max)) {
        $o = [ordered]@{}
        for ($i = 0; $i -lt $names.Count; $i++) { $o[$names[$i]] = if ($i -eq $pk) { $row.RowId } elseif ($i -lt $row.Values.Count) { $row.Values[$i] } else { $null } }
        [pscustomobject]$o
    }
}


# ===== Private/Yara.ps1 =====
# Optional YARA scanning. WinForensicX does not ship or download YARA: it uses a yara executable the
# analyst already trusts (-YaraExe, $env:WFX_YARA_EXE, or yara64.exe / yara.exe / yara on PATH) with rules the
# analyst supplies (-YaraRules, $env:WFX_YARA). YARA only reads the files it scans.

function Find-WfxYaraExe {
    param([string]$Path = $env:WFX_YARA_EXE)
    if ($Path) { if (Test-Path -LiteralPath $Path -PathType Leaf) { return (Resolve-Path -LiteralPath $Path).Path }; return $null }
    foreach ($n in 'yara64.exe', 'yara.exe', 'yara') { $c = Get-Command $n -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1; if ($c) { return $c.Source } }
    $null
}

function Invoke-WfxYaraScan {
    <#
    .SYNOPSIS Runs YARA rules over a list of files and/or folders and returns { Rule; Namespace; Tags; Path }.
    .PARAMETER Rules   .yar / .yara files or folders of them.
    .PARAMETER Target  Files to scan (deduplicated, missing files skipped).
    .PARAMETER Folder  Folders to scan recursively.
    .PARAMETER ListDir Case folder to keep the list of scanned files in (enables one yara run for all files).
    #>
    param([Parameter(Mandatory)][string[]]$Rules, [string[]]$Target = @(), [string[]]$Folder = @(), [string]$YaraExe = '', [int]$TimeoutSec = 60, [int]$MaxFiles = 20000, [string]$ListDir = '')
    $exe = Find-WfxYaraExe -Path $YaraExe
    if (-not $exe) { Add-WfxGap -Source 'yara' -Reason 'YARA rules were given but no yara executable was found.' -Fix 'Install YARA (virustotal.github.io/yara) and put yara64.exe on PATH, or pass -YaraExe / set WFX_YARA_EXE.'; return }
    $ruleFiles = @(foreach ($r in $Rules) {
            if (Test-Path -LiteralPath $r -PathType Container) { Get-ChildItem -LiteralPath $r -Recurse -File -Include *.yar, *.yara -ErrorAction SilentlyContinue | ForEach-Object FullName }
            elseif (Test-Path -LiteralPath $r) { (Resolve-Path -LiteralPath $r).Path }
        })
    if (-not $ruleFiles.Count) { Add-WfxGap -Source 'yara' -Reason "No .yar/.yara files found in: $($Rules -join ', ')"; return }
    $files = @($Target | Where-Object { $_ } | Sort-Object -Unique | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -First $MaxFiles)
    $out = New-Object System.Collections.Generic.List[object]
    $run = {
        param([string[]]$ArgList)
        $psi = New-Object Diagnostics.ProcessStartInfo
        $psi.FileName = $exe; $psi.UseShellExecute = $false; $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true; $psi.CreateNoWindow = $true
        $psi.Arguments = (@($ArgList | ForEach-Object { if ($_ -match '[\s"]') { '"' + ($_ -replace '"', '\"') + '"' } else { $_ } }) -join ' ')
        $p = [Diagnostics.Process]::Start($psi)
        $errTask = $p.StandardError.ReadToEndAsync()
        $text = $p.StandardOutput.ReadToEnd(); $p.WaitForExit()
        $err = $errTask.Result
        if ($p.ExitCode -ne 0 -and $err) { Add-WfxGap -Source 'yara' -Reason ("yara exited with {0}: {1}" -f $p.ExitCode, (Get-WfxShortText $err 300)) }
        foreach ($line in ($text -split "`r?`n")) {
            $m = [regex]::Match($line, '^(?:(?<ns>[^:\s]+):)?(?<rule>[A-Za-z_][A-Za-z0-9_]*)\s+(?:\[(?<tags>[^\]]*)\]\s+)?(?<path>.+)$')
            if ($m.Success) { $out.Add([pscustomobject]@{ Rule = $m.Groups['rule'].Value; Namespace = $m.Groups['ns'].Value; Tags = $m.Groups['tags'].Value; Path = $m.Groups['path'].Value.Trim() }) }
        }
    }
    $common = @('-w', '-g', '-a', [string]$TimeoutSec) + $ruleFiles
    if ($files.Count) {
        if ($ListDir -and (Test-Path -LiteralPath $ListDir -PathType Container)) {
            # The list of scanned files is kept in the case (raw\yara-scan-list.txt) as a record of what was scanned.
            $listFile = Join-Path $ListDir 'yara-scan-list.txt'
            [IO.File]::WriteAllLines($listFile, $files)
            & $run (@('--scan-list') + $common + @($listFile))
        } else {
            # No case folder to write a list into: one yara run per file (nothing is written anywhere).
            foreach ($f in @($files | Select-Object -First 500)) { & $run ($common + @($f)) }
            if ($files.Count -gt 500) { Add-WfxGap -Source 'yara' -Reason "Only the first 500 of $($files.Count) files were scanned (no case folder for a scan list)." }
        }
    }
    foreach ($d in $Folder) { if (Test-Path -LiteralPath $d -PathType Container) { & $run (@('-r') + $common + @($d)) } }
    $seen = @{}
    foreach ($h in $out) { $k = "$($h.Rule)|$($h.Path)"; if (-not $seen[$k]) { $seen[$k] = $true; $h } }
}

function Invoke-WfxYaraAnalyzer {
    param([object[]]$Hit, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($h in @($Hit | Where-Object { $_ })) {
        $findings.Add((New-WfxFinding -Id "YARA-$($h.Rule)" -Title "YARA rule $($h.Rule) matched: $(Get-WfxLeaf $h.Path)" -Severity 'High' -Confidence 'Medium' -Category 'Malware' -Technique @() `
                    -Description "The file matched YARA rule $($h.Rule)$(if ($h.Tags) { " (tags: $($h.Tags))" }). How much this means depends on the rule: check its description and author." `
                    -Recommendation 'Hash the file, check it against threat intelligence, and look at how it arrived and whether it ran (Explore › Evidence of execution).' `
                    -Entity "file:$($h.Path)" -HostName $HostName -Source 'yara' -Evidence ([ordered]@{ Rule = $h.Rule; Namespace = $h.Namespace; Tags = $h.Tags; Path = $h.Path })))
    }
    , $findings.ToArray()
}


# ===== Analyzers/Activity.ps1 =====
# Activity analyzer — turns "what changed recently" records into findings for the changes attackers make.
# Input: normalized activity records { Time, Category, Action, Target, Detail, Actor, Source }.

function Invoke-WfxActivityAnalyzer {
    param([object[]]$Activity, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $acts = @($Activity | Where-Object { $_ })
    if (-not $acts.Count) { return , $findings.ToArray() }
    $threats = $null; try { $threats = Get-WfxRulePack -Name 'threats' } catch {}
    $rmm = @($threats.rmmProcesses | ForEach-Object { ([string]$_ -replace '\.exe$', '').ToLowerInvariant() } | Where-Object { $_.Length -ge 4 })
    $offensive = @($threats.offensiveProcesses)
    $rmmExe = @($threats.rmmProcesses)
    $c2Ports = @(4444, 5555, 1337, 31337, 6666, 6667, 9001, 9002, 12345, 50050)
    $execExt = '(?i)\.(?:exe|dll|scr|com|pif|ps1|psm1|bat|cmd|vbs|vbe|js|jse|wsf|hta|msi|lnk|cpl|jar)$'
    $ev = { param($a) [ordered]@{ Time = $a.Time; Action = $a.Action; Target = $a.Target; Detail = $a.Detail; Actor = $a.Actor; Source = $a.Source } }
    $add = {
        param($Id, $Title, $Sev, $Conf, $Tech, $Desc, $Rec, $A, [string]$Cat = 'Activity')
        $findings.Add((New-WfxFinding -Id $Id -Title $Title -Severity $Sev -Confidence $Conf -Category $Cat -Technique $Tech -Description $Desc -Recommendation $Rec `
                    -Entity "activity:${Id}:$($A.Target)" -HostName $HostName -Time $A.Time -Source "activity:$($A.Source)" -Evidence (& $ev $A)))
    }

    foreach ($a in $acts) {
        $act = [string]$a.Action; $tgt = [string]$a.Target; $det = [string]$a.Detail; $actor = [string]$a.Actor
        switch -Regex ($act) {
            '^Hijack key written' {
                & $add 'ACT-HIJACK-KEY-CHANGED' "Execution-hijack registry key changed: $(Get-WfxLeaf $tgt)" 'High' 'Medium' @('T1546.012', 'T1548.002') `
                    'An Image File Execution Options, SilentProcessExit or shell-handler key was written in the look-back window. These keys let an attacker run code whenever a program starts or bypass UAC.' `
                    'Inspect the key values (Detail) and remove any Debugger / command values you did not set.' $a
            }
            '^Autostart key written' {
                & $add 'ACT-AUTOSTART-KEY-CHANGED' "Autostart registry location changed recently: $tgt" 'Medium' 'Low' @('T1547.001') `
                    'A Run/RunOnce/Winlogon/AppInit autostart key was modified in the look-back window. Installers do this too; check what was added.' `
                    'Compare the values with the Autostart list and confirm each entry is expected.' $a
            }
            '^Defence key written' {
                $sev = if ($tgt -match '(?i)\\Exclusions\\') { 'High' } else { 'Medium' }
                & $add 'ACT-DEFENCE-KEY-CHANGED' "Security-control setting changed: $tgt" $sev 'Medium' @('T1562.001') `
                    'A Defender exclusion, Defender policy, PowerShell logging policy or firewall-rule key was modified in the look-back window — attackers change these right before dropping tools.' `
                    'Confirm the change was approved; review what the exclusion / policy now allows.' $a
            }
            '^Credentials key written' {
                if ($tgt -match '(?i)WDigest' -or $det -match '(?i)UseLogonCredential=1|RunAsPPL=0') {
                    & $add 'ACT-CRED-KEY-CHANGED' "Credential-protection setting changed: $tgt" 'High' 'Medium' @('T1112', 'T1003.001') `
                        'The WDigest or LSA configuration key was written. Attackers enable WDigest clear-text credentials or weaken LSA protection before dumping passwords.' `
                        'Check UseLogonCredential (should be 0 / absent) and RunAsPPL; reset credentials if weakened.' $a
                }
            }
            '^Software installed' {
                $hit = @($rmm | Where-Object { $tgt.ToLowerInvariant().Contains($_) }) | Select-Object -First 1
                if ($hit) {
                    & $add 'ACT-RMM-INSTALLED' "Remote-access software installed: $hit" 'Medium' 'Medium' @('T1219') `
                        'A remote monitoring/management tool was installed in the look-back window. Intruders install these for persistent hands-on access.' `
                        'Confirm IT installed it; if not, remove it and investigate how it arrived.' $a
                }
            }
            '^Service installed' {
                if ($tgt -match '(?i)^(?:PSEXESVC|PAExec\S*|RemComSvc|csexecsvc|winexesvc|BTOBTO|SMBExec\S*)$' -or $det -match '(?i)\\(?:users|programdata|windows\\temp|temp|appdata)\\|cmd(?:\.exe)?\s+/c|powershell|\\\\[^\\]+\\(?:admin|c)\$|(?:%SystemRoot%|[a-z]:\\windows)\\[^\\]+\.exe') {
                    & $add 'ACT-SERVICE-SUSPICIOUS' "Service installed from an unusual location: $tgt" 'High' 'Medium' @('T1543.003', 'T1569.002') `
                        'A new service runs a shell command or a binary from a user-writable folder or admin share — the pattern of PsExec-style remote execution and service persistence.' `
                        'Inspect the service binary and the account that created it.' $a
                }
            }
            '^(?:All firewall rules deleted|Firewall rule added|Firewall profile setting changed)' {
                if ($act -match 'All firewall' -or ($actor -and $actor -notmatch '(?i)\\(?:svchost|mpssvc|msmpeng|system32\\(?:netsh|dllhost)|wbem\\wmiprvse)\.exe$|^System$')) {
                    & $add 'ACT-FIREWALL-CHANGED' "Firewall changed by $(if ($actor) { Get-WfxLeaf $actor } else { 'unknown' }): $tgt" 'Medium' 'Medium' @('T1562.004') `
                        'A firewall rule was added or settings changed by a program that is not the usual Windows management path.' `
                        'Review the rule (program, ports, direction) and remove it if not expected.' $a
                }
            }
            '^Audit policy changed' { & $add 'ACT-AUDIT-POLICY-CHANGED' 'Audit policy was changed' 'Medium' 'Medium' @('T1562.002') 'The audit policy was modified — attackers turn auditing off to avoid leaving events.' 'Check the current audit policy (auditpol /get /category:*) and who changed it.' $a }
            '^(?:Event logging shut down|Security log cleared|Event log cleared)' { & $add 'ACT-LOGGING-TAMPER' "$act" 'High' 'High' @('T1070.001') 'Event logging was cleared or stopped, destroying evidence.' 'Recover logs from forwarding/SIEM and review what happened just before.' $a }
            '^System time changed' {
                if ($det -notmatch '(?i)svchost|w32time|^$' -and $actor -notmatch '(?i)LOCAL SERVICE|NETWORK SERVICE') {
                    & $add 'ACT-TIME-CHANGED' 'System time changed manually' 'Low' 'Low' @('T1070.006') 'The system clock was changed by something other than time synchronisation, which can be used to confuse timelines.' 'Account for the shift when reading timestamps; identify who changed it.' $a
                }
            }
            'timestomp' { & $add 'ACT-TIMESTOMP' "File timestamp altered: $(Get-WfxLeaf $tgt)" 'Medium' 'Medium' @('T1070.006') 'A file''s creation time was changed (Sysmon 2) — used to hide new files among old ones. Some installers and browsers also do this.' 'Check the process that changed it (Actor) and the file.' $a }
            '^BITS transfer' {
                if ($tgt -notmatch '(?i)\.(?:microsoft|windowsupdate|windows|office|msedge|live|bing|skype|azureedge|msftconnecttest|xboxlive|onedrive|sharepoint|adobe|google|gvt1|mozilla|dropbox)\.(?:com|net)') {
                    & $add 'ACT-BITS-DOWNLOAD' "BITS download from an unusual source: $(Get-WfxShortText $tgt 80)" 'Medium' 'Medium' @('T1197', 'T1105') 'A BITS job transferred a file from a non-vendor URL. BITS is a quiet way to download payloads and survive reboots.' 'List BITS jobs (bitsadmin /list /allusers /verbose) and retrieve the file for analysis.' $a
                }
            }
            '^Permanent WMI subscription' { & $add 'ACT-WMI-SUBSCRIPTION' 'Permanent WMI event subscription registered' 'High' 'Medium' @('T1546.003') 'A permanent WMI event consumer was registered — a stealthy persistence mechanism.' 'Inspect root\subscription filters, consumers and bindings; remove unknown ones.' $a }
            '^(?:Real-time protection disabled|Virus scanning disabled|Spyware scanning disabled)' { & $add 'ACT-DEFENDER-DISABLED' "$act" 'High' 'High' @('T1562.001') 'Microsoft Defender protection was turned off.' 'Re-enable protection and find who disabled it.' $a }
            '^Program ran \(BAM\)' {
                if ((Test-WfxUserWritablePath $tgt) -and $tgt -match '(?i)\.(?:exe|scr|com)$') {
                    & $add 'ACT-EXEC-USERPATH' "Program ran from a user folder: $(Get-WfxLeaf $tgt)" 'Low' 'Low' @('T1204.002') 'A program in a user-writable folder (Downloads, Temp, AppData, ProgramData…) was executed in the look-back window. Common for installers; also how most malware first runs.' 'Hash and check the file (Hunt & analyze → file triage) if you do not recognise it.' $a
                }
            }
            '^Outbound RDP' { & $add 'ACT-RDP-OUTBOUND' "Outbound RDP to $tgt" 'Info' 'Medium' @('T1021.001') 'This host was used to connect to another machine over RDP — context for lateral movement.' 'Confirm the connection was expected.' $a }
            '^(?:Created|Executable/script created)' {
                if ($a.Category -eq 'File' -and $tgt -match '(?i)\\Start Menu\\Programs\\Startup\\[^\\]+$' -and $tgt -notmatch '(?i)\\desktop\.ini$') {
                    & $add 'ACT-STARTUP-DROP' "File placed in a Startup folder: $(Get-WfxLeaf $tgt)" 'High' 'Medium' @('T1547.001') 'A file was created in a Startup folder; it will run at every logon of that user (or all users).' 'Inspect the file and remove it if it was not installed by known software.' $a
                }
                if ($a.Category -eq 'File' -and $tgt -match '(?i)\.(?:pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|txt|rtf|zip|rar|mp4|mp3)\.(?:exe|scr|com|pif|js|jse|vbs|vbe|wsf|hta|bat|cmd|lnk|ps1)$') {
                    & $add 'ACT-DOUBLE-EXTENSION' "File with a disguised double extension: $(Get-WfxLeaf $tgt)" 'High' 'Medium' @('T1036.007') 'A file name ends in a document/media extension followed by an executable one (e.g. invoice.pdf.exe). Explorer hides known extensions by default, so the user sees "invoice.pdf". This is a classic phishing lure.' 'Do not open it; hash it and check its origin (Zone.Identifier, browser history, mail).' $a
                }
                if ($a.Category -eq 'File' -and $tgt -match '(?i)\\[^\\]*(?:decrypt|ransom|recover[_ -]?(?:your|my|all)?[_ -]?(?:files|data)|restore[_ -]?(?:your|my|all)?[_ -]?files|how[_ -]?to[_ -]?(?:decrypt|recover|restore|back))[^\\]*\.(?:txt|html?|hta|url|rtf)$') {
                    & $add 'ACT-RANSOM-NOTE' "Possible ransom note created: $(Get-WfxLeaf $tgt)" 'High' 'Low' @('T1486') 'A file was created whose name matches the naming used by ransomware notes (decrypt / recover files / how to restore …).' 'Open the file with a text viewer (do not run it); if it is a ransom note, isolate the host immediately.' $a
                }
                if ((Test-WfxNameInList $tgt $offensive)) {
                    & $add 'ACT-OFFENSIVE-TOOL-DROPPED' "Known offensive tool written to disk: $(Get-WfxLeaf $tgt)" 'High' 'Medium' @('T1588.002') "A file with the name of a known attack / credential-theft tool was created. $($threats.offensiveNote)" 'Hash the file and check it; determine who placed it and whether it ran (Prefetch, BAM).' $a
                }
                if ($act -match '^Created and deleted' -and $a.Category -eq 'File' -and $tgt -match $execExt -and $tgt -notmatch '(?i)\\(?:windows\\(?:softwaredistribution|winsxs|servicing)|program files|programdata\\(?:microsoft|package cache))\\') {
                    & $add 'ACT-SHORTLIVED-EXEC' "Executable created and deleted again: $(Get-WfxLeaf $tgt)" 'Medium' 'Low' @('T1070.004') 'An executable or script existed only briefly — the pattern of a dropper that runs a payload and removes it. Installers and updaters also do this.' 'Check execution artefacts (Prefetch, BAM, Sysmon) around this time for the same name.' $a
                }
                if ($a.Category -eq 'File' -and $tgt -match '(?i)\\(?:windows\\(?:temp|tasks|tracing)|programdata|users\\public|perflogs|\$recycle\.bin)\\[^\\]*\.(?:exe|dll|scr|ps1|bat|vbs|hta)$') {
                    & $add 'ACT-DROP-EXECUTABLE' "Executable written to a staging folder: $(Get-WfxLeaf $tgt)" 'Medium' 'Low' @('T1105') 'A program or script was created in a folder commonly used to stage malware.' 'Hash and check the file.' $a
                }
            }
            '^(?:Deleted|File deleted|Permanently deleted|Deleted to Recycle Bin)' {
                if ($tgt -match '(?i)\\winevt\\Logs\\[^\\]+\.evtx$') {
                    & $add 'ACT-EVTX-DELETED' "Event log file deleted: $(Get-WfxLeaf $tgt)" 'High' 'Medium' @('T1070.001') 'A Windows event log file was deleted from the log folder — evidence destruction.' 'Recover the log from forwarding/SIEM or backups; review what happened just before.' $a
                }
                if ($tgt -match '(?i)\\PSReadLine\\ConsoleHost_history\.txt$') {
                    & $add 'ACT-PSHISTORY-DELETED' 'PowerShell command history deleted' 'Medium' 'Medium' @('T1070.003') 'The PSReadLine history file (record of typed PowerShell commands) was deleted.' 'Check other execution evidence (4104 script blocks, Prefetch) for the same period.' $a
                }
            }
            '^Program (?:ran|launched)' {
                if (Test-WfxNameInList $tgt $offensive) {
                    & $add 'ACT-OFFENSIVE-TOOL-RAN' "Known offensive tool executed: $(Get-WfxLeaf $tgt)" 'High' 'Medium' @('T1588.002') "A program with the name of a known attack / credential-theft tool ran on this host. $($threats.offensiveNote)" 'Confirm whether this was an authorised test; if not, treat the host as compromised.' $a
                } elseif (Test-WfxNameInList $tgt $rmmExe) {
                    & $add 'ACT-RMM-RAN' "Remote-access tool executed: $(Get-WfxLeaf $tgt)" 'Medium' 'Low' @('T1219') 'A remote monitoring / remote desktop tool ran. Legitimate for IT support, and a common intruder access method.' 'Confirm the tool is sanctioned and who used it.' $a
                }
            }
            '^Defender configuration changed' {
                if ($tgt -match '(?i)\\Exclusions\\') {
                    & $add 'ACT-DEFENDER-EXCLUSION' "Defender exclusion changed: $(Get-WfxShortText $tgt 120)" 'High' 'Medium' @('T1562.001') 'A Microsoft Defender exclusion (path, process or extension) was added or changed. Attackers exclude their tools from scanning.' 'Review the exclusion list (Get-MpPreference) and remove anything not approved.' $a
                }
            }
            '^Malware detected' { & $add 'ACT-MALWARE-DETECTED' "Defender detected malware: $(Get-WfxShortText $tgt 120)" 'High' 'High' @() 'Microsoft Defender reported a detection. Check whether it was remediated and how the file arrived.' 'Review Defender history (Explore → Events → Defender) and the file''s origin.' $a }
            '^User created' { & $add 'ACT-USER-CREATED' "Local account created: $tgt" 'Medium' 'Medium' @('T1136.001') 'A new account was created. Intruders create accounts for persistent access.' 'Confirm the account is expected and who created it (Actor).' $a }
            '^Added to group' {
                if ($tgt -match '(?i)→\s*(?:Administrators|Domain Admins|Enterprise Admins|Remote Desktop Users|Remote Management Users|Backup Operators)\s*$') {
                    $sev = if ($tgt -match '(?i)Admin') { 'High' } else { 'Medium' }
                    & $add 'ACT-PRIV-GROUP-ADD' "Account added to a privileged group: $tgt" $sev 'Medium' @('T1098') 'An account was added to a group that grants administrative or remote access.' 'Confirm the change was approved; remove the membership if not.' $a
                }
            }
            '^Scheduled task (?:created|changed|registered|updated)' {
                if ($det) {
                    foreach ($r in (Test-WfxCommandLine -CommandLine $det)) { & $add $r.id "$($r.title) (scheduled task $tgt)" $r.severity $r.confidence @(Get-WfxValue $r 'technique' @()) 'A scheduled task was created or changed with a command matching a known attack technique.' 'Inspect the task (schtasks /query /tn <name> /xml) and remove it if not expected.' $a }
                    $img = Get-WfxImagePath $det
                    if ($img -and (Test-WfxUserWritablePath $img)) { & $add 'ACT-TASK-USERPATH' "Scheduled task runs a program from a user-writable folder: $tgt" 'Medium' 'Medium' @('T1053.005') 'A scheduled task created or changed in the look-back window launches a program from Temp, AppData, ProgramData, Public or Downloads.' 'Inspect the task and the program it runs.' $a }
                }
            }
            '^Outbound connection' {
                if ($tgt -match '^(.+):(\d+)$' -and -not (Test-WfxPrivateIp $Matches[1]) -and [int]$Matches[2] -in $c2Ports) {
                    & $add 'ACT-C2-PORT' "Outbound connection to a port typical of C2 / reverse shells: $tgt" 'Medium' 'Low' @('T1571') 'An outbound connection used a port commonly used by attack frameworks and reverse shells (e.g. 4444, 50050). Suggestive, not conclusive.' 'Identify the process (Actor) and the destination''s reputation.' $a
                }
            }
            'Alternate (?:data )?stream' {
                if ($a.Category -eq 'File' -and $tgt -match '(?i)\.(?:exe|dll|txt|log|ini|jpg|png)$' -and $tgt -notmatch '(?i)\\(?:Downloads|INetCache)\\') {
                    & $add 'ACT-ADS-WRITTEN' "Alternate data stream written: $(Get-WfxLeaf $tgt)" 'Low' 'Low' @('T1564.004') 'An NTFS alternate data stream was added to a file outside download folders. ADS can hide payloads.' 'List streams with Get-Item -Stream * and inspect unexpected ones.' $a
                }
            }
        }
    }

    # Bursts: mass deletion / mass content change in user data (ransomware / wiper behaviour).
    $files = @($acts | Where-Object { $_.Category -eq 'File' -and [string]$_.Target -match '(?i)\\users\\' -and [string]$_.Target -notmatch '(?i)\\appdata\\|\\\.git\\|\\node_modules\\' })
    foreach ($kind in @(@{ Rx = 'Deleted'; Id = 'ACT-MASS-DELETE'; T = 'Mass file deletion in user folders'; Tech = @('T1485', 'T1070.004') }, @{ Rx = 'Content overwritten|^Renamed|^Moved'; Id = 'ACT-MASS-MODIFY'; T = 'Mass file modification/renaming in user folders'; Tech = @('T1486') })) {
        $set = @($files | Where-Object { $_.Action -match $kind.Rx } | ForEach-Object { [pscustomobject]@{ T = ConvertTo-WfxDateTime $_.Time; A = $_ } } | Where-Object { $_.T } | Sort-Object T)
        if ($set.Count -lt 300) { continue }
        $best = 0; $bi = 0; $j = 0
        for ($i = 0; $i -lt $set.Count; $i++) { while ($set[$i].T - $set[$j].T -gt [TimeSpan]::FromMinutes(10)) { $j++ }; if (($i - $j + 1) -gt $best) { $best = $i - $j + 1; $bi = $i } }
        if ($best -ge 300) {
            $first = $set[$bi - $best + 1].A
            $findings.Add((New-WfxFinding -Id $kind.Id -Title "$($kind.T): $best files within 10 minutes" -Severity 'High' -Confidence 'Medium' -Category 'Activity' -Technique $kind.Tech `
                        -Description 'Hundreds of user files were deleted or rewritten within minutes — consistent with ransomware, a wiper, or a large legitimate clean-up/sync. Check which process was active at that time.' `
                        -Recommendation 'Isolate the host if unexpected; check shadow copies/backups; correlate with process execution at that time.' `
                        -Entity "activity:$($kind.Id)" -HostName $HostName -Time $first.Time -Source 'activity:burst' `
                        -Evidence ([ordered]@{ Files = $best; From = $first.Time; To = $set[$bi].A.Time; Sample = @($set[($bi - [Math]::Min(9, $best - 1))..$bi] | ForEach-Object { $_.A.Target }) })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Artifacts.ps1 =====
# Artifact analyzer — turns execution and user-activity artifacts (ShimCache, Amcache, Prefetch, BAM,
# UserAssist, PCA, ShellBags, Jump Lists, shortcuts, RunMRU, browser downloads, Defender logs) into findings.
#
# One program usually appears in several artifacts (Amcache + ShimCache + Prefetch + BAM). Findings about a
# file are therefore made once per file, listing every artifact that saw it and the earliest/latest times.

function Join-WfxDict {
    <# Copy of an ordered dictionary with extra keys appended (works the same on PowerShell 5.1 and 7). #>
    param($A, $B)
    $o = [ordered]@{}; foreach ($k in $A.Keys) { $o[$k] = $A[$k] }; foreach ($k in $B.Keys) { $o[$k] = $B[$k] }; $o
}

function Invoke-WfxArtifactAnalyzer {
    param([object[]]$Artifacts, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $arts = @($Artifacts | Where-Object { $_ })
    if (-not $arts.Count) { return , $findings.ToArray() }
    $threats = $null; try { $threats = Get-WfxRulePack -Name 'threats' } catch { }
    $dnsPack = $null; try { $dnsPack = Get-WfxRulePack -Name 'dns' } catch { }
    $offensive = @($threats.offensiveProcesses | ForEach-Object { ([string]$_).ToLowerInvariant() })
    $rmm = @($threats.rmmProcesses | ForEach-Object { ([string]$_).ToLowerInvariant() })
    $vulnDrv = @($threats.vulnerableDrivers | ForEach-Object { ([string]$_).ToLowerInvariant() })
    $exfil = @($threats.exfilTools | ForEach-Object { ([string]$_).ToLowerInvariant() })
    $paste = @($dnsPack.pasteSites | ForEach-Object { ([string]$_).ToLowerInvariant() })
    $tunnel = @($dnsPack.tunnelDomains | ForEach-Object { ([string]$_).ToLowerInvariant() })
    $tlds = @($dnsPack.suspiciousTlds | ForEach-Object { ([string]$_).ToLowerInvariant().TrimStart('.') })
    $exeRx = '(?i)\.(?:exe|scr|com|pif|cpl|msi|dll|sys)$'
    $riskyDl = '(?i)\.(?:exe|scr|com|pif|cpl|msi|msix|appx|dll|ps1|psm1|bat|cmd|vbs|vbe|js|jse|wsf|wsh|hta|lnk|url|iso|img|vhd|vhdx|one|jar|xll|reg|chm|appref-ms|library-ms|search-ms|svg|html?)$'
    $sysNames = @('svchost.exe', 'lsass.exe', 'csrss.exe', 'winlogon.exe', 'services.exe', 'smss.exe', 'wininit.exe', 'spoolsv.exe', 'taskhostw.exe', 'dllhost.exe', 'conhost.exe', 'rundll32.exe', 'lsm.exe', 'sihost.exe', 'ctfmon.exe', 'msmpeng.exe', 'searchindexer.exe', 'runtimebroker.exe', 'explorer.exe', 'taskmgr.exe', 'regsvr32.exe', 'wmiprvse.exe')
    $staging = '(?i)^(?:[a-z]:|\(volume\))?\\(?:users\\public\\|users\\[^\\]+\\appdata\\local\\temp\\|windows\\temp\\|perflogs\\|\$recycle\.bin\\|programdata\\[^\\]+\.(?:exe|scr|dll|com)$|users\\[^\\]+\\appdata\\roaming\\[^\\]+\.(?:exe|scr|dll|com)$|windows\\tasks\\|windows\\debug\\|windows\\fonts\\[^\\]+\.exe$|intel\\|temp\\)'
    $isFull = { param($p) $p -match '^(?:[a-z]:\\|\\\\|\(volume\)\\|%[a-z]+%\\)' }
    $add = {
        param($Id, $Title, $Sev, $Conf, [string[]]$Tech, $Desc, $Rec, $Entity, $Time, $Ev, [string]$Cat = 'Execution', [string]$Src = 'artifacts')
        $findings.Add((New-WfxFinding -Id $Id -Title $Title -Severity $Sev -Confidence $Conf -Category $Cat -Technique $Tech -Description $Desc -Recommendation $Rec `
                    -Entity $Entity -HostName $HostName -Time $Time -Source $Src -Evidence $Ev))
    }

    # ── group per file: execution / presence evidence for the same path from several artifacts ──
    $byFile = @{}
    foreach ($a in $arts) {
        if ($a.Evidence -notin 'Execution', 'Presence', 'Install') { continue }
        $p = ConvertFrom-WfxEnvPath ([string]$a.Path); if (-not $p) { continue }
        $key = $p.ToLowerInvariant() -replace '^\(volume\)', '' -replace '^[a-z]:', ''
        if (-not $byFile.ContainsKey($key)) { $byFile[$key] = New-Object System.Collections.Generic.List[object] }
        $byFile[$key].Add($a)
    }
    foreach ($key in $byFile.Keys) {
        $rows = $byFile[$key].ToArray()
        $first = $rows[0]; $path = ConvertFrom-WfxEnvPath ([string]$first.Path)
        $full = @($rows | Where-Object { & $isFull (ConvertFrom-WfxEnvPath $_.Path) } | Select-Object -First 1); if ($full) { $path = ConvertFrom-WfxEnvPath ([string]$full[0].Path) }
        $leaf = (Get-WfxLeaf $path).ToLowerInvariant()
        $kinds = @($rows | ForEach-Object Artifact | Select-Object -Unique)
        $ran = [bool]@($rows | Where-Object Evidence -eq 'Execution').Count
        $times = @($rows | ForEach-Object Time | Where-Object { $_ } | Sort-Object)
        $sha = @($rows | ForEach-Object Sha1 | Where-Object { $_ } | Select-Object -First 1)
        $pub = @($rows | ForEach-Object { if ($_.Extra -and $_.Extra.PSObject.Properties['Publisher']) { [string]$_.Extra.Publisher } } | Where-Object { $_ } | Select-Object -First 1)
        $users = @($rows | ForEach-Object User | Where-Object { $_ } | Select-Object -Unique)
        $ev = [ordered]@{ Path = $path; SeenIn = ($kinds -join ', '); FirstSeen = $(if ($times) { $times[0] }); LastSeen = $(if ($times) { $times[-1] }); Sha1 = $(if ($sha) { $sha[0] }); Publisher = $(if ($pub) { $pub[0] }); Users = ($users -join ', ') }
        $what = if ($ran) { 'ran' } else { 'was present' }
        $when = if ($times) { $times[-1] } else { $null }
        $entity = "file:$path"

        $offHit = @($offensive | Where-Object { $leaf -eq $_ -or ($_ -notmatch '\.' -and $leaf.Contains($_)) } | Select-Object -First 1)
        if ($offHit) {
            & $add 'ART-OFFENSIVE-TOOL' "Offensive / remote-execution tool ${what}: $leaf" $(if ($ran) { 'High' } else { 'Medium' }) 'Medium' @('T1588.002') `
                "Execution artifacts ($($kinds -join ', ')) show $leaf, a tool used for credential theft, discovery or lateral movement. These artifacts survive deletion of the file, so this holds even if the tool is gone." `
                'Establish who ran it and when (see Seen in / times), hash-match it if the file still exists, and scope the accounts and hosts it could have touched.' $entity $when $ev
            continue
        }
        $exfHit = @($exfil | Where-Object { $leaf -eq $_ } | Select-Object -First 1)
        if ($exfHit -and ($ran -or $first.Artifact -eq 'DefenderLog')) {
            & $add 'ART-EXFIL-TOOL' "Data-transfer tool ran: $leaf" 'High' 'Medium' @('T1567.002', 'T1048') `
                "$leaf copies files to cloud storage or remote servers and is the most common exfiltration tool in ransomware intrusions. Seen in: $($kinds -join ', ')." `
                'Find its configuration file (e.g. rclone.conf) and command lines, establish what was copied and where to, and preserve proxy / firewall logs.' $entity $when $ev 'Exfiltration'
            continue
        }
        $rmmHit = @($rmm | Where-Object { $leaf -eq $_ } | Select-Object -First 1)
        if ($rmmHit -and $ran) {
            & $add 'ART-RMM-TOOL' "Remote-access tool ran: $leaf" 'Medium' 'Medium' @('T1219') `
                'A remote monitoring / remote desktop tool ran on this host. Intruders install these for persistent hands-on access that blends in with IT tooling.' `
                'Confirm IT uses this tool here; if not, remove it and review its connection logs.' $entity $when $ev
        }
        $okDir = '(?i)\\windows\\(?:system32|syswow64|winsxs|servicing|softwaredistribution)\\|^(?:[a-z]:|\(volume\))\\windows\\(?:explorer|regedit|notepad|hh|write)\.exe$'
        if ($leaf -eq 'msmpeng.exe') { $okDir = '(?i)\\(?:program files\\windows defender|programdata\\microsoft\\windows defender\\platform\\[^\\]+)\\msmpeng\.exe$' }
        if ($leaf -in $sysNames -and (& $isFull $path) -and $path -notmatch $okDir) {
            & $add 'ART-MASQUERADE' "System program name in the wrong folder: $path" 'High' 'Medium' @('T1036.005') `
                "$leaf is a Windows system program, but this copy $what outside the Windows system folders. Malware uses system names so it looks normal in a process list." `
                'Hash and inspect the file; check its parent process and persistence.' $entity $when $ev 'Defense Evasion'
            continue
        }
        # Installer bootstrappers unpack into Temp\{GUID}\ all the time; they are not interesting on their own.
        $installer = $path -match '(?i)\\temp\\\{[0-9a-f-]{36}\}(?:~setup)?\\|\\temp\\(?:vmware-[^\\]+|msi[0-9a-f]+\.tmp|is-[a-z0-9]+\.tmp|ckz_[a-z0-9]+|nsu[0-9a-z]+\.tmp|[0-9a-f]{8}-[0-9a-f-]{27})\\' -or
            $leaf -match '(?i)^(?:setup\d*|install(?:er)?|unins\d*|dismhost|mpsigstub|am_delta.*|mpam-.*|onedrivesetup|msedgeupdate.*|googleupdate.*|vc_?redist.*|dotnet.*|ndp\d+.*|windows\d+\.\d-kb\d+.*)\.exe$'
        if ($leaf -match $exeRx -and $path -match $staging -and -not $installer) {
            $sev = if ($pub) { 'Low' } elseif ($ran) { 'Medium' } else { 'Low' }
            & $add 'ART-EXEC-STAGING-PATH' "Program $what from a staging folder: $path" $sev 'Medium' @('T1204.002', 'T1074.001') `
                "Executables in Temp, Public, PerfLogs, the Recycle Bin or the root of ProgramData are where droppers and hands-on intruders stage tools. Seen in: $($kinds -join ', ')." `
                'Check the file hash and signer; find how it arrived (downloads, mail, archives) and what it started.' $entity $when $ev
        }
        if ($first.Artifact -eq 'AmcacheDriver' -or ($leaf -match '\.sys$')) {
            if ($leaf -in $vulnDrv) {
                & $add 'ART-VULNERABLE-DRIVER' "Known-vulnerable driver recorded: $leaf" 'High' 'Medium' @('T1068', 'T1562.001') `
                    "$leaf is a signed but vulnerable driver abused to kill security tools or gain kernel access (bring-your-own-vulnerable-driver)." `
                    'Find the service that loaded it and when; enable the Microsoft vulnerable driver blocklist.' $entity $when $ev 'Defense Evasion'
            }
        }
    }

    # Risky / attack-tool downloads, for browser history and for $MFT Zone.Identifier streams alike.
    $dlCheck = {
        param($p, $x, $time, $ev)
            $url = if ($x) { [string]$x.Url } else { '' }
            $host_ = ''; try { if ($url) { $host_ = ([uri]$url).Host.ToLowerInvariant() } } catch { }
            $rawIp = $host_ -match '^\d{1,3}(?:\.\d{1,3}){3}$|^\[?[0-9a-f:]+\]?$'
            $why = @()
            if ($rawIp -and -not (Test-WfxPrivateIp $host_)) { $why += 'served from a bare IP address' }
            if ($host_ -and @($paste | Where-Object { $host_ -eq $_ -or $host_.EndsWith(".$_") }).Count) { $why += 'from a paste / file-sharing site' }
            if ($host_ -and @($tunnel | Where-Object { $host_ -eq $_ -or $host_.EndsWith(".$_") }).Count) { $why += 'from a tunnelling service' }
            $tld = ($host_ -split '\.')[-1]; if ($host_ -and -not $rawIp -and $tld -in $tlds) { $why += "from a .$tld domain" }
            if ($x -and $x.Danger -and $x.Danger -notmatch 'safe|allowlisted') { $why += "the browser warned: $($x.Danger)" }
            if ($p -match $riskyDl -and $why.Count) {
                $sev = if (($x -and $x.Opened) -or $why.Count -ge 2) { 'High' } else { 'Medium' }
                & $add 'ART-RISKY-DOWNLOAD' "Risky download: $(Get-WfxLeaf $p)" $sev 'Medium' @('T1105', 'T1204.002') `
                    "An executable, script or disk-image file was downloaded ($($why -join '; ')). This is how loaders and phishing payloads arrive." `
                    'Check whether it was opened or run (Amcache / Prefetch / ShimCache for the same name), hash it, and review the referrer and the source site.' "download:$p" $time (Join-WfxDict $ev ([ordered]@{ Url = $url; Referrer = $(if ($x) { $x.Referrer }); Opened = $(if ($x) { $x.Opened }) })) 'Initial Access'
            }
            $leaf = (Get-WfxLeaf $p).ToLowerInvariant()
            if (@($offensive | Where-Object { $leaf -eq $_ -or ($_ -notmatch '\.' -and $leaf.Contains($_)) }).Count) {
                & $add 'ART-OFFENSIVE-DOWNLOAD' "Attack tool downloaded: $leaf" 'High' 'Medium' @('T1105', 'T1588.002') `
                    'A browser download saved a file named like a known attack tool.' 'Check whether it ran (execution artifacts for the same name) and who downloaded it.' "download:$p" $time (Join-WfxDict $ev ([ordered]@{ Url = $url })) 'Initial Access'
            }
    }

    foreach ($a in $arts) {
        $p = [string]$a.Path; $x = $a.Extra; $time = $a.Time
        $ev = [ordered]@{ Artifact = $a.Artifact; Time = $a.Time; TimeKind = $a.TimeKind; Path = $p; Detail = $a.Detail; User = $a.User; Source = $a.Source }
        switch ($a.Artifact) {
            'DefenderLog' {
                if ($a.Evidence -ne 'Detection') { break }
                $threat = [string]$a.Name
                $sev = if ($threat -match '(?i)^(?:PUA|PUADlMgr|Adware|BrowserModifier|SoftwareBundler|App):') { 'Low' } elseif ($threat -match '(?i)^(?:Ransom|Backdoor|HackTool|Exploit|Trojan|Behavior|VirTool):') { 'High' } else { 'Medium' }
                & $add 'ART-DEFENDER-DETECTION' "Defender detection in its own log: $threat" $sev 'High' @() `
                    "Microsoft Defender's support log records a detection of $threat on $p. This log is separate from the event log, so it can survive when event logs were cleared." `
                    'Confirm the remediation succeeded, find how the file arrived, and check for related detections on other hosts.' "defender:${threat}:$p" $time $ev 'Malware'
            }
            'Download' { & $dlCheck $p $x $time $ev }
            'SRUM' {
                if (-not $x -or -not $x.PSObject.Properties['BytesSent']) { break }
                $sent = [double]$x.BytesSent; $recv = [double]$x.BytesReceived
                $leaf = (Get-WfxLeaf $p).ToLowerInvariant()
                $isExfil = [bool]@($exfil | Where-Object { $leaf -eq $_ }).Count
                # Programs that upload by design: sync clients, browsers, mail, Windows itself.
                $expected = $p -match '(?i)(?:^System$|^\(unnamed app|\\(?:onedrive|dropbox|googledrivefs|box|boxsync|teams|ms-teams|outlook|thunderbird|chrome|msedge|firefox|brave|opera|iexplore|svchost|backgroundtransferhost|backgroundtaskhost|lsass|searchapp|msmpeng|mpdefendercoreservice|wuauclt|usoclient|code|zoom)\.exe$)'
                $big = $sent -ge 500MB -or ($sent -ge 100MB -and $sent -ge 4 * $recv)
                $sz = if ($sent -ge 1GB) { '{0:n1} GB' -f ($sent / 1GB) } else { '{0:n0} MB' -f ($sent / 1MB) }
                if (($isExfil -and $sent -ge 10MB) -or ($big -and -not $expected)) {
                    $sev = if ($isExfil -or ($p -match $staging)) { 'High' } else { 'Medium' }
                    & $add 'ART-SRUM-UPLOAD' "Large upload by $(Get-WfxLeaf $p): $sz sent" $sev 'Medium' @('T1048', 'T1567') `
                        "Windows' resource usage database (SRUM) records that $(Get-WfxLeaf $p) sent $sz over the network ($('{0:n0}' -f ($recv / 1MB)) MB received) in $($x.Hours) hourly records. Sending far more than receiving is the shape of an upload; SRUM keeps this for weeks, even after the program is deleted." `
                        'Find what the program is and who ran it; check proxy and firewall logs for the destination in the same hours, and what data it could reach.' "srum:$p|$($a.User)" $time (Join-WfxDict $ev ([ordered]@{ BytesSent = $x.BytesSent; BytesReceived = $x.BytesReceived; FirstSeen = $x.FirstSeen; Hours = $x.Hours })) 'Exfiltration'
                }
            }
            'MFT' {
                if ($x -and $x.PSObject.Properties['Url'] -and $x.Url) { & $dlCheck $p $x $time $ev }
                if ($x -and $x.PSObject.Properties['Timestomp'] -and $x.Timestomp) {
                    $sev = if ([int]$x.TimestompScore -ge 3) { 'High' } else { 'Medium' }
                    & $add 'ART-TIMESTOMP' "File timestamps rewritten: $(Get-WfxLeaf $p)" $sev 'Medium' @('T1070.006') `
                        "The `$MFT shows signs that this file's timestamps were changed after it was written: $($x.Timestomp). Attackers backdate their tools so they hide among old system files and fall outside a timeline." `
                        'Trust the $FILE_NAME times for this file; hash and inspect it, and check what ran around the $FILE_NAME creation time.' "timestomp:$p" $(if ($x.FNCreated) { $x.FNCreated } else { $time }) (Join-WfxDict $ev ([ordered]@{ FNCreated = $x.FNCreated; Reasons = $x.Timestomp })) 'Defense Evasion'
                }
            }
            { $_ -in 'ShellBag', 'JumpList', 'Shortcut', 'TypedPath' } {
                if ($p -match '^\\\\([^\\]+)\\(?:[a-z]\$|admin\$)(?:\\|$)') {
                    & $add 'ART-ADMIN-SHARE-ACCESS' "Administrative share opened: $p" 'Medium' 'Medium' @('T1021.002') `
                        "A user browsed the hidden administrative share of $($Matches[1]) ($($a.Artifact)). Attackers use C$ / ADMIN$ to copy tools to other machines and to collect data." `
                        'Confirm the user had a reason to open admin shares on that host; check that host for the same time window.' "share:$p" $time $ev 'Lateral Movement'
                }
                $args_ = if ($x -and $x.PSObject.Properties['Arguments']) { [string]$x.Arguments } else { '' }
                if ($args_) {
                    foreach ($r in @(Test-WfxCommandLine -CommandLine ("`"$p`" $args_") -Image $p)) {
                        & $add $r.id "$($r.title) (in a shortcut)" $r.severity $r.confidence $r.technique "$($r.description) The command is stored in a shortcut / Jump List entry ($($a.Source))." $r.recommendation "shortcut:$($a.Source)" $time (Join-WfxDict $ev ([ordered]@{ Arguments = $args_ }))
                    }
                }
                if ($x -and $x.PSObject.Properties['DriveType'] -and $x.DriveType -eq 'Removable') {
                    $isExe = $p -match $exeRx -or $p -match '(?i)\.(?:ps1|bat|cmd|vbs|js|hta|lnk)$'
                    & $add $(if ($isExe) { 'ART-REMOVABLE-EXEC' } else { 'ART-REMOVABLE-ACCESS' }) "$(if ($isExe) { 'Program run from a removable drive' } else { 'File opened from a removable drive' }): $(Get-WfxLeaf $p)" $(if ($isExe) { 'Medium' } else { 'Low' }) 'Medium' $(if ($isExe) { @('T1091') } else { @() }) `
                        "$($a.Artifact) records $p on a removable drive$(if ($x.VolumeLabel) { " labelled '$($x.VolumeLabel)'" })$(if ($x.VolumeSerial) { " (volume serial $($x.VolumeSerial))" }). Useful for data-theft and USB-malware questions." `
                        'Match the volume serial with USB device history (Explore → USB history) to identify the device.' "usb:$p" $time $ev 'Collection'
                }
            }
            'RunMRU' {
                foreach ($r in @(Test-WfxCommandLine -CommandLine $p)) {
                    & $add $r.id "$($r.title) (typed into the Run dialog)" $r.severity $r.confidence (@($r.technique) + 'T1204.004') `
                        "$($r.description) It was typed or pasted into Win+R — the 'ClickFix' / fake-CAPTCHA lure tells users to do exactly this." $r.recommendation "runmru:$p" $time $ev
                }
            }
            'Search' {
                if ($p -match '(?i)passw|credential|\bcreds?\b|secret|\.kdbx|keepass|vpn|wallet|seed|private key|id_rsa|\.pem|\.pfx|unattend|sysprep|ntds|\bsam\b') {
                    & $add 'ART-SENSITIVE-SEARCH' "Explorer search for credentials: '$p'" 'Medium' 'Low' @('T1083', 'T1552.001') `
                        'Someone searched the file system for password or key material from Explorer. Intruders with desktop access do this to find stored credentials.' `
                        'Confirm with the user; check what files matching that search were opened next (Jump Lists, shortcuts).' "search:$($a.User):$p" $time $ev 'Credential Access'
                }
            }
        }
    }
    , $findings.ToArray()
}


# ===== Analyzers/Events.ps1 =====
# Event-log analyzer. Operates on normalized events:
#   { Log, Provider, Id, TimeCreated (UTC ISO), Computer, Fields = @{ TargetUserName=…; IpAddress=…; CommandLine=…; … } }
# Works identically on live logs and exported .evtx (the collector normalizes both). Rules are matched on
# BOTH event id and log name, so an unrelated provider's event 104 in Application.evtx is never "log cleared".

function Join-WfxScriptBlock {
    <# Re-assembles PowerShell 4104 script blocks that were split across several events (MessageNumber/
       MessageTotal sharing one ScriptBlockId) so detections see the whole script, not fragments. #>
    param([object[]]$Event)
    $out = New-Object System.Collections.Generic.List[object]
    $groups = @{}
    foreach ($e in $Event) {
        $fl = Get-WfxValue $e 'Fields' @{}
        $sbid = [string](Get-WfxValue $fl 'ScriptBlockId' '')
        $tot = (ConvertTo-WfxInt (Get-WfxValue $fl 'MessageTotal' 1))
        if ((ConvertTo-WfxInt (Get-WfxValue $e 'Id' 0)) -eq 4104 -and $sbid -and $tot -gt 1) {
            if (-not $groups.ContainsKey($sbid)) { $groups[$sbid] = New-Object System.Collections.Generic.List[object] }
            $groups[$sbid].Add($e)
        } else { $out.Add($e) }
    }
    foreach ($k in $groups.Keys) {
        $parts = @($groups[$k] | Sort-Object { (ConvertTo-WfxInt (Get-WfxValue (Get-WfxValue $_ 'Fields' @{}) 'MessageNumber' 0)) })
        $text = ($parts | ForEach-Object { [string](Get-WfxValue (Get-WfxValue $_ 'Fields' @{}) 'ScriptBlockText' '') }) -join ''
        $first = $parts[0]
        $fields = @{}
        foreach ($kv in (Get-WfxValue $first 'Fields' @{}).GetEnumerator()) { $fields[$kv.Key] = $kv.Value }
        $fields['ScriptBlockText'] = $text
        $fields['MessageParts'] = "$($parts.Count)/$((Get-WfxValue $fields 'MessageTotal' $parts.Count))"
        $out.Add([pscustomobject]@{ Log = (Get-WfxValue $first 'Log' ''); Provider = (Get-WfxValue $first 'Provider' ''); Id = 4104; TimeCreated = (Get-WfxValue $first 'TimeCreated'); Computer = (Get-WfxValue $first 'Computer' ''); Message = ''; Fields = $fields })
    }
    , $out.ToArray()
}

function Test-WfxRuleLog {
    <# True when the rule's "logs" list is empty or contains the event's log (short or full channel name). #>
    param($Rule, [string]$Log)
    $logs = @(Get-WfxValue $Rule 'logs' @() | Where-Object { $_ })
    if ($logs.Count -eq 0 -or -not $Log) { return $true }
    foreach ($l in $logs) { if ($Log -eq $l) { return $true } }
    return $false
}

function Invoke-WfxEventAnalyzer {
    param([object[]]$Event, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $joined = Join-WfxScriptBlock -Event @($Event | Where-Object { $_ })
    $events = @($joined)
    if ($events.Count -eq 0) { return , $findings.ToArray() }
    $pack = Get-WfxRulePack -Name 'events'
    $byId = @{}
    foreach ($rule in $pack.rules) { foreach ($i in @($rule.eventIds)) { if (-not $byId.ContainsKey([int]$i)) { $byId[[int]$i] = New-Object System.Collections.Generic.List[object] }; $byId[[int]$i].Add($rule) } }

    $f = { param($e, $k) [string](Get-WfxValue (Get-WfxValue $e 'Fields' @{}) $k '') }

    # ── Per-event rules (Sigma-lite) ──
    foreach ($e in $events) {
        $id = (ConvertTo-WfxInt (Get-WfxValue $e 'Id' 0))
        if (-not $byId.ContainsKey($id)) { continue }
        $log = [string](Get-WfxValue $e 'Log' '')
        foreach ($rule in $byId[$id]) {
            if ($rule.PSObject.Properties['perEvent'] -and -not $rule.perEvent) { continue }   # aggregate-only rule, handled below
            if (-not (Test-WfxRuleLog $rule $log)) { continue }
            $text = @($rule.fields | ForEach-Object { & $f $e $_ }) -join ' '
            if ($text.Trim() -eq '') { $text = [string](Get-WfxValue $e 'Message' '') }

            if ($rule.pattern -eq '__lotl__') {
                $img = (& $f $e 'NewProcessName'); if (-not $img) { $img = (& $f $e 'Image') }
                $cl = (& $f $e 'CommandLine'); if (-not $cl) { $cl = $text }
                foreach ($r in (Test-WfxCommandLine -CommandLine $cl -Image $img)) {
                    $findings.Add((New-WfxFinding -Id $r.id -Title "$($r.title) (event $id)" -Severity $r.severity -Confidence $r.confidence `
                                -Category 'EventLog' -Technique $r.technique -Description $r.description -Recommendation $r.recommendation `
                                -Entity "event:${id}:$($r.id):$((& $f $e 'ProcessId'), (& $f $e 'NewProcessId'), (& $f $e 'ScriptBlockId') -join '')" -HostName $HostName -Time (Get-WfxValue $e 'TimeCreated') -Source "evt:$log" `
                                -Evidence ([ordered]@{ EventId = $id; Time = (Get-WfxValue $e 'TimeCreated'); Image = $img; Command = (Protect-WfxText $(if ($cl.Length -gt 3000) { $cl.Substring(0, 3000) + ' …' } else { $cl })); Parent = ((& $f $e 'ParentProcessName') + (& $f $e 'ParentImage')); User = ((& $f $e 'SubjectUserName') + (& $f $e 'User')) })))
                }
                if ($id -eq 4104 -or $id -eq 4688 -or $id -eq 1) {
                    $decoded = Get-WfxEncodedCommandPayload $cl
                    if ($decoded) {
                        foreach ($r in (Test-WfxCommandLine -CommandLine $decoded -Image 'powershell.exe')) {
                            if ($r.id -eq 'LOTL-PS-ENCODED') { continue }
                            $findings.Add((New-WfxFinding -Id $r.id -Title "$($r.title) (inside encoded command, event $id)" -Severity $r.severity -Confidence $r.confidence `
                                        -Category 'EventLog' -Technique $r.technique -Description $r.description -Recommendation $r.recommendation `
                                        -Entity "event:${id}:$($r.id):decoded:$(Get-WfxValue $e 'TimeCreated')" -HostName $HostName -Time (Get-WfxValue $e 'TimeCreated') -Source "evt:$log" `
                                        -Evidence ([ordered]@{ EventId = $id; DecodedCommand = (Protect-WfxText $(if ($decoded.Length -gt 2000) { $decoded.Substring(0, 2000) } else { $decoded })) })))
                        }
                    }
                }
                continue
            }
            if ($rule.rx -and -not (Test-WfxRegex $rule.rx $text)) { continue }
            if ($rule.rxExclude -and (Test-WfxRegex $rule.rxExclude $text)) { continue }
            $firstField = if (@($rule.fields).Count) { & $f $e (@($rule.fields)[0]) } else { '' }
            $findings.Add((New-WfxFinding -Id $rule.id -Title $rule.title -Severity $rule.severity -Confidence $rule.confidence `
                        -Category 'EventLog' -Technique $rule.technique -Description $rule.description -Recommendation $rule.recommendation `
                        -Entity "event:$($rule.id):$firstField" -HostName $HostName -Time (Get-WfxValue $e 'TimeCreated') -Source "evt:$log" `
                        -Evidence ([ordered]@{ EventId = $id; Log = $log; Time = (Get-WfxValue $e 'TimeCreated'); Details = (Protect-WfxText $(if ($text.Length -gt 3000) { $text.Substring(0, 3000) + ' …' } else { $text })) })))
        }
    }

    # ── Aggregate rules: failed-logon bursts and spraying (4625) ──
    $fails = @($events | Where-Object { (ConvertTo-WfxInt (Get-WfxValue $_ 'Id' 0)) -eq 4625 })
    if ($fails.Count -ge 10) {
        $bySource = $fails | Group-Object { & $f $_ 'IpAddress' }
        foreach ($g in $bySource) {
            $users = @($g.Group | ForEach-Object { & $f $_ 'TargetUserName' } | Where-Object { $_ } | Sort-Object -Unique)
            $src = if ($g.Name -and $g.Name -ne '-') { $g.Name } else { '(local / unknown source)' }
            $times = @($g.Group | ForEach-Object { ConvertTo-WfxDateTime (Get-WfxValue $_ 'TimeCreated') } | Where-Object { $_ } | Sort-Object)
            $span = if ($times.Count -ge 2) { "$(ConvertTo-WfxUtcString $times[0]) → $(ConvertTo-WfxUtcString $times[-1])" } else { '' }
            if ($g.Count -ge 10 -and $users.Count -ge 5) {
                $findings.Add((New-WfxFinding -Id 'EVT-4625-SPRAY' -Title "Password spraying from $src ($($users.Count) accounts, $($g.Count) failures)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'EventLog' -Technique @('T1110.003') `
                            -Description "Many failed logons for many different accounts from one source — the signature of password spraying." `
                            -Recommendation "Block the source, confirm no logon succeeded, and enforce lockout + MFA." `
                            -Entity "spray:$src" -HostName $HostName -Time $(if ($times.Count) { $times[0] } else { $null }) -Source 'evt:Security' `
                            -Evidence ([ordered]@{ Source = $src; Accounts = $users.Count; Failures = $g.Count; Window = $span; Sample = ($users | Select-Object -First 8) })))
            } elseif ($g.Count -ge 20 -and $users.Count -le 2) {
                $findings.Add((New-WfxFinding -Id 'EVT-4625-BRUTE' -Title "Brute force on $($users -join ',') from $src ($($g.Count) failures)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'EventLog' -Technique @('T1110') `
                            -Description "Many failed logons for one or two accounts from one source — a password-guessing attack." `
                            -Recommendation "Block the source and confirm whether a success (4624) followed." `
                            -Entity "brute:$src" -HostName $HostName -Time $(if ($times.Count) { $times[0] } else { $null }) -Source 'evt:Security' `
                            -Evidence ([ordered]@{ Source = $src; Accounts = $users; Failures = $g.Count; Window = $span })))
            }
        }
    }

    # ── Correlation: repeated failures (in the 24 h BEFORE) then a success, same user + source. O(n) via index. ──
    $failIdx = @{}
    $failBySrc = @{}
    foreach ($x in $fails) {
        $k = "$((& $f $x 'TargetUserName').ToLowerInvariant())|$(& $f $x 'IpAddress')"
        $t = ConvertTo-WfxDateTime (Get-WfxValue $x 'TimeCreated')
        if (-not $t) { continue }
        if (-not $failIdx.ContainsKey($k)) { $failIdx[$k] = New-Object System.Collections.Generic.List[datetime] }
        $failIdx[$k].Add($t)
        $fsrc = & $f $x 'IpAddress'
        if ($fsrc -and $fsrc -ne '-') {
            if (-not $failBySrc.ContainsKey($fsrc)) { $failBySrc[$fsrc] = New-Object System.Collections.Generic.List[object] }
            $failBySrc[$fsrc].Add([pscustomobject]@{ T = $t; U = (& $f $x 'TargetUserName').ToLowerInvariant() })
        }
    }
    $successes = @($events | Where-Object { (ConvertTo-WfxInt (Get-WfxValue $_ 'Id' 0)) -eq 4624 -and (& $f $_ 'LogonType') -in @('2', '3', '7', '10', '11') })
    $reported = @{}
    foreach ($s in $successes) {
        $src = & $f $s 'IpAddress'; $user = & $f $s 'TargetUserName'; $lt = & $f $s 'LogonType'
        $st = ConvertTo-WfxDateTime (Get-WfxValue $s 'TimeCreated')
        $srcIp = $null
        $isIp = $src -and [System.Net.IPAddress]::TryParse($src.Trim('[', ']'), [ref]$srcIp)   # '-' and host names are not addresses
        if ($isIp -and -not (Test-WfxPrivateIp $src) -and $lt -in @('10', '7')) {
            $findings.Add((New-WfxFinding -Id 'EVT-RDP-EXTERNAL' -Title "Remote logon for $user from external address $src" `
                        -Severity 'Medium' -Confidence 'Medium' -Category 'EventLog' -Technique @('T1021.001', 'T1133') `
                        -Description "An interactive/remote-desktop logon succeeded from a public IP. Internet-facing RDP is a frequent intrusion vector." `
                        -Recommendation "Confirm the source is expected; restrict RDP behind VPN/MFA." `
                        -Entity "rdp:${src}:$user" -HostName $HostName -Time $st -Source 'evt:Security' `
                        -Evidence ([ordered]@{ User = $user; Source = $src; LogonType = $lt; Time = (Get-WfxValue $s 'TimeCreated') })))
        }
        if (-not $user -or -not $st) { continue }
        $k = "$($user.ToLowerInvariant())|$src"
        # A password spray rarely fails against the account that finally works: also correlate by source address.
        if ((-not $failIdx.ContainsKey($k)) -and $isIp -and $failBySrc.ContainsKey($src) -and -not $reported.ContainsKey("src|$src")) {
            $priorSrc = @($failBySrc[$src] | Where-Object { $_.T -lt $st -and $_.T -ge $st.AddHours(-24) })
            $usersTried = @($priorSrc | ForEach-Object { $_.U } | Sort-Object -Unique)
            if ($priorSrc.Count -ge 8) {
                $reported["src|$src"] = $true
                $findings.Add((New-WfxFinding -Id 'EVT-4625-THEN-4624' -Title "Successful logon for $user from $src after $($priorSrc.Count) failed logons from that source ($($usersTried.Count) accounts tried, previous 24 h)" `
                            -Severity 'High' -Confidence 'High' -Category 'EventLog' -Technique @('T1110', 'T1110.003') `
                            -Description 'A source that was failing to log on with many attempts (password guessing or spraying) then logged on successfully. The account that succeeded is likely compromised.' `
                            -Recommendation 'Reset the account''s password, review what it did after the logon, and block the source.' `
                            -Entity "bruteok:${src}:$user" -HostName $HostName -Time $st -Source 'evt:Security' `
                            -Evidence ([ordered]@{ User = $user; Source = $src; LogonType = $lt; Failures = $priorSrc.Count; AccountsTried = $usersTried.Count; Time = (Get-WfxValue $s 'TimeCreated') })))
            }
            continue
        }
        if (-not $failIdx.ContainsKey($k) -or $reported.ContainsKey($k)) { continue }
        $prior = @($failIdx[$k] | Where-Object { $_ -lt $st -and $_ -ge $st.AddHours(-24) })
        if ($prior.Count -ge 8) {
            $reported[$k] = $true
            $findings.Add((New-WfxFinding -Id 'EVT-4625-THEN-4624' -Title "Successful logon for $user after $($prior.Count) failures (same source, previous 24 h)" `
                        -Severity 'High' -Confidence 'High' -Category 'EventLog' -Technique @('T1110') `
                        -Description "An account failed to log on repeatedly, then succeeded, from the same source — consistent with a guessed or sprayed password." `
                        -Recommendation "Reset the password, review the session's activity, and investigate the source host." `
                        -Entity "cracked:${src}:$user" -HostName $HostName -Time $st -Source 'evt:Security' `
                        -Evidence ([ordered]@{ User = $user; Source = $src; PriorFailures = $prior.Count; FirstFailure = (ConvertTo-WfxUtcString ($prior | Sort-Object | Select-Object -First 1)); SuccessTime = (ConvertTo-WfxUtcString $st) })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Exposure.ps1 =====
# Secrets-exposure & security-hygiene analyzer.
#
# This is a DEFENSIVE audit: it reports WHERE sensitive material or a misconfiguration exists and
# WHY it is a risk, so it can be remediated. It never emits secret values — matches are redacted to a
# type + length via Find-WfxSecret / Format-WfxSecret — and it does not read, copy, decrypt or parse
# credential stores (SAM/NTDS, browser login DBs, DPAPI, LSASS). Detecting exposure needs none of that.
#
# Input: normalized exposure records the collector builds:
#   { Kind, Path, Detail, Accessible, WorldReadable, Content (small text only, for secret scanning) }
# Kind ∈ GppCpassword, UnattendPassword, SensitiveHive, ShadowCopy, CredFileWorldReadable,
#        SecretInFile, SecretInEnv, SecretInHistory, AiKey, SshKeyUnprotected, AutoLogon.

function Invoke-WfxExposureAnalyzer {
    param([object[]]$Exposure, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $items = @($Exposure | Where-Object { $_ })
    if ($items.Count -eq 0) { return , $findings.ToArray() }

    foreach ($x in $items) {
        $kind = [string](Get-WfxValue $x 'Kind' '')
        $path = [string](Get-WfxValue $x 'Path' '')
        $detail = [string](Get-WfxValue $x 'Detail' '')
        $content = [string](Get-WfxValue $x 'Content' '')
        $entity = "exposure:$kind`:$path"

        switch ($kind) {
            'GppCpassword' {
                $findings.Add((New-WfxFinding -Id 'EXPO-GPP-CPASSWORD' -Title "Group Policy Preferences password (MS14-025): $(Get-WfxLeaf $path)" `
                            -Severity 'Critical' -Confidence 'High' -Category 'Exposure' -Technique @('T1552.006') `
                            -Description "A GPP XML file contains a cPassword. Microsoft published the decryption key in 2014, so any domain user can recover this password. It is one of the most reliable privilege-escalation findings in a Windows domain." `
                            -Recommendation "Remove the GPP that sets the password, change the affected account's password, and apply KB2962486. Use Windows LAPS to manage local admin passwords instead." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path })))
            }
            'UnattendPassword' {
                $findings.Add((New-WfxFinding -Id 'EXPO-UNATTEND-PASSWORD' -Title "Credential in an unattended-install file: $(Get-WfxLeaf $path)" `
                            -Severity 'High' -Confidence 'High' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "A Windows unattended-setup file contains a password (sometimes only Base64-wrapped, not encrypted). These are readable by anyone who can reach the file." `
                            -Recommendation "Remove the file or the password element, and rotate the account's password." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path })))
            }
            'SensitiveHive' {
                $acc = [bool](Get-WfxValue $x 'Accessible' $false)
                if (-not $acc) {
                    # A stray copy (RegBack / repair / Windows.old) with correct ACLs: worth knowing, not an exposure.
                    $findings.Add((New-WfxFinding -Id 'EXPO-HIVE-COPY' -Title "Stray copy of $detail present (ACL restricted)" `
                                -Severity 'Info' -Confidence 'High' -Category 'Exposure' -Technique @('T1003.002') `
                                -Description "A backup copy of a credential-bearing hive exists ($detail). Its permissions are restricted to administrators, so this is not an exposure — but it is an extra copy an admin-level attacker could take." `
                                -Recommendation "If the copy is not needed (e.g. old Windows.old), remove it with Disk Cleanup." `
                                -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path; Accessible = $false })))
                    break
                }
                $findings.Add((New-WfxFinding -Id 'EXPO-HIVE-ACCESS' -Title "$detail readable by non-administrators" `
                            -Severity $(if (Get-WfxValue $x 'Live' $false) { 'Critical' } else { 'High' }) -Confidence 'High' -Category 'Exposure' -Technique @('T1003.002') `
                            -Description "A registry hive or database that stores password material ($detail) is accessible to accounts that should not be able to read it. An attacker could copy it and recover hashes offline." `
                            -Recommendation "Restore correct ACLs (only SYSTEM/Administrators). If the file is a stray backup, remove it. Review how it became readable." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path; Accessible = $acc })))
            }
            'ShadowCopy' {
                $findings.Add((New-WfxFinding -Id 'EXPO-SHADOW-COPY' -Title "Volume shadow copies present ($detail)" `
                            -Severity 'Low' -Confidence 'Low' -Category 'Exposure' -Technique @('T1003.002') `
                            -Description "Volume Shadow Copies exist. They are useful for recovery, but also let an attacker with admin rights read otherwise-locked files such as the SAM hive. Reported for awareness, not as a compromise." `
                            -Recommendation "This is informational. Ensure admin access to the host is tightly controlled." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Detail = $detail })))
            }
            'CredFileWorldReadable' {
                $findings.Add((New-WfxFinding -Id 'EXPO-CREDFILE-READABLE' -Title "Credential file readable by other users: $(Get-WfxLeaf $path)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "A file that normally holds credentials ($detail) can be read by users other than its owner. On a shared machine this exposes those credentials." `
                            -Recommendation "Restrict the file's permissions to its owner, and rotate any credentials it contains." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path; Detail = $detail })))
            }
            'AutoLogon' {
                $findings.Add((New-WfxFinding -Id 'EXPO-AUTOLOGON' -Title "Automatic logon password stored in the registry" `
                            -Severity 'High' -Confidence 'High' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "A DefaultPassword is stored in clear text under Winlogon for automatic logon. Any local user can read it." `
                            -Recommendation "Disable auto-logon, or use the LSA-secrets method; rotate the password." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Account = $detail })))
            }
            'SshKeyUnprotected' {
                $findings.Add((New-WfxFinding -Id 'EXPO-SSH-KEY' -Title "Unencrypted SSH private key: $(Get-WfxLeaf $path)" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'Exposure' -Technique @('T1552.004') `
                            -Description "An SSH private key is stored without a passphrase. If this host or file is compromised, the key can be used directly to reach whatever it unlocks." `
                            -Recommendation "Add a passphrase (ssh-keygen -p), restrict the file's permissions, and rotate the key if exposure is suspected." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path })))
            }
            'AiKey' {
                $findings.Add((New-WfxFinding -Id 'AI-KEY-EXPOSED' -Title "AI provider API key in clear text: $detail" `
                            -Severity 'High' -Confidence 'High' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "An API key for an AI provider was found in clear text ($detail). These keys are billable and often broadly scoped; a leaked key can be abused immediately and run up cost." `
                            -Recommendation "Revoke and rotate the key with the provider, remove it from the file/variable, and store it in a secret manager." `
                            -Entity $entity -HostName $HostName -Source 'exposure' `
                            -Evidence ([ordered]@{ Where = $path; Type = $detail; Redacted = (Get-WfxValue $x 'Redacted' '') })))
            }
            { $_ -in @('SecretInFile', 'SecretInEnv', 'SecretInHistory') } {
                $where = switch ($kind) { 'SecretInFile' { "file $path" } 'SecretInEnv' { "environment variable $detail" } 'SecretInHistory' { "command history ($path)" } }
                # Prefer a redaction the collector already computed (so the raw value never enters a record
                # that might be persisted). Fall back to scanning Content when a caller supplied it directly.
                $preRedacted = @(Get-WfxValue $x 'Redacted' @() | Where-Object { $_ })
                $secrets = if ($content) { Find-WfxSecret $content } else { @() }
                $redactedList = if ($preRedacted.Count) { $preRedacted } else { @($secrets | ForEach-Object { "$($_.Type) (line $($_.Line)): $($_.Redacted)" }) }
                $label = if ($detail) { $detail } elseif ($secrets) { ($secrets | Select-Object -First 1).Type } elseif ($preRedacted.Count) { (($preRedacted[0] -split ' \(line| \(env')[0]) } else { 'credential-like string' }
                $sev = if ($kind -eq 'SecretInHistory') { 'Medium' } else { 'High' }
                $findings.Add((New-WfxFinding -Id "EXPO-$($kind.ToUpper())" -Title "Possible secret in $where" `
                            -Severity $sev -Confidence 'Low' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "Text that looks like a credential ($label) was found in $where. Clear-text secrets can be read by anyone (or any malware) with access to this location." `
                            -Recommendation "Confirm whether it is a live secret; if so, rotate it and move it to a secret store. Avoid passing secrets on the command line (they land in history and logs)." `
                            -Entity $entity -HostName $HostName -Source 'exposure' `
                            -Evidence ([ordered]@{ Where = $where; Type = $label; Redacted = $redactedList })))
            }
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Files.ps1 =====
# File and web-shell analyzer. Operates on normalized file records the collector produces:
#   { Path, Directory, Extension, Length, LastWrite, Content (first N KB, optional), Entropy (optional),
#     SignatureStatus, Zone (MOTW), InWebRoot }
# Content is only read for small text files in web roots / script locations, and is never emitted raw —
# only rule ids, a short redacted snippet and line numbers.

# Signatures that indicate a web shell. Each: id, regex, languages, description.
$script:WfxWebShellSigs = @(
    @{ Id = 'eval-request'; Rx = '(?i)\b(?:eval|assert|system|exec|shell_exec|passthru|popen|proc_open)\s*\(\s*(?:\$_(?:GET|POST|REQUEST|COOKIE|SERVER)|request|base64_decode|gzinflate|str_rot13)'; Desc = 'Executes attacker-supplied input from an HTTP request.' }
    @{ Id = 'aspx-process'; Rx = '(?i)(?:Process\.Start|ProcessStartInfo|cmd\.exe|/c\s|Server\.CreateObject\("WScript\.Shell"\)|Runtime\.getRuntime\(\)\.exec)'; Desc = 'Spawns an OS process from a web page.' }
    @{ Id = 'jsp-runtime'; Rx = '(?i)Runtime\.getRuntime\(\)\.exec|ProcessBuilder\(|<%@\s*page\s+import="java\.(?:io|lang)'; Desc = 'Java/JSP page that executes commands.' }
    @{ Id = 'webshell-named'; Rx = '(?i)\b(?:c99|r57|b374k|wso|weevely|china\s*chopper|antsword|behinder|godzilla|p0wny|reGeorg|tunna)\b'; Desc = 'Matches a known web-shell family name/marker.' }
    @{ Id = 'obf-eval'; Rx = '(?i)(?:eval|assert)\s*\(\s*(?:base64_decode|gzinflate|gzuncompress|str_rot13|convert_uudecode)\s*\('; Desc = 'Obfuscated code execution (packed/encoded payload).' }
    @{ Id = 'preg-e'; Rx = '(?i)preg_replace\s*\(\s*["''][^"'']*/[a-z]*e[a-z]*["'']'; Desc = 'preg_replace /e modifier — legacy PHP code execution.' }
    @{ Id = 'create-function'; Rx = '(?i)\b(?:create_function|call_user_func(?:_array)?)\s*\(\s*(?:\$_(?:GET|POST|REQUEST)|base64_decode)'; Desc = 'Builds and calls a function from request input.' }
)

function Invoke-WfxFileAnalyzer {
    param([object[]]$File, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $files = @($File | Where-Object { $_ })
    if ($files.Count -eq 0) { return , $findings.ToArray() }
    $executable = @('.exe', '.dll', '.scr', '.com', '.pif', '.cpl', '.sys', '.ocx')
    $script = @('.ps1', '.bat', '.cmd', '.vbs', '.vbe', '.js', '.jse', '.wsf', '.hta', '.jar')

    foreach ($rec in $files) {
        $path = [string](Get-WfxValue $rec 'Path' '')
        $ext = ([string](Get-WfxValue $rec 'Extension' '')).ToLowerInvariant()
        if (-not $ext -and $path) { $ext = [IO.Path]::GetExtension($path).ToLowerInvariant() }
        $content = [string](Get-WfxValue $rec 'Content' '')
        $inWeb = [bool](Get-WfxValue $rec 'InWebRoot' $false)
        $zone = [string](Get-WfxValue $rec 'Zone' '')
        $entity = "file:$path"

        # 1. Web shells
        if ($content -and ($inWeb -or $ext -in @('.php', '.asp', '.aspx', '.ashx', '.asmx', '.jsp', '.jspx', '.phtml', '.php5', '.cfm'))) {
            foreach ($sig in $script:WfxWebShellSigs) {
                $m = @(Get-WfxRxMatches $sig.Rx $content) | Select-Object -First 1
                if ($m) {
                    $line = ($content.Substring(0, $m.Index) -split "`n").Count
                    $snippet = Protect-WfxText ($content.Substring([Math]::Max(0, $m.Index - 10), [Math]::Min(90, $content.Length - [Math]::Max(0, $m.Index - 10))))
                    $nameOnly = $sig.Id -eq 'webshell-named'
                    $findings.Add((New-WfxFinding -Id 'FILE-WEBSHELL' -Title "Possible web shell in $(Get-WfxLeaf $path)" `
                                -Severity $(if ($nameOnly) { 'High' } else { 'Critical' }) -Confidence $(if ($nameOnly) { 'Low' } else { 'Medium' }) -Category 'File' -Technique @('T1505.003', 'T1190') `
                                -Description "A file served by a web application contains code that runs commands or executes request input ($($sig.Desc)). Web shells give attackers remote control of a server." `
                                -Recommendation "Isolate the web server, preserve the file, and review web access logs for requests to it. Determine how it was written (upload flaw, vulnerable app)." `
                                -Entity $entity -HostName $HostName -Time (Get-WfxValue $rec 'LastWrite') -Source 'file' `
                                -Evidence ([ordered]@{ Path = $path; Signature = $sig.Id; Line = $line; Snippet = $snippet; LastWrite = (Get-WfxValue $rec 'LastWrite') })))
                    break
                }
            }
        }

        # 2. Double extension masquerade (e.g. invoice.pdf.exe)
        if ($path -match '(?i)\.(pdf|doc|docx|xls|xlsx|jpg|jpeg|png|txt|csv|zip|rtf)\.(exe|scr|com|pif|bat|cmd|vbs|js|hta|lnk)$') {
            $findings.Add((New-WfxFinding -Id 'FILE-DOUBLE-EXT' -Title "Double-extension file: $(Get-WfxLeaf $path)" `
                        -Severity 'High' -Confidence 'High' -Category 'File' -Technique @('T1036') `
                        -Description "The file name hides its real type behind a fake document/image extension — a classic trick to get users to run malware." `
                        -Recommendation "Do not open it. Hash and analyze it, and find how it reached the host." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $rec 'LastWrite') -Source 'file' `
                        -Evidence ([ordered]@{ Path = $path; LastWrite = (Get-WfxValue $rec 'LastWrite') })))
        }

        # 3. Executable/script downloaded from the internet (Mark-of-the-Web), in a user folder
        if (($ext -in $executable -or $ext -in $script) -and $zone -match '3|4' -and (Test-WfxUserWritablePath $path)) {
            $findings.Add((New-WfxFinding -Id 'FILE-MOTW-EXEC' -Title "Internet-downloaded executable in a user folder: $(Get-WfxLeaf $path)" `
                        -Severity 'Medium' -Confidence 'Medium' -Category 'File' -Technique @('T1105', 'T1204.002') `
                        -Description "An executable or script carrying a Mark-of-the-Web (downloaded from the internet) sits in a user-writable folder." `
                        -Recommendation "Hash it and check reputation; confirm the user intended to download and run it." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $rec 'LastWrite') -Source 'file' `
                        -Evidence ([ordered]@{ Path = $path; Zone = $zone; HostUrl = (Get-WfxValue $rec 'HostUrl' ''); ReferrerUrl = (Get-WfxValue $rec 'ReferrerUrl' ''); SHA256 = (Get-WfxValue $rec 'SHA256'); LastWrite = (Get-WfxValue $rec 'LastWrite') })))
        }

        # 4. High-entropy executable in a user folder (packed/encrypted payload)
        $entropy = [double](Get-WfxValue $rec 'Entropy' 0)
        if ($ext -in $executable -and $entropy -ge 7.2 -and (Test-WfxUserWritablePath $path)) {
            $findings.Add((New-WfxFinding -Id 'FILE-PACKED' -Title "Highly compressed/encrypted executable: $(Get-WfxLeaf $path)" `
                        -Severity 'Low' -Confidence 'Low' -Category 'File' -Technique @('T1027') `
                        -Description "The executable's content is near-random (entropy $entropy/8), which is typical of packed or encrypted malware (but also of some legitimate installers)." `
                        -Recommendation "Submit the hash to threat intelligence; treat as suspicious if from an unknown source." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $rec 'LastWrite') -Source 'file' `
                        -Evidence ([ordered]@{ Path = $path; Entropy = $entropy; SHA256 = (Get-WfxValue $rec 'SHA256') })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}

# ─────────────────────────── ransomware note / mass-change heuristic ───────────────────────────
function Invoke-WfxRansomwareAnalyzer {
    <#
    .SYNOPSIS Flags ransom notes and bursts of newly-created encrypted-looking files.
    .PARAMETER Note  Candidate ransom-note files: { Path, Content }
    .PARAMETER RecentFile  Recently modified files: { Path, Extension, Entropy, LastWrite }
    #>
    param([object[]]$Note = @(), [object[]]$RecentFile = @(), [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    # Bounded gaps (.{0,200}) instead of .* keep this linear on hostile input; it also runs with a timeout.
    $noteRx = '(?i)(your files (?:have been|are) (?:encrypted|locked)|all your (?:files|data|documents)|decrypt(?:ion)?\s+(?:key|tool|service|id)|bitcoin|\.onion\b|recover (?:your )?files|how_to_(?:decrypt|recover)|readme.{0,200}decrypt|pay(?:ment)? .{0,200}(?:ransom|decrypt)|contact us.{0,200}(?:tox|telegram|protonmail|session id))'
    foreach ($n in @($Note | Where-Object { $_ })) {
        $c = [string](Get-WfxValue $n 'Content' '')
        $hits = @(Get-WfxRxMatches $noteRx $c).Count
        $copies = (ConvertTo-WfxInt (Get-WfxValue $n 'Copies' 1))
        if ($hits -ge 2 -or ($hits -ge 1 -and $copies -ge 5)) {
            $findings.Add((New-WfxFinding -Id 'RANSOM-NOTE' -Title "Possible ransom note: $(Get-WfxLeaf ([string](Get-WfxValue $n 'Path' '')))" `
                        -Severity 'Critical' -Confidence 'Medium' -Category 'Ransomware' -Technique @('T1486') `
                        -Description "A file reads like a ransomware ransom note (encryption claim, payment/decryption instructions)." `
                        -Recommendation "Isolate the host from the network immediately. Preserve evidence, identify the family, and check backups and other hosts." `
                        -Entity "file:$([string](Get-WfxValue $n 'Path' ''))" -HostName $HostName -Source 'file' `
                        -Evidence ([ordered]@{ Path = (Get-WfxValue $n 'Path'); Markers = $hits; CopiesOfSameName = $copies })))
        }
    }
    $recent = @($RecentFile | Where-Object { $_ })
    $encLike = @($recent | Where-Object {
            $e = ([string](Get-WfxValue $_ 'Extension' '')).ToLowerInvariant()
            $e -match '^\.(?:encrypt(?:ed)?|locked|crypt(?:ed)?|enc|crypto|[a-z0-9]{5,12})$' -and
            $e -notmatch '^\.(?:exe|dll|docx|xlsx|pptx|jpeg|config|manifest|nupkg|vsix|woff2|blob|cache|crdownload|partial|msix|appx|appxbundle|msixbundle|tgz|gzip|bzip2|lzma|webm|webp|heic|avif|opus|flac|ldb|sqlite|sqlite3|blockmap|pack|odex|asar|tflite|onnx|safetensors|parquet|zstd|bundle|backup)$' -and
            ([double](Get-WfxValue $_ 'Entropy' 0) -ge 7.4)
        })
    # A real encryption burst shows ONE unusual extension dominating, spread over many folders.
    $top = @($encLike | ForEach-Object { ([string](Get-WfxValue $_ 'Extension' '')).ToLowerInvariant() } | Group-Object | Sort-Object Count -Descending | Select-Object -First 1)
    $topFiles = if ($top.Count) { @($encLike | Where-Object { ([string](Get-WfxValue $_ 'Extension' '')).ToLowerInvariant() -eq $top[0].Name }) } else { @() }
    $dirs = @($topFiles | ForEach-Object { $d = [string](Get-WfxValue $_ 'Directory' ''); if (-not $d) { $d = Split-Path -Parent ([string](Get-WfxValue $_ 'Path' '')) }; $d } | Sort-Object -Unique)
    if ($topFiles.Count -ge 25 -and $dirs.Count -ge 3 -and ($topFiles.Count / [double]$encLike.Count) -ge 0.6) {
        $exts = $top
        $findings.Add((New-WfxFinding -Id 'RANSOM-MASS-ENCRYPT' -Title "Mass creation of encrypted-looking files ($($encLike.Count))" `
                    -Severity 'Critical' -Confidence 'Medium' -Category 'Ransomware' -Technique @('T1486') `
                    -Description "A large number of recently written files have random (high-entropy) content and uniform unusual extensions — consistent with active ransomware encryption." `
                    -Recommendation "Isolate the host now and stop the responsible process. Preserve a sample and the ransom note before any remediation." `
                    -Entity 'ransom:mass-encrypt' -HostName $HostName -Source 'file' `
                    -Evidence ([ordered]@{ Files = $topFiles.Count; Folders = $dirs.Count; TopExtension = ($exts.Name); Sample = (@($encLike | Select-Object -First 5 | ForEach-Object { Get-WfxValue $_ 'Path' })) })))
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/LogIntegrity.ps1 =====
# Event log integrity: signs that the logs themselves were tampered with, beyond the obvious "log cleared"
# events (1102 / 104, handled by the event rules).
#
#  * Time running backwards. Windows numbers records in the order they are written (RecordId), so their
#    timestamps should never go back. When a record written later carries a time well before its
#    predecessor, the system clock was set back while logging, the classic way to make later activity
#    blend into an earlier period or to break timelines.
#  * Silence in a busy log. A log that normally records every few minutes and then has nothing for hours,
#    while other logs on the same machine kept recording, suggests records were removed or logging was
#    stopped. Kept deliberately strict (busy log, long gap, other logs active) so a machine that was simply
#    switched off is not reported.
#  * Sysmon stopped or reconfigured (Sysmon events 4 and 16).
#
# Every check works on the events that were collected, so it only claims what those records show.

function Invoke-WfxLogIntegrityAnalyzer {
    [CmdletBinding()]
    param([object[]]$Event = @(), [string]$HostName = '')
    $out = New-Object System.Collections.Generic.List[object]
    $rows = foreach ($e in $Event) {
        if (-not $e) { continue }
        $t = ConvertTo-WfxDateTime (Get-WfxValue $e 'TimeCreated' (Get-WfxValue $e 'Time' $null))
        if (-not $t) { continue }
        [pscustomobject]@{ Log = [string](Get-WfxValue $e 'Log' ''); Computer = [string](Get-WfxValue $e 'Computer' ''); Id = ConvertTo-WfxInt (Get-WfxValue $e 'Id' 0)
            RecordId = [long](ConvertTo-WfxInt (Get-WfxValue $e 'RecordId' 0)); Time = $t; Fields = (Get-WfxValue $e 'Fields' $null) }
    }
    $rows = @($rows)

    # 1. Time running backwards, per log and machine, in write order.
    foreach ($g in @($rows | Where-Object { $_.RecordId -gt 0 -and $_.Log } | Group-Object Log, Computer)) {
        $seq = @($g.Group | Sort-Object RecordId)
        $hits = New-Object System.Collections.Generic.List[object]
        for ($i = 1; $i -lt $seq.Count; $i++) {
            $a = $seq[$i - 1]; $b = $seq[$i]
            # Close record numbers only: a large jump can be two generations of the log (an archive and the
            # current file), whose numbering restarted, not a clock change.
            if (($b.RecordId - $a.RecordId) -gt 50) { continue }
            $back = ($a.Time - $b.Time).TotalMinutes
            if ($back -gt 2) { $hits.Add([pscustomobject]@{ From = $a; To = $b; Minutes = [Math]::Round($back, 1) }) }
        }
        if (-not $hits.Count) { continue }
        $worst = @($hits | Sort-Object Minutes -Descending)[0]
        $log = $seq[0].Log
        $ev = [ordered]@{
            Log = $log; Computer = $seq[0].Computer; Occurrences = $hits.Count
            Record = "$($worst.From.RecordId) at $(ConvertTo-WfxUtcString $worst.From.Time)"
            NextRecord = "$($worst.To.RecordId) at $(ConvertTo-WfxUtcString $worst.To.Time)"
            WentBack = "$($worst.Minutes) minutes"
            Examples = (@($hits | Select-Object -First 5 | ForEach-Object { "$($_.From.RecordId) -> $($_.To.RecordId): back $($_.Minutes) min" }) -join '; ')
        }
        $out.Add((New-WfxFinding -Id 'LOG-TIME-BACKWARDS' -Title "Clock set back while logging: $log" -Severity 'Medium' -Confidence 'Medium' -Category 'Defense Evasion' `
                    -Technique @('T1070.006') -HostName $HostName -Time $worst.To.Time -Source "evt:$log" -Entity "log:$log" -Evidence $ev `
                    -Description "Records in $log are numbered in the order Windows wrote them, but record $($worst.To.RecordId) carries a time $($worst.Minutes) minutes earlier than record $($worst.From.RecordId) before it. The system clock was set back while the log was recording ($($hits.Count) time$(if ($hits.Count -ne 1) { 's' })). Attackers do this so later activity sorts into an earlier, innocent-looking period." `
                    -Recommendation 'Treat timestamps after the change with care; order this period by record number, not time. Look for who changed the time (Security 4616, System 1) and what ran just before.'))
    }

    # 2. Silence in a busy log while other logs kept recording.
    foreach ($g in @($rows | Where-Object { $_.Log -match '^(?:Security|Microsoft-Windows-Sysmon/Operational)$' } | Group-Object Log, Computer)) {
        $seq = @($g.Group | Sort-Object Time)
        if ($seq.Count -lt 50) { continue }
        $gaps = for ($i = 1; $i -lt $seq.Count; $i++) { ($seq[$i].Time - $seq[$i - 1].Time).TotalMinutes }
        $sorted = @($gaps | Sort-Object); $median = $sorted[[int][Math]::Floor($sorted.Count / 2)]
        if ($median -gt 10) { continue }          # not a busy log: long quiet spells are normal
        $log = $seq[0].Log; $comp = $seq[0].Computer
        $others = @($rows | Where-Object { $_.Log -ne $log -and (-not $comp -or -not $_.Computer -or $_.Computer -eq $comp) })
        for ($i = 1; $i -lt $seq.Count; $i++) {
            $a = $seq[$i - 1].Time; $b = $seq[$i].Time; $hours = ($b - $a).TotalHours
            if ($hours -lt 6) { continue }
            $during = @($others | Where-Object { $_.Time -gt $a -and $_.Time -lt $b })
            $logsDuring = @($during | ForEach-Object Log | Select-Object -Unique)
            if ($during.Count -lt 20 -or $logsDuring.Count -lt 1) { continue }
            $ev = [ordered]@{ Log = $log; Computer = $comp; LastBefore = (ConvertTo-WfxUtcString $a); FirstAfter = (ConvertTo-WfxUtcString $b); Hours = [Math]::Round($hours, 1)
                UsualInterval = "$([Math]::Round($median, 1)) minutes"; OtherLogsDuring = "$($during.Count) records in $($logsDuring -join ', ')" }
            $out.Add((New-WfxFinding -Id 'LOG-SILENT-GAP' -Title "$log recorded nothing for $([Math]::Round($hours, 1)) hours while other logs were active" -Severity 'Low' -Confidence 'Low' -Category 'Defense Evasion' `
                        -Technique @('T1070.001') -HostName $HostName -Time $b -Source "evt:$log" -Entity "log:${log}:$(ConvertTo-WfxUtcString $a)" -Evidence $ev `
                        -Description "$log usually records every $([Math]::Round($median, 1)) minutes, but has no collected records between $(ConvertTo-WfxUtcString $a) and $(ConvertTo-WfxUtcString $b) UTC, while $($during.Count) records were written to other logs. Records may have been deleted selectively, or logging was stopped for that period." `
                        -Recommendation 'Compare with a forwarded copy (SIEM / WEF) for the same period; check for the event log service or audit policy being changed, and for tools that delete single records.'))
        }
    }

    # 3. Sysmon stopped or reconfigured.
    foreach ($r in @($rows | Where-Object { $_.Log -match 'Sysmon' -and $_.Id -in 4, 16 })) {
        $f = $r.Fields; $g = { param($n) [string](Get-WfxValue $f $n '') }
        if ($r.Id -eq 4 -and (& $g 'State') -match '(?i)stopped') {
            $out.Add((New-WfxFinding -Id 'LOG-SYSMON-STOPPED' -Title 'Sysmon service stopped' -Severity 'High' -Confidence 'Medium' -Category 'Defense Evasion' -Technique @('T1562.001') `
                        -HostName $HostName -Time $r.Time -Source "evt:$($r.Log)" -Entity "sysmon:stopped:$(ConvertTo-WfxUtcString $r.Time)" -Evidence ([ordered]@{ EventId = 4; Time = (ConvertTo-WfxUtcString $r.Time); State = (& $g 'State'); Version = (& $g 'Version') }) `
                        -Description 'Sysmon reported that its service stopped. Unless this was an upgrade or a planned change, process, network and file telemetry stopped from this moment.' `
                        -Recommendation 'Check who stopped it (System 7036/7040, Security 4688 for sc.exe or fltmc.exe) and what happened while it was down.'))
        } elseif ($r.Id -eq 16) {
            $out.Add((New-WfxFinding -Id 'LOG-SYSMON-CONFIG' -Title 'Sysmon configuration changed' -Severity 'Medium' -Confidence 'Low' -Category 'Defense Evasion' -Technique @('T1562.001') `
                        -HostName $HostName -Time $r.Time -Source "evt:$($r.Log)" -Entity "sysmon:config:$(ConvertTo-WfxUtcString $r.Time)" -Evidence ([ordered]@{ EventId = 16; Time = (ConvertTo-WfxUtcString $r.Time); Configuration = (& $g 'Configuration'); Hash = (& $g 'ConfigurationFileHash') }) `
                        -Description 'The Sysmon configuration was replaced. An attacker can load a configuration that excludes their tools, keeping Sysmon running but blind.' `
                        -Recommendation 'Compare the configuration hash with the one you deploy; if it differs, recover the file and see what it excludes.'))
        }
    }
    , $out.ToArray()
}


# ===== Analyzers/Network.ps1 =====
# Network and DNS analyzers. Pure functions over normalized data.
#   Connection: Protocol, LocalAddress, LocalPort, RemoteAddress, RemotePort, State, Pid, Process
#   DnsEntry:   Name, Type, Data, (optional) Count
#   Beacon samples: { Remote, Times[] } (connection timestamps to one destination)

function Invoke-WfxNetworkAnalyzer {
    param([object[]]$Connection, [string]$HostName = '', [hashtable]$DnsMap = @{})
    $findings = New-Object System.Collections.Generic.List[object]
    $conns = @($Connection | Where-Object { $_ })
    if ($conns.Count -eq 0) { return , $findings.ToArray() }

    $dns = Get-WfxRulePack -Name 'dns'
    $ai = Get-WfxRulePack -Name 'ai'
    $tunnelHosts = @($dns.tunnelDomains)
    $aiPorts = @($ai.runtimePorts)

    # Listeners on all interfaces (0.0.0.0 / ::) for non-standard ports. Default Windows listeners are a
    # baseline, not a finding: well-known service ports, and the RPC dynamic range (49152-65535) when owned by
    # core Windows processes (lsass, wininit, services, spoolsv, svchost, System).
    $commonListen = @(80, 443, 135, 139, 445, 3389, 5985, 5986, 47001, 53, 88, 389, 636, 464, 3268, 3269, 25, 110, 143, 993, 995, 1433, 3306, 5432, 22,
        5040, 7680, 5357, 5358, 2869, 1801, 2103, 2105, 2107, 9389, 5722, 593, 6602)
    $coreProcs = @('system', 'svchost', 'lsass', 'wininit', 'services', 'spoolsv', 'svchost.exe', 'lsass.exe', 'wininit.exe', 'services.exe', 'spoolsv.exe', 'dns', 'dns.exe', 'ismserv', 'ntfrs', 'dfsrs', 'dfsrs.exe')
    $seenListen = @{}
    foreach ($c in $conns) {
        $state = [string](Get-WfxValue $c 'State' '')
        $laddr = [string](Get-WfxValue $c 'LocalAddress' '')
        $lport = (ConvertTo-WfxInt (Get-WfxValue $c 'LocalPort' 0))
        $proc = [string](Get-WfxValue $c 'Process' '')
        $pid2 = Get-WfxValue $c 'Pid' '?'
        if ($state -match '^Listen' -and ($laddr -eq '0.0.0.0' -or $laddr -eq '::' -or $laddr -eq '[::]' -or $laddr -eq '*')) {
            $isCoreDynamic = ($lport -ge 49152 -and $coreProcs -contains $proc.ToLowerInvariant())
            $lk = "${lport}|$pid2"   # one finding per port+process, not one per address family
            if ($commonListen -notcontains $lport -and -not $isCoreDynamic -and -not $seenListen.ContainsKey($lk)) {
                $seenListen[$lk] = $true
                $isAi = $aiPorts -contains $lport
                $findings.Add((New-WfxFinding -Id ($(if ($isAi) { 'AI-OLLAMA-EXPOSED' } else { 'NET-LISTENER-EXPOSED' })) `
                            -Title ($(if ($isAi) { "Local AI runtime API exposed on all interfaces (port $lport)" } else { "Process listening on all interfaces on non-standard port $lport" })) `
                            -Severity ($(if ($isAi) { 'Medium' } else { 'Low' })) -Confidence ($(if ($isAi) { 'Medium' } else { 'Low' })) -Category 'Network' `
                            -Technique @('T1133') `
                            -Description ($(if ($isAi) { "A local AI model runtime is listening on 0.0.0.0:$lport. Its API is usually unauthenticated, so anyone who can reach the port can use the model and run it at this host's expense." } else { "A process is listening for connections from any network on an unusual port. Confirm it is an expected service and not a backdoor or exposed dev server." })) `
                            -Recommendation ($(if ($isAi) { "Bind the runtime to 127.0.0.1 and restrict the port with the firewall." } else { "Identify the process and confirm the service is intended to be network-reachable." })) `
                            -Entity "listen:${lport}:$proc" -HostName $HostName -Source 'network' `
                            -Evidence ([ordered]@{ Pid = $pid2; Process = $proc; Local = "${laddr}:$lport"; Protocol = (Get-WfxValue $c 'Protocol' 'TCP') })))
            }
        }

        # Established connections to public addresses on suspicious / tunneling ports or hosts.
        $raddr = [string](Get-WfxValue $c 'RemoteAddress' '')
        $rport = (ConvertTo-WfxInt (Get-WfxValue $c 'RemotePort' 0))
        if ($state -match 'Establish' -and $raddr -and -not (Test-WfxPrivateIp $raddr)) {
            $rhost = [string](Get-WfxValue $c 'RemoteHost' '')
            if (-not $rhost -and $DnsMap.ContainsKey($raddr)) { $rhost = (@($DnsMap[$raddr]) -join ',') }
            $rnames = @($rhost -split ',' | Where-Object { $_ } | ForEach-Object { $_.Trim().TrimEnd('.').ToLowerInvariant() })
            $tun = @($tunnelHosts | Where-Object { $t = $_.TrimStart('.').ToLowerInvariant(); @($rnames | Where-Object { $_ -eq $t -or $_.EndsWith(".$t") }).Count }) | Select-Object -First 1
            if ($tun) {
                $findings.Add((New-WfxFinding -Id 'NET-TUNNEL-SERVICE' -Title "Connection to a tunneling service ($tun)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Network' -Technique @('T1572', 'T1090') `
                            -Description "A connection to an ad-hoc tunneling service was found. $($dns.tunnelNote)" `
                            -Recommendation "Identify the process and what it exposes; block the service if unauthorized." `
                            -Entity "conn:${raddr}:$rport" -HostName $HostName -Source 'network' `
                            -Evidence ([ordered]@{ Pid = $pid2; Process = $proc; Remote = "$rhost ($raddr):$rport" })))
            }
            if ($rport -in @(4444, 5555, 1337, 31337, 8081, 6666, 6667, 9001, 9002, 1234, 12345, 50050)) {
                $findings.Add((New-WfxFinding -Id 'NET-SUSPICIOUS-PORT' -Title "Connection to a commonly malicious port ($rport)" `
                            -Severity 'Medium' -Confidence 'Low' -Category 'Network' -Technique @('T1571', 'T1071') `
                            -Description "An outbound connection targets a port frequently used by C2 frameworks and reverse shells (e.g. Metasploit 4444, Cobalt Strike 50050)." `
                            -Recommendation "Identify the process and destination reputation; this is suggestive, not conclusive." `
                            -Entity "conn:${raddr}:$rport" -HostName $HostName -Source 'network' `
                            -Evidence ([ordered]@{ Pid = $pid2; Process = $proc; Remote = "${raddr}:$rport" })))
            }
            # A non-browser process talking to an AI provider API (billable key use / possible agent exfil path).
            $rhostL = $rhost.ToLowerInvariant()
            if ($rhost -and ($ai.apiDomains | Where-Object { $d = $_.ToLowerInvariant(); @($rnames | Where-Object { $_ -eq $d -or $_.EndsWith(".$d") }).Count })) {
                $leaf = (Get-WfxLeaf $proc).ToLowerInvariant()
                if ($leaf -and $leaf -notin @('chrome.exe', 'msedge.exe', 'firefox.exe', 'brave.exe', 'opera.exe')) {
                    $findings.Add((New-WfxFinding -Id 'AI-API-NONBROWSER' -Title "Non-browser process contacting an AI provider API: $leaf" `
                                -Severity 'Info' -Confidence 'Low' -Category 'AI' -Technique @() `
                                -Description "A process other than a web browser is talking to an AI provider's API. Usually benign (a CLI or app), but worth noting when an API key or data exposure is in scope." `
                                -Recommendation "Confirm the tool and that it uses an authorized API key." `
                                -Entity "conn:${leaf}:$rhostL" -HostName $HostName -Source 'network' `
                                -Evidence ([ordered]@{ Pid = $pid2; Process = $leaf; Remote = $rhost })))
                }
            }
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}

function Invoke-WfxDnsAnalyzer {
    param([object[]]$DnsEntry, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $entries = @($DnsEntry | Where-Object { $_ })
    if ($entries.Count -eq 0) { return , $findings.ToArray() }
    $dns = Get-WfxRulePack -Name 'dns'

    foreach ($e in $entries) {
        $fqdn = ([string](Get-WfxValue $e 'Name' '')).Trim('.').ToLowerInvariant()
        if (-not $fqdn -or $fqdn -notmatch '\.') { continue }
        $labels = $fqdn -split '\.'
        $tld = '.' + $labels[-1]
        $reg = if ($labels.Count -ge 2) { $labels[-2] } else { $labels[-1] }

        if ($dns.suspiciousTlds -contains $tld) {
            $findings.Add((New-WfxFinding -Id 'DNS-SUSPICIOUS-TLD' -Title "Lookup of a high-risk TLD domain: $fqdn" `
                        -Severity 'Low' -Confidence 'Low' -Category 'DNS' -Technique @('T1071.004') `
                        -Description "The domain uses a top-level domain disproportionately associated with malware and abuse ($tld)." `
                        -Recommendation "Check the domain's reputation and which process resolved it." `
                        -Entity "dns:$fqdn" -HostName $HostName -Source 'dns' -Evidence ([ordered]@{ Name = $fqdn; TLD = $tld })))
        }
        if ($dns.tunnelDomains | Where-Object { $t = $_.TrimStart('.').ToLowerInvariant(); $fqdn -eq $t -or $fqdn.EndsWith(".$t") }) {
            $findings.Add((New-WfxFinding -Id 'DNS-TUNNEL-SERVICE' -Title "Lookup of a tunneling service: $fqdn" `
                        -Severity 'Medium' -Confidence 'Medium' -Category 'DNS' -Technique @('T1572') `
                        -Description "A tunneling/relay service domain was resolved. $($dns.tunnelNote)" `
                        -Recommendation "Identify the process and whether a tunnel was established." `
                        -Entity "dns:$fqdn" -HostName $HostName -Source 'dns' -Evidence ([ordered]@{ Name = $fqdn })))
        }
        if ($dns.pasteSites | Where-Object { $fqdn -eq $_ -or $fqdn.EndsWith('.' + $_) }) {
            $findings.Add((New-WfxFinding -Id 'DNS-PASTE-SITE' -Title "Lookup of a paste / anonymous-file site: $fqdn" `
                        -Severity 'Low' -Confidence 'Low' -Category 'DNS' -Technique @('T1105', 'T1567') `
                        -Description "A text-paste or anonymous file-sharing site was resolved. $($dns.pasteNote)" `
                        -Recommendation "Check which process accessed it and whether a payload was fetched or data uploaded." `
                        -Entity "dns:$fqdn" -HostName $HostName -Source 'dns' -Evidence ([ordered]@{ Name = $fqdn })))
        }
        # DGA-like: long, high-entropy registrable label, few vowels.
        $entropy = Get-WfxEntropy $reg
        $vowels = ([regex]::Matches($reg, '[aeiou]')).Count
        $digits = ([regex]::Matches($reg, '\d')).Count
        if ($reg.Length -ge 12 -and $entropy -ge 3.6 -and ($vowels / [double]$reg.Length) -lt 0.28 -and $reg -notmatch '^(?:xn--|www\d*$)') {
            $findings.Add((New-WfxFinding -Id 'DNS-DGA-LIKE' -Title "High-entropy domain (possible DGA): $fqdn" `
                        -Severity 'Medium' -Confidence 'Low' -Category 'DNS' -Technique @('T1568.002', 'T1071.004') `
                        -Description "The domain's name looks algorithmically generated (long, random-looking, few vowels). Malware families use domain-generation algorithms for C2 that is hard to block by name." `
                        -Recommendation "Check reputation and resolution history; correlate with connections from the resolving process." `
                        -Entity "dns:$fqdn" -HostName $HostName -Source 'dns' `
                        -Evidence ([ordered]@{ Name = $fqdn; Entropy = $entropy; Length = $reg.Length; Digits = $digits })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}

function Invoke-WfxBeaconAnalyzer {
    <#
    .SYNOPSIS Flags regular, low-jitter connections to one destination (C2 beaconing).
    .PARAMETER Beacon  Objects with Remote (string) and Times (datetime[] of connection events).
    #>
    param([object[]]$Beacon, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($b in @($Beacon | Where-Object { $_ })) {
        $times = @(Get-WfxValue $b 'Times' @() | ForEach-Object { [datetime]$_ } | Sort-Object)
        if ($times.Count -lt 6) { continue }
        $deltas = for ($i = 1; $i -lt $times.Count; $i++) { ($times[$i] - $times[$i - 1]).TotalSeconds }
        $deltas = @($deltas | Where-Object { $_ -gt 0 })
        if ($deltas.Count -lt 5) { continue }
        $mean = ($deltas | Measure-Object -Average).Average
        if ($mean -lt 1) { continue }
        $var = ($deltas | ForEach-Object { ($_ - $mean) * ($_ - $mean) } | Measure-Object -Average).Average
        $cv = [Math]::Sqrt($var) / $mean      # coefficient of variation: low = very regular
        if ($cv -le 0.18) {
            $sev = if ($mean -ge 30 -and $mean -le 3600) { 'High' } else { 'Medium' }
            $findings.Add((New-WfxFinding -Id 'NET-BEACON' -Title ("Regular beaconing to $([string](Get-WfxValue $b 'Remote' '?')) (~{0:N0}s)" -f $mean) `
                        -Severity $sev -Confidence 'Medium' -Category 'Network' -Technique @('T1071.001', 'T1573') `
                        -Description "Connections to this destination arrive at a near-constant interval with very little variation ($($deltas.Count + 1) connections, jitter $([Math]::Round($cv*100))%). Regular, low-jitter check-ins are a hallmark of C2 beaconing." `
                        -Recommendation "Identify the process and destination; check the destination's reputation. Legitimate software also polls on a schedule, so confirm before acting." `
                        -Entity "beacon:$([string](Get-WfxValue $b 'Remote' '?'))" -HostName $HostName -Source 'network' `
                        -Evidence ([ordered]@{ Remote = (Get-WfxValue $b 'Remote'); Connections = $times.Count; MeanSeconds = [Math]::Round($mean, 1); JitterPct = [Math]::Round($cv * 100, 1) })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Persistence.ps1 =====
# Persistence analyzer. Operates on normalized autostart entries:
#   { Kind, Name, Command, Path, Location, User, Enabled, SignatureStatus }
# Kind ∈ RunKey, Startup, Service, ScheduledTask, WmiSubscription, Winlogon, AppInit, ImageFileExecution,
#         ComHijack, LsaProvider, BootExecute, Driver, OfficeAddin, BrowserExtension.

function Invoke-WfxPersistenceAnalyzer {
    param([object[]]$Autostart, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $items = @($Autostart | Where-Object { $_ })
    if ($items.Count -eq 0) { return , $findings.ToArray() }

    $threats = Get-WfxRulePack -Name 'threats'
    $drivers = @($threats.vulnerableDrivers | ForEach-Object { $_.ToLowerInvariant() })

    foreach ($a in $items) {
        $kind = [string](Get-WfxValue $a 'Kind' '')
        $name = [string](Get-WfxValue $a 'Name' '')
        $cmd = [string](Get-WfxValue $a 'Command' '')
        $path = [string](Get-WfxValue $a 'Path' '')
        if (-not $path -and $cmd -and $kind -ne 'RunMRU') { $path = Get-WfxImagePath $cmd }
        $loc = [string](Get-WfxValue $a 'Location' '')
        $sig = [string](Get-WfxValue $a 'SignatureStatus' '')
        $entity = "autostart:$kind`:$name"
        $userWritable = (Test-WfxUserWritablePath $path)
        $trusted = Test-WfxTrustedSignature $sig
        $where = if ($kind -eq 'RunMRU') { 'typed into the Run dialog' } else { "in $kind persistence" }

        # Command-line rules apply to the autostart command too (encoded PS, proxy exec, etc.)
        foreach ($r in (Test-WfxCommandLine -CommandLine $cmd -Image $path)) {
            $findings.Add((New-WfxFinding -Id $r.id -Title "$($r.title) ($where)" -Severity $r.severity -Confidence $r.confidence `
                        -Category $(if ($kind -eq 'RunMRU') { 'Execution' } else { 'Persistence' }) -Technique $r.technique -Description $r.description -Recommendation $r.recommendation `
                        -Entity $entity -HostName $HostName -Source 'persistence' `
                        -Evidence ([ordered]@{ Kind = $kind; Name = $name; Location = $loc; Command = (Protect-WfxText $cmd) })))
        }

        # High-signal persistence locations are suspicious on their own.
        $highSignal = @{
            'WmiSubscription'     = @('T1546.003', 'A WMI event subscription runs code when a system event fires. Rarely legitimate and a favourite stealthy persistence mechanism.')
            'AppInit'             = @('T1546.010', 'AppInit_DLLs loads a DLL into almost every process. Legacy and heavily abused.')
            'ImageFileExecution'  = @('T1546.012', 'An Image File Execution Options debugger hijacks a program so an attacker binary runs in its place (also used to disable security tools).')
            'ComHijack'           = @('T1546.015', 'A COM object was redirected to a user-controlled DLL/command — a quiet persistence and defense-evasion trick.')
            'LsaProvider'         = @('T1547.004', 'A security/authentication package was registered with LSA, which can capture credentials and persist.')
            'Winlogon'            = @('T1547.004', 'A Winlogon helper (Shell/Userinit/Notify) was modified to run extra code at logon.')
            'BootExecute'         = @('T1547.001', 'A BootExecute entry runs before the user logs on and is very rarely changed legitimately.')
        }
        if ($highSignal.ContainsKey($kind)) {
            $info = $highSignal[$kind]
            $sev = if (($userWritable -and -not $trusted) -or ($sig -and -not $trusted)) { 'High' } else { 'Medium' }
            $findings.Add((New-WfxFinding -Id "PERSIST-$($kind.ToUpper())" -Title "$kind persistence: $name" -Severity $sev -Confidence 'Medium' `
                        -Category 'Persistence' -Technique @($info[0]) -Description $info[1] `
                        -Recommendation "Confirm this entry is expected; capture and analyze the referenced code before removing it." `
                        -Entity $entity -HostName $HostName -Source 'persistence' `
                        -Evidence ([ordered]@{ Kind = $kind; Name = $name; Location = $loc; Command = (Protect-WfxText $cmd); Path = $path; Signature = $sig })))
        }

        # Run keys / startup / services / tasks pointing at user-writable or unsigned binaries.
        # Validly-signed programs installed per-user (OneDrive, Teams, …) are normal; they are kept as low-weight
        # context because signed binaries in user folders are also used for DLL side-loading.
        $unsigned = [bool]($sig -and -not $trusted)
        if ($kind -in @('RunKey', 'Startup', 'Service', 'ScheduledTask') -and ($userWritable -or $unsigned)) {
            $tech = switch ($kind) { 'RunKey' { 'T1547.001' } 'Startup' { 'T1547.001' } 'Service' { 'T1543.003' } 'ScheduledTask' { 'T1053.005' } }
            $signedOk = $trusted -and $userWritable
            $findings.Add((New-WfxFinding -Id $(if ($signedOk) { "PERSIST-$($kind.ToUpper())-USERPATH-SIGNED" } else { "PERSIST-$($kind.ToUpper())-SUSPECT" }) `
                        -Title $(if ($signedOk) { "$kind autostart runs a signed program from a user folder: $name" } else { "$kind autostart from an untrusted location: $name" }) `
                        -Severity $(if ($signedOk) { 'Info' } else { 'Medium' }) -Confidence $(if ($signedOk) { 'Low' } else { 'Medium' }) -Category 'Persistence' -Technique @($tech) `
                        -Description $(if ($signedOk) { "A $kind entry starts a validly signed program from a user-writable folder. Usually a per-user install; listed for completeness (signed programs in user folders can be abused for DLL side-loading)." } else { "A $kind autostart entry runs a program that is unsigned or located in a user-writable folder — a common way malware survives reboot." }) `
                        -Recommendation "Verify the program's publisher and purpose; remove if not legitimate." `
                        -Entity $entity -HostName $HostName -Source 'persistence' `
                        -Evidence ([ordered]@{ Kind = $kind; Name = $name; Location = $loc; Path = $path; Signature = $sig; Command = (Protect-WfxText $cmd) })))
        }

        # Known-vulnerable driver used for BYOVD.
        if ($kind -eq 'Driver') {
            $leaf = (Get-WfxLeaf $path).ToLowerInvariant()
            if ($drivers -contains $leaf) {
                $findings.Add((New-WfxFinding -Id 'PERSIST-VULN-DRIVER' -Title "Known-vulnerable driver installed: $leaf" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Persistence' -Technique @('T1068', 'T1562.001') `
                            -Description "A driver known to be abused in bring-your-own-vulnerable-driver attacks is present. $($threats.vulnerableDriverNote)" `
                            -Recommendation "Confirm the driver is required. If not, remove it; attackers use these to disable EDR and gain kernel access." `
                            -Entity $entity -HostName $HostName -Source 'persistence' `
                            -Evidence ([ordered]@{ Driver = $leaf; Path = $path; Signature = $sig })))
            } elseif ($userWritable) {
                $findings.Add((New-WfxFinding -Id 'PERSIST-DRIVER-USERPATH' -Title "Driver loaded from a user-writable path: $(Get-WfxLeaf $path)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Persistence' -Technique @('T1014') `
                            -Description "A kernel driver is loaded from an unusual, user-writable location. Legitimate drivers live under System32\drivers." `
                            -Recommendation "Verify the driver's signature and origin." `
                            -Entity $entity -HostName $HostName -Source 'persistence' -Evidence ([ordered]@{ Path = $path; Signature = $sig })))
            }
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Posture.ps1 =====
# Security-posture analyzer. Turns the posture object from Get-WfxSecurityData into findings about
# defensive gaps: disabled/evaded AV, suspicious Defender exclusions (a common tamper IOC), missing
# audit logging (a visibility gap, so "no findings" is interpreted correctly), weak RDP, and LSASS
# protection. These are hardening/visibility findings, not proof of compromise — severities reflect that.

function Invoke-WfxPostureAnalyzer {
    param($Posture, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    if (-not $Posture) { return , $findings.ToArray() }

    $def = Get-WfxValue $Posture 'Defender' $null
    $thirdParty = @(Get-WfxValue $Posture 'ThirdPartyAV' @())
    $hasThirdParty = $thirdParty.Count -gt 0

    # ── Defender: real-time protection / AV off with no third-party engine ──
    if ($def -and (Get-WfxValue $def 'Installed' $false)) {
        $rtp = Get-WfxValue $def 'RealTimeProtectionEnabled' $null
        $av = Get-WfxValue $def 'AntivirusEnabled' $null
        if (($rtp -eq $false -or $av -eq $false) -and -not $hasThirdParty) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-AV-DISABLED' -Title 'Antivirus real-time protection is OFF (no other AV present)' `
                        -Severity 'High' -Confidence 'High' -Category 'Posture' -Technique @('T1562.001') `
                        -Description "Microsoft Defender real-time/antivirus protection is disabled and no third-party AV is registered. The host is running without active malware protection — this is often the first thing an intruder disables." `
                        -Recommendation "Re-enable real-time protection, confirm it was not disabled by malware or GPO, and review when and by what it was turned off." `
                        -Entity 'posture:defender:rtp' -HostName $HostName -Source 'posture' `
                        -Evidence ([ordered]@{ RealTimeProtection = $rtp; AntivirusEnabled = $av; ThirdPartyAV = $thirdParty })))
        }
        # Tamper protection off
        if ((Get-WfxValue $def 'TamperProtectionEnabled' $null) -eq $false) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-TAMPER-OFF' -Title 'Defender Tamper Protection is off' `
                        -Severity 'Low' -Confidence 'Medium' -Category 'Posture' -Technique @('T1562.001') `
                        -Description "Tamper Protection is disabled, so Defender settings can be changed by local admin tools or malware without resistance." `
                        -Recommendation "Enable Tamper Protection (Windows Security > Virus & threat protection settings)." `
                        -Entity 'posture:defender:tamper' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ TamperProtection = $false })))
        }
        # Stale signatures
        $sigAge = Get-WfxValue $def 'SignatureAgeDays' $null
        if ($null -ne $sigAge -and [int]$sigAge -ge 7) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-SIG-STALE' -Title "Antivirus signatures are $sigAge days old" `
                        -Severity 'Medium' -Confidence 'High' -Category 'Posture' -Technique @('T1562.001') `
                        -Description "Defender definitions have not updated in $sigAge days. Detection of recent threats is degraded; updates may be blocked (no connectivity, disabled service, or deliberate tampering)." `
                        -Recommendation "Force a signature update and investigate why updates stopped." `
                        -Entity 'posture:defender:sigage' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ SignatureAgeDays = $sigAge })))
        }
        # Suspicious exclusions — attackers add these to carve out a safe folder for their tools.
        $exPaths = @(Get-WfxValue $def 'ExclusionPath' @())
        foreach ($ex in $exPaths) {
            $broadOrWritable = ($ex -match '(?i)^[a-z]:\\?$' -or $ex -match '(?i)\\$' -and $ex.Length -le 4) -or (Test-WfxUserWritablePath $ex) -or ($ex -match '(?i)\\(users|temp|tmp|downloads|appdata|programdata|public)\b')
            if ($broadOrWritable) {
                $findings.Add((New-WfxFinding -Id 'POSTURE-DEFENDER-EXCLUSION' -Title "Suspicious Defender exclusion: $ex" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'Posture' -Technique @('T1562.001') `
                            -Description "Defender is configured to ignore '$ex'. Broad or user-writable exclusions are a classic way for an attacker to make a folder where their tools won't be scanned. Verify it was set intentionally." `
                            -Recommendation "Confirm the business reason for this exclusion; remove it if unexplained and scan the excluded location." `
                            -Entity "posture:defender:exclusion:$ex" -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ Exclusion = $ex })))
            }
        }
        $exProc = @(Get-WfxValue $def 'ExclusionProcess' @())
        foreach ($ep in $exProc) {
            if ($ep -match '(?i)(powershell|cmd|wscript|cscript|mshta|rundll32|regsvr32|python|node)\b') {
                $findings.Add((New-WfxFinding -Id 'POSTURE-DEFENDER-PROC-EXCLUSION' -Title "Defender process exclusion for an interpreter: $ep" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'Posture' -Technique @('T1562.001') `
                            -Description "Defender is told not to scan activity by '$ep'. Excluding a scripting interpreter effectively blinds AV to script-based attacks." `
                            -Recommendation "Remove the exclusion unless there is a strong, documented reason." `
                            -Entity "posture:defender:procexcl:$ep" -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ Process = $ep })))
            }
        }
    } elseif (-not $hasThirdParty) {
        $findings.Add((New-WfxFinding -Id 'POSTURE-NO-AV' -Title 'No antivirus engine detected' `
                    -Severity 'Medium' -Confidence 'Low' -Category 'Posture' -Technique @('T1562.001') `
                    -Description "Neither Microsoft Defender status nor a registered third-party AV could be confirmed. The host may have no active AV, or status collection was blocked (see collection gaps)." `
                    -Recommendation "Confirm an AV product is installed, running and updating." `
                    -Entity 'posture:av:none' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ ThirdPartyAV = $thirdParty })))
    }

    # ── Logging visibility ──
    $audit = Get-WfxValue $Posture 'Audit' $null
    if ($audit) {
        $sysmon = Get-WfxValue $audit 'SysmonInstalled' $false
        # Only an explicit $false is "off"; $null means it could not be determined (recorded as a gap).
        $pc = Get-WfxValue $audit 'ProcessCreation' $null
        if ($null -ne $pc -and $pc -eq $false -and -not $sysmon) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-NO-PROCESS-AUDIT' -Title 'Process-creation auditing is off (4688 / Sysmon absent)' `
                        -Severity 'Medium' -Confidence 'High' -Category 'Visibility' -Technique @('T1562.002') `
                        -Description "Neither Security 4688 process-creation auditing nor Sysmon is active. Most process-based detections in this tool and in any SIEM are blind on this host — absence of findings here does not mean absence of activity." `
                        -Recommendation "Enable 'Audit Process Creation' (Success) via GPO, or deploy Sysmon. Also enable command-line auditing." `
                        -Entity 'posture:audit:proc' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ ProcessCreationAudit = $false; Sysmon = $sysmon })))
        }
        if ((Get-WfxValue $audit 'CommandLineInProcessCreation' $false) -eq $false -and -not $sysmon -and $pc -ne $false) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-NO-CMDLINE-AUDIT' -Title 'Command-line logging in 4688 is disabled' `
                        -Severity 'Low' -Confidence 'High' -Category 'Visibility' -Technique @('T1562.002') `
                        -Description "Process-creation events will not include command lines, so encoded/abusive command lines cannot be reviewed after the fact." `
                        -Recommendation "Enable 'Include command line in process creation events' via GPO." `
                        -Entity 'posture:audit:cmdline' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ CommandLineAudit = $false })))
        }
        if ((Get-WfxValue $audit 'ScriptBlockLogging' $false) -eq $false) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-NO-SCRIPTBLOCK-LOG' -Title 'PowerShell script-block logging is off' `
                        -Severity 'Medium' -Confidence 'High' -Category 'Visibility' -Technique @('T1562.002') `
                        -Description "PowerShell Script Block Logging (4104) is disabled, so malicious/obfuscated PowerShell leaves little forensic trace. PowerShell is one of the most abused tools in intrusions." `
                        -Recommendation "Enable Script Block Logging via GPO (Administrative Templates > Windows Components > Windows PowerShell)." `
                        -Entity 'posture:audit:sbl' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ ScriptBlockLogging = $false })))
        }
    }

    # ── Firewall ──
    $fw = Get-WfxValue $Posture 'Firewall' $null
    if ($fw) {
        $off = @()
        foreach ($p in @('Domain', 'Private', 'Public')) { if ((Get-WfxValue $fw $p $true) -eq $false) { $off += $p } }
        if ($off.Count -gt 0) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-FIREWALL-OFF' -Title "Windows Firewall disabled on profile(s): $($off -join ', ')" `
                        -Severity 'Medium' -Confidence 'High' -Category 'Posture' -Technique @('T1562.004') `
                        -Description "One or more firewall profiles are turned off, widening the host's network exposure. Attackers disable the firewall to enable lateral movement and inbound tooling." `
                        -Recommendation "Re-enable the firewall on all profiles and confirm it was not disabled by malware or an overly broad policy." `
                        -Entity 'posture:firewall' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ Disabled = $off })))
        }
    }

    # ── RDP without NLA ──
    $rdp = Get-WfxValue $Posture 'Rdp' $null
    if ($rdp -and (Get-WfxValue $rdp 'Enabled' $false) -and (Get-WfxValue $rdp 'NlaEnabled' $true) -eq $false) {
        $findings.Add((New-WfxFinding -Id 'POSTURE-RDP-NO-NLA' -Title 'RDP is enabled without Network Level Authentication' `
                    -Severity 'Medium' -Confidence 'High' -Category 'Posture' -Technique @('T1021.001') `
                    -Description "Remote Desktop is accepting connections without NLA, which weakens protection against unauthenticated and brute-force attacks on the RDP service." `
                    -Recommendation "Require NLA for RDP, restrict it to a VPN/jump host, and enforce account lockout + MFA where possible." `
                    -Entity 'posture:rdp:nla' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ RdpEnabled = $true; NLA = $false })))
    }

    # ── LSASS not protected (informational hardening) ──
    $lsa = Get-WfxValue $Posture 'Lsa' $null
    if ($lsa -and (Get-WfxValue $lsa 'RunAsPPL' $false) -eq $false -and (Get-WfxValue $lsa 'CredentialGuard' $false) -ne $true) {
        $findings.Add((New-WfxFinding -Id 'POSTURE-LSASS-UNPROTECTED' -Title 'LSASS is not running as a protected process (no PPL / Credential Guard)' `
                    -Severity 'Low' -Confidence 'Medium' -Category 'Posture' -Technique @('T1003.001') `
                    -Description "LSASS has neither RunAsPPL nor Credential Guard enabled, so credential material in memory is easier for an admin-level attacker to access. This is a hardening gap, not evidence of compromise." `
                    -Recommendation "Enable LSA Protection (RunAsPPL) and, where supported, Credential Guard." `
                    -Entity 'posture:lsa:ppl' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ RunAsPPL = $false; CredentialGuard = (Get-WfxValue $lsa 'CredentialGuard' $null) })))
    }

    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Process.ps1 =====
# Process analyzer: turns a normalized process list into findings. Pure function — no WMI,
# no platform calls — so it runs and is tested anywhere. Each process object is expected to have:
#   Pid, Ppid, Name, Path, CommandLine, User, ParentName, ParentPath, SignatureStatus, Company, CreateTime.

# Legit parents for sensitive system processes (lowercased leaf names).
$script:WfxExpectedParents = @{
    'lsass.exe'    = @('wininit.exe')
    'services.exe' = @('wininit.exe')
    'wininit.exe'  = @('smss.exe', '')
    'csrss.exe'    = @('smss.exe', '')
    'smss.exe'     = @('smss.exe', 'system', '')
    'winlogon.exe' = @('smss.exe', '')
    'lsaiso.exe'   = @('wininit.exe')
    'spoolsv.exe'  = @('services.exe')
    'taskhostw.exe' = @('services.exe', 'svchost.exe')
}
# Processes that should only ever run from System32/SysWOW64.
$script:WfxSystem32Only = @('svchost.exe', 'lsass.exe', 'services.exe', 'wininit.exe', 'csrss.exe',
    'smss.exe', 'winlogon.exe', 'spoolsv.exe', 'conhost.exe', 'dllhost.exe', 'taskhostw.exe',
    'runtimebroker.exe', 'searchindexer.exe', 'sihost.exe', 'fontdrvhost.exe', 'lsaiso.exe')
# Office / browser / mail processes that should not normally spawn script interpreters.
$script:WfxOfficeParents = @('winword.exe', 'excel.exe', 'powerpnt.exe', 'outlook.exe', 'onenote.exe',
    'mspub.exe', 'msaccess.exe', 'visio.exe', 'wordpad.exe', 'acrord32.exe', 'acrobat.exe')
$script:WfxBrowserParents = @('chrome.exe', 'msedge.exe', 'firefox.exe', 'brave.exe', 'opera.exe', 'iexplore.exe')
$script:WfxScriptChildren = @('powershell.exe', 'pwsh.exe', 'cmd.exe', 'mshta.exe', 'wscript.exe',
    'cscript.exe', 'rundll32.exe', 'regsvr32.exe', 'certutil.exe', 'bitsadmin.exe', 'curl.exe',
    'msbuild.exe', 'installutil.exe', 'schtasks.exe')

function Invoke-WfxProcessAnalyzer {
    param([object[]]$Process, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $procs = @($Process | Where-Object { $_ })
    if ($procs.Count -eq 0) { return , $findings.ToArray() }

    $threats = Get-WfxRulePack -Name 'threats'
    $ai = Get-WfxRulePack -Name 'ai'
    $offensive = @($threats.offensiveProcesses | ForEach-Object { $_.ToLowerInvariant() })
    $rmm = @($threats.rmmProcesses | ForEach-Object { $_.ToLowerInvariant() })
    $aiRuntime = @($ai.runtimeProcesses | ForEach-Object { $_.ToLowerInvariant() })
    $aiAssist = @($ai.assistantProcesses | ForEach-Object { $_.ToLowerInvariant() })
    # Assistants installed as npm / pip packages run as node.exe or python.exe: recognise them by package path.
    $aiAssistCmd = @($ai.assistantCommandHints | ForEach-Object { ([string]$_).ToLowerInvariant() } | Where-Object { $_ })
    $agentHints = @($ai.agentHints | ForEach-Object { ([string]$_).ToLowerInvariant() } | Where-Object { $_ })
    $byPid = @{}
    foreach ($p in $procs) { if ($null -ne $p.Pid) { $byPid[[string]$p.Pid] = $p } }

    foreach ($p in $procs) {
        $name = (Get-WfxLeaf (Get-WfxValue $p 'Name' '')).ToLowerInvariant()
        if (-not $name) { $name = (Get-WfxLeaf (Get-WfxValue $p 'Path' '')).ToLowerInvariant() }
        $path = [string](Get-WfxValue $p 'Path' '')
        $cmd = [string](Get-WfxValue $p 'CommandLine' '')
        $parent = (Get-WfxLeaf (Get-WfxValue $p 'ParentName' '')).ToLowerInvariant()
        # PID reuse guard: if the recorded "parent" started AFTER this process, the real parent has exited and
        # its PID was recycled — the name is unrelated and must not drive parent-based detections.
        $ct = ConvertTo-WfxDateTime (Get-WfxValue $p 'CreateTime')
        $pct = ConvertTo-WfxDateTime (Get-WfxValue $p 'ParentCreateTime')
        if ($ct -and $pct -and $pct -gt $ct) { $parent = '' }
        $entity = "process:$(Get-WfxValue $p 'Pid' '?'):$name"
        $sig = [string](Get-WfxValue $p 'SignatureStatus' '')
        $pcmd = [string](Get-WfxValue $p 'ParentCommandLine' '')

        # 1. Command-line rules (the big one — LotL, proxy exec, cred access, recovery inhibition…)
        foreach ($r in (Test-WfxCommandLine -CommandLine $cmd -Image $path)) {
            $findings.Add((New-WfxFinding -Id $r.id -Title $r.title -Severity $r.severity -Confidence $r.confidence `
                        -Category 'Process' -Technique $r.technique -Description $r.description -Recommendation $r.recommendation `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Parent = $parent; CommandLine = (Protect-WfxText $cmd); Path = $path })))
        }

        # 1b. Encoded PowerShell: decode (text only — never executed) and run the rules over the decoded script.
        $isPs = $name -in @('powershell.exe', 'pwsh.exe', 'powershell_ise.exe')
        $canonCmd = ConvertTo-WfxCanonicalCommand $cmd
        if ($isPs -or $canonCmd -match '(?i)\bp(?:ower)?sh' -or $canonCmd -match '(?i)(?:^|\s)-(?:e|ec|en|enc|encodedcommand)\s+["'']?[A-Za-z0-9+/]{20,}') {
            $decoded = Get-WfxEncodedCommandPayload $canonCmd
            if ($decoded -and -not $isPs -and $canonCmd -notmatch '(?i)\bp(?:ower)?sh(?:ell)?(?:_ise)?(?:\.exe)?\b' -and $decoded -match '(?i)[a-z]+-[a-z]+|\biex\b|\$[a-z_]') {
                # A PowerShell payload handed to a program that is not called PowerShell: a copied/renamed interpreter.
                $findings.Add((New-WfxFinding -Id 'PROC-RENAMED-INTERPRETER' -Title "Encoded PowerShell run by a program named $name (renamed PowerShell?)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Process' -Technique @('T1036.003', 'T1059.001') `
                            -Description 'The process received a Base64 -EncodedCommand that decodes to PowerShell, but its executable is not named PowerShell. Attackers copy powershell.exe under another name to slip past name-based rules.' `
                            -Recommendation 'Hash the executable and compare with System32\WindowsPowerShell\v1.0\powershell.exe; read the decoded script.' `
                            -Entity "$entity`:renamed" -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                            -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path; DecodedCommand = (Protect-WfxText $(if ($decoded.Length -gt 600) { $decoded.Substring(0, 600) + ' …' } else { $decoded })) })))
            }
            if ($decoded) {
                $dshort = Protect-WfxText $(if ($decoded.Length -gt 2000) { $decoded.Substring(0, 2000) + ' …[truncated]' } else { $decoded })
                foreach ($r in (Test-WfxCommandLine -CommandLine $decoded -Image 'powershell.exe')) {
                    if ($r.id -eq 'LOTL-PS-ENCODED') { continue }
                    $findings.Add((New-WfxFinding -Id $r.id -Title "$($r.title) (inside encoded command)" -Severity $r.severity -Confidence $r.confidence `
                                -Category 'Process' -Technique $r.technique -Description $r.description -Recommendation $r.recommendation `
                                -Entity "$entity`:decoded" -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                                -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Parent = $parent; DecodedCommand = $dshort })))
                }
                $findings.Add((New-WfxFinding -Id 'PROC-ENCODED-DECODED' -Title "Decoded PowerShell payload ($name, pid $(Get-WfxValue $p 'Pid' '?'))" `
                            -Severity 'Info' -Confidence 'High' -Category 'Process' -Technique @('T1027.010') `
                            -Description 'The encoded command was decoded for review (decoding only; nothing was executed).' `
                            -Recommendation 'Read the decoded script; correlate with 4104 script-block logs.' `
                            -Entity "$entity`:payload" -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                            -Evidence ([ordered]@{ Pid = $p.Pid; DecodedCommand = $dshort })))
            }
        }

        # 2. Masquerading: system-process name running from the wrong place
        if ($script:WfxSystem32Only -contains $name -and $path -and -not (Test-WfxSystemPath $path)) {
            $findings.Add((New-WfxFinding -Id 'PROC-SYSNAME-WRONGPATH' -Title "System process name '$name' running from an unusual path" `
                        -Severity 'High' -Confidence 'High' -Category 'Process' -Technique @('T1036.005') `
                        -Description "A process using the name of a core Windows binary is running from outside System32/SysWOW64. Malware often copies a trusted name to blend in." `
                        -Recommendation "Verify the image path and signature. The real $name runs only from the Windows system folders." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path; Parent = $parent })))
        }

        # 3. Parent spoofing of sensitive processes
        if ($script:WfxExpectedParents.ContainsKey($name) -and $parent) {
            if ($script:WfxExpectedParents[$name] -notcontains $parent) {
                $findings.Add((New-WfxFinding -Id 'PROC-PARENT-SPOOF' -Title "$name has an unexpected parent ($parent)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Process' -Technique @('T1055.012', 'T1036') `
                            -Description "Core Windows processes are started by a fixed parent. A different parent can indicate process hollowing or a masqueraded binary." `
                            -Recommendation "Expected parent for $name is $($script:WfxExpectedParents[$name] -join '/'). Investigate the parent process." `
                            -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                            -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Parent = $parent; Path = $path })))
            }
        }

        # 4. Office / browser spawning a script interpreter → likely malicious document or exploit
        if (($script:WfxOfficeParents -contains $parent -or $script:WfxBrowserParents -contains $parent) -and $script:WfxScriptChildren -contains $name) {
            $isOffice = $script:WfxOfficeParents -contains $parent
            $findings.Add((New-WfxFinding -Id ($(if ($isOffice) { 'PROC-OFFICE-SPAWN' } else { 'PROC-BROWSER-SPAWN' })) `
                        -Title "$parent spawned $name" -Severity 'High' -Confidence 'Medium' -Category 'Process' `
                        -Technique @('T1204.002', 'T1059.001') `
                        -Description "$(if ($isOffice) {'An Office application'} else {'A web browser'}) started a scripting tool. This is the classic result of a malicious document or a browser exploit/ClickFix lure." `
                        -Recommendation "Review the command line and what $parent opened (recent documents / browser history) just before this ran." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Parent = $parent; CommandLine = (Protect-WfxText $cmd); ParentCommandLine = (Protect-WfxText $pcmd) })))
        }

        # 5. Unsigned / untrusted binary from a user-writable location
        if ($path -and (Test-WfxUserWritablePath $path) -and $name -notin @('', 'explorer.exe')) {
            $untrusted = $sig -and $sig -notin @('Valid', 'Signed', 'Trusted', '')
            if ($untrusted) {
                $findings.Add((New-WfxFinding -Id 'PROC-UNSIGNED-USERPATH' -Title "Unsigned process running from a user-writable folder: $name" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'Process' -Technique @('T1036') `
                            -Description "An unsigned or untrusted executable is running from a location any user can write to — a common staging pattern for malware." `
                            -Recommendation "Hash the file and check it against threat intelligence; confirm the publisher." `
                            -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                            -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path; Signature = $sig; Parent = $parent })))
            }
        }

        # 6. Known offensive / hacking tools
        if ($offensive | Where-Object { $name -eq $_ -or ($_ -notmatch '\.' -and $name -like "*$_*") }) {
            $findings.Add((New-WfxFinding -Id 'PROC-OFFENSIVE-TOOL' -Title "Offensive security tool running: $name" `
                        -Severity 'High' -Confidence 'Medium' -Category 'Process' -Technique @('T1588.002') `
                        -Description "A process matching a known credential-dumping, C2 or attack tool is running. $($threats.offensiveNote)" `
                        -Recommendation "Confirm whether an authorized test is in progress. If not, treat the host as compromised." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path; CommandLine = (Protect-WfxText $cmd) })))
        }

        # 7. Remote-management (RMM) tools — attacker persistence / access on endpoints
        if ($rmm -contains $name) {
            $findings.Add((New-WfxFinding -Id 'PROC-RMM-TOOL' -Title "Remote-management tool running: $name" `
                        -Severity 'Low' -Confidence 'Low' -Category 'Process' -Technique @('T1219') `
                        -Description "A remote access / RMM tool is running. These are legitimate, but intruders frequently install one for durable access, especially if it is not your standard tool." `
                        -Recommendation "Confirm this RMM tool is sanctioned on this host and tied to a known administrator." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path })))
        }

        # 8. AI-era context (informational): local LLM runtime + AI assistant with shell access
        if ($aiRuntime -contains $name) {
            $findings.Add((New-WfxFinding -Id 'AI-RUNTIME-PRESENT' -Title "Local AI model runtime running: $name" `
                        -Severity 'Info' -Confidence 'High' -Category 'AI' -Technique @() `
                        -Description "A local large-language-model runtime is running. Noted for context: these often expose an unauthenticated API on localhost (see network findings)." `
                        -Recommendation "Confirm it is bound to localhost and not reachable from the network." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path })))
        }
        $cmdL = $cmd.ToLowerInvariant()
        $agent = @($agentHints | Where-Object { $cmdL.Contains($_) }) | Select-Object -First 1
        if ($agent) {
            $findings.Add((New-WfxFinding -Id 'AI-AGENT-SHELL' -Title "Autonomous AI agent framework running ($agent)" `
                        -Severity 'Low' -Confidence 'Low' -Category 'AI' -Technique @('T1059.001', 'T1204.004') `
                        -Description "An AI agent framework able to run shell commands is active. Some commands on this host may have been generated and run by it rather than typed by a person." `
                        -Recommendation "When reconstructing a timeline, consider the agent as a possible actor and review its logs." `
                        -Entity "$entity`:agent" -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Hint = $agent; CommandLine = (Protect-WfxText $cmd) })))
        }
        $assistHint = if ($aiAssist -contains $name) { $name } else { @($aiAssistCmd | Where-Object { $cmdL.Replace('\', '/').Contains($_) }) | Select-Object -First 1 }
        if ($assistHint) {
            $findings.Add((New-WfxFinding -Id 'AI-ASSISTANT-PRESENT' -Title "AI assistant / agent running: $(if ($assistHint -ne $name) { "$assistHint (in $name)" } else { $name })" `
                        -Severity 'Info' -Confidence 'Low' -Category 'AI' -Technique @('T1204.004') `
                        -Description "An AI coding assistant or agent capable of running commands is present. Relevant when attributing activity: some commands may have been generated and run by this tool." `
                        -Recommendation "If reconstructing a timeline, consider this tool as a possible actor for shell activity." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Hint = $assistHint })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Collectors/Activity.ps1 =====
# Activity collector — "what changed recently?" Reconstructs attacker-relevant change history from artefacts
# Windows already keeps, without any prior monitoring:
#   Registry   key last-write times of persistence / defence / software / task locations
#   Files      NTFS change journal (create, delete, content change, rename, ADS, timestamp change), Recycle Bin
#   Software   MSI install/remove events, driver installs, Uninstall-key write times
#   Execution  Prefetch, BAM, UserAssist
#   Network    Sysmon 3, Security 5156, firewall log, live connection creation times, outbound RDP history
#   Config     service / task / account / audit-policy / firewall-rule / Defender / time / log-clear / BITS / WMI events
# Every record is normalized to:
#   { Time (UTC ISO), Category, Action, Target, Detail, Actor, Source }
# Everything is read-only. Note: reading key timestamps needs one small compiled helper (Add-Type), which in
# Windows PowerShell 5.1 briefly writes compiler temp files to %TEMP%.

$script:WfxRegTimeReady = $false

function Get-WfxEventQuick {
    <# Reads events with their data fields (no slow message formatting unless -Message). #>
    param([string]$Log, [int[]]$Id, [int]$Days = 7, [int]$Max = 5000, [switch]$Message, [string]$Path = '')
    $flt = @{ Id = $Id; StartTime = (Get-Date).AddDays(-[Math]::Abs($Days)) }
    if ($Path) { $flt.Path = $Path } else { $flt.LogName = $Log }
    $ev = @()
    try { $ev = @(Get-WinEvent -FilterHashtable $flt -MaxEvents $Max -ErrorAction Stop) }
    catch { if (-not (Test-WfxNoEventsError $_)) { throw } }
    foreach ($e in $ev) {
        $f = @{}
        try { foreach ($d in @(([xml]$e.ToXml()).Event.EventData.Data)) { if ($d -and $d.Name) { $f[$d.Name] = [string]$d.'#text' } } } catch {}
        try { foreach ($u in @(([xml]$e.ToXml()).Event.UserData.ChildNodes)) { foreach ($c in @($u.ChildNodes)) { if ($c.LocalName) { $f[$c.LocalName] = [string]$c.InnerText } } } } catch {}
        [pscustomobject]@{ Time = $e.TimeCreated; Id = $e.Id; Level = $e.LevelDisplayName; Fields = $f; Message = $(if ($Message) { try { [string]$e.Message } catch { '' } } else { '' }) }
    }
}


function Initialize-WfxRegTime {
    if ($script:WfxRegTimeReady) { return $true }
    if (-not (Test-WfxWindows)) { return $false }
    try {
        if (-not ('WfxRegTime' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class WfxRegTime {
    [DllImport("advapi32.dll", CharSet = CharSet.Unicode)]
    private static extern int RegQueryInfoKey(IntPtr hKey, IntPtr cls, IntPtr clsLen, IntPtr reserved, IntPtr subKeys, IntPtr maxSubKey,
        IntPtr maxClass, IntPtr values, IntPtr maxValueName, IntPtr maxValueLen, IntPtr secDesc, out long lastWrite);
    // Returns the key's last-write FILETIME (UTC) or -1. Read-only query.
    public static long LastWrite(IntPtr hKey) { long ft; return RegQueryInfoKey(hKey, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, out ft) == 0 ? ft : -1; }
}
'@ -ErrorAction Stop
        }
        $script:WfxRegTimeReady = $true
    } catch { Add-WfxGap -Source 'activity:registry' -Reason "Key timestamps unavailable: $($_.Exception.Message)" }
    return $script:WfxRegTimeReady
}

function Get-WfxRegKeyTime {
    <# Last-write time (UTC DateTime) of a registry key given as a PowerShell path, or $null. #>
    param([string]$Path)
    if (-not (Initialize-WfxRegTime)) { return $null }
    try {
        $k = Get-Item -LiteralPath $Path -ErrorAction Stop
        $ft = [WfxRegTime]::LastWrite($k.Handle.DangerousGetHandle())
        if ($ft -gt 0) { return [DateTime]::FromFileTimeUtc($ft) }
    } catch {}
    return $null
}

function Get-WfxRegKeyObjectTime {
    <# Last-write time (UTC) of an open Microsoft.Win32.RegistryKey, or $null. #>
    param($Key)
    if (-not $Key -or -not (Initialize-WfxRegTime)) { return $null }
    try { $ft = [WfxRegTime]::LastWrite($Key.Handle.DangerousGetHandle()); if ($ft -gt 0) { return [DateTime]::FromFileTimeUtc($ft) } } catch { }
    $null
}

function New-WfxActivity {
    param($Time, [string]$Category, [string]$Action, [string]$Target, [string]$Detail = '', [string]$Actor = '', [string]$Source = '')
    [pscustomobject]@{ Time = (ConvertTo-WfxUtcString $Time); Category = $Category; Action = $Action; Target = (Protect-WfxText $Target); Detail = (Protect-WfxText $(if ($Detail.Length -gt 600) { $Detail.Substring(0, 600) + ' …' } else { $Detail })); Actor = $Actor; Source = $Source }
}

function Get-WfxRegValueSummary {
    param($Key, [int]$Max = 6)
    try {
        $names = @($Key.GetValueNames() | Select-Object -First $Max)
        (@($names | ForEach-Object { $v = $Key.GetValue($_); if ($v -is [byte[]]) { $v = "<$($v.Length) bytes>" } elseif ($v -is [array]) { $v = $v -join ';' }; "$(if ($_) { $_ } else { '(Default)' })=$(Get-WfxShortText ([string]$v) 120)" }) -join ' | ')
    } catch { '' }
}


# Registry locations attackers change, with how to read them. Sub = also check each direct subkey.
$script:WfxActivityRegKeys = @(
    @{ P = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Run'; C = 'Autostart'; Hive = 'Both' }
    @{ P = 'SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'; C = 'Autostart'; Hive = 'Both' }
    @{ P = 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'; C = 'Autostart'; Hive = 'HKLM' }
    @{ P = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run'; C = 'Autostart'; Hive = 'Both' }
    @{ P = 'SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'; C = 'Autostart'; Hive = 'Both' }
    @{ P = 'SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows'; C = 'Autostart'; Hive = 'Both' }
    @{ P = 'Environment'; C = 'Autostart'; Hive = 'HKU' }
    @{ P = 'SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options'; C = 'Hijack'; Hive = 'HKLM'; Sub = $true }
    @{ P = 'SOFTWARE\Microsoft\Windows NT\CurrentVersion\SilentProcessExit'; C = 'Hijack'; Hive = 'HKLM'; Sub = $true }
    @{ P = 'SOFTWARE\Classes\ms-settings\Shell\Open\command'; C = 'Hijack'; Hive = 'HKU' }
    @{ P = 'SOFTWARE\Classes\mscfile\Shell\Open\command'; C = 'Hijack'; Hive = 'HKU' }
    @{ P = 'SYSTEM\CurrentControlSet\Control\Lsa'; C = 'Credentials'; Hive = 'HKLM' }
    @{ P = 'SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest'; C = 'Credentials'; Hive = 'HKLM' }
    @{ P = 'SYSTEM\CurrentControlSet\Control\Terminal Server'; C = 'Remote access'; Hive = 'HKLM' }
    @{ P = 'SOFTWARE\Microsoft\Windows Defender\Exclusions\Paths'; C = 'Defence'; Hive = 'HKLM' }
    @{ P = 'SOFTWARE\Microsoft\Windows Defender\Exclusions\Processes'; C = 'Defence'; Hive = 'HKLM' }
    @{ P = 'SOFTWARE\Microsoft\Windows Defender\Exclusions\Extensions'; C = 'Defence'; Hive = 'HKLM' }
    @{ P = 'SOFTWARE\Policies\Microsoft\Windows Defender'; C = 'Defence'; Hive = 'HKLM'; Sub = $true }
    @{ P = 'SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\FirewallRules'; C = 'Defence'; Hive = 'HKLM' }
    @{ P = 'SOFTWARE\Policies\Microsoft\Windows\PowerShell'; C = 'Defence'; Hive = 'HKLM'; Sub = $true }
    @{ P = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'; C = 'Software'; Hive = 'Both'; Sub = $true }
    @{ P = 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'; C = 'Software'; Hive = 'HKLM'; Sub = $true }
    @{ P = 'SOFTWARE\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache\Tree'; C = 'Scheduled task'; Hive = 'HKLM'; Sub = $true }
    @{ P = 'SYSTEM\CurrentControlSet\Services'; C = 'Service'; Hive = 'HKLM'; Sub = $true }
)

function Get-WfxRegistryActivity {
    param([int]$Days = 7)
    if (-not (Test-WfxWindows) -or -not (Initialize-WfxRegTime)) { return @() }
    $cut = (Get-Date).ToUniversalTime().AddDays(-[Math]::Abs($Days))
    $out = New-Object System.Collections.Generic.List[object]
    $users = @(Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-|^S-1-12-1-' -and $_.PSChildName -notmatch '_Classes$' } | ForEach-Object { $_.PSChildName })
    foreach ($k in $script:WfxActivityRegKeys) {
        $roots = switch ($k.Hive) { 'HKLM' { @('HKLM:') } 'HKU' { @($users | ForEach-Object { "Registry::HKEY_USERS\$_" }) } default { @('HKLM:') + @($users | ForEach-Object { "Registry::HKEY_USERS\$_" }) } }
        foreach ($r in $roots) {
            $path = "$r\$($k.P)"
            if (-not (Test-Path -LiteralPath $path)) { continue }
            $paths = @($path)
            if ($k.Sub) { $paths += @(Get-ChildItem -LiteralPath $path -ErrorAction SilentlyContinue | ForEach-Object { $_.PSPath }) }
            foreach ($p in $paths) {
                $t = Get-WfxRegKeyTime $p
                if (-not $t -or $t -lt $cut) { continue }
                $item = Get-Item -LiteralPath $p -ErrorAction SilentlyContinue
                $disp = ($p -replace '^Microsoft\.PowerShell\.Core\\Registry::', '' -replace '^HKLM:', 'HKEY_LOCAL_MACHINE')
                $detail = if ($item) { Get-WfxRegValueSummary $item } else { '' }
                if ($k.C -eq 'Software' -and $item) { $dn = $item.GetValue('DisplayName'); if ($dn) { $detail = "$dn $($item.GetValue('DisplayVersion')) — $($item.GetValue('Publisher'))" } }
                if ($k.C -eq 'Service' -and $item) { $detail = "ImagePath=$($item.GetValue('ImagePath')) Start=$($item.GetValue('Start'))" }
                $out.Add((New-WfxActivity -Time $t -Category 'Registry' -Action "$($k.C) key written" -Target $disp -Detail $detail -Source 'registry key last-write time'))
            }
        }
    }
    $out.ToArray()
}

# ── NTFS change journal ──────────────────────────────────────────────────────────────────────────────
# USN reason flags ([MS-FSCC] / winioctl.h USN_REASON_*). The English text form is what "fsutil usn readjournal"
# prints on some builds instead of hex, so both are accepted.
$script:WfxUsnReason = @(
    [pscustomobject]@{ Bit = 0x00000001; Name = 'Data Overwrite' }
    [pscustomobject]@{ Bit = 0x00000002; Name = 'Data Extend' }
    [pscustomobject]@{ Bit = 0x00000004; Name = 'Data Truncation' }
    [pscustomobject]@{ Bit = 0x00000010; Name = 'Named Data Overwrite' }
    [pscustomobject]@{ Bit = 0x00000020; Name = 'Named Data Extend' }
    [pscustomobject]@{ Bit = 0x00000040; Name = 'Named Data Truncation' }
    [pscustomobject]@{ Bit = 0x00000100; Name = 'File Create' }
    [pscustomobject]@{ Bit = 0x00000200; Name = 'File Delete' }
    [pscustomobject]@{ Bit = 0x00000400; Name = 'EA Change' }
    [pscustomobject]@{ Bit = 0x00000800; Name = 'Security Change' }
    [pscustomobject]@{ Bit = 0x00001000; Name = 'Rename Old Name' }
    [pscustomobject]@{ Bit = 0x00002000; Name = 'Rename New Name' }
    [pscustomobject]@{ Bit = 0x00004000; Name = 'Indexable Change' }
    [pscustomobject]@{ Bit = 0x00008000; Name = 'Basic Info Change' }
    [pscustomobject]@{ Bit = 0x00010000; Name = 'Hard Link Change' }
    [pscustomobject]@{ Bit = 0x00020000; Name = 'Compression Change' }
    [pscustomobject]@{ Bit = 0x00040000; Name = 'Encryption Change' }
    [pscustomobject]@{ Bit = 0x00080000; Name = 'Object ID Change' }
    [pscustomobject]@{ Bit = 0x00100000; Name = 'Reparse Point Change' }
    [pscustomobject]@{ Bit = 0x00200000; Name = 'Stream Change' }
    [pscustomobject]@{ Bit = 0x00400000; Name = 'Transacted Change' }
    [pscustomobject]@{ Bit = 0x00800000; Name = 'Integrity Change' }
    [pscustomobject]@{ Bit = 0x80000000L; Name = 'Close' }
)
# What an examiner calls each flag, in reporting order. (Arrays, not [ordered] dictionaries: indexing an
# ordered dictionary with an integer reads by POSITION, not by key.)
$script:WfxUsnLabel = @(
    [pscustomobject]@{ Bit = 0x100; Name = 'Created' }
    [pscustomobject]@{ Bit = 0x200; Name = 'Deleted' }
    [pscustomobject]@{ Bit = 0x1; Name = 'Content overwritten' }
    [pscustomobject]@{ Bit = 0x2; Name = 'Content extended' }
    [pscustomobject]@{ Bit = 0x4; Name = 'Content truncated' }
    [pscustomobject]@{ Bit = 0x10; Name = 'Alternate stream written' }
    [pscustomobject]@{ Bit = 0x20; Name = 'Alternate stream written' }
    [pscustomobject]@{ Bit = 0x200000; Name = 'Alternate stream added/removed' }
    [pscustomobject]@{ Bit = 0x8000; Name = 'Timestamps/attributes changed' }
    [pscustomobject]@{ Bit = 0x800; Name = 'Permissions changed' }
    [pscustomobject]@{ Bit = 0x10000; Name = 'Hard link changed' }
    [pscustomobject]@{ Bit = 0x100000; Name = 'Reparse point changed' }
)
$script:WfxUsnInteresting = 0x100 -bor 0x200 -bor 0x1 -bor 0x2 -bor 0x4 -bor 0x10 -bor 0x20 -bor 0x200000 -bor 0x8000 -bor 0x800 -bor 0x10000 -bor 0x100000 -bor 0x2000
# Names that are high-volume system churn, not user or attacker activity.
$script:WfxUsnNoise = '(?i)\.(?:tmp|etl|blf|regtrans-ms|pf|db-wal|db-shm|sqlite-journal|ldb|lock|evtx|dat\.log\d?|log\d?)$|^~\$|^\$(?!R)|^(?:ntuser\.dat|usrclass\.dat)'

function ConvertFrom-WfxUsnReason {
    <# "0x80000200" or "File delete | Close" → integer flags. Returns -1 when unreadable. #>
    param([string]$Text)
    $t = ([string]$Text).Trim().Trim('"')
    $m = [regex]::Match($t, '^0[xX]([0-9a-fA-F]{1,8})$')
    if ($m.Success) { return [Convert]::ToInt64($m.Groups[1].Value, 16) }
    if ($t -match '^[0-9a-fA-F]{8}$') { return [Convert]::ToInt64($t, 16) }      # bare 8-digit hex
    $flags = [int64]0; $known = 0
    foreach ($tok in ($t -split '\|')) {
        $n = ($tok -replace '[^A-Za-z]', '').ToLowerInvariant()
        if (-not $n) { continue }
        foreach ($pair in $script:WfxUsnReason) {
            if (($pair.Name -replace '[^A-Za-z]', '').ToLowerInvariant() -eq $n) { $flags = $flags -bor [int64]$pair.Bit; $known++; break }
        }
    }
    if ($known) { return $flags } else { return -1 }
}

function Split-WfxCsvLine {
    <# Splits one CSV line (RFC 4180 quoting) into fields. #>
    param([string]$Line)
    $f = New-Object System.Collections.Generic.List[string]
    foreach ($m in $script:WfxCsvField.Matches($Line)) {
        $v = $m.Groups[1].Value
        if ($v.Length -ge 2 -and $v[0] -eq '"' -and $v[-1] -eq '"') { $v = $v.Substring(1, $v.Length - 2).Replace('""', '"') }
        $f.Add($v)
    }
    , $f.ToArray()
}
$script:WfxCsvField = New-Object System.Text.RegularExpressions.Regex('(?:^|,)("(?:[^"]|"")*"|[^,]*)', [System.Text.RegularExpressions.RegexOptions]::Compiled)

function ConvertFrom-WfxUsnCsv {
    <#
    .SYNOPSIS Parses "fsutil usn readjournal <vol> csv" output into USN records. Pure; no system access.
    .DESCRIPTION Columns are located by header name when the header is English, otherwise by their documented
    position (Usn, File name, File name length, Reason, Time stamp, File attributes, File ID, Parent file ID).
    Rows before -Since are dropped. Returns objects { Usn, Time (local DateTime), Name, Flags, Attributes, FileId, ParentId }.
    #>
    param([string[]]$Line, [datetime]$Since = [datetime]::MinValue)
    $col = @{ Name = 1; Reason = 3; Time = 4; Attr = 5; Id = 6; Parent = 7 }
    $byName = @{ 'file name' = 'Name'; 'reason' = 'Reason'; 'time stamp' = 'Time'; 'file attributes' = 'Attr'; 'file id' = 'Id'; 'parent file id' = 'Parent' }
    $cultures = @([Globalization.CultureInfo]::CurrentCulture, [Globalization.CultureInfo]::InvariantCulture)
    foreach ($l in $Line) {
        if ([string]::IsNullOrWhiteSpace($l)) { continue }
        $f = Split-WfxCsvLine $l
        if ($f.Count -lt 8) { continue }
        $first = $f[0].Trim()
        if ($first -notmatch '^\d+$') {
            if ($first -match '^(?i)usn$') { for ($i = 0; $i -lt $f.Count; $i++) { $k = $byName[$f[$i].Trim().ToLowerInvariant()]; if ($k) { $col[$k] = $i } } }
            continue
        }
        $flags = ConvertFrom-WfxUsnReason $f[$col.Reason]
        if ($flags -lt 0) { continue }
        $ts = $f[$col.Time].Trim(); $t = $null
        foreach ($c in $cultures) { $tmp = [datetime]::MinValue; if ([datetime]::TryParse($ts, $c, [Globalization.DateTimeStyles]::AssumeLocal, [ref]$tmp)) { $t = $tmp; break } }
        if ($null -eq $t -or $t -lt $Since) { continue }
        $attr = 0; $a = $f[$col.Attr].Trim(); if ($a -match '^(?:0x)?([0-9a-fA-F]+)$') { $attr = [Convert]::ToInt64($Matches[1], 16) }
        [pscustomobject]@{ Usn = [int64]$first; Time = $t; Name = $f[$col.Name]; Flags = $flags; Attributes = $attr
            FileId = ($f[$col.Id].Trim() -replace '^0x', '').ToLowerInvariant(); ParentId = ($f[$col.Parent].Trim() -replace '^0x', '').ToLowerInvariant() }
    }
}

function ConvertTo-WfxUsnActivity {
    <#
    .SYNOPSIS Turns USN records into examiner-level events. Pure, given a path resolver.
    .DESCRIPTION
      - One event per completed change (the record carrying the CLOSE flag), labelled from its reason flags.
      - Renames are paired with their "old name" record by file ID, so a move is reported with both paths.
        A rename into $Recycle.Bin\<SID>\$R… is what Explorer's Delete does; it is reported as
        "Deleted to Recycle Bin" with the original path.
      - Deleting a $R… item is the Recycle Bin being emptied (permanent deletion).
      - Folders are identified from the directory attribute.
    .PARAMETER Resolve  Scriptblock: param($ParentId) → folder path or ''.
    #>
    param([object[]]$Record, [scriptblock]$Resolve, [string]$Volume = 'C:')
    $old = @{}
    $events = New-Object System.Collections.Generic.List[object]
    foreach ($r in ($Record | Sort-Object Usn)) {
        if ($r.Flags -band 0x1000) { $old[$r.FileId] = $r }
        if (-not ($r.Flags -band 0x80000000L)) { continue }
        if (-not ($r.Flags -band $script:WfxUsnInteresting)) { continue }
        $isRecycleItem = $r.Name -match '^\$R[A-Z0-9]{5,}'
        $isRename = [bool]($r.Flags -band 0x2000)
        $prev = if ($isRename) { $old[$r.FileId] } else { $null }
        $evidenceDelete = ($r.Flags -band 0x200) -and $r.Name -match '(?i)\.evtx$'      # deleting event logs is anti-forensics, not churn
        if (-not $isRename -and -not $isRecycleItem -and -not $evidenceDelete -and $r.Name -match $script:WfxUsnNoise) { continue }
        if ($isRename -and -not $isRecycleItem -and $r.Name -match $script:WfxUsnNoise -and (-not $prev -or $prev.Name -match $script:WfxUsnNoise)) { continue }
        $events.Add([pscustomobject]@{ R = $r; Prev = $prev; Rename = $isRename; RecycleItem = $isRecycleItem })
    }
    # Resolve each distinct folder once.
    $cache = @{}
    $dirOf = { param($id) if (-not $id) { return '' }; if (-not $cache.ContainsKey($id)) { $cache[$id] = [string](& $Resolve $id) }; $cache[$id] }
    $full = { param($id, $name) $d = & $dirOf $id; if ($d) { $d.TrimEnd('\') + '\' + $name } else { "$Volume\<folder 0x$id>\$name" } }
    foreach ($e in $events) {
        $r = $e.R
        $kind = if ($r.Attributes -band 0x10) { 'folder' } else { 'file' }
        $target = & $full $r.ParentId $r.Name
        $detail = ''
        if ($e.Rename -and $e.Prev) {
            $from = & $full $e.Prev.ParentId $e.Prev.Name
            if ($e.RecycleItem) { $action = 'Deleted to Recycle Bin'; $detail = "$kind · now $target"; $target = $from }
            elseif ($e.Prev.ParentId -eq $r.ParentId) { $action = 'Renamed'; $detail = "$kind · was: $($e.Prev.Name)" }
            else { $action = 'Moved'; $detail = "$kind · from: $from" }
        } elseif ($e.Rename) {
            $action = 'Renamed/moved (old name outside journal window)'; $detail = $kind
        } else {
            $labels = @($script:WfxUsnLabel | Where-Object { $r.Flags -band $_.Bit } | ForEach-Object { $_.Name } | Select-Object -Unique)
            if ($labels -contains 'Created' -and $labels -contains 'Deleted') { $labels = @('Created and deleted (short-lived)') }
            $action = $labels -join ', '
            if ($e.RecycleItem -and ($r.Flags -band 0x200)) { $action = 'Permanently deleted (Recycle Bin emptied)' }
            $detail = $kind
        }
        $sid = if ($target -match '(?i)\\\$Recycle\.Bin\\(S-1-[0-9-]+)') { $Matches[1] } else { '' }
        [pscustomobject]@{ Time = $r.Time; Action = $action; Target = $target; Detail = $detail; Usn = $r.Usn; Sid = $sid }
    }
}

function Resolve-WfxFileId {
    <# Folder path for an NTFS file ID via "fsutil file queryFileNameById" (read-only). Tries the full 128-bit
       form and the 64-bit file reference number. Returns '' if the folder no longer exists. #>
    param([string]$Volume, [string]$Id)
    $cands = @("0x$Id")
    if ($Id.Length -eq 32 -and $Id.StartsWith('0000000000000000')) { $cands += "0x$($Id.Substring(16))" }
    foreach ($c in $cands) {
        $o = @(fsutil file queryFileNameById "$Volume\" $c 2>$null) -join ' '
        if ($LASTEXITCODE -eq 0 -and $o -match '\\\\\?\\(.+)$') { return $Matches[1].Trim() }
    }
    ''
}

function Get-WfxUsnActivity {
    <#
    .SYNOPSIS File-system changes from the NTFS change journal of a volume (admin; read-only, via fsutil).
    .DESCRIPTION Reads the newest part of the journal ($MaxRecords records; the journal itself only keeps a
    limited history — typically hours to a few days on a busy system drive). Records a gap explaining exactly
    why when nothing can be read, and notes how far back the readable window actually goes.
    #>
    param([int]$Days = 7, [string]$Drive = $env:SystemDrive, [int]$MaxRecords = 150000, [int]$MaxResolve = 400)
    if (-not (Test-WfxWindows)) { return }
    if (-not (Test-WfxAdmin)) { Add-WfxGap -Source 'activity:usn' -Reason 'The NTFS change journal can only be read by an administrator.' -Fix 'Open PowerShell with "Run as administrator" and run WinForensicX again.'; return }
    $vol = $Drive.TrimEnd('\')
    $q = @(fsutil usn queryjournal $vol 2>&1 | ForEach-Object { [string]$_ })
    if ($LASTEXITCODE -ne 0) { Add-WfxGap -Source 'activity:usn' -Reason "No change journal on $vol ($((($q -join ' ') -replace '\s+', ' ').Trim()))." -Fix 'The journal may be disabled; nothing can be reconstructed from it on this volume.'; return }
    $hexes = @($q | ForEach-Object { if ($_ -match ':\s*0x([0-9a-fA-F]+)') { [Convert]::ToInt64($Matches[1], 16) } })
    $first = $null; $next = $null
    foreach ($l in $q) { if ($l -match '^\s*First Usn\s*:\s*0x([0-9a-fA-F]+)') { $first = [Convert]::ToInt64($Matches[1], 16) } elseif ($l -match '^\s*Next Usn\s*:\s*0x([0-9a-fA-F]+)') { $next = [Convert]::ToInt64($Matches[1], 16) } }
    if ($null -eq $next -and $hexes.Count -ge 3) { $first = $hexes[1]; $next = $hexes[2] }          # documented order: ID, First, Next
    if ($null -eq $next) { Add-WfxGap -Source 'activity:usn' -Reason "Could not read the journal range from fsutil output: $((($q | Select-Object -First 3) -join ' / '))"; return }
    $start = [Math]::Max([int64]$first, [int64]$next - [int64]$MaxRecords * 120)       # ~120 bytes per record
    $raw = @(fsutil usn readjournal $vol "startusn=$start" csv 2>&1 | ForEach-Object { [string]$_ })
    if ($LASTEXITCODE -ne 0 -or $raw.Count -lt 2) { Add-WfxGap -Source 'activity:usn' -Reason "fsutil usn readjournal $vol csv failed: $((($raw | Select-Object -First 2) -join ' ') -replace '\s+', ' ')" -Fix 'This Windows build''s fsutil may not support CSV output; the other Recent-changes views still work.'; return }
    $cut = (Get-Date).AddDays(-[Math]::Abs($Days))
    $recs = @(ConvertFrom-WfxUsnCsv -Line $raw)
    if (-not $recs.Count) {
        $sample = @($raw | Where-Object { $_ -match '\S' } | Select-Object -First 2) -join ' ⏎ '
        Add-WfxGap -Source 'activity:usn' -Reason "fsutil returned $($raw.Count) lines but none could be parsed as journal records. First lines: $(Get-WfxShortText $sample 300)" -Fix 'Please report this output format (Windows version + these lines) so the parser can support it.'
        return
    }
    $oldest = ($recs | Measure-Object -Property Time -Minimum).Minimum
    if ($oldest -gt $cut) { Add-WfxGap -Source 'activity:usn' -Reason ("The readable journal window on {0} starts at {1} (local time); changes before that are not shown." -f $vol, $oldest.ToString('yyyy-MM-dd HH:mm')) }
    $recent = @($recs | Where-Object { $_.Time -ge $cut -or ($_.Flags -band 0x1000) })
    $script:WfxUsnResolveCount = 0         # each lookup starts fsutil once; bounded so a huge journal stays fast
    $resolver = { param($id) if ($script:WfxUsnResolveCount -ge $MaxResolve) { return '' }; $script:WfxUsnResolveCount++; Resolve-WfxFileId -Volume $vol -Id $id }
    $sids = @{}
    foreach ($e in (ConvertTo-WfxUsnActivity -Record $recent -Resolve $resolver -Volume $vol)) {
        if ($e.Time -lt $cut) { continue }
        $actor = ''
        if ($e.Sid) { if (-not $sids.ContainsKey($e.Sid)) { $sids[$e.Sid] = try { (New-Object Security.Principal.SecurityIdentifier($e.Sid)).Translate([Security.Principal.NTAccount]).Value } catch { $e.Sid } }; $actor = $sids[$e.Sid] }
        New-WfxActivity -Time $e.Time -Category 'File' -Action $e.Action -Target $e.Target -Detail $e.Detail -Actor $actor -Source "NTFS change journal $vol (USN $($e.Usn))"
    }
}

function Get-WfxRecycleBinActivity {
    <# Parses Recycle Bin $I metadata files on every fixed drive: original path, size, deletion time, owner,
       whether the item ($R) is still recoverable and whether it was a file or a folder. #>
    param([int]$Days = 30, [string[]]$Root = @())
    if (-not $Root.Count) {
        if (-not (Test-WfxWindows)) { return }
        $Root = @([IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq 'Fixed' -and $_.IsReady } | ForEach-Object { Join-Path $_.RootDirectory.FullName '$Recycle.Bin' })
    }
    $cut = (Get-Date).ToUniversalTime().AddDays(-[Math]::Abs($Days))
    foreach ($rb in $Root) {
        if (-not (Test-Path -LiteralPath $rb)) { continue }
        $dirs = @(Get-ChildItem -LiteralPath $rb -Directory -Force -ErrorAction SilentlyContinue)
        foreach ($sidDir in $dirs) {
            $user = try { (New-Object Security.Principal.SecurityIdentifier($sidDir.Name)).Translate([Security.Principal.NTAccount]).Value } catch { $sidDir.Name }
            $items = @(Get-ChildItem -LiteralPath $sidDir.FullName -Force -ErrorAction SilentlyContinue | Where-Object { -not $_.PSIsContainer -and $_.Name -like '$I*' })
            foreach ($i in $items) {
                $info = Read-WfxRecycleInfo -Path $i.FullName
                if (-not $info) { Add-WfxGap -Source 'activity:recyclebin' -Reason "Unrecognised Recycle Bin metadata file $($i.FullName)"; continue }
                if ($info.Deleted -lt $cut) { continue }
                $rPath = Join-Path $sidDir.FullName ('$R' + $i.Name.Substring(2))
                $rItem = Get-Item -LiteralPath $rPath -Force -ErrorAction SilentlyContinue
                $state = if (-not $rItem) { 'content gone (bin emptied or item restored/purged)' } elseif ($rItem.PSIsContainer) { "folder · recoverable at $rPath" } else { "file · recoverable at $rPath" }
                New-WfxActivity -Time $info.Deleted -Category 'File' -Action 'Deleted to Recycle Bin' -Target $info.OriginalPath -Detail ("{0} · {1:N0} bytes" -f $state, $info.Size) -Actor $user -Source "Recycle Bin $($i.Name)"
            }
        }
    }
}

function Read-WfxRecycleInfo {
    <# Parses one $I file (Vista/7/8 version 1, Windows 10+ version 2). Pure apart from reading the file. #>
    param([string]$Path, [byte[]]$Bytes)
    if (-not $Bytes) { try { $Bytes = [IO.File]::ReadAllBytes($Path) } catch { return $null } }
    $b = $Bytes
    if ($b.Length -lt 24) { return $null }
    $ver = [BitConverter]::ToInt64($b, 0)
    $ft = [BitConverter]::ToInt64($b, 16)
    if ($ft -le 0) { return $null }
    $name = $null
    if ($ver -eq 2) {
        if ($b.Length -lt 30) { return $null }
        $len = [BitConverter]::ToInt32($b, 24)
        if ($len -le 0 -or 28 + $len * 2 -gt $b.Length) { return $null }
        $name = [Text.Encoding]::Unicode.GetString($b, 28, $len * 2).TrimEnd([char]0)
    } elseif ($ver -eq 1) {
        $name = [Text.Encoding]::Unicode.GetString($b, 24, [Math]::Min(520, $b.Length - 24)).Split([char]0)[0]
    } else { return $null }
    [pscustomobject]@{ Version = $ver; Size = [BitConverter]::ToInt64($b, 8); Deleted = [DateTime]::FromFileTimeUtc($ft); OriginalPath = $name }
}

function Get-WfxEventActivity {
    <# Change events from the logs, normalized. Only reads data fields (fast). #>
    param([int]$Days = 7)
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $q = {
        param($Log, [int[]]$Id, [int]$Max = 2000)
        try { @(Get-WfxEventQuick -Log $Log -Id $Id -Days $Days -Max $Max) } catch { Add-WfxGap -Source "activity:$Log" -Reason $_.Exception.Message; @() }
    }
    foreach ($e in (& $q 'Application' 11707, 11724, 1033, 1034)) {
        $f = $e.Fields; $txt = (@($f.Values) | Where-Object { $_ }) -join ' '
        $act = if ($e.Id -in 11724, 1034) { 'Software removed' } else { 'Software installed' }
        $out.Add((New-WfxActivity -Time $e.Time -Category 'Software' -Action $act -Target (Get-WfxShortText $txt 200) -Source "Application log $($e.Id) (MsiInstaller)"))
    }
    foreach ($e in (& $q 'System' 7045, 7040, 20001, 6, 1)) {
        $f = $e.Fields
        switch ($e.Id) {
            7045 { $out.Add((New-WfxActivity -Time $e.Time -Category 'Service' -Action 'Service installed' -Target $f.ServiceName -Detail "$($f.ImagePath) · start=$($f.StartType) · account=$($f.AccountName)" -Source 'System 7045')) }
            7040 { $out.Add((New-WfxActivity -Time $e.Time -Category 'Service' -Action 'Service start type changed' -Target $f.param1 -Detail "$($f.param2) → $($f.param3)" -Source 'System 7040')) }
            20001 { $out.Add((New-WfxActivity -Time $e.Time -Category 'Software' -Action 'Device driver installed' -Target ((@($f.Values) | Where-Object { $_ }) -join ' ') -Source 'System 20001 (UserPnp)')) }
            6 { if ($f.ContainsKey('ImageName')) { $out.Add((New-WfxActivity -Time $e.Time -Category 'Software' -Action 'Kernel driver loaded' -Target $f.ImageName -Source 'System 6 (FilterManager)')) } }
            1 { if ($f.ContainsKey('NewTime')) { $out.Add((New-WfxActivity -Time $e.Time -Category 'Logging' -Action 'System time changed' -Target "$($f.OldTime) → $($f.NewTime)" -Source 'System 1 (Kernel-General)')) } }
        }
    }
    $secNames = @{ 4698 = 'Scheduled task created'; 4699 = 'Scheduled task deleted'; 4702 = 'Scheduled task changed'; 4720 = 'User created'; 4722 = 'User enabled'; 4724 = 'Password reset'; 4726 = 'User deleted'; 4728 = 'Added to group'; 4732 = 'Added to group'; 4756 = 'Added to group'; 4738 = 'User changed'; 4719 = 'Audit policy changed'; 1102 = 'Security log cleared'; 4616 = 'System time changed'; 1100 = 'Event logging shut down'; 4657 = 'Registry value modified'; 5136 = 'Directory object changed' }
    foreach ($e in (& $q 'Security' @($secNames.Keys) 3000)) {
        $f = $e.Fields
        $cat = switch ($e.Id) { { $_ -in 4698, 4699, 4702 } { 'Scheduled task' } { $_ -in 4719, 1102, 4616, 1100 } { 'Logging' } 4657 { 'Registry' } default { 'Account' } }
        $target = switch ($e.Id) {
            { $_ -in 4698, 4699, 4702 } { $f.TaskName }
            { $_ -in 4728, 4732, 4756 } { "$($f.MemberName) → $($f.TargetUserName)" }
            4657 { "$($f.ObjectName)\$($f.ObjectValueName)" }
            4616 { "$($f.PreviousTime) → $($f.NewTime)" }
            4719 { "$($f.SubcategoryGuid) $($f.AuditPolicyChanges)" }
            default { $(if ($f.TargetUserName) { "$($f.TargetDomainName)\$($f.TargetUserName)" } else { '' }) }
        }
        $detail = if ($e.Id -in 4698, 4702) { Get-WfxShortText (([string]$f.TaskContent) -replace '(?s).*?<Exec>(.*?)</Exec>.*', '$1' -replace '<[^>]+>', ' ') 300 } elseif ($e.Id -eq 4616) { $f.ProcessName } else { '' }
        $out.Add((New-WfxActivity -Time $e.Time -Category $cat -Action $secNames[[int]$e.Id] -Target $target -Detail $detail -Actor "$($f.SubjectDomainName)\$($f.SubjectUserName)" -Source "Security $($e.Id)"))
    }
    foreach ($e in (& $q 'System' 104)) { $out.Add((New-WfxActivity -Time $e.Time -Category 'Logging' -Action 'Event log cleared' -Target $e.Fields.Channel -Actor "$($e.Fields.SubjectDomainName)\$($e.Fields.SubjectUserName)" -Source 'System 104')) }
    foreach ($e in (& $q 'Microsoft-Windows-TaskScheduler/Operational' 106, 140, 141)) {
        $out.Add((New-WfxActivity -Time $e.Time -Category 'Scheduled task' -Action @{ 106 = 'Scheduled task registered'; 140 = 'Scheduled task updated'; 141 = 'Scheduled task deleted' }[[int]$e.Id] -Target $e.Fields.TaskName -Actor $e.Fields.UserContext -Source "TaskScheduler $($e.Id)"))
    }
    foreach ($e in (& $q 'Microsoft-Windows-Windows Defender/Operational' 5001, 5004, 5007, 5010, 5012, 1116)) {
        $f = $e.Fields
        $a = @{ 5001 = 'Real-time protection disabled'; 5004 = 'Real-time protection config changed'; 5007 = 'Defender configuration changed'; 5010 = 'Spyware scanning disabled'; 5012 = 'Virus scanning disabled'; 1116 = 'Malware detected' }[[int]$e.Id]
        $t = if ($e.Id -eq 5007) { Get-WfxShortText "$($f.'Old Value') → $($f.'New Value')" 300 } elseif ($e.Id -eq 1116) { "$($f.'Threat Name') · $($f.Path)" } else { '' }
        $out.Add((New-WfxActivity -Time $e.Time -Category 'Defender' -Action $a -Target $t -Source "Defender $($e.Id)"))
    }
    foreach ($e in (& $q 'Microsoft-Windows-Windows Firewall With Advanced Security/Firewall' 2004, 2005, 2006, 2033, 2097, 2099, 2003)) {
        $f = $e.Fields
        $a = @{ 2004 = 'Firewall rule added'; 2097 = 'Firewall rule added'; 2005 = 'Firewall rule changed'; 2099 = 'Firewall rule changed'; 2006 = 'Firewall rule deleted'; 2033 = 'All firewall rules deleted'; 2003 = 'Firewall profile setting changed' }[[int]$e.Id]
        $out.Add((New-WfxActivity -Time $e.Time -Category 'Firewall' -Action $a -Target "$($f.RuleName)" -Detail "app=$($f.ApplicationPath) ports=$($f.LocalPorts) dir=$($f.Direction) action=$($f.Action)" -Actor "$($f.ModifyingApplication)" -Source "Firewall $($e.Id)"))
    }
    foreach ($e in (& $q 'Microsoft-Windows-Bits-Client/Operational' 59, 60)) {
        if ($e.Fields.url) { $out.Add((New-WfxActivity -Time $e.Time -Category 'Download' -Action 'BITS transfer' -Target $e.Fields.url -Detail "job=$($e.Fields.name)" -Source "BITS $($e.Id)")) }
    }
    foreach ($e in (& $q 'Microsoft-Windows-WMI-Activity/Operational' 5861)) {
        $out.Add((New-WfxActivity -Time $e.Time -Category 'WMI' -Action 'Permanent WMI subscription registered' -Target (Get-WfxShortText ((@($e.Fields.Values) | Where-Object { $_ }) -join ' ') 300) -Source 'WMI-Activity 5861'))
    }
    foreach ($e in (& $q 'Microsoft-Windows-TerminalServices-RDPClient/Operational' 1024, 1102)) {
        $out.Add((New-WfxActivity -Time $e.Time -Category 'Network' -Action 'Outbound RDP connection' -Target "$($e.Fields.Value)" -Source "RDPClient $($e.Id)"))
    }
    foreach ($e in (& $q 'Microsoft-Windows-Sysmon/Operational' 2, 11, 12, 13, 14, 23, 26 5000)) {
        $f = $e.Fields
        switch ($e.Id) {
            2 { $out.Add((New-WfxActivity -Time $e.Time -Category 'File' -Action 'File creation time changed (timestomp?)' -Target $f.TargetFilename -Detail "$($f.PreviousCreationUtcTime) → $($f.CreationUtcTime)" -Actor $f.Image -Source 'Sysmon 2')) }
            11 { if ($f.TargetFilename -match '(?i)\.(?:exe|dll|sys|ps1|bat|cmd|vbs|js|hta|scr|lnk|msi)$') { $out.Add((New-WfxActivity -Time $e.Time -Category 'File' -Action 'Executable/script created' -Target $f.TargetFilename -Actor $f.Image -Source 'Sysmon 11')) } }
            { $_ -in 12, 13, 14 } { $out.Add((New-WfxActivity -Time $e.Time -Category 'Registry' -Action $(switch ($e.Id) { 12 { "Registry $($f.EventType)" } 13 { 'Registry value set' } 14 { 'Registry key renamed' } }) -Target $f.TargetObject -Detail $f.Details -Actor $f.Image -Source "Sysmon $($e.Id)")) }
            { $_ -in 23, 26 } { $out.Add((New-WfxActivity -Time $e.Time -Category 'File' -Action 'File deleted' -Target $f.TargetFilename -Actor $f.Image -Source "Sysmon $($e.Id)")) }
        }
    }
    $out.ToArray()
}

function Get-WfxExecutionActivity {
    <# Program execution evidence: Prefetch (last run), BAM (last run per user, full path), UserAssist (GUI launches). #>
    param([int]$Days = 7)
    if (-not (Test-WfxWindows)) { return @() }
    $cut = (Get-Date).ToUniversalTime().AddDays(-[Math]::Abs($Days))
    $out = New-Object System.Collections.Generic.List[object]
    Get-ChildItem -LiteralPath (Join-Path $env:SystemRoot 'Prefetch') -Filter *.pf -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTimeUtc -ge $cut } | ForEach-Object {
        $out.Add((New-WfxActivity -Time $_.LastWriteTimeUtc -Category 'Execution' -Action 'Program ran (Prefetch)' -Target ($_.BaseName -replace '-[0-9A-F]{8}$', '') -Detail "first seen $(ConvertTo-WfxUtcString $_.CreationTimeUtc)" -Source 'Prefetch'))
    }
    foreach ($bamRoot in 'HKLM:\SYSTEM\CurrentControlSet\Services\bam\State\UserSettings', 'HKLM:\SYSTEM\CurrentControlSet\Services\bam\UserSettings') {
        foreach ($sidKey in (Get-ChildItem -LiteralPath $bamRoot -ErrorAction SilentlyContinue)) {
            $user = try { (New-Object Security.Principal.SecurityIdentifier($sidKey.PSChildName)).Translate([Security.Principal.NTAccount]).Value } catch { $sidKey.PSChildName }
            foreach ($n in $sidKey.GetValueNames()) {
                $v = $sidKey.GetValue($n)
                if ($v -isnot [byte[]] -or $v.Length -lt 8) { continue }
                $t = [DateTime]::FromFileTimeUtc([BitConverter]::ToInt64($v, 0))
                if ($t -lt $cut) { continue }
                $path = $n -replace '^\\Device\\HarddiskVolume\d+', '(volume)'
                $out.Add((New-WfxActivity -Time $t -Category 'Execution' -Action 'Program ran (BAM)' -Target $path -Actor $user -Source 'BAM registry'))
            }
        }
    }
    foreach ($h in @(Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-|^S-1-12-1-' -and $_.PSChildName -notmatch '_Classes$' })) {
        $ua = "Registry::HKEY_USERS\$($h.PSChildName)\Software\Microsoft\Windows\CurrentVersion\Explorer\UserAssist"
        foreach ($g in (Get-ChildItem -LiteralPath $ua -ErrorAction SilentlyContinue)) {
            $ck = Get-Item -LiteralPath (Join-Path $g.PSPath 'Count') -ErrorAction SilentlyContinue
            if (-not $ck) { continue }
            foreach ($n in $ck.GetValueNames()) {
                $v = $ck.GetValue($n)
                if ($v -isnot [byte[]] -or $v.Length -lt 68) { continue }
                $ft = [BitConverter]::ToInt64($v, 60); if ($ft -le 0) { continue }
                $t = [DateTime]::FromFileTimeUtc($ft); if ($t -lt $cut) { continue }
                $name = -join ($n.ToCharArray() | ForEach-Object { $c = [int]$_; if ($c -ge 65 -and $c -le 90) { [char](65 + ($c - 52) % 26) } elseif ($c -ge 97 -and $c -le 122) { [char](97 + ($c - 84) % 26) } else { $_ } })
                $out.Add((New-WfxActivity -Time $t -Category 'Execution' -Action 'Program launched by user (UserAssist)' -Target $name -Detail "run count $([BitConverter]::ToInt32($v, 4))" -Actor $h.PSChildName -Source 'UserAssist registry'))
            }
        }
    }
    $out.ToArray()
}

function Get-WfxConnectionActivity {
    <# Connection history from whatever this host records: Sysmon 3, Security 5156, the firewall log,
       live connection creation times, outbound RDP history. #>
    param([int]$Days = 7, [int]$Max = 5000)
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $cut = (Get-Date).AddDays(-[Math]::Abs($Days))
    try {
        foreach ($e in @(Get-WfxEventQuick -Log 'Microsoft-Windows-Sysmon/Operational' -Id 3 -Days $Days -Max $Max)) {
            $f = $e.Fields
            if (Test-WfxPrivateIp $f.DestinationIp) { continue }
            $out.Add((New-WfxActivity -Time $e.Time -Category 'Network' -Action 'Outbound connection' -Target "$($f.DestinationIp):$($f.DestinationPort)" -Detail $(if ($f.DestinationHostname) { $f.DestinationHostname } else { '' }) -Actor $f.Image -Source 'Sysmon 3'))
        }
    } catch {}
    try {
        foreach ($e in @(Get-WfxEventQuick -Log Security -Id 5156 -Days $Days -Max $Max)) {
            $f = $e.Fields
            if ([string]$f.Direction -notmatch '14593|Outbound' -or (Test-WfxPrivateIp $f.DestAddress)) { continue }
            $out.Add((New-WfxActivity -Time $e.Time -Category 'Network' -Action 'Outbound connection allowed' -Target "$($f.DestAddress):$($f.DestPort)" -Actor $f.Application -Source 'Security 5156 (WFP)'))
        }
    } catch {}
    $fwLog = Join-Path $env:SystemRoot 'System32\LogFiles\Firewall\pfirewall.log'
    if (Test-Path -LiteralPath $fwLog) {
        try {
            foreach ($l in (Get-Content -LiteralPath $fwLog -Tail 20000 -ErrorAction Stop)) {
                if ($l -notmatch '^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2}) (ALLOW|DROP) (\S+) (\S+) (\S+) (\S+) (\S+)') { continue }
                $t = [datetime]::ParseExact("$($Matches[1]) $($Matches[2])", 'yyyy-MM-dd HH:mm:ss', $null)
                if ($t -lt $cut) { continue }
                $dst = $Matches[6]; $src = $Matches[5]
                if ((Test-WfxPrivateIp $dst) -and (Test-WfxPrivateIp $src)) { continue }
                $out.Add((New-WfxActivity -Time $t -Category 'Network' -Action "Firewall $($Matches[3].ToLower()) ($($Matches[4]))" -Target "$src → ${dst}:$($Matches[8])" -Source 'pfirewall.log'))
            }
        } catch {}
    }
    try {
        $names = @{}; Get-Process -ErrorAction SilentlyContinue | ForEach-Object { $names[[int]$_.Id] = $_.ProcessName }
        Get-NetTCPConnection -State Established -ErrorAction Stop | Where-Object { $_.CreationTime -ge $cut -and -not (Test-WfxPrivateIp $_.RemoteAddress) } | ForEach-Object {
            $out.Add((New-WfxActivity -Time $_.CreationTime -Category 'Network' -Action 'Connection opened (still open)' -Target "$($_.RemoteAddress):$($_.RemotePort)" -Actor $names[[int]$_.OwningProcess] -Source 'live TCP table'))
        }
    } catch {}
    foreach ($h in @(Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-|^S-1-12-1-' -and $_.PSChildName -notmatch '_Classes$' })) {
        $srv = "Registry::HKEY_USERS\$($h.PSChildName)\Software\Microsoft\Terminal Server Client\Servers"
        foreach ($s in (Get-ChildItem -LiteralPath $srv -ErrorAction SilentlyContinue)) {
            $t = Get-WfxRegKeyTime $s.PSPath
            $out.Add((New-WfxActivity -Time $t -Category 'Network' -Action 'Outbound RDP target (saved)' -Target $s.PSChildName -Detail "user hint: $($s.GetValue('UsernameHint'))" -Actor $h.PSChildName -Source 'Terminal Server Client registry'))
        }
    }
    $out.ToArray()
}

function Get-WfxActivityData {
    <#
    .SYNOPSIS Collects all recent-activity evidence (see file header). Each part degrades to a gap on error.
    .PARAMETER Days       Look-back window.
    .PARAMETER Journal    Also read the NTFS change journal (admin; slower).
    #>
    param([int]$Days = 7, [switch]$Journal)
    if (-not (Test-WfxWindows)) { return @() }
    $all = New-Object System.Collections.Generic.List[object]
    foreach ($part in @(
            @{ N = 'activity:registry'; S = { Get-WfxRegistryActivity -Days $Days } }
            @{ N = 'activity:events'; S = { Get-WfxEventActivity -Days $Days } }
            @{ N = 'activity:execution'; S = { Get-WfxExecutionActivity -Days $Days } }
            @{ N = 'activity:network'; S = { Get-WfxConnectionActivity -Days $Days } }
            @{ N = 'activity:recyclebin'; S = { Get-WfxRecycleBinActivity -Days ([Math]::Max($Days, 30)) } }
        )) {
        foreach ($r in @(Invoke-WfxStep $part.N $part.S @())) { if ($r) { $all.Add($r) } }
    }
    if ($Journal) { foreach ($r in @(Invoke-WfxStep 'activity:usn' { Get-WfxUsnActivity -Days $Days } @())) { if ($r) { $all.Add($r) } } }
    $all.ToArray() | Sort-Object Time -Descending
}


# ===== Collectors/Artifacts.ps1 =====
# Evidence-of-execution and user-activity artifacts: ShimCache, Amcache, ShellBags, Jump Lists, shortcut
# files, Program Compatibility Assistant logs, Defender support logs and browser download history.
#
# Every parser works on bytes or text that has already been read, so the same code serves a live host and
# a folder of collected files (KAPE output, a mounted image, CTF evidence). Nothing is executed, loaded
# into the registry, or written back; files are opened read-only with sharing so the system keeps running.
#
# Every record has the same shape (New-WfxArtifact) so analyzers, the timeline, the report and the
# exports treat them alike:
#   Artifact  ShimCache | Amcache | AmcacheProgram | AmcacheDriver | ShellBag | JumpList | Shortcut | PCA | DefenderLog | Download
#   Time      UTC ISO-8601; what the time means is in TimeKind
#   Evidence  Execution | Presence | Access | Download | Detection | Install
#   Path, Name, Sha1, User, Detail, Source (the file or key it came from), Extra (artifact-specific fields)

function New-WfxArtifact {
    param([string]$Artifact, $Time, [string]$TimeKind, [string]$Evidence, [string]$Path, [string]$Name = '',
        [string]$Sha1 = '', [string]$User = '', [string]$Detail = '', [string]$Source = '', $Extra = $null)
    if (-not $Name -and $Path) { $Name = ($Path -split '[\\/]')[-1] }
    [pscustomobject]@{
        Artifact = $Artifact; Time = (ConvertTo-WfxUtcString $Time); TimeKind = $TimeKind; Evidence = $Evidence
        Path = (Protect-WfxText $Path); Name = (Protect-WfxText $Name); Sha1 = $Sha1; User = $User
        Detail = (Protect-WfxText $Detail); Source = $Source; Extra = $Extra
    }
}

# ───────────────────────────── ShimCache (AppCompatCache) ─────────────────────────────
function ConvertFrom-WfxShimCache {
    <#
    .SYNOPSIS Parses the AppCompatCache registry value (Windows 7 / 8 / 8.1 / 10 / 11).
    Each entry is a file the shell checked for compatibility: proof the file EXISTED at that path, not proof
    that it ran. LastModified is the file's own $STANDARD_INFORMATION modification time, not a run time.
    Position 0 is the most recent entry. Windows writes the cache to the registry at shutdown.
    #>
    param([byte[]]$Bytes)
    $b = $Bytes
    if (-not $b -or $b.Length -lt 0x34) { return }
    $sig0 = [BitConverter]::ToUInt32($b, 0)
    $rd = { param($o, $n) if ($o -ge 0 -and $n -gt 0 -and $o + $n -le $b.Length) { [Text.Encoding]::Unicode.GetString($b, $o, $n) } else { '' } }
    $pos = 0
    if ($sig0 -eq 0xBADC0FEEL) {                                        # Windows 7 / 2008 R2
        $count = [BitConverter]::ToUInt32($b, 4)
        $x64 = ($b.Length -ge 0x80 + 0x30) -and ([BitConverter]::ToUInt32($b, 0x80 + 4) -eq 0)
        $sz = if ($x64) { 0x30 } else { 0x20 }
        for ($i = 0; $i -lt $count -and 0x80 + ($i + 1) * $sz -le $b.Length; $i++) {
            $e = 0x80 + $i * $sz; $len = [BitConverter]::ToUInt16($b, $e)
            if ($x64) { $po = [BitConverter]::ToInt64($b, $e + 8); $lm = [BitConverter]::ToInt64($b, $e + 16); $fl = [BitConverter]::ToUInt32($b, $e + 24) }
            else { $po = [BitConverter]::ToUInt32($b, $e + 4); $lm = [BitConverter]::ToInt64($b, $e + 8); $fl = [BitConverter]::ToUInt32($b, $e + 16) }
            [pscustomobject]@{ Position = $i; Path = (& $rd ([int]$po) $len); LastModified = (ConvertFrom-WfxFileTime $lm); Executed = [bool]($fl -band 2); Format = 'Win7' }
        }
        return
    }
    if ($b.Length -ge 0x84 -and $sig0 -eq 0x80) {                       # Windows 8 / 8.1: 128-byte header, '00ts' / '10ts'
        $pos = 0x80; $i = 0
        while ($pos + 14 -le $b.Length) {
            $sig = [Text.Encoding]::ASCII.GetString($b, $pos, 4); if ($sig -notin '00ts', '10ts') { break }
            $esz = [BitConverter]::ToUInt32($b, $pos + 8); $len = [BitConverter]::ToUInt16($b, $pos + 12)
            $p = $pos + 14; $path = & $rd $p $len; $p += $len
            if ($p + 2 -le $b.Length) { $p += 2 + [BitConverter]::ToUInt16($b, $p) }      # package name
            $fl = if ($p + 4 -le $b.Length) { [BitConverter]::ToUInt32($b, $p) } else { 0 }
            $lm = if ($p + 16 -le $b.Length) { [BitConverter]::ToInt64($b, $p + 8) } else { 0 }
            [pscustomobject]@{ Position = $i; Path = $path; LastModified = (ConvertFrom-WfxFileTime $lm); Executed = [bool]($fl -band 2); Format = 'Win8' }
            $i++; $pos += 12 + $esz
        }
        return
    }
    if ($sig0 -in 0x30, 0x34) {                                           # Windows 10 / 11
        $pos = [int]$sig0; $i = 0
        while ($pos + 14 -le $b.Length) {
            if ([Text.Encoding]::ASCII.GetString($b, $pos, 4) -ne '10ts') { break }
            $esz = [BitConverter]::ToUInt32($b, $pos + 8); $len = [BitConverter]::ToUInt16($b, $pos + 12)
            $p = $pos + 14; $path = & $rd $p $len; $p += $len
            $lm = if ($p + 8 -le $b.Length) { [BitConverter]::ToInt64($b, $p) } else { 0 }
            [pscustomobject]@{ Position = $i; Path = $path; LastModified = (ConvertFrom-WfxFileTime $lm); Executed = $null; Format = 'Win10' }
            $i++; $pos += 12 + $esz
        }
        return
    }
    Write-Verbose ("unsupported AppCompatCache format 0x{0:X}" -f $sig0)
}

function Get-WfxShimCacheRecord {
    param([byte[]]$Bytes, [string]$Source)
    foreach ($e in @(ConvertFrom-WfxShimCache $Bytes)) {
        if (-not $e.Path -or $e.Path -match '^[0-9a-f]{8}\t') { continue }     # packaged (Store) app entries carry no file path
        $path = $e.Path -replace '^\\\?\?\\', ''
        $ex = if ($e.Executed) { 'Execution' } else { 'Presence' }
        New-WfxArtifact -Artifact 'ShimCache' -Time $e.LastModified -TimeKind 'File modified' -Evidence $ex -Path $path `
            -Detail ("Cache position {0} ({1}); {2}" -f $e.Position, $e.Format, $(if ($e.Executed) { 'execution flag set' } else { 'shows the file existed; not proof it ran' })) `
            -Source $Source -Extra ([pscustomobject]@{ Position = $e.Position })
    }
}

function Get-WfxSystemHiveShimCache {
    param($Hive, [string]$Source)
    $cur = 1
    $sel = Get-WfxHiveKey $Hive 'Select'
    if ($sel) { $c = (Get-WfxHiveValue $Hive $sel -Name 'Current').Data; if ($c) { $cur = [int]$c } }
    $k = Get-WfxHiveKey $Hive ('ControlSet{0:D3}\Control\Session Manager\AppCompatCache' -f $cur)
    if (-not $k) { $k = Get-WfxHiveKey $Hive ('ControlSet{0:D3}\Control\Session Manager\AppCompatibility' -f $cur) }
    if (-not $k) { return }
    $v = Get-WfxHiveValue $Hive $k -Name 'AppCompatCache'
    if ($v) { Get-WfxShimCacheRecord -Bytes ([byte[]]$v.Data) -Source "$Source\ControlSet$('{0:D3}' -f $cur)\...\AppCompatCache" }
}

# ───────────────────────────── Amcache ─────────────────────────────
function Get-WfxAmcacheRecord {
    <#
    .SYNOPSIS Amcache.hve: programs Windows inventoried, with SHA-1. Windows 10/11 layout
    (Root\InventoryApplicationFile, Root\InventoryApplication) and the older Root\File layout.
    The key's last-write time is when Windows recorded the file, usually near its first run or install.
    #>
    param($Hive, [string]$Source, [int]$Max = 20000)
    $n = 0
    $iaf = Get-WfxHiveKey $Hive 'Root\InventoryApplicationFile'
    if ($iaf) {
        foreach ($k in @(Get-WfxHiveSubkey $Hive $iaf)) {
            if ($n++ -ge $Max) { break }
            $v = @{}; foreach ($x in @(Get-WfxHiveValue $Hive $k)) { $v[$x.Name] = $x.Data }
            $path = [string]$v['LowerCaseLongPath']; if (-not $path) { continue }
            $sha = ([string]$v['FileId']) -replace '^0000', ''
            $link = [string]$v['LinkDate']
            New-WfxArtifact -Artifact 'Amcache' -Time $k.LastWrite -TimeKind 'Recorded' -Evidence 'Execution' -Path $path -Name ([string]$v['Name']) -Sha1 $sha.ToLowerInvariant() `
                -Detail (@(@($v['Publisher'], $v['ProductName'], $v['Version']) | Where-Object { $_ }) -join ' · ') -Source "$Source\Root\InventoryApplicationFile" `
                -Extra ([pscustomobject]@{ Publisher = [string]$v['Publisher']; Product = [string]$v['ProductName']; Version = [string]$v['Version']; LinkDate = $link
                    Size = $v['Size']; OsComponent = ([string]$v['IsOsComponent'] -eq '1'); BinaryType = [string]$v['BinaryType']; ProgramId = [string]$v['ProgramId'] })
        }
    }
    $ia = Get-WfxHiveKey $Hive 'Root\InventoryApplication'
    if ($ia) {
        foreach ($k in @(Get-WfxHiveSubkey $Hive $ia)) {
            $v = @{}; foreach ($x in @(Get-WfxHiveValue $Hive $k)) { $v[$x.Name] = $x.Data }
            $nm = [string]$v['Name']; if (-not $nm) { continue }
            $inst = ConvertTo-WfxDateTime ([string]$v['InstallDate'])
            New-WfxArtifact -Artifact 'AmcacheProgram' -Time $(if ($inst) { $inst } else { $k.LastWrite }) -TimeKind $(if ($inst) { 'Installed' } else { 'Recorded' }) -Evidence 'Install' `
                -Path ([string]$v['RootDirPath']) -Name $nm -Detail (@(@($v['Publisher'], $v['Version'], $v['Source']) | Where-Object { $_ }) -join ' · ') `
                -Source "$Source\Root\InventoryApplication" -Extra ([pscustomobject]@{ Publisher = [string]$v['Publisher']; Version = [string]$v['Version']; InstallSource = [string]$v['Source']; ProgramId = $k.Name; UninstallString = [string]$v['UninstallString'] })
        }
    }
    $file = Get-WfxHiveKey $Hive 'Root\File'                               # Windows 8 / early Windows 10 layout (also carries DLLs)
    if ($file) {
        foreach ($vol in @(Get-WfxHiveSubkey $Hive $file)) {
            foreach ($k in @(Get-WfxHiveSubkey $Hive $vol)) {
                if ($n++ -ge $Max) { break }
                $v = @{}; foreach ($x in @(Get-WfxHiveValue $Hive $k)) { $v[$x.Name] = $x.Data }
                $path = [string]$v['15']; if (-not $path) { continue }
                $mod = if ($v['17']) { ConvertFrom-WfxFileTime ([long]$v['17']) } else { $null }
                New-WfxArtifact -Artifact 'Amcache' -Time $k.LastWrite -TimeKind 'Recorded' -Evidence 'Execution' -Path $path -Sha1 ((([string]$v['101']) -replace '^0000', '').ToLowerInvariant()) `
                    -Detail (@(@($v['1'], $v['0']) | Where-Object { $_ }) -join ' · ') -Source "$Source\Root\File" `
                    -Extra ([pscustomobject]@{ Publisher = [string]$v['1']; Product = [string]$v['0']; Modified = (ConvertTo-WfxUtcString $mod) })
            }
        }
    }
    $drv = Get-WfxHiveKey $Hive 'Root\InventoryDriverBinary'                 # drivers Windows has seen (BYOVD hunting)
    if ($drv) {
        foreach ($k in @(Get-WfxHiveSubkey $Hive $drv)) {
            if ($n++ -ge $Max) { break }
            $v = @{}; foreach ($x in @(Get-WfxHiveValue $Hive $k)) { $v[$x.Name] = $x.Data }
            $path = ($k.Name -replace '/', '\')
            $signed = if ($v.ContainsKey('DriverSigned')) { [string]$v['DriverSigned'] -eq '1' } else { $null }
            New-WfxArtifact -Artifact 'AmcacheDriver' -Time $k.LastWrite -TimeKind 'Recorded' -Evidence 'Presence' -Path $path -Name ([string]$v['DriverName']) `
                -Sha1 ((([string]$v['DriverId']) -replace '^0000', '').ToLowerInvariant()) `
                -Detail (@(@($v['DriverCompany'], $v['Product'], $v['DriverVersion'], $(if ($signed -eq $false) { 'unsigned' })) | Where-Object { $_ }) -join ' · ') -Source "$Source\Root\InventoryDriverBinary" `
                -Extra ([pscustomobject]@{ Company = [string]$v['DriverCompany']; Product = [string]$v['Product']; Version = [string]$v['DriverVersion']; Signed = $signed; Service = [string]$v['Service'] })
        }
    }
}

