    '5E6C858F-0E22-4760-9AFE-EA3317B67173' = '%USERPROFILE%'; '9E3995AB-1F9C-4F13-B827-48B24B6C7174' = 'User Pinned'
    '018D5C66-4533-4307-9B53-224DE2ED1FE6' = 'OneDrive'; '679F85CB-0220-4080-B29B-5540CC05AAB6' = 'Quick access'
