    'D20EA4E1-3957-11D2-A40B-0C5020524153' = 'Administrative Tools'; '2227A280-3AEA-1069-A2DE-08002B30309D' = 'Printers'; 'ED7BA470-8E54-465E-825C-99712043E01C' = 'All Tasks (God Mode)'
}

function ConvertFrom-WfxDosTime {
    param([uint32]$Value)
    if (-not $Value) { return $null }
    $date = $Value -band 0xFFFF; $time = ($Value -shr 16) -band 0xFFFF
    try { [datetime]::new(1980 + ($date -shr 9), ($date -shr 5) -band 0xF, $date -band 0x1F, $time -shr 11, ($time -shr 5) -band 0x3F, ($time -band 0x1F) * 2, [DateTimeKind]::Utc) } catch { $null }
}

function ConvertFrom-WfxShellItem {
    <#
    .SYNOPSIS Decodes one shell item (an entry of an ITEMIDLIST) into a display name and its kind.
    Covers root folders, drives, file/folder entries (with the long name and times from the 0xBEEF0004
    extension block), network locations and URIs; anything else is returned with its type byte.
    #>
    param([byte[]]$B)
    if (-not $B -or $B.Length -lt 3) { return $null }
    $t = $B[2]; $kind = 'Other'; $name = ''; $mod = $null; $created = $null; $accessed = $null; $mft = $null
    $ascii = { param($o) $e = $o; while ($e -lt $B.Length -and $B[$e] -ne 0) { $e++ }; if ($e -gt $o) { [Text.Encoding]::GetEncoding(28591).GetString($B, $o, $e - $o) } else { '' } }
    $uni = { param($o) $e = $o; while ($e + 1 -lt $B.Length -and ($B[$e] -ne 0 -or $B[$e + 1] -ne 0)) { $e += 2 }; if ($e -gt $o) { [Text.Encoding]::Unicode.GetString($B, $o, $e - $o) } else { '' } }
    # Long name and times from a BEEF0004 extension block, wherever it sits in the item.
    $ext = {
        for ($i = 4; $i + 8 -lt $B.Length; $i++) {
            if ($B[$i] -eq 0x04 -and $B[$i + 1] -eq 0x00 -and $B[$i + 2] -eq 0xEF -and $B[$i + 3] -eq 0xBE) {
                $s = $i - 4; $ver = [BitConverter]::ToUInt16($B, $s + 2)
                if ($s -lt 0 -or $s + 0x14 -gt $B.Length) { return $null }
                $off = if ($ver -ge 9) { 0x2E } elseif ($ver -ge 8) { 0x2A } elseif ($ver -ge 7) { 0x26 } else { 0x14 }
                $mftRef = if ($ver -ge 7 -and $s + 0x1C -le $B.Length) { [BitConverter]::ToUInt64($B, $s + 0x14) } else { $null }
                return [pscustomobject]@{ Created = (ConvertFrom-WfxDosTime ([BitConverter]::ToUInt32($B, $s + 8))); Accessed = (ConvertFrom-WfxDosTime ([BitConverter]::ToUInt32($B, $s + 12)))
                    Name = $(if ($s + $off -lt $B.Length) { & $uni ($s + $off) } else { '' }); Mft = $mftRef }
            }
        }
        $null
    }
    switch ($t) {
        0x1F {
            $kind = 'Root'
            $txt = [Text.Encoding]::GetEncoding(28591).GetString($B)
            $dm = [regex]::Match($txt, '[A-Za-z]:\\')
            if ($B.Length -eq 20) { $g = ([guid]::new([byte[]]$B[4..19])).ToString().ToUpperInvariant(); $name = if ($script:WfxKnownFolder[$g]) { $script:WfxKnownFolder[$g] } else { "{$g}" } }
            elseif ($dm.Success) { $kind = 'Drive'; $name = $dm.Value }
            elseif ($B.Length -ge 10 -and [BitConverter]::ToUInt32($B, 6) -eq 0x23A3DFD5) { $name = 'Search Folder' }
            elseif ($B.Length -ge 20) { $g = ([guid]::new([byte[]]$B[4..19])).ToString().ToUpperInvariant(); $name = if ($script:WfxKnownFolder[$g]) { $script:WfxKnownFolder[$g] } else { "{$g}" } }
        }
        { $_ -ge 0x20 -and $_ -le 0x2F } {
            $kind = 'Drive'
            if ($B.Length -ge 6 -and $B[4] -eq 0x3A -and (($B[3] -bor 0x20) -ge 0x61) -and (($B[3] -bor 0x20) -le 0x7A)) { $name = & $ascii 3 }
            elseif ($B.Length -ge 20) {
                $g = ([guid]::new([byte[]]$B[4..19])).ToString().ToUpperInvariant()
                if ($script:WfxKnownFolder[$g]) { $kind = 'Root'; $name = $script:WfxKnownFolder[$g] } else { $name = "{$g}" }
            } else { $name = '{Drive}' }
        }
        0x01 {
            $kind = 'ControlPanel'
            $cats = @('All Control Panel Items', 'Appearance and Personalization', 'Hardware and Sound', 'Network and Internet', 'Sounds, Speech and Audio Devices', 'System and Security', 'Clock and Region', 'Ease of Access', 'Programs', 'User Accounts', 'Security Center', 'Mobile PC')
            $ci = if ($B.Length -ge 12) { [BitConverter]::ToUInt32($B, 8) } else { 99 }
            $name = if ($ci -lt $cats.Count) { $cats[$ci] } else { 'Control Panel category' }
        }
        { $_ -ge 0x30 -and $_ -le 0x3F } {
            $kind = if ($t -band 0x01) { 'Folder' } elseif ($t -band 0x02) { 'File' } else { 'Entry' }
            if ($B.Length -ge 14) {
                $mod = ConvertFrom-WfxDosTime ([BitConverter]::ToUInt32($B, 8))
                $name = if ($t -band 0x04) { & $uni 14 } else { & $ascii 14 }
            }
            $x = & $ext; if ($x) { if ($x.Name) { $name = $x.Name }; $created = $x.Created; $accessed = $x.Accessed; $mft = $x.Mft }
        }
        { $_ -ge 0x40 -and $_ -le 0x4F } {
            $kind = 'Network'; $name = & $ascii 5
        }
        0xC3 { $kind = 'Network'; $name = & $ascii 5 }
        0x61 {
            $kind = 'URI'
            $u = [regex]::Match([Text.Encoding]::Unicode.GetString($B, 0, $B.Length - ($B.Length % 2)), '(?i)(?:https?|ftp|file|ms-[a-z-]+):[^\x00]+')
            if (-not $u.Success) { $u = [regex]::Match([Text.Encoding]::GetEncoding(28591).GetString($B), '(?i)(?:https?|ftp|file):[^\x00]+') }
            if (-not $u.Success -and $B.Length -gt 1) { $u = [regex]::Match([Text.Encoding]::Unicode.GetString($B, 1, $B.Length - 1 - (($B.Length - 1) % 2)), '(?i)(?:https?|ftp|file):[^\x00]+') }
            $name = if ($u.Success) { $u.Value } else { '(URI)' }
        }
        0x71 {
            $kind = 'ControlPanel'
            if ($B.Length -ge 0x1E) { $g = ([guid]::new([byte[]]$B[14..29])).ToString().ToUpperInvariant(); $name = if ($script:WfxKnownFolder[$g]) { $script:WfxKnownFolder[$g] } else { "Control Panel item {$g}" } }
        }
        0x74 {
            $kind = 'Folder'; $x = & $ext
            if ($x) { $name = $x.Name; $created = $x.Created; $accessed = $x.Accessed; $mft = $x.Mft }
            if (-not $name -and $B.Length -gt 0x1A) { $name = & $ascii 0x1A }
        }
        default {
            $x = & $ext
            if ($x -and $x.Name) { $kind = 'Entry'; $name = $x.Name; $created = $x.Created; $accessed = $x.Accessed; $mft = $x.Mft }
            else { $name = ('(shell item 0x{0:X2})' -f $t) }
        }
    }
    [pscustomobject]@{ Kind = $kind; Name = $name; Modified = $mod; Created = $created; Accessed = $accessed; MftEntry = $(if ($mft) { $mft -band 0xFFFFFFFFFFFFL } else { $null }) }
}

function Join-WfxShellPath {
    param([string]$Parent, $Item)
    if (-not $Item) { return $Parent }
    $n = [string]$Item.Name
    if (-not $Parent) { if ($Item.Kind -eq 'Network' -and $n -notmatch '^\\\\') { return "\\$n" }; return $n }
    if ($Parent -in 'This PC', 'Network', 'Libraries', 'Quick access', 'Users Files' -and $Item.Kind -in 'Drive', 'Network') { return $n }
    if ($Item.Kind -in 'Drive', 'URI') { return $n }
    if ($Item.Kind -eq 'Network' -and $n -match '^\\\\') { return $n }
    return ($Parent.TrimEnd('\') + '\' + $n)
}

function ConvertFrom-WfxIdList {
    <# Splits an ITEMIDLIST (u16-size-prefixed items, ending with 0) into decoded shell items. #>
    param([byte[]]$Bytes, [int]$Offset = 0)
    $p = $Offset
    while ($p + 2 -le $Bytes.Length) {
        $sz = [BitConverter]::ToUInt16($Bytes, $p); if ($sz -lt 3 -or $p + $sz -gt $Bytes.Length) { break }
        $item = New-Object byte[] $sz; [Array]::Copy($Bytes, $p, $item, 0, $sz)
        ConvertFrom-WfxShellItem $item
        $p += $sz
    }
}

# ───────────────────────────── ShellBags ─────────────────────────────
function Get-WfxShellBagRecord {
    <#
    .SYNOPSIS Folders a user opened in Explorer (including on USB drives, network shares and deleted
    folders) from the BagMRU tree of UsrClass.dat / NTUSER.DAT. Works on an offline hive handle
    (-Hive) or on a live registry key (-LiveKey). Time = last write of the folder's BagMRU key, which is
    roughly the last time the folder's view was updated.
    #>
    param($Hive, $LiveKey, [string]$KeyPath, [string]$User = '', [string]$Source = '', [int]$Max = 20000)
    $out = New-Object System.Collections.Generic.List[object]
    $stack = New-Object System.Collections.Generic.Stack[object]
    if ($Hive) { $root = Get-WfxHiveKey $Hive $KeyPath; if (-not $root) { return }; $stack.Push(@($root, '', 0)) }
    elseif ($LiveKey) { $stack.Push(@($LiveKey, '', 0)) } else { return }
    $seen = 0
    while ($stack.Count -and $seen -lt $Max) {
        $f = $stack.Pop(); $node = $f[0]; $parentPath = $f[1]; $depth = $f[2]
        if ($depth -gt 64) { continue }
        if ($Hive) {
            $vals = @{}; foreach ($v in @(Get-WfxHiveValue $Hive $node)) { if ($v.Name -match '^\d+$') { $vals[$v.Name] = [byte[]]$v.Data } }
            $subs = @{}; foreach ($k in @(Get-WfxHiveSubkey $Hive $node)) { $subs[$k.Name] = $k }
        } else {
            $vals = @{}; foreach ($vn in @($node.GetValueNames())) { if ($vn -match '^\d+$') { $d = $node.GetValue($vn); if ($d -is [byte[]]) { $vals[$vn] = $d } } }
            $subs = @{}; foreach ($sn in @($node.GetSubKeyNames())) { if ($sn -match '^\d+$') { $subs[$sn] = $sn } }
        }
        foreach ($num in $vals.Keys) {
            $seen++
            $item = ConvertFrom-WfxShellItem $vals[$num]
            $path = Join-WfxShellPath $parentPath $item
            $child = $subs[$num]
            $childNode = $null; $lw = $null
            if ($child) {
                if ($Hive) { $childNode = $child; $lw = $child.LastWrite }
                else { try { $childNode = $node.OpenSubKey($child, $false); $lw = Get-WfxRegKeyObjectTime $childNode } catch { } }
            }
            $out.Add((New-WfxArtifact -Artifact 'ShellBag' -Time $lw -TimeKind 'Folder view updated' -Evidence 'Access' -Path $path -Name ([string]$item.Name) -User $User `
                        -Detail ("{0}{1}" -f $item.Kind, $(if ($item.Accessed) { "; folder accessed $(ConvertTo-WfxUtcString $item.Accessed)" })) -Source $Source `
                        -Extra ([pscustomobject]@{ Kind = $item.Kind; Created = (ConvertTo-WfxUtcString $item.Created); Modified = (ConvertTo-WfxUtcString $item.Modified); Accessed = (ConvertTo-WfxUtcString $item.Accessed); MftEntry = $item.MftEntry })))
            if ($childNode) { $stack.Push(@($childNode, $path, $depth + 1)) }
        }
    }
    $out.ToArray()
}

# ───────────────────────────── compound files (Jump Lists) ─────────────────────────────
function Read-WfxCompoundFile {
    <#
    .SYNOPSIS Minimal read-only [MS-CFB] reader. Returns @{ Name; Bytes } for every stream, or $null when
    the data is not a compound file. Bounded: chains are cut at the file size to defeat loops.
    #>
    param([byte[]]$Bytes)
    $b = $Bytes
    if (-not $b -or $b.Length -lt 512 -or [BitConverter]::ToString($b, 0, 8) -ne 'D0-CF-11-E0-A1-B1-1A-E1') { return $null }
    $ss = 1 -shl [BitConverter]::ToUInt16($b, 0x1E); $mss = 1 -shl [BitConverter]::ToUInt16($b, 0x20)
    if ($ss -notin 512, 4096 -or $mss -ne 64) { return $null }
    $cutoff = [BitConverter]::ToUInt32($b, 0x38)
    $maxSec = [int][Math]::Ceiling($b.Length / $ss)
    $secOff = { param([long]$s) ($s + 1) * $ss }
    # FAT sector list from the header DIFAT (109 entries) and any DIFAT sectors.
    $fatSecs = New-Object System.Collections.Generic.List[uint32]
    for ($i = 0; $i -lt 109; $i++) { $s = [BitConverter]::ToUInt32($b, 0x4C + $i * 4); if ($s -lt 0xFFFFFFFAL) { $fatSecs.Add($s) } }
    $dif = [BitConverter]::ToUInt32($b, 0x44); $guard = 0
    while ($dif -lt 0xFFFFFFFAL -and $guard++ -lt $maxSec) {
        $o = & $secOff $dif; if ($o + $ss -gt $b.Length) { break }
        for ($i = 0; $i -lt ($ss / 4) - 1; $i++) { $s = [BitConverter]::ToUInt32($b, $o + $i * 4); if ($s -lt 0xFFFFFFFAL) { $fatSecs.Add($s) } }
        $dif = [BitConverter]::ToUInt32($b, $o + $ss - 4)
    }
    $fat = New-Object System.Collections.Generic.List[uint32]
    foreach ($fs in $fatSecs) { $o = & $secOff $fs; if ($o + $ss -gt $b.Length) { continue }; for ($i = 0; $i -lt $ss / 4; $i++) { $fat.Add([BitConverter]::ToUInt32($b, $o + $i * 4)) } }
    $chain = {
        param([uint32]$Start)
        $list = New-Object System.Collections.Generic.List[uint32]; $s = $Start; $g = 0
        while ($s -lt 0xFFFFFFFAL -and $s -lt $fat.Count -and $g++ -lt $maxSec) { $list.Add($s); $s = $fat[[int]$s] }
        , $list.ToArray()
    }
    $readChain = {
        param([uint32]$Start, [long]$Size)
        $ms = New-Object IO.MemoryStream
        foreach ($s in (& $chain $Start)) { $o = & $secOff $s; if ($o + $ss -gt $b.Length) { break }; $ms.Write($b, [int]$o, $ss); if ($ms.Length -ge $Size) { break } }
        $a = $ms.ToArray(); if ($a.Length -gt $Size) { $t = New-Object byte[] $Size; [Array]::Copy($a, $t, $Size); $a = $t }; , $a
    }
    $dir = & $readChain ([BitConverter]::ToUInt32($b, 0x30)) ([long]$b.Length)
    $entries = New-Object System.Collections.Generic.List[object]
    for ($o = 0; $o + 128 -le $dir.Length; $o += 128) {
        $nl = [BitConverter]::ToUInt16($dir, $o + 0x40); $type = $dir[$o + 0x42]
        if ($type -eq 0 -or $nl -lt 2 -or $nl -gt 64) { continue }
        $size = if ($ss -eq 512) { [long][BitConverter]::ToUInt32($dir, $o + 0x78) } else { [BitConverter]::ToInt64($dir, $o + 0x78) }
        $entries.Add([pscustomobject]@{ Name = [Text.Encoding]::Unicode.GetString($dir, $o, $nl - 2); Type = $type; Start = [BitConverter]::ToUInt32($dir, $o + 0x74); Size = $size })
    }
    $root = $entries | Where-Object Type -eq 5 | Select-Object -First 1
    if (-not $root) { return $null }
    $mini = & $readChain $root.Start $root.Size
    $mfat = New-Object System.Collections.Generic.List[uint32]
    $mfStart = [BitConverter]::ToUInt32($b, 0x3C)
    if ($mfStart -lt 0xFFFFFFFAL) { foreach ($s in (& $chain $mfStart)) { $o = & $secOff $s; if ($o + $ss -gt $b.Length) { break }; for ($i = 0; $i -lt $ss / 4; $i++) { $mfat.Add([BitConverter]::ToUInt32($b, $o + $i * 4)) } } }
    foreach ($e in $entries) {
        if ($e.Type -ne 2 -or $e.Size -le 0 -or $e.Size -gt $b.Length * 4) { continue }
        if ($e.Size -lt $cutoff) {
            $ms = New-Object IO.MemoryStream; $s = $e.Start; $g = 0
            while ($s -lt 0xFFFFFFFAL -and $g++ -lt 1000000 -and $ms.Length -lt $e.Size) {
                $o = [long]$s * 64; if ($o + 64 -gt $mini.Length) { break }
                $ms.Write($mini, [int]$o, 64); if ($s -ge $mfat.Count) { break }; $s = $mfat[[int]$s]
            }
            $a = $ms.ToArray(); if ($a.Length -gt $e.Size) { $t = New-Object byte[] $e.Size; [Array]::Copy($a, $t, $e.Size); $a = $t }
        } else { $a = & $readChain $e.Start $e.Size }
        [pscustomobject]@{ Name = $e.Name; Bytes = $a }
    }
}

function Get-WfxJumpListAppName {
    <# Common AppIDs (the file-name prefix of a Jump List) — CRC-64 of the application path, so they are stable. #>
    param([string]$AppId)
    $known = @{
        '1b4dd67f29cb1962' = 'Windows Explorer'; 'f01b4d95cf55d32a' = 'Windows Explorer'; '5f7b5f1e01b83767' = 'Quick Access'; '9b9cdc69c1c24e2b' = 'Notepad (64-bit)'
        '7e4dca80246863e3' = 'Control Panel'; '5d696d521de238c3' = 'Google Chrome'; '9d1f905ce5044aee' = 'Microsoft Edge'; 'f0275e8685d95486' = 'Microsoft Edge'
        '6824f4a902c78fbd' = 'Mozilla Firefox'; '5c450709f7ae4396' = 'Mozilla Firefox'; 'a7bd71699cd38d1c' = 'Microsoft Word'; 'fb3b0dbfee58fac8' = 'Microsoft Word'
        '12dc1ea8e34b5a6' = 'Microsoft Paint'; 'd00655d2aa12ff6d' = 'Microsoft PowerPoint'; 'b8ab77100df80ab2' = 'Microsoft Excel'; 'f5ac5390b9115fdb' = 'Microsoft PowerPoint'
        '1bc392b8e104a00e' = 'Remote Desktop Connection'; '590aee7bdd69b59b' = 'PowerShell'; '9f5c7755804b850a' = 'Windows Script Host'; '6d2bac8f1edf6668' = 'Microsoft Outlook'
        '69639df789022856' = 'Windows Media Player'; 'b74736c2bd8cc8a5' = 'WinZip'; '290532160612e071' = 'WinRAR'; 'f1a4c04eebef2906' = '7-Zip'; '4b6925efc53a3c08' = 'Microsoft Excel'
        'bc0c37e84e063727' = 'Command Prompt'; '4cb9c5750d51c07f' = 'Movies & TV'; 'ccba5a5986c77e43' = 'Microsoft Teams'; '9839aec31243a928' = 'Microsoft Excel'
        '8e4e81d9adc545b8' = 'Microsoft Teams'; 'cfb56c56fa0f0478' = 'TeamViewer'; '4fd44f9f4ce5ec0d' = 'AnyDesk'; 'e2a593822e01aed3' = 'Adobe Acrobat'; 'ee462c3b81abb6f6' = 'Adobe Reader'
    }
    if ($known[$AppId]) { $known[$AppId] } else { '' }
}

function Get-WfxJumpListRecord {
    <#
    .SYNOPSIS Files and folders an application opened, from *.automaticDestinations-ms (with DestList:
    last-used time, open count, pin state) and *.customDestinations-ms (pinned / task items).
    #>
    param([string]$Path, [byte[]]$Bytes, [string]$User = '')
    if (-not $Bytes) { try { $Bytes = [IO.File]::ReadAllBytes($Path) } catch { return } }
    $file = Split-Path -Leaf $Path
    $appId = ($file -split '\.')[0].ToLowerInvariant()
    $app = Get-WfxJumpListAppName $appId
    $appLabel = if ($app) { "$app ($appId)" } else { "AppID $appId" }
    if ($file -match '(?i)\.customDestinations-ms$') {
        $offs = New-Object System.Collections.Generic.List[int]
        for ($i = 0; $i + 20 -le $Bytes.Length; $i++) { if ($Bytes[$i] -eq 0x4C -and $Bytes[$i + 1] -eq 0 -and $Bytes[$i + 2] -eq 0 -and $Bytes[$i + 3] -eq 0 -and $Bytes[$i + 4] -eq 0x01 -and $Bytes[$i + 5] -eq 0x14 -and $Bytes[$i + 6] -eq 0x02) { $offs.Add($i) } }
        for ($k = 0; $k -lt $offs.Count; $k++) {
            $end = if ($k + 1 -lt $offs.Count) { $offs[$k + 1] } else { $Bytes.Length }
            $seg = New-Object byte[] ($end - $offs[$k]); [Array]::Copy($Bytes, $offs[$k], $seg, 0, $seg.Length)
            $l = Get-WfxLnkInfo -Bytes $seg; if (-not $l -or -not $l.Target) { continue }
            New-WfxArtifact -Artifact 'JumpList' -Time $l.Written -TimeKind 'Target modified' -Evidence 'Access' -Path $l.Target -User $User `
                -Detail ("{0}; custom/pinned item{1}" -f $appLabel, $(if ($l.Arguments) { "; arguments: $($l.Arguments)" })) -Source $Path `
                -Extra ([pscustomobject]@{ App = $app; AppId = $appId; Arguments = $l.Arguments; DriveType = $l.DriveType; VolumeSerial = $l.DriveSerial; VolumeLabel = $l.VolumeLabel; MachineId = $l.MachineId; Pinned = $true; Count = $null })
        }
        return
    }
    $streams = @(Read-WfxCompoundFile $Bytes)
    if (-not $streams.Count) { return }
    $dest = @{}
    $dl = $streams | Where-Object Name -eq 'DestList' | Select-Object -First 1
    if ($dl -and $dl.Bytes.Length -ge 32) {
        $d = $dl.Bytes; $ver = [BitConverter]::ToUInt32($d, 0); $n = [BitConverter]::ToUInt32($d, 4)
        $p = 32
        for ($i = 0; $i -lt $n -and $p + 114 -le $d.Length; $i++) {
            $num = [BitConverter]::ToUInt32($d, $p + 88)
            $host_ = ([Text.Encoding]::ASCII.GetString($d, $p + 72, 16)).TrimEnd([char]0)
            $mod = ConvertFrom-WfxFileTime ([BitConverter]::ToInt64($d, $p + 100))
            $pin = [BitConverter]::ToInt32($d, $p + 108)
            if ($ver -ge 2) {
                if ($p + 130 -gt $d.Length) { break }
                $cnt = [BitConverter]::ToInt32($d, $p + 116); $plen = [BitConverter]::ToUInt16($d, $p + 128); $po = $p + 130; $tail = 4
            } else { $cnt = $null; $plen = [BitConverter]::ToUInt16($d, $p + 112); $po = $p + 114; $tail = 0 }
            if ($po + $plen * 2 -gt $d.Length) { break }
            $dpath = [Text.Encoding]::Unicode.GetString($d, $po, $plen * 2)
            $dest['{0:x}' -f $num] = [pscustomobject]@{ Time = $mod; Pinned = ($pin -ge 0); Count = $cnt; Host = $host_; Path = $dpath }
            $p = $po + $plen * 2 + $tail
        }
    }
    foreach ($s in $streams) {
        if ($s.Name -eq 'DestList' -or $s.Name -notmatch '^[0-9a-fA-F]+$') { continue }
        $l = Get-WfxLnkInfo -Bytes $s.Bytes
        $e = $dest[$s.Name.ToLowerInvariant()]
        $target = if ($l -and $l.Target -and -not ($e -and $e.Path -and $e.Path -notmatch '^::' -and $l.Target -eq $l.IdListPath)) { $l.Target } elseif ($e -and $e.Path) { $e.Path } elseif ($l) { $l.Target } else { '' }
        if (-not $target) { continue }
        $time = if ($e -and $e.Time) { $e.Time } elseif ($l) { $l.Written } else { $null }
        $bits = @($appLabel)
        if ($e -and $null -ne $e.Count) { $bits += "opened $($e.Count) time(s)" }
        if ($e -and $e.Pinned) { $bits += 'pinned' }
        if ($l -and $l.DriveType -and $l.DriveType -ne 'Fixed') { $bits += "$($l.DriveType) drive$(if ($l.VolumeLabel) { " '$($l.VolumeLabel)'" })$(if ($l.DriveSerial) { " serial $($l.DriveSerial)" })" }
        if ($l -and $l.Arguments) { $bits += "arguments: $($l.Arguments)" }
        New-WfxArtifact -Artifact 'JumpList' -Time $time -TimeKind $(if ($e -and $e.Time) { 'Last opened' } else { 'Target modified' }) -Evidence 'Access' -Path $target -User $User `
            -Detail ($bits -join '; ') -Source $Path `
            -Extra ([pscustomobject]@{ App = $app; AppId = $appId; Count = $(if ($e) { $e.Count }); Pinned = $(if ($e) { $e.Pinned } else { $false }); Host = $(if ($e) { $e.Host }); Arguments = $(if ($l) { $l.Arguments })
                DriveType = $(if ($l) { $l.DriveType }); VolumeSerial = $(if ($l) { $l.DriveSerial }); VolumeLabel = $(if ($l) { $l.VolumeLabel }); MachineId = $(if ($l) { $l.MachineId }); TargetCreated = $(if ($l) { ConvertTo-WfxUtcString $l.Created }) })
    }
}

function Get-WfxShortcutRecord {
    <# A .lnk file (Recent items, Desktop, Startup): the target, arguments and where the target lived. #>
    param([string]$Path, [byte[]]$Bytes, [string]$User = '', $FileTime = $null)
    $l = Get-WfxLnkInfo -Path $Path -Bytes $Bytes
    if (-not $l -or -not ($l.Target -or $l.Arguments)) { return }
    $bits = @()
    if ($l.Arguments) { $bits += "arguments: $($l.Arguments)" }
    if ($l.DriveType -and $l.DriveType -ne 'Fixed') { $bits += "$($l.DriveType) drive$(if ($l.VolumeLabel) { " '$($l.VolumeLabel)'" })$(if ($l.DriveSerial) { " serial $($l.DriveSerial)" })" }
    if ($l.ShowCommand -ne 'Normal') { $bits += "window: $($l.ShowCommand)" }
    if ($l.MachineId) { $bits += "created on $($l.MachineId)" }
    $time = if ($FileTime) { $FileTime } else { $l.Accessed }
    New-WfxArtifact -Artifact 'Shortcut' -Time $time -TimeKind $(if ($FileTime) { 'Shortcut modified' } else { 'Target accessed' }) -Evidence 'Access' -Path $l.Target -User $User `
        -Detail ($bits -join '; ') -Source $Path `
        -Extra ([pscustomobject]@{ Arguments = $l.Arguments; WorkingDir = $l.WorkingDir; Icon = $l.IconLocation; ShowCommand = $l.ShowCommand; DriveType = $l.DriveType; VolumeSerial = $l.DriveSerial; VolumeLabel = $l.VolumeLabel
            NetName = $l.NetName; MachineId = $l.MachineId; MacAddress = $l.MacAddress; TargetCreated = (ConvertTo-WfxUtcString $l.Created); TargetModified = (ConvertTo-WfxUtcString $l.Written); TargetSize = $l.Size })
}

# ───────────────────────────── browser downloads ─────────────────────────────
function ConvertFrom-WfxWebkitTime {
    param($Value)
    $v = 0L; if (-not [long]::TryParse([string]$Value, [ref]$v) -or $v -le 0) { return $null }
    ConvertFrom-WfxFileTime ($v * 10)
}

function Get-WfxBrowserDownloadRecord {
    <#
    .SYNOPSIS Files downloaded through Chromium browsers (Chrome, Edge, Brave, Opera, Vivaldi: the
    "History" database) or Firefox ("places.sqlite"): source URL, referrer, saved path, size, whether the
    browser flagged it as dangerous and whether it was opened.
    #>
    param([string]$Path, [byte[]]$Bytes, [string]$User = '', [string]$Browser = '')
    $db = Open-WfxSqlite -Path $Path -Bytes $Bytes
    if (-not $db) { return }
    if (-not $Browser) { $Browser = if ($Path -match '(?i)\\Edge\\') { 'Edge' } elseif ($Path -match '(?i)Brave') { 'Brave' } elseif ($Path -match '(?i)\\Opera') { 'Opera' } elseif ($Path -match '(?i)Vivaldi') { 'Vivaldi' } elseif ($Path -match '(?i)places\.sqlite$') { 'Firefox' } else { 'Chrome' } }
    $danger = @{ 1 = 'dangerous file'; 2 = 'dangerous URL'; 3 = 'dangerous content'; 4 = 'maybe dangerous'; 5 = 'uncommon'; 6 = 'user accepted a warning'; 7 = 'dangerous host'; 8 = 'potentially unwanted'; 9 = 'allowlisted by policy'; 10 = 'async scanning'; 11 = 'blocked: password-protected'; 12 = 'blocked: too large'; 13 = 'sensitive content warning'; 14 = 'sensitive content blocked'; 15 = 'deep scanned safe'; 16 = 'deep scanned: user opened dangerous'; 17 = 'prompt for scanning'; 18 = 'blocked: unsupported file type'; 19 = 'dangerous account compromise' }
    $dl = @(Get-WfxSqliteTable $db 'downloads')
    if ($dl.Count) {
        $chain = @{}
        foreach ($c in @(Get-WfxSqliteTable $db 'downloads_url_chains')) { if (-not $chain[[long]$c.id]) { $chain[[long]$c.id] = New-Object 'System.Collections.Generic.SortedList[long,string]' }; $chain[[long]$c.id][[long]$c.chain_index] = [string]$c.url }
        foreach ($d in $dl) {
            $urls = @(if ($chain[[long]$d.id]) { $chain[[long]$d.id].Values })
            $final = if ($urls.Count) { $urls[-1] } else { [string]$d.tab_url }
            $state = switch ([int]$d.state) { 1 { 'complete' } 2 { 'cancelled' } 3 { 'interrupted' } 4 { 'interrupted' } default { 'in progress' } }
            $dg = [int]$d.danger_type
            $bits = @("$Browser download ($state)")
            if ($final) { $bits += "from $final" }
            if ($d.referrer) { $bits += "referrer $($d.referrer)" }
            if ($dg -and $danger[$dg]) { $bits += "browser warning: $($danger[$dg])" }
            if ([int]$d.opened) { $bits += 'opened from the browser' }
            New-WfxArtifact -Artifact 'Download' -Time (ConvertFrom-WfxWebkitTime $d.start_time) -TimeKind 'Download started' -Evidence 'Download' -Path ([string]$d.target_path) -User $User `
                -Detail ($bits -join '; ') -Source $Path `
                -Extra ([pscustomobject]@{ Browser = $Browser; Url = $final; FirstUrl = $(if ($urls.Count) { $urls[0] }); Referrer = [string]$d.referrer; TabUrl = [string]$d.tab_url; Mime = [string]$d.mime_type
                    Bytes = $d.received_bytes; TotalBytes = $d.total_bytes; State = $state; Danger = $(if ($dg) { $danger[$dg] }); Opened = [bool][int]$d.opened; Finished = (ConvertTo-WfxUtcString (ConvertFrom-WfxWebkitTime $d.end_time)) })
        }
        return
    }
    $attrs = @{}; foreach ($a in @(Get-WfxSqliteTable $db 'moz_anno_attributes')) { $attrs[[long]$a.id] = [string]$a.name }
    if (-not $attrs.Count) { return }
    $dest = ($attrs.GetEnumerator() | Where-Object Value -eq 'downloads/destinationFileURI' | Select-Object -First 1).Key
    if (-not $dest) { return }
    $meta = ($attrs.GetEnumerator() | Where-Object Value -eq 'downloads/metaData' | Select-Object -First 1).Key
    $annos = @(Get-WfxSqliteTable $db 'moz_annos')
    $need = @{}; foreach ($a in $annos) { if ([long]$a.anno_attribute_id -eq $dest) { $need[[long]$a.place_id] = $a } }
    if (-not $need.Count) { return }
    # moz_places can hold hundreds of thousands of rows: look up only the downloaded ones by rowid.
    $places = @{}; $ps = Get-WfxSqliteSchema $db 'moz_places'
    if ($ps) { $ui = [array]::IndexOf($ps.Names, 'url'); foreach ($id in $need.Keys) { $v = Find-WfxSqliteRow $db $ps.Root ([long]$id); if ($v -and $ui -ge 0) { $places[[long]$id] = [pscustomobject]@{ url = $v[$ui] } } } }
    $metaBy = @{}; if ($meta) { foreach ($a in $annos) { if ([long]$a.anno_attribute_id -eq $meta) { $metaBy[[long]$a.place_id] = [string]$a.content } } }
    foreach ($k in $need.Keys) {
        $a = $need[$k]; $url = [string]$places[$k].url
        $file = [string]$a.content
        try { if ($file -match '^file:') { $file = ([uri]$file).LocalPath } } catch { }
        $state = ''; $size = $null
        if ($metaBy[$k]) { try { $m = $metaBy[$k] | ConvertFrom-Json; $state = switch ([int]$m.state) { 1 { 'complete' } 3 { 'cancelled' } 4 { 'paused' } 8 { 'blocked' } 9 { 'blocked by policy' } 0 { 'in progress' } default { "state $($m.state)" } }; $size = $m.fileSize } catch { } }
        $added = $null; $us = 0L; if ([long]::TryParse([string]$a.dateAdded, [ref]$us) -and $us -gt 0) { $added = [DateTimeOffset]::FromUnixTimeMilliseconds([long]($us / 1000)).UtcDateTime }
        New-WfxArtifact -Artifact 'Download' -Time $added -TimeKind 'Download started' -Evidence 'Download' -Path $file -User $User `
            -Detail ("Firefox download$(if ($state) { " ($state)" }); from $url") -Source $Path `
            -Extra ([pscustomobject]@{ Browser = 'Firefox'; Url = $url; Bytes = $size; State = $state })
    }
}

# ───────────────────────────── Program Compatibility Assistant (Windows 11 22H2+) ─────────────────────────────
function Read-WfxTextFile {
    <# Reads a log file that may be UTF-16 (with or without BOM) or UTF-8 / ANSI, with sharing. #>
    param([string]$Path, [byte[]]$Bytes, [int]$MaxMB = 64)
    if (-not $Bytes) {
        try {
            $fs = New-Object IO.FileStream($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
            try { $len = [int][Math]::Min($fs.Length, $MaxMB * 1MB); $Bytes = New-Object byte[] $len; $n = 0; while ($n -lt $len) { $r = $fs.Read($Bytes, $n, $len - $n); if ($r -le 0) { break }; $n += $r } } finally { $fs.Dispose() }
        } catch { return '' }
    }
    if ($Bytes.Length -ge 2 -and $Bytes[0] -eq 0xFF -and $Bytes[1] -eq 0xFE) { return [Text.Encoding]::Unicode.GetString($Bytes, 2, $Bytes.Length - 2) }
    if ($Bytes.Length -ge 3 -and $Bytes[0] -eq 0xEF -and $Bytes[1] -eq 0xBB -and $Bytes[2] -eq 0xBF) { return [Text.Encoding]::UTF8.GetString($Bytes, 3, $Bytes.Length - 3) }
    $zeros = 0; $probe = [Math]::Min(400, $Bytes.Length); for ($i = 1; $i -lt $probe; $i += 2) { if ($Bytes[$i] -eq 0) { $zeros++ } }
    if ($probe -gt 10 -and $zeros -gt $probe / 4) { return [Text.Encoding]::Unicode.GetString($Bytes, 0, $Bytes.Length - ($Bytes.Length % 2)) }
    [Text.Encoding]::UTF8.GetString($Bytes)
}

function Get-WfxPcaRecord {
    <#
    .SYNOPSIS Program Compatibility Assistant logs (C:\Windows\appcompat\pca): PcaAppLaunchDic.txt
    (path|last launch, UTC) and PcaGeneralDb0/1.txt (time|status|path|description|vendor|version|...).
    Execution evidence for programs launched from Explorer.
    #>
    param([string]$Path, [string]$Text)
    if (-not $Text) { $Text = Read-WfxTextFile -Path $Path }
    $leaf = Split-Path -Leaf $Path
    foreach ($line in ($Text -split "`r?`n")) {
        $line = $line.Trim([char]0, ' '); if (-not $line) { continue }
        $f = $line -split '\|'
        if ($leaf -match '(?i)AppLaunchDic' -and $f.Count -ge 2) {
            New-WfxArtifact -Artifact 'PCA' -Time (ConvertTo-WfxDateTime ($f[1] + 'Z')) -TimeKind 'Last launched' -Evidence 'Execution' -Path $f[0] -Detail 'Launched from Explorer (PcaAppLaunchDic)' -Source $Path
        } elseif ($f.Count -ge 3 -and $f[0] -match '^\d{4}-\d\d-\d\d') {
            $desc = @(@($f[3], $f[4], $f[5]) | Where-Object { $_ }) -join ' · '
            $status = switch ($f[1]) { '0' { 'installer' } '1' { 'driver blocked' } '2' { 'abnormal process exit' } '3' { 'PCA resolve call' } default { "status $($f[1])" } }
            New-WfxArtifact -Artifact 'PCA' -Time (ConvertTo-WfxDateTime ($f[0] + 'Z')) -TimeKind 'Recorded' -Evidence 'Execution' -Path ([Environment]::ExpandEnvironmentVariables($f[2])) `
                -Detail ("$status$(if ($desc) { "; $desc" }) (PcaGeneralDb)") -Source $Path -Extra ([pscustomobject]@{ Status = $status; Description = $f[3]; Vendor = $f[4]; Version = $f[5]; ExitCode = $(if ($f.Count -gt 7) { $f[7] }) })
        }
    }
}

# ───────────────────────────── Microsoft Defender support logs ─────────────────────────────
function Get-WfxDefenderLogRecord {
    <#
    .SYNOPSIS Microsoft Defender MPLog / MPDetection logs (ProgramData\Microsoft\Windows Defender\Support).
    Keeps detections (threat name + file) and the "EstimatedImpact" lines that name processes Defender saw
    running — useful when the event logs were cleared, because these logs are separate files.
    #>
    param([string]$Path, [string]$Text, [int]$Max = 20000)
    if (-not $Text) { $Text = Read-WfxTextFile -Path $Path }
    $n = 0; $seen = @{}
    foreach ($line in ($Text -split "`r?`n")) {
        if ($n -ge $Max) { break }
        $m = [regex]::Match($line, '^\s*(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z?)\s+(.*)$')
        if (-not $m.Success) { continue }
        $time = ConvertTo-WfxDateTime ($m.Groups[1].Value.TrimEnd('Z') + 'Z'); $rest = $m.Groups[2].Value
        $d = [regex]::Match($rest, '(?i)\b(DETECTION(?:EVENT|_ADD|_CLEAN)?\S*)\s+(?:MPSOURCE_\S+\s+)?([A-Za-z]+:[A-Za-z0-9]+/[^\s;!]+(?:![A-Za-z0-9.]+)?)\s*(?:(file|process|regkey|containerfile|behavior|amsi_script|webfile|startup)\s*:\s*)?([^;]*)')
        if ($d.Success) {
            $n++
            New-WfxArtifact -Artifact 'DefenderLog' -Time $time -TimeKind 'Detected' -Evidence 'Detection' -Path ($d.Groups[4].Value.Trim()) -Name ($d.Groups[2].Value) `
                -Detail ("{0}: {1}{2}" -f $d.Groups[1].Value, $d.Groups[2].Value, $(if ($d.Groups[3].Value) { " ($($d.Groups[3].Value))" })) -Source $Path `
                -Extra ([pscustomobject]@{ Threat = $d.Groups[2].Value; Kind = $d.Groups[3].Value; Action = $d.Groups[1].Value })
            continue
        }
        $p = [regex]::Match($rest, '(?i)ProcessImageName:\s*([^,]+),.*?(?:\bPid:\s*(\d+))?')
        if ($p.Success) {
            $img = $p.Groups[1].Value.Trim(); $key = $img.ToLowerInvariant()
            if ($seen.ContainsKey($key)) { continue }; $seen[$key] = $true; $n++
            New-WfxArtifact -Artifact 'DefenderLog' -Time $time -TimeKind 'Seen running' -Evidence 'Execution' -Path $img `
                -Detail 'Process named in a Defender performance (EstimatedImpact) line; first sighting in this log' -Source $Path
        }
    }
}

# ───────────────────────────── user registry (offline NTUSER.DAT) and BAM (offline SYSTEM) ─────────────────────────────
function ConvertFrom-WfxRot13 { param([string]$Text) -join ($Text.ToCharArray() | ForEach-Object { $c = [int]$_; if ($c -ge 65 -and $c -le 90) { [char](65 + ($c - 52) % 26) } elseif ($c -ge 97 -and $c -le 122) { [char](97 + ($c - 84) % 26) } else { $_ } }) }

function Get-WfxNtuserRecord {
    <#
    .SYNOPSIS From an offline NTUSER.DAT: UserAssist (GUI program launches with run count), RunMRU (commands
    typed in Win+R), TypedPaths (paths typed in the Explorer address bar) and WordWheelQuery (Explorer searches).
    #>
    param($Hive, [string]$Source, [string]$User = '')
    $exp = 'Software\Microsoft\Windows\CurrentVersion\Explorer'
    $ua = Get-WfxHiveKey $Hive "$exp\UserAssist"
    foreach ($g in @(Get-WfxHiveSubkey $Hive $ua)) {
        $ck = @(Get-WfxHiveSubkey $Hive $g | Where-Object Name -eq 'Count')[0]; if (-not $ck) { continue }
        foreach ($v in @(Get-WfxHiveValue $Hive $ck)) {
            $d = [byte[]]$v.Data; if ($d.Length -lt 68) { continue }
            $ft = ConvertFrom-WfxFileTime ([BitConverter]::ToInt64($d, 60)); if (-not $ft) { continue }
            $name = ConvertFrom-WfxRot13 $v.Name
            $name = $name -replace '^\{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7\}', '%SystemRoot%\System32' -replace '^\{6D809377-6AF0-444B-8957-A3773F02200E\}', '%ProgramFiles%' -replace '^\{7C5A40EF-A0FB-4BFC-874A-C0F2E0B9FA8E\}', '%ProgramFiles(x86)%' -replace '^\{F38BF404-1D43-42F2-9305-67DE0B28FC23\}', '%SystemRoot%'
            New-WfxArtifact -Artifact 'UserAssist' -Time $ft -TimeKind 'Last run' -Evidence 'Execution' -Path $name -User $User -Detail "run count $([BitConverter]::ToInt32($d, 4)); focus time $([Math]::Round([BitConverter]::ToUInt32($d, 12) / 1000)) s" -Source "$Source\$exp\UserAssist"
        }
    }
    $run = Get-WfxHiveKey $Hive "$exp\RunMRU"
    if ($run) {
        $order = [string](Get-WfxHiveValue $Hive $run -Name 'MRUList').Data
        $vals = @{}; foreach ($v in @(Get-WfxHiveValue $Hive $run)) { if ($v.Name -match '^[a-z]$') { $vals[$v.Name] = ([string]$v.Data) -replace '\\1$', '' } }
        $i = 0
        foreach ($ch in $order.ToCharArray()) {
            $k = [string]$ch; if (-not $vals.ContainsKey($k)) { continue }
            New-WfxArtifact -Artifact 'RunMRU' -Time $(if ($i -eq 0) { $run.LastWrite } else { $null }) -TimeKind $(if ($i -eq 0) { 'Most recent (key write)' } else { 'Earlier' }) -Evidence 'Execution' -Path $vals[$k] -Name $vals[$k] -User $User `
                -Detail "Typed in the Run dialog (Win+R), order $($i + 1) of $($order.Length)" -Source "$Source\$exp\RunMRU"
            $i++
        }
    }
    $tp = Get-WfxHiveKey $Hive 'Software\Microsoft\Internet Explorer\TypedURLs'
    $tp2 = Get-WfxHiveKey $Hive "$exp\TypedPaths"
    foreach ($k in @($tp2) | Where-Object { $_ }) {
        foreach ($v in @(Get-WfxHiveValue $Hive $k | Sort-Object { [int](($_.Name -replace '\D', '0')) })) {
            New-WfxArtifact -Artifact 'TypedPath' -Time $(if ($v.Name -eq 'url1') { $k.LastWrite }) -TimeKind 'Most recent (key write)' -Evidence 'Access' -Path ([string]$v.Data) -User $User -Detail "Typed in the Explorer address bar ($($v.Name))" -Source "$Source\$exp\TypedPaths"
        }
    }
    $ww = Get-WfxHiveKey $Hive "$exp\WordWheelQuery"
    if ($ww) {
        foreach ($v in @(Get-WfxHiveValue $Hive $ww)) {
            if ($v.Name -notmatch '^\d+$') { continue }
            $q = ([Text.Encoding]::Unicode.GetString([byte[]]$v.Data)).TrimEnd([char]0)
            New-WfxArtifact -Artifact 'Search' -Time $null -TimeKind '' -Evidence 'Access' -Path $q -Name $q -User $User -Detail 'Searched for in Explorer (WordWheelQuery)' -Source "$Source\$exp\WordWheelQuery"
        }
    }
    $null = $tp
}

function Get-WfxSystemHiveBam {
    <# BAM/DAM from an offline SYSTEM hive: full path and last execution time per user SID. #>
    param($Hive, [string]$Source)
    $cur = 1; $sel = Get-WfxHiveKey $Hive 'Select'; if ($sel) { $c = (Get-WfxHiveValue $Hive $sel -Name 'Current').Data; if ($c) { $cur = [int]$c } }
    foreach ($rel in 'Services\bam\State\UserSettings', 'Services\bam\UserSettings') {
        $root = Get-WfxHiveKey $Hive ('ControlSet{0:D3}\{1}' -f $cur, $rel); if (-not $root) { continue }
        foreach ($sid in @(Get-WfxHiveSubkey $Hive $root)) {
            foreach ($v in @(Get-WfxHiveValue $Hive $sid)) {
                $d = [byte[]]$v.Data; if ($v.Type -ne 'REG_BINARY' -or $d.Length -lt 8) { continue }
                $t = ConvertFrom-WfxFileTime ([BitConverter]::ToInt64($d, 0)); if (-not $t) { continue }
                New-WfxArtifact -Artifact 'BAM' -Time $t -TimeKind 'Last run' -Evidence 'Execution' -Path ($v.Name -replace '^\\Device\\HarddiskVolume\d+', '(volume)') -User $sid.Name -Detail 'Background Activity Moderator' -Source "$Source\...\$rel"
            }
        }
        break
    }
}

# ───────────────────────────── collection: live host ─────────────────────────────
function Get-WfxArtifactData {
    <#
    .SYNOPSIS Collects execution / user-activity artifacts from the live host. Read-only; every source that
    cannot be read is recorded as a gap with the reason.
    #>
    param([int]$MaxPerSource = 5000)
    $out = New-Object System.Collections.Generic.List[object]
    if (-not (Test-WfxWindows)) { return , $out.ToArray() }
    $add = { param($rows) foreach ($r in @($rows | Select-Object -First $MaxPerSource)) { if ($r) { $out.Add($r) } } }
    # ShimCache from the live registry value.
    try {
        $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SYSTEM\CurrentControlSet\Control\Session Manager\AppCompatCache', $false)
        $v = if ($k) { $k.GetValue('AppCompatCache') } else { $null }
        if ($v -is [byte[]]) { & $add (Get-WfxShimCacheRecord -Bytes $v -Source 'HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\AppCompatCache') }
        else { Add-WfxGap -Source 'ShimCache' -Reason 'AppCompatCache value not readable (needs administrator rights).' }
    } catch { Add-WfxGap -Source 'ShimCache' -Reason $_.Exception.Message }
    # Amcache: Windows keeps the hive open without sharing; try, and say how to get it if locked.
    $am = Join-Path $env:SystemRoot 'appcompat\Programs\Amcache.hve'
    if (Test-Path -LiteralPath $am) {
        $h = Open-WfxHive -Path $am
        if ($h) { & $add (Get-WfxAmcacheRecord -Hive $h -Source $am) }
        else { Add-WfxGap -Source 'Amcache' -Reason 'Amcache.hve is locked by Windows. Copy it with a raw-copy tool (KAPE, FTK Imager) and analyze the copy: Invoke-WfxTriage -ArtifactPath <folder>.' }
    }
    # SRUM: the SRUM service keeps its database open; try, and say how to get it if locked.
    $sru = Join-Path $env:SystemRoot 'System32\sru\SRUDB.dat'
    if (Test-Path -LiteralPath $sru) {
        try { & $add (Get-WfxSrumRecord -Path $sru) }
        catch { Add-WfxGap -Source 'SRUM' -Reason "SRUDB.dat could not be read ($($_.Exception.Message)). Copy it with a raw-copy tool (KAPE, FTK Imager) and analyze the copy: Invoke-WfxTriage -ArtifactPath <folder>." }
    }
    # PCA (Windows 11 22H2+)
    foreach ($f in @(Get-ChildItem -LiteralPath (Join-Path $env:SystemRoot 'appcompat\pca') -Filter 'Pca*.txt' -File -ErrorAction SilentlyContinue)) { & $add (Get-WfxPcaRecord -Path $f.FullName) }
    # Defender support logs
    $sup = Join-Path $env:ProgramData 'Microsoft\Windows Defender\Support'
    if (Test-Path -LiteralPath $sup) {
        $logs = @(Get-ChildItem -LiteralPath $sup -File -ErrorAction SilentlyContinue | Where-Object Name -match '(?i)^MP(Log|Detection)-.*\.log$')
        if (-not $logs.Count) { Add-WfxGap -Source 'Defender logs' -Reason 'No MPLog files readable (needs administrator rights).' }
        foreach ($f in $logs) { & $add (Get-WfxDefenderLogRecord -Path $f.FullName) }
    }
    # Prefetch file names (full parsing of compressed Prefetch is out of scope; name + times are reliable).
    & $add (Get-WfxPrefetchRecord -Folder (Join-Path $env:SystemRoot 'Prefetch'))
    # Per user: ShellBags, Jump Lists, Recent shortcuts, browser downloads.
    $loaded = @{}
    foreach ($h in @(Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue)) { $loaded[$h.PSChildName] = $true }
    foreach ($prof in @(Get-WfxUserProfilePath)) {
        $user = Split-Path -Leaf $prof
        $sid = $null
        try { $sid = (New-Object Security.Principal.NTAccount($user)).Translate([Security.Principal.SecurityIdentifier]).Value } catch { }
        foreach ($bag in @(@('UsrClass', "$prof\AppData\Local\Microsoft\Windows\UsrClass.dat", "${sid}_Classes", 'Local Settings\Software\Microsoft\Windows\Shell\BagMRU'),
                @('NTUSER', "$prof\NTUSER.DAT", $sid, 'Software\Microsoft\Windows\Shell\BagMRU'))) {
            try {
                if ($bag[2] -and $loaded[$bag[2]]) {
                    $rk = [Microsoft.Win32.Registry]::Users.OpenSubKey("$($bag[2])\$($bag[3])", $false)
                    if ($rk) { & $add (Get-WfxShellBagRecord -LiveKey $rk -User $user -Source "HKU\$($bag[2])\$($bag[3])") }
                } elseif (Test-Path -LiteralPath $bag[1]) {
                    $hv = Open-WfxHive -Path $bag[1]
                    if ($hv) {
                        & $add (Get-WfxShellBagRecord -Hive $hv -KeyPath $bag[3] -User $user -Source $bag[1])
                        if ($bag[0] -eq 'NTUSER') { & $add (Get-WfxNtuserRecord -Hive $hv -Source $bag[1] -User $user) }
                    }
                }
            } catch { Add-WfxGap -Source "ShellBags ($user)" -Reason $_.Exception.Message }
        }
        $recent = Join-Path $prof 'AppData\Roaming\Microsoft\Windows\Recent'
        foreach ($sub in 'AutomaticDestinations', 'CustomDestinations') {
            foreach ($f in @(Get-ChildItem -LiteralPath (Join-Path $recent $sub) -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 200)) {
                try { & $add (Get-WfxJumpListRecord -Path $f.FullName -User $user) } catch { Write-Verbose "jumplist: $($f.FullName): $_" }
            }
        }
        foreach ($f in @(Get-ChildItem -LiteralPath $recent -Filter *.lnk -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1000)) {
            & $add (Get-WfxShortcutRecord -Path $f.FullName -User $user -FileTime $f.LastWriteTimeUtc)
        }
        foreach ($db in @(Get-WfxBrowserDatabase -ProfilePath $prof)) {
            try { & $add (Get-WfxBrowserDownloadRecord -Path $db.FullName -User $user) } catch { Add-WfxGap -Source "Browser ($user)" -Reason "$($db.FullName): $($_.Exception.Message)" }
        }
    }
    , $out.ToArray()
}

function Get-WfxBrowserDatabase {
    param([string]$ProfilePath)
    $local = Join-Path $ProfilePath 'AppData\Local'; $roam = Join-Path $ProfilePath 'AppData\Roaming'
    foreach ($root in "$local\Google\Chrome\User Data", "$local\Microsoft\Edge\User Data", "$local\BraveSoftware\Brave-Browser\User Data", "$local\Vivaldi\User Data", "$roam\Opera Software\Opera Stable", "$local\Chromium\User Data") {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        Get-ChildItem -LiteralPath $root -Filter History -File -Recurse -Depth 2 -ErrorAction SilentlyContinue | Where-Object { $_.Length -lt 512MB }
    }
    $ff = Join-Path $roam 'Mozilla\Firefox\Profiles'
    if (Test-Path -LiteralPath $ff) { Get-ChildItem -LiteralPath $ff -Filter places.sqlite -File -Recurse -Depth 2 -ErrorAction SilentlyContinue | Where-Object { $_.Length -lt 512MB } }
}

function Get-WfxPrefetchRecord {
    <# Prefetch: one file per program run from a given path. Name = executable; file times = first / last run. #>
    param([string]$Folder, [object[]]$Files)
    if (-not $Files) { $Files = @(Get-ChildItem -LiteralPath $Folder -Filter *.pf -File -ErrorAction SilentlyContinue) }
    foreach ($f in $Files) {
        $exe = $f.Name -replace '-[0-9A-Fa-f]{8}\.pf$', ''
        New-WfxArtifact -Artifact 'Prefetch' -Time $f.LastWriteTimeUtc -TimeKind 'Last run' -Evidence 'Execution' -Path $exe -Name $exe `
            -Detail "first run about $(ConvertTo-WfxUtcString $f.CreationTimeUtc) (file created); prefetch hash $(($f.BaseName -split '-')[-1])" -Source $f.FullName
    }
}

# ───────────────────────────── collection: files from another system ─────────────────────────────
function ConvertFrom-WfxSidBytes {
    <# Binary SID -> S-1-5-21-... text. #>
    param([byte[]]$B)
    if (-not $B -or $B.Length -lt 8) { return '' }
    $n = $B[1]; if ($B.Length -lt 8 + 4 * $n) { return '' }
    $auth = 0L; for ($i = 2; $i -lt 8; $i++) { $auth = ($auth -shl 8) -bor $B[$i] }
    $s = "S-$($B[0])-$auth"
    for ($i = 0; $i -lt $n; $i++) { $s += '-' + [BitConverter]::ToUInt32($B, 8 + 4 * $i) }
    $s
}

function Get-WfxSrumRecord {
    <#
    .SYNOPSIS Artifact records from SRUM (System Resource Usage Monitor, C:\Windows\System32\sru\SRUDB.dat): for
    each program and account, the network bytes sent and received and the disk bytes read and written, as
    Windows recorded them hour by hour for about 30 to 60 days. One row per program, account and table.
    #>
    param([Parameter(Mandatory)][string]$Path)
    $db = Open-WfxEse -Path $Path
    $ids = @{}
    foreach ($r in (Get-WfxEseTable $db 'SruDbIdMapTable' -Column 'IdType', 'IdIndex', 'IdBlob')) {
        $blob = $r['IdBlob']; if ($null -eq $r['IdIndex']) { continue }
        $v = if ($blob -is [byte[]]) {
            if ([int]$r['IdType'] -eq 3) { ConvertFrom-WfxSidBytes $blob } else { [Text.Encoding]::Unicode.GetString($blob, 0, $blob.Length - ($blob.Length % 2)).TrimEnd([char]0) }
        } else { [string]$blob }
        $ids[[int]$r['IdIndex']] = $v
    }
    $app = {
        param($id)
        $s = [string]$ids[[int]$id]
        if (-not $s) { return "(unnamed app $id)" }
        $s -replace '(?i)^\\device\\harddiskvolume\d+\\', '(volume)\'
    }
    $mb = { param([double]$x) if ($x -ge 1GB) { '{0:n1} GB' -f ($x / 1GB) } elseif ($x -ge 1MB) { '{0:n1} MB' -f ($x / 1MB) } else { '{0:n0} KB' -f ($x / 1KB) } }
    $tables = @(
        @{ Guid = '{973F5D5C-1D90-4944-BE8E-24B94231A174}'; Kind = 'Network'; A = 'BytesSent'; B = 'BytesRecvd' },
        @{ Guid = '{D10CA2FE-6FCF-4F6D-848E-B2E99266FA89}'; Kind = 'Resources'; A = 'ForegroundBytesWritten'; A2 = 'BackgroundBytesWritten'; B = 'ForegroundBytesRead'; B2 = 'BackgroundBytesRead' })
    foreach ($tb in $tables) {
        if (-not $db.Tables.ContainsKey($tb.Guid)) { continue }
        $agg = @{}
        $cols = @('AppId', 'UserId', 'TimeStamp', $tb.A, $tb.B) + @(@($tb.A2, $tb.B2) | Where-Object { $_ })
        foreach ($r in (Get-WfxEseTable $db $tb.Guid -Column $cols)) {
            $k = "$($r['AppId'])|$($r['UserId'])"
            if (-not $agg.ContainsKey($k)) { $agg[$k] = [pscustomobject]@{ App = $r['AppId']; User = $r['UserId']; A = 0.0; B = 0.0; First = $null; Last = $null; Hours = 0 } }
            $g = $agg[$k]
            $g.A += [double]$r[$tb.A] + $(if ($tb.A2) { [double]$r[$tb.A2] } else { 0 })
            $g.B += [double]$r[$tb.B] + $(if ($tb.B2) { [double]$r[$tb.B2] } else { 0 })
            $ts = $r['TimeStamp']
            if ($ts -is [datetime]) { if (-not $g.First -or $ts -lt $g.First) { $g.First = $ts }; if (-not $g.Last -or $ts -gt $g.Last) { $g.Last = $ts } }
            $g.Hours++
        }
        foreach ($g in $agg.Values) {
            $path = & $app $g.App
            $user = [string]$ids[[int]$g.User]
            $detail = if ($tb.Kind -eq 'Network') { "network: $(& $mb $g.A) sent, $(& $mb $g.B) received in $($g.Hours) hourly records" } else { "disk: $(& $mb $g.A) written, $(& $mb $g.B) read in $($g.Hours) hourly records" }
            if ($g.First) { $detail += " since $(ConvertTo-WfxUtcString $g.First)" }
            $extra = [ordered]@{ Table = $tb.Kind; FirstSeen = (ConvertTo-WfxUtcString $g.First); Hours = $g.Hours }
            if ($tb.Kind -eq 'Network') { $extra.BytesSent = [long]$g.A; $extra.BytesReceived = [long]$g.B } else { $extra.BytesWritten = [long]$g.A; $extra.BytesRead = [long]$g.B }
            New-WfxArtifact -Artifact 'SRUM' -Time $g.Last -TimeKind 'Last hour recorded' -Evidence 'Execution' -Path $path -User $user -Detail $detail -Source $Path -Extra ([pscustomobject]$extra)
        }
    }
}

function Get-WfxMftArtifactRecord {
    <#
    .SYNOPSIS Artifact records from a copied $MFT: executables, scripts, archives, disk images and shortcuts in
    folders users can write to (including deleted ones), every file with a Zone.Identifier (downloaded),
    and every executable or script whose timestamps look rewritten (timestomped). Not every file, which would
    be millions of rows.
    .PARAMETER Volume  Drive letter to show (default: taken from a KAPE-style ...\C\$MFT path, else "(volume)").
    #>
    param([Parameter(Mandatory)][string]$Path, [string]$Volume = '', [int]$Max = 20000)
    if (-not $Volume) { $Volume = if ($Path -match '(?i)[\\/]([A-Z])[\\/]\$MFT$') { "$($Matches[1].ToUpperInvariant()):" } else { '(volume)' } }
    $exeRx = '(?i)\.(?:exe|dll|sys|scr|com|cpl|ps1|psm1|bat|cmd|vbs|vbe|js|jse|wsf|hta|lnk|msi|iso|img|vhdx?|zip|rar|7z|jar)$'
    $userRx = '(?i)^\\(?:Users|ProgramData\\[^\\]+$|ProgramData\\(?!Microsoft\\|Package Cache\\)|PerfLogs|\$Recycle\.Bin|Windows\\Temp|Temp|Intel|Recovery)\\|^\\[^\\]+$|^\\\[Orphaned\]\\'
    $quiet = '(?i)^\\Users\\[^\\]+\\AppData\\Local\\(?:Microsoft\\(?:Windows\\INetCache|OneDrive|Edge|Teams|WindowsApps)|Packages|Google\\Chrome\\User Data\\[^\\]+\\(?:Code Cache|Service Worker))\\'
    $pre = {
        param($b)
        if ($b.IsDir) { return $false }
        if ($b.Zone) { return $true }
        $nm = $b.FN.Name
        if ($nm -notmatch $exeRx) { return $false }
        $true
    }
    $entries = @(Read-WfxMft -Path $Path -Prefilter $pre)
    # Timestomp candidates. Windows Setup, updates and installers legitimately write files with backdated,
    # whole-second times (they keep the times of the build), so this is only checked where attackers drop
    # tools (folders users can write to), never in System Restore copies. An installer unpacks many such
    # files into one folder within a minute; five or more backdated programs in one folder and minute are
    # treated as an installer. A handful (an attacker's toolkit, even with identical copied times) is not.
    $codeRx = '(?i)\.(?:exe|dll|sys|scr|com|cpl|ps1|psm1|bat|cmd|vbs|vbe|js|jse|wsf|hta)$'
    $tsOf = @{}; $byDirMin = @{}
    $dirMin = { param($e) ($e.Path -replace '\\[^\\]*$', '') + '|' + $e.FNCreated.ToString('yyyyMMddHHmm') }
    foreach ($e in $entries) {
        if ($e.Name -notmatch $codeRx -or -not $e.FNCreated -or $e.Path -notmatch $userRx -or $e.Path -match '(?i)^\\System Volume Information\\') { continue }
        # Boot files at the volume root are written by Setup with build times.
        if ($e.Path -match '(?i)^\\(?:ntldr|ntdetect\.com|bootmgr|io\.sys|msdos\.sys|bootsect\.bak|autoexec\.bat|config\.sys|BOOTNXT)$') { continue }
        $ts = Test-WfxMftTimestomp $e
        if (-not $ts) { continue }
        $tsOf[$e.Number] = $ts
        $dk = & $dirMin $e; $byDirMin[$dk] = 1 + [int]$byDirMin[$dk]
    }
    $n = 0
    foreach ($e in $entries) {
        $ts = $null
        if ($tsOf.ContainsKey($e.Number) -and $byDirMin[(& $dirMin $e)] -lt 5) { $ts = $tsOf[$e.Number] }
        $userPath = $e.Path -match $userRx -and $e.Path -notmatch $quiet -and $e.Path -notmatch '(?i)^\\System Volume Information\\'
        if (-not ($e.Zone -or $ts -or $userPath)) { continue }
        if (++$n -gt $Max) { Add-WfxGap -Source "artifacts:$Path" -Reason "More than $Max interesting `$MFT entries; the rest were not listed." -Fix 'Filter the $MFT with a dedicated tool (MFTECmd) for a full listing.'; break }
        $url = ''; $zoneId = ''
        if ($e.Zone) {
            if ($e.Zone -match '(?im)^\s*ZoneId\s*=\s*(\d)') { $zoneId = $Matches[1] }
            if ($e.Zone -match '(?im)^\s*HostUrl\s*=\s*(\S+)') { $url = $Matches[1] } elseif ($e.Zone -match '(?im)^\s*ReferrerUrl\s*=\s*(\S+)') { $url = $Matches[1] }
        }
        $bits = New-Object System.Collections.Generic.List[string]
        if (-not $e.InUse) { $bits.Add('deleted') }
        if ($null -ne $e.Size) { $bits.Add("$($e.Size) bytes") }
        if ($zoneId) { $bits.Add("downloaded (zone $zoneId)" + $(if ($url) { " from $url" } else { '' })) }
        if ($ts) { $bits.Add('timestamps look rewritten') }
        $extra = [ordered]@{ Record = $e.Number; Deleted = (-not $e.InUse); FNCreated = (ConvertTo-WfxUtcString $e.FNCreated); SIModified = (ConvertTo-WfxUtcString $e.SIModified) }
        if ($url) { $extra.Url = $url }
        if ($zoneId) { $extra.ZoneId = $zoneId }
        if ($ts) { $extra.Timestomp = ($ts.Reasons -join '; '); $extra.TimestompScore = $ts.Score }
        $other = @($e.Ads | Where-Object { $_ -ne 'Zone.Identifier' -and $_ -notmatch '^(?:SmartScreen|\$Kernel\.Purge.*|encryptable|favicon|OECustomProperty)$' })
        if ($other) { $extra.Streams = ($other -join ', ') }
        New-WfxArtifact -Artifact 'MFT' -Time $e.SICreated -TimeKind 'Created ($SI)' -Evidence $(if ($zoneId) { 'Download' } else { 'Presence' }) `
            -Path ($Volume + $e.Path) -Detail ($bits -join '; ') -Source $Path -Extra ([pscustomobject]$extra)
    }
}

function Import-WfxArtifact {
    <#
    .SYNOPSIS Parses artifacts from a folder of collected evidence (KAPE / Velociraptor output, a mounted
    image, CTF files) or a single file. Files are recognised by their content and name: registry hives
    (SYSTEM, Amcache.hve, NTUSER.DAT, UsrClass.dat), Jump Lists, .lnk, browser databases, PCA and Defender
    logs, Prefetch, $MFT, SRUM (SRUDB.dat). Nothing in the folder is executed or modified.
    .OUTPUTS Artifact records. Event logs (*.evtx) are listed in $script:WfxImportEvtx for the caller.
    #>
    param([Parameter(Mandatory)][string]$Path, [int]$MaxFiles = 20000)
    $script:WfxImportEvtx = New-Object System.Collections.Generic.List[string]
    if (-not (Test-Path -LiteralPath $Path)) { Add-WfxGap -Source 'artifacts' -Reason "Path not found: $Path"; return }
    $files = if (Test-Path -LiteralPath $Path -PathType Leaf) { @(Get-Item -LiteralPath $Path) } else { @(Get-ChildItem -LiteralPath $Path -File -Recurse -Force -ErrorAction SilentlyContinue | Select-Object -First $MaxFiles) }
    $pf = New-Object System.Collections.Generic.List[object]
    foreach ($f in $files) {
        $name = $f.Name; $full = $f.FullName
        $user = if ($full -match '(?i)[\\/]Users[\\/]([^\\/]+)[\\/]') { $Matches[1] } else { '' }
        try {
            if ($name -match '(?i)\.evtx$') { $script:WfxImportEvtx.Add($full); continue }
            if ($name -match '(?i)^\$MFT$|^MFT$|\.mft$' -and $f.Length -ge 1024) { Get-WfxMftArtifactRecord -Path $full; continue }
            if ($name -match '(?i)^SRUDB\.dat$') { Get-WfxSrumRecord -Path $full; continue }
            if ($name -match '(?i)\.pf$') { $pf.Add($f); continue }
            if ($name -match '(?i)\.(automaticDestinations-ms|customDestinations-ms)$') { Get-WfxJumpListRecord -Path $full -User $user; continue }
            if ($name -match '(?i)\.lnk$') { Get-WfxShortcutRecord -Path $full -User $user -FileTime $f.LastWriteTimeUtc; continue }
            if ($name -match '(?i)^Pca(AppLaunchDic|GeneralDb\d*)\.txt$') { Get-WfxPcaRecord -Path $full; continue }
            if ($name -match '(?i)^MP(Log|Detection)-.*\.log$') { Get-WfxDefenderLogRecord -Path $full; continue }
            if ($name -match '(?i)^(History|places\.sqlite)$') { Get-WfxBrowserDownloadRecord -Path $full -User $user; continue }
            if ($name -match '(?i)\.(log\d?|tmp|bak|blf|regtrans-ms)$' -or $f.Length -lt 8192 -or $f.Length -gt 1GB) { continue }
            $head = New-Object byte[] 4
            $fs = [IO.File]::Open($full, 'Open', 'Read', 'ReadWrite'); try { $null = $fs.Read($head, 0, 4) } finally { $fs.Dispose() }
            if ([Text.Encoding]::ASCII.GetString($head) -ne 'regf') { continue }
            $h = Open-WfxHive -Path $full; if (-not $h) { continue }
            if ($h.Dirty) { Add-WfxGap -Source 'artifacts' -Reason "$name is a 'dirty' hive and no transaction log continues it (copy $name.LOG1 and $name.LOG2 from the same folder at the same time): the newest registry writes may be missing." -Fix 'Collect the hive together with its .LOG1/.LOG2 files.' }
            elseif ($h.Replayed) { Write-Verbose "$full : replayed $($h.Replayed) transaction-log entries" }
            switch (Get-WfxHiveKind $h) {
                'SYSTEM' {
                    Get-WfxSystemHiveShimCache -Hive $h -Source $full; Get-WfxSystemHiveBam -Hive $h -Source $full
                    $cn = Get-WfxHiveKey $h 'ControlSet001\Control\ComputerName\ComputerName'
                    if ($cn) { $v = (Get-WfxHiveValue $h $cn -Name 'ComputerName').Data; if ($v) { $script:WfxImportHost = [string]$v } }
                }
                'SOFTWARE' {
                    $cv = Get-WfxHiveKey $h 'Microsoft\Windows NT\CurrentVersion'
                    if ($cv) { $vals = @{}; foreach ($x in @(Get-WfxHiveValue $h $cv)) { $vals[$x.Name] = $x.Data }; $script:WfxImportOs = (@($vals['ProductName'], $vals['DisplayVersion'], $(if ($vals['CurrentBuild']) { "build $($vals['CurrentBuild'])" })) | Where-Object { $_ }) -join ' ' }
                }
                'AMCACHE' { Get-WfxAmcacheRecord -Hive $h -Source $full }
                'USRCLASS' { Get-WfxShellBagRecord -Hive $h -KeyPath 'Local Settings\Software\Microsoft\Windows\Shell\BagMRU' -User $user -Source $full }
                'NTUSER' { Get-WfxShellBagRecord -Hive $h -KeyPath 'Software\Microsoft\Windows\Shell\BagMRU' -User $user -Source $full; Get-WfxNtuserRecord -Hive $h -Source $full -User $user }
            }
        } catch { Add-WfxGap -Source 'artifacts' -Reason "${full}: $($_.Exception.Message)" }
    }
    if ($pf.Count) { Get-WfxPrefetchRecord -Files $pf.ToArray() }
}


# ===== Collectors/Bundle.ps1 =====
# Collection aggregator — runs the collectors and returns ONE normalized bundle object.
# This is the single unit of data that: (a) the analyzers consume, (b) gets saved as raw evidence,
# and (c) is shipped back from a remote WinRM session. Every field is already OS-neutral, timestamps are
# UTC ISO-8601 strings, and text is secret-scrubbed, so the bundle is safe to serialize and move off-box.

function Get-WfxCollectionBundle {
    <#
    .SYNOPSIS Collects all live triage data into one bundle. Each section degrades to [] on error (recorded as a gap).
    .PARAMETER Hours        Event look-back window.
    .PARAMETER FileScan     Include the web-root / drop-folder / ransomware file scan (slower).
    .PARAMETER ExposureScan Include the deeper config-file and domain-SYSVOL secret scan.
    .PARAMETER Sections     Limit collection to these sections (default: all).
    #>
    param(
        [int]$Hours = 72,
        [switch]$FileScan,
        [switch]$ExposureScan,
        [ValidateSet('Host', 'Process', 'Network', 'Dns', 'Persistence', 'Events', 'Activity', 'Artifacts', 'Files', 'Exposure', 'Security')]
        [string[]]$Sections = @('Host', 'Process', 'Network', 'Dns', 'Persistence', 'Events', 'Activity', 'Artifacts', 'Files', 'Exposure', 'Security')
    )
    $want = @{}; foreach ($s in $Sections) { $want[$s] = $true }
    Clear-WfxGap
    $script:WfxSigCache = @{}
    $started = Get-WfxUtcNow
    $steps = @('Host', 'Dns', 'Network', 'Process', 'Persistence', 'Events', 'Activity', 'Artifacts', 'Files', 'Exposure', 'Security') | Where-Object { $want[$_] -and ($_ -ne 'Files' -or $FileScan) }
    $script:WfxProgress = @{ N = 0; Total = @($steps).Count }
    $stage = {
        param([string]$Label, [scriptblock]$Body)
        $script:WfxProgress.N++
        $sw = [Diagnostics.Stopwatch]::StartNew()
        Write-WfxConsole ("  [{0}/{1}] {2,-34}" -f $script:WfxProgress.N, $script:WfxProgress.Total, $Label) -Kind Plain -NoNewline
        if (-not $script:WfxQuiet) { Write-Progress -Activity 'WinForensicX collection' -Status $Label -PercentComplete ([int](100 * ($script:WfxProgress.N - 1) / [Math]::Max(1, $script:WfxProgress.Total))) }
        $r = & $Body
        $count = if ($null -eq $r) { 0 } elseif ($r -is [System.Collections.IEnumerable] -and $r -isnot [string]) { @($r).Count } else { 1 }
        Write-WfxConsole ("{0,7:N1}s  {1}" -f $sw.Elapsed.TotalSeconds, $(if ($count -gt 1) { "$count items" } else { '' })) -Kind Dim
        $r
    }

    # Volatile, fast-changing state first (DNS cache, connections, processes), then the rest.
    $hostInfo = if ($want.Host) { & $stage 'System information' { Get-WfxHostInfo } } else { $null }
    $dns = if ($want.Dns) { @(& $stage 'DNS cache' { Get-WfxDnsData }) } else { @() }
    $net = if ($want.Network) { @(& $stage 'Network connections' { Get-WfxNetworkData }) } else { @() }
    $procs = if ($want.Process) { @(& $stage 'Processes (+ signatures)' { Get-WfxProcessData }) } else { @() }

    $persist = @()
    if ($want.Persistence) { $persist = @(& $stage 'Autostarts, services, drivers' { @(Get-WfxPersistenceData) + @(Get-WfxServiceAndDriver) }) }

    $events = @()
    if ($want.Events) { $events = @(& $stage "Event logs (last $Hours h)" { Get-WfxEventData -Hours $Hours }) }

    $activity = @()
    $days = [int][Math]::Max(1, [Math]::Ceiling($Hours / 24.0))
    if ($want.Activity) { $activity = @(& $stage "Recent changes (last $days d$(if ($FileScan) { ', incl. NTFS journal' }))" { Get-WfxActivityData -Days $days -Journal:$FileScan }) }

    $artifacts = @()
    if ($want.Artifacts) { $artifacts = @(& $stage 'Execution & user-activity artifacts' { Get-WfxArtifactData }) }

    $files = @(); $ransom = [pscustomobject]@{ Note = @(); RecentFile = @() }
    if ($want.Files -and $FileScan) {
        $files = @(& $stage 'File scan (web roots, drops, ransomware)' { $script:WfxRansomTmp = Get-WfxRansomwareData; Get-WfxFileData })
        $ransom = $script:WfxRansomTmp
    }

    $exposure = @()
    if ($want.Exposure) { $exposure = @(& $stage 'Credential exposure audit (redacted)' { Get-WfxExposureData -IncludeFileScan:$ExposureScan }) }

    $security = if ($want.Security) { & $stage 'Security posture' { Get-WfxSecurityData } } else { $null }
    if (-not $script:WfxQuiet) { Write-Progress -Activity 'WinForensicX collection' -Completed }

    [pscustomobject]@{
        Schema      = 'winforensicx.bundle/2'
        ToolVersion = $script:WfxVersion
        Started     = $started
        Collected   = (Get-WfxUtcNow)
        HostName    = if ($hostInfo) { $hostInfo.HostName } else { [Environment]::MachineName }
        Host        = $hostInfo
        Process     = $procs
        Network     = $net
        Dns         = $dns
        Persistence = $persist
        Events      = $events
        Activity    = $activity
        Artifacts   = $artifacts
        Files       = $files
        Ransom      = $ransom
        Exposure    = $exposure
        Security    = $security
        Gaps        = @(Get-WfxGap | Expand-WfxRecord)
        Meta        = [pscustomobject]@{ Mode = 'live'; Hours = $Hours; FileScan = [bool]$FileScan; ExposureScan = [bool]$ExposureScan; Sections = @($Sections) }
    }
}

function Get-WfxOfflineBundle {
    <#
    .SYNOPSIS Builds a bundle from exported .evtx files ONLY (no live data from the analysis machine).
    The host name is taken from the events' Computer field (the most common value).
    #>
    param([Parameter(Mandatory)][string]$EvtxPath, [int]$MaxPerLog = 50000)
    Clear-WfxGap
    $files = if (Test-Path -LiteralPath $EvtxPath -PathType Container) { @(Get-ChildItem -LiteralPath $EvtxPath -Filter *.evtx -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object FullName) } else { @((Resolve-Path -LiteralPath $EvtxPath).Path) }
    if (-not $files.Count) { Add-WfxGap -Source 'offline' -Reason "No .evtx files found under $EvtxPath" }
    $events = @(Get-WfxEventData -EvtxFile $files -MaxPerLog $MaxPerLog)
    $hn = @($events | ForEach-Object { [string]$_.Computer } | Where-Object { $_ } | Group-Object | Sort-Object Count -Descending | Select-Object -First 1).Name
    if (-not $hn) { $hn = 'unknown-offline-host' }
    $hostName = ($hn -split '\.')[0]
    [pscustomobject]@{
        Schema      = 'winforensicx.bundle/2'
        ToolVersion = $script:WfxVersion
        Started     = (Get-WfxUtcNow)
        Collected   = (Get-WfxUtcNow)
        HostName    = $hostName
        Host        = [pscustomobject]@{ HostName = $hostName; Fqdn = $hn; Os = '(offline event logs)'; Collected = (Get-WfxUtcNow); Admin = $null; Operator = [Environment]::UserName }
        Process     = @(); Network = @(); Dns = @(); Persistence = @(); Activity = @(); Artifacts = @(); Files = @(); Exposure = @(); Security = $null
        Ransom      = [pscustomobject]@{ Note = @(); RecentFile = @() }
        Events      = $events
        Gaps        = @(Get-WfxGap | Expand-WfxRecord)
        Meta        = [pscustomobject]@{ Mode = 'offline'; EvtxPath = $EvtxPath; EvtxFiles = @($files) }
    }
}

function Get-WfxArtifactBundle {
    <#
    .SYNOPSIS Builds a bundle from a folder of collected evidence (KAPE / Velociraptor output, a mounted image,
    CTF files): registry hives, Jump Lists, shortcuts, browser databases, PCA / Defender logs, Prefetch and any
    .evtx files found. Nothing is collected from the machine running the tool.
    #>
    param([Parameter(Mandatory)][string]$Path, [int]$MaxPerLog = 50000)
    Clear-WfxGap
    $script:WfxImportHost = $null; $script:WfxImportOs = $null
    $arts = @(Import-WfxArtifact -Path $Path)
    $evtx = @($script:WfxImportEvtx)
    $events = if ($evtx.Count) { @(Get-WfxEventData -EvtxFile $evtx -MaxPerLog $MaxPerLog) } else { @() }
    $hn = $script:WfxImportHost
    if (-not $hn) { $hn = @($events | ForEach-Object { [string]$_.Computer } | Where-Object { $_ } | Group-Object | Sort-Object Count -Descending | Select-Object -First 1).Name; if ($hn) { $hn = ($hn -split '\.')[0] } }
    if (-not $hn) { $hn = 'unknown-offline-host' }
    [pscustomobject]@{
        Schema      = 'winforensicx.bundle/2'
        ToolVersion = $script:WfxVersion
        Started     = (Get-WfxUtcNow)
        Collected   = (Get-WfxUtcNow)
        HostName    = $hn
        Host        = [pscustomobject]@{ HostName = $hn; Os = $(if ($script:WfxImportOs) { $script:WfxImportOs } else { '(collected artifacts)' }); Collected = (Get-WfxUtcNow); Admin = $null; Operator = [Environment]::UserName }
        Process     = @(); Network = @(); Dns = @(); Persistence = @(); Activity = @(); Files = @(); Exposure = @(); Security = $null
        Ransom      = [pscustomobject]@{ Note = @(); RecentFile = @() }
        Events      = $events
        Artifacts   = $arts
        Gaps        = @(Get-WfxGap | Expand-WfxRecord)
        Meta        = [pscustomobject]@{ Mode = 'artifacts'; ArtifactPath = $Path; EvtxFiles = $evtx; ArtifactCount = $arts.Count }
    }
}


# ===== Collectors/Events.ps1 =====
# Event collector — normalizes Windows events from live logs or from exported .evtx files.
# Both paths produce { Log, Provider, Id, TimeCreated (UTC ISO), Computer, RecordId, Message, Fields = @{...} }.

# High-volume IDs get their own query (and cap) so they can't crowd rare, high-value events out of the window.
# Msg = $true only where the rendered message is needed: formatting Message text is by far the slowest part
# of reading events (milliseconds each), and high-volume events carry everything we need in their data fields.
$script:WfxEventQuery = @(
    @{ Log = 'Security'; Ids = @(4624, 4625, 4648, 4688); Max = 15000; Msg = $false }
    @{ Log = 'Security'; Ids = @(1102, 4697, 4698, 4720, 4726, 4728, 4732, 4740, 4756); Max = 3000; Msg = $true }
    @{ Log = 'System'; Ids = @(104, 7030, 7040, 7045); Max = 3000; Msg = $true }
    @{ Log = 'Microsoft-Windows-PowerShell/Operational'; Ids = @(4104); Max = 5000; Msg = $false }
    @{ Log = 'Microsoft-Windows-TaskScheduler/Operational'; Ids = @(106, 140, 141, 200); Max = 3000; Msg = $false }
    @{ Log = 'Microsoft-Windows-Windows Defender/Operational'; Ids = @(1116, 1117, 5001, 5007); Max = 2000; Msg = $true }
    @{ Log = 'Microsoft-Windows-Sysmon/Operational'; Ids = @(1, 3, 4, 7, 8, 10, 11, 13, 16, 22, 23); Max = 15000; Msg = $false }
    @{ Log = 'Microsoft-Windows-TerminalServices-RemoteConnectionManager/Operational'; Ids = @(1149); Max = 2000; Msg = $false }
)
# Only fields that can carry free text are secret-scrubbed; names, SIDs, IPs, GUIDs and codes cannot.
$script:WfxEventTextFields = @('CommandLine', 'ProcessCommandLine', 'ParentCommandLine', 'ScriptBlockText', 'Payload', 'ContextInfo', 'ImagePath', 'Details', 'TaskContent', 'Path', 'Detection User', 'Param1', 'Param2', 'Param3', 'Data', 'Message')
# Get-WinEvent rejects FilterHashtable queries with too many Id values; keep each query well under the limit.
$script:WfxMaxIdsPerQuery = 20

function Test-WfxNoEventsError {
    param($ErrorRecord)
    return ([string]$ErrorRecord.FullyQualifiedErrorId -like 'NoMatchingEventsFound*')
}

function Get-WfxEventData {
    <#
    .SYNOPSIS Collects security-relevant events from live logs, or from .evtx files when -EvtxFile is given.
    .PARAMETER EvtxFile  One or more exported .evtx files (offline / dead-box analysis).
    .PARAMETER Hours     Live mode: look back this many hours (default 72).
    .PARAMETER MaxPerLog Cap per .evtx file (offline). Live queries have per-query caps. Hitting a cap is a gap.
    #>
    param([string[]]$EvtxFile = @(), [int]$Hours = 72, [int]$MaxPerLog = 50000)
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]

    if ($EvtxFile.Count) {
        $ids = @(@($script:WfxEventQuery) + @($script:WfxSigmaEventQuery | Where-Object { $_ }) | ForEach-Object { $_.Ids } | Sort-Object -Unique)
        foreach ($f in $EvtxFile) {
            $leaf = Get-WfxLeaf $f
            Invoke-WfxStep "events:evtx:$leaf" {
                $n = 0
                for ($i = 0; $i -lt $ids.Count; $i += $script:WfxMaxIdsPerQuery) {
                    $chunk = $ids[$i..([Math]::Min($i + $script:WfxMaxIdsPerQuery, $ids.Count) - 1)]
                    try {
                        Get-WinEvent -FilterHashtable @{ Path = $f; Id = $chunk } -MaxEvents ($MaxPerLog - $n) -ErrorAction Stop |
                            ForEach-Object { $out.Add((ConvertTo-WfxEvent $_ '' -WithMessage:($_.Id -in 1102, 104, 7045, 1116, 1117, 5001, 5007))); $n++ }
                    } catch { if (-not (Test-WfxNoEventsError $_)) { throw } }
                    if ($n -ge $MaxPerLog) { Add-WfxGap -Source "events:evtx:$leaf" -Reason "Capped at $MaxPerLog events; older events in this file were not analyzed."; break }
                }
            } | Out-Null
        }
        return $out.ToArray()
    }

    $start = (Get-Date).AddHours(-[Math]::Abs($Hours))
    foreach ($q in @(@($script:WfxEventQuery) + @($script:WfxSigmaEventQuery | Where-Object { $_ }))) {
        Invoke-WfxStep "events:$($q.Log):$($q.Ids -join ',')" {
            $ev = $null
            try { $ev = @(Get-WinEvent -FilterHashtable @{ LogName = $q.Log; Id = $q.Ids; StartTime = $start } -MaxEvents $q.Max -ErrorAction Stop) }
            catch {
                if (Test-WfxNoEventsError $_) { return }        # log exists, nothing matched: that's a result, not a gap
                throw
            }
            foreach ($e in $ev) { $out.Add((ConvertTo-WfxEvent $e $q.Log -WithMessage:$q.Msg)) }
            if ($ev.Count -ge $q.Max) { Add-WfxGap -Source "events:$($q.Log)" -Reason "Capped at $($q.Max) events for IDs $($q.Ids -join ','); the oldest part of the $Hours h window was not collected." -Fix 'Re-run with a smaller -Hours window, or export the log and use -EvtxPath.' }
        } | Out-Null
    }
    $out.ToArray()
}

function ConvertTo-WfxEvent {
    param($Record, [string]$Log, [switch]$WithMessage)
    $fields = @{}
    try {
        $xml = [xml]$Record.ToXml()
        foreach ($d in @($xml.Event.EventData.Data)) {
            if ($d -and $d.Name) { $fields[$d.Name] = [string]$d.'#text' }
        }
        foreach ($d in @($xml.Event.UserData.ChildNodes)) {
            foreach ($c in @($d.ChildNodes)) { if ($c.LocalName) { $fields[$c.LocalName] = [string]$c.InnerText } }
        }
    } catch {}
    # Friendly aliases the analyzer uses regardless of schema.
    if (-not $fields.ContainsKey('CommandLine') -and $fields.ContainsKey('ProcessCommandLine')) { $fields['CommandLine'] = $fields['ProcessCommandLine'] }
    if (-not $fields.ContainsKey('ScriptBlockText') -and $Record.Id -eq 4104) { try { $fields['ScriptBlockText'] = [string]$Record.Properties[2].Value } catch {} }
    $msg = ''
    if ($WithMessage) { try { $msg = [string]$Record.Message } catch { $msg = '' } }
    # Redact secrets in the message and every field value at collection time (4688 command lines and 4104
    # script blocks in particular can carry passwords/keys). Structure and tool names are preserved.
    $msg = Protect-WfxText $msg
    if ($msg.Length -gt 8192) { $msg = $msg.Substring(0, 8192) + ' …[truncated]' }
    foreach ($fk in @($fields.Keys)) {
        $v = [string]$fields[$fk]
        if ($v.Length -gt 12 -and ($script:WfxEventTextFields -contains $fk -or $v.Length -gt 200)) { $fields[$fk] = Protect-WfxText $v }
    }
    $logName = if ($Record.LogName) { [string]$Record.LogName } else { $Log }
    [pscustomobject]@{
        Log         = $logName
        Provider    = [string]$Record.ProviderName
        Id          = [int]$Record.Id
        RecordId    = [long]$Record.RecordId
        TimeCreated = ConvertTo-WfxUtcString $Record.TimeCreated
        Computer    = [string]$Record.MachineName
        Message     = $msg
        Fields      = $fields
    }
}


# ===== Collectors/Exposure.ps1 =====
# ─────────────────────────────────────────────────────────────────────────────────────────────
# Secrets-exposure & security-hygiene COLLECTOR.  DEFENSIVE / READ-ONLY by design.
#
# What this does:  detects and reports THAT sensitive material or a misconfiguration EXISTS and is
#   exposed (GPP cPassword, unattend passwords, accessible SAM/SYSTEM/SECURITY/NTDS, world-readable
#   cloud-credential files, auto-logon password, unencrypted SSH keys, AI/API keys, secrets in env
#   vars / PowerShell history / config files) so an analyst can remediate it.
#
# What this deliberately does NOT do — and must never be extended to do:
#   • It never opens, copies, parses or decrypts a credential store (SAM/NTDS, LSA secrets, DPAPI
#     blobs, browser login DBs, LSASS). For hives it checks existence and ACLs only.
#   • It never emits a secret VALUE. Every match is reduced to type + length via Find-WfxSecret /
#     Format-WfxSecret BEFORE it leaves this collector. Records returned here carry only redacted
#     strings in a .Redacted field — raw values are discarded immediately and never persisted.
#   • It never decrypts the GPP cPassword (reversible though it is): reporting its presence is enough.
#
# The exposure analyzer consumes: { Kind, Path, Detail, Accessible, WorldReadable, Redacted }.
# ─────────────────────────────────────────────────────────────────────────────────────────────

# Identities that should not normally be able to read a per-user or protected file.
$script:WfxOtherReadSids = @(
    'S-1-1-0'        # Everyone
    'S-1-5-11'       # Authenticated Users
    'S-1-5-32-545'   # BUILTIN\Users
    'S-1-5-4'        # INTERACTIVE
    'S-1-5-7'        # ANONYMOUS
)
# Secret types that are specifically AI-provider keys (routed to the AiKey finding).
$script:WfxAiKeyTypes = @('Anthropic API key', 'OpenAI API key', 'OpenRouter API key', 'Google API key',
    'Hugging Face token', 'Groq API key', 'xAI API key', 'Replicate token')

function Test-WfxOtherUserReadable {
    <# True if a non-admin, non-owner principal (Everyone / Users / Authenticated Users / INTERACTIVE)
       is granted read access. ACL-only; the file's contents are never opened. #>
    param([string]$Path)
    if (-not (Test-WfxWindows) -or -not (Test-Path -LiteralPath $Path)) { return $false }
    try {
        $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
        foreach ($ace in $acl.Access) {
            if ([string]$ace.AccessControlType -ne 'Allow') { continue }
            if ($ace.InheritanceFlags -ne 'None' -and $ace.PropagationFlags -eq 'InheritOnly') { continue }
            # Check the actual right bits: ReadData (0x1), GENERIC_READ (0x80000000), GENERIC_ALL (0x10000000).
            # (Matching the enum's text on "Read" wrongly counted ReadAttributes / ReadPermissions.)
            $bits = [int64]([int]$ace.FileSystemRights) -band 0xFFFFFFFFL
            if (-not (($bits -band 0x1) -or ($bits -band 0x80000000L) -or ($bits -band 0x10000000L))) { continue }
            $sid = ''
            try { $sid = ($ace.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier])).Value } catch { $sid = [string]$ace.IdentityReference }
            if ($sid -in $script:WfxOtherReadSids) { return $true }
        }
    } catch {}
    return $false
}

function Get-WfxRedactedHits {
    <# Returns redacted secret descriptors for a block of text WITHOUT returning any raw value.
       Combines Find-WfxSecret (known key formats) with a generic key=value / assignment detector. #>
    param([AllowEmptyString()][string]$Text, [int]$MaxHits = 20)
    $hits = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrEmpty($Text)) { return , $hits.ToArray() }
    foreach ($s in (Find-WfxSecret $Text)) {
        if ($hits.Count -ge $MaxHits) { break }
        $hits.Add([pscustomobject]@{ Type = $s.Type; Line = $s.Line; Redacted = "$($s.Type) (line $($s.Line)): $($s.Redacted)" })
    }
    # Generic assignments (db_password=..., ANTHROPIC_API_KEY=..., clientSecret: ...) not caught by a
    # known key format. The name may carry an underscore/dot prefix, so we match the whole identifier.
    $lines = $Text -split "`r?`n"
    $assignRx = '(?i)([A-Za-z0-9_.\-]*(?:password|passwd|pwd|secret|api[_-]?key|apikey|token|credential|connectionstring|access[_-]?key)[A-Za-z0-9_.\-]*)\s*[:=]\s*("[^"]{4,}"|''[^'']{4,}''|\S{4,})'
    $seen = @{}
    foreach ($h in $hits) { $seen["$($h.Line)"] = $true }
    for ($i = 0; $i -lt $lines.Count -and $hits.Count -lt $MaxHits; $i++) {
        $m = [regex]::Match($lines[$i], $assignRx)
        if (-not $m.Success) { continue }
        if ($seen.ContainsKey([string]($i + 1))) { continue }   # a known-format key already covered this line
        $raw = $m.Groups[2].Value.Trim('"', "'")
        # Skip obvious placeholders.
        if ($raw -match '(?i)^(?:\*+|x+|changeme|your[_-]?\w+|<[^>]+>|%[^%]+%|\$\{?\w+\}?|null|none|empty|example|xxx+)$') { continue }
        $name = $m.Groups[1].Value
        $hits.Add([pscustomobject]@{ Type = "$name assignment"; Line = $i + 1; Redacted = "$name (line $($i+1)): $(Format-WfxSecret $raw)" })
    }
    # Command-line secrets passed as separate args or concatenated flags (mysql -pSecret, aws ... set
    # aws_secret_access_key <value>) — common in shell history. Guarded to avoid placeholder noise.
    for ($i = 0; $i -lt $lines.Count -and $hits.Count -lt $MaxHits; $i++) {
        if ($seen.ContainsKey([string]($i + 1))) { continue }
        $mp = [regex]::Match($lines[$i], '(?i)(?:^|\s)-p(?!assword\b)([^\s]{4,})')
        if ($mp.Success) { $hits.Add([pscustomobject]@{ Type = 'password flag'; Line = $i + 1; Redacted = "password flag (line $($i+1)): $(Format-WfxSecret $mp.Groups[1].Value)" }); continue }
        $ma = [regex]::Match($lines[$i], '(?i)\b([A-Za-z0-9_.\-]{0,40}(?:password|passwd|pwd|secret|api[_-]?key|access[_-]?key|token)[A-Za-z0-9_.\-]{0,20})\s+(\S{8,})\s*$')
        if ($ma.Success -and $ma.Groups[2].Value -notmatch '(?i)^(?:changeme|example|<[^>]+>|%[^%]+%)$') {
            $hits.Add([pscustomobject]@{ Type = "$($ma.Groups[1].Value) value"; Line = $i + 1; Redacted = "$($ma.Groups[1].Value) (line $($i+1)): $(Format-WfxSecret $ma.Groups[2].Value)" })
        }
    }
    $hits.ToArray()
}

function Get-WfxExposureData {
    <#
    .SYNOPSIS Defensive secrets-exposure audit. Returns redacted exposure records (see file header).
    .PARAMETER IncludeFileScan  Also scan a small set of likely-credential config files in user profiles.
    #>
    param([switch]$IncludeFileScan)
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $add = { param($Kind, $Path, $Detail = '', $Accessible = $false, $WorldReadable = $false, $Redacted = @())
        $out.Add([pscustomobject]@{ Kind = $Kind; Path = $Path; Detail = $Detail; Accessible = [bool]$Accessible; WorldReadable = [bool]$WorldReadable; Content = ''; Redacted = @($Redacted) }) }

    # ── 1. GPP cPassword (presence only; never decrypted) ──
    Invoke-WfxStep 'expo:gpp' {
        $gppRoots = @("$env:SystemRoot\SYSVOL", "$env:ProgramData\Microsoft\Group Policy\History")
        # The domain SYSVOL share is remote (network traffic to a DC), so it is only searched with -ExposureScan.
        if ($IncludeFileScan) {
            try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue; if ($cs.PartOfDomain -and $cs.Domain) { $gppRoots += "\\$($cs.Domain)\SYSVOL" } } catch {}
        }
        foreach ($root in $gppRoots) {
            if (-not (Test-Path -LiteralPath $root)) { continue }
            Get-ChildItem -LiteralPath $root -Recurse -File -Include 'Groups.xml', 'Services.xml', 'ScheduledTasks.xml', 'DataSources.xml', 'Printers.xml', 'Drives.xml' -ErrorAction SilentlyContinue |
                Select-Object -First 100 | ForEach-Object {
                    $hit = $false
                    try { $hit = (Select-String -LiteralPath $_.FullName -Pattern 'cpassword\s*=\s*"[^"]+"' -SimpleMatch:$false -Quiet -ErrorAction Stop) } catch {}
                    if ($hit) { & $add 'GppCpassword' $_.FullName 'GPP XML with cpassword attribute' }
                }
        }
    } | Out-Null

    # ── 2. Unattend / sysprep passwords (presence only) ──
    Invoke-WfxStep 'expo:unattend' {
        $cand = @(
            "$env:SystemDrive\unattend.xml", "$env:SystemDrive\autounattend.xml"
            "$env:SystemRoot\Panther\unattend.xml", "$env:SystemRoot\Panther\Unattend\unattend.xml"
            "$env:SystemRoot\System32\Sysprep\unattend.xml", "$env:SystemRoot\System32\Sysprep\Panther\unattend.xml"
            "$env:SystemRoot\System32\Sysprep\sysprep.xml", "$env:SystemRoot\System32\sysprep.inf"
        )
        foreach ($f in $cand) {
            if (-not (Test-Path -LiteralPath $f)) { continue }
            $hasPw = $false
            try { $hasPw = (Select-String -LiteralPath $f -Pattern '<Password>|<AdministratorPassword>|<DomainPassword>|\bpassword\b' -Quiet -ErrorAction Stop) } catch {}
            if ($hasPw) { & $add 'UnattendPassword' $f 'Unattended-setup file containing a password element' }
        }
    } | Out-Null

    # ── 3. Sensitive hives — existence + ACL only, contents NEVER read ──
    Invoke-WfxStep 'expo:hives' {
        $ntds = Get-WfxRegValue 'HKLM:\SYSTEM\CurrentControlSet\Services\NTDS\Parameters' 'DSA Database file'
        $hiveFiles = @(
            # Live hives: present on every system — only reported if their ACL lets non-admins read them
            # (CVE-2021-36934 "HiveNightmare" / SeriousSAM). Contents are never opened.
            @{ P = "$env:SystemRoot\System32\config\SAM"; D = 'SAM hive'; Live = $true }
            @{ P = "$env:SystemRoot\System32\config\SYSTEM"; D = 'SYSTEM hive'; Live = $true }
            @{ P = "$env:SystemRoot\System32\config\SECURITY"; D = 'SECURITY hive'; Live = $true }
            @{ P = "$env:SystemRoot\NTDS\ntds.dit"; D = 'Active Directory database (NTDS.dit)'; Live = $true }
            @{ P = "$env:SystemRoot\System32\config\RegBack\SAM"; D = 'SAM hive backup (RegBack)' }
            @{ P = "$env:SystemRoot\System32\config\RegBack\SYSTEM"; D = 'SYSTEM hive backup (RegBack)' }
            @{ P = "$env:SystemRoot\System32\config\RegBack\SECURITY"; D = 'SECURITY hive backup (RegBack)' }
            @{ P = "$env:SystemRoot\repair\SAM"; D = 'SAM hive copy (repair)' }
            @{ P = "$env:SystemRoot\repair\SYSTEM"; D = 'SYSTEM hive copy (repair)' }
            @{ P = "$env:SystemRoot\repair\SECURITY"; D = 'SECURITY hive copy (repair)' }
            @{ P = "$env:SystemDrive\Windows.old\Windows\System32\config\SAM"; D = 'SAM hive in Windows.old' }
        )
        if ($ntds -and $ntds -notlike "$env:SystemRoot\NTDS\*") { $hiveFiles += @{ P = $ntds; D = 'Active Directory database (NTDS.dit, custom path)'; Live = $true } }
        foreach ($h in $hiveFiles) {
            if (-not (Test-Path -LiteralPath $h.P)) { continue }
            $f = Get-Item -LiteralPath $h.P -ErrorAction SilentlyContinue
            if (-not $f -or $f.Length -eq 0) { continue }   # RegBack is often present but zero-length
            $readable = Test-WfxOtherUserReadable $h.P
            if ($h.Live -and -not $readable) { continue }   # a live hive with correct ACLs is normal, not a finding
            & $add 'SensitiveHive' $h.P $h.D $readable $readable
            $out[$out.Count - 1] | Add-Member -NotePropertyName Live -NotePropertyValue ([bool]$h.Live) -Force
        }
    } | Out-Null

    # ── 4. Shadow copies (informational) ──
    Invoke-WfxStep 'expo:shadow' {
        $sc = @(Get-CimInstance Win32_ShadowCopy -ErrorAction Stop)
        if ($sc.Count -gt 0) { & $add 'ShadowCopy' '' "$($sc.Count) volume shadow copy(ies) present" }
    } | Out-Null

    # ── 5. World/other-readable cloud & credential files ──
    Invoke-WfxStep 'expo:credfiles' {
        $rel = @(
            @{ R = '.aws\credentials'; D = 'AWS CLI credentials' }
            @{ R = '.azure\accessTokens.json'; D = 'Azure CLI access tokens' }
            @{ R = '.azure\msal_token_cache.json'; D = 'Azure MSAL token cache' }
            @{ R = '.config\gcloud\credentials.db'; D = 'gcloud credentials' }
            @{ R = '.config\gcloud\access_tokens.db'; D = 'gcloud access tokens' }
            @{ R = '.docker\config.json'; D = 'Docker registry auth' }
            @{ R = '.kube\config'; D = 'Kubernetes config (cluster tokens)' }
            @{ R = '.git-credentials'; D = 'Git stored credentials' }
            @{ R = '_netrc'; D = 'netrc credentials' }
            @{ R = '.netrc'; D = 'netrc credentials' }
            @{ R = '.npmrc'; D = 'npm auth token' }
            @{ R = '.pypirc'; D = 'PyPI upload credentials' }
        )
        foreach ($userHome in (Get-WfxUserProfilePath)) {
            foreach ($c in $rel) {
                $p = Join-Path $userHome $c.R
                if (-not (Test-Path -LiteralPath $p)) { continue }
                if (Test-WfxOtherUserReadable $p) { & $add 'CredFileWorldReadable' $p $c.D $true $true }
            }
        }
    } | Out-Null

    # ── 6. Auto-logon password in Winlogon (presence only; value never read) ──
    Invoke-WfxStep 'expo:autologon' {
        $wl = 'HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Winlogon'
        if (Test-Path $wl) {
            $k = Get-ItemProperty $wl -ErrorAction SilentlyContinue
            if ("$($k.AutoAdminLogon)" -eq '1' -and $k.PSObject.Properties['DefaultPassword'] -and $k.DefaultPassword) {
                & $add 'AutoLogon' $wl ("DefaultUserName=" + $k.DefaultUserName)
            }
        }
    } | Out-Null

    # ── 7. Unencrypted SSH private keys (header inspected for cipher only; key bytes never emitted) ──
    Invoke-WfxStep 'expo:sshkeys' {
        foreach ($prof in (Get-WfxUserProfilePath)) {
            $sshDir = Join-Path $prof '.ssh'
            if (-not (Test-Path -LiteralPath $sshDir)) { continue }
            Get-ChildItem -LiteralPath $sshDir -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -match '^(id_(rsa|dsa|ecdsa|ed25519)|.*\.(pem|key|ppk))$' -and $_.Name -notmatch '\.pub$' } |
                ForEach-Object {
                    $head = ''
                    try { $head = (Get-Content -LiteralPath $_.FullName -TotalCount 5 -ErrorAction Stop) -join "`n" } catch { return }
                    if ($head -notmatch 'PRIVATE KEY|PuTTY-User-Key') { return }
                    $encrypted = $false
                    if ($head -match 'Proc-Type:\s*4,ENCRYPTED' -or $head -match 'DEK-Info:' -or $head -match 'Encryption:\s*aes') { $encrypted = $true }
                    elseif ($head -match 'BEGIN OPENSSH PRIVATE KEY') {
                        # OpenSSH keys embed the cipher name; 'none' = unencrypted. Inspect header block only.
                        try {
                            $b64 = ((Get-Content -LiteralPath $_.FullName -ErrorAction Stop) | Where-Object { $_ -notmatch 'PRIVATE KEY-----' } | Select-Object -First 2) -join ''
                            $bytes = [Convert]::FromBase64String($b64.PadRight([int](([Math]::Ceiling($b64.Length / 4.0)) * 4), '='))
                            $asText = [Text.Encoding]::ASCII.GetString($bytes)
                            if ($asText -notmatch 'none' -and ($asText -match 'aes|chacha|3des')) { $encrypted = $true }
                        } catch { $encrypted = $true }  # if unsure, assume protected (avoid false alarm)
                    }
                    elseif ($_.Extension -eq '.ppk') { $encrypted = $true }  # conservative
                    if (-not $encrypted) { & $add 'SshKeyUnprotected' $_.FullName 'SSH private key without a passphrase' }
                }
        }
    } | Out-Null

    # ── 8. Secrets in environment variables (redacted immediately) ──
    Invoke-WfxStep 'expo:env' {
        $nameRx = '(?i)(key|token|secret|password|passwd|pwd|credential|conn(ection)?string|sas|dsn)'
        foreach ($scope in @('Process', 'User', 'Machine')) {
            $vars = @{}
            try { $vars = [Environment]::GetEnvironmentVariables([EnvironmentVariableTarget]::$scope) } catch { continue }
            foreach ($name in $vars.Keys) {
                $val = [string]$vars[$name]
                if ([string]::IsNullOrWhiteSpace($val) -or $val.Length -lt 8) { continue }
                $known = Find-WfxSecret $val
                if ($known.Count -gt 0) {
                    $type = $known[0].Type
                    $red = "$type`: $($known[0].Redacted)"
                    if ($type -in $script:WfxAiKeyTypes) { & $add 'AiKey' "env:$scope`:$name" "$type in `$env:$name" $false $false @($red) }
                    else { & $add 'SecretInEnv' "env:$scope`:$name" $name $false $false @("$name ($scope): $($known[0].Redacted)") }
                } elseif ($name -match $nameRx -and $name -notmatch '(?i)^(?:PSModulePath|KEYBOARD\w*)$' -and $val -notmatch '(?i)^(?:\*+|changeme|your[_-]?\w+|%[^%]+%|<[^>]+>|true|false|\d{1,4})$' -and $val -notmatch '^[A-Za-z]:\\') {
                    & $add 'SecretInEnv' "env:$scope`:$name" $name $false $false @("$name ($scope): $(Format-WfxSecret $val)")
                }
            }
        }
    } | Out-Null

    # ── 9. Secrets in PowerShell / shell history (redacted immediately) ──
    Invoke-WfxStep 'expo:history' {
        $histFiles = New-Object System.Collections.Generic.List[string]
        foreach ($prof in (Get-WfxUserProfilePath)) {
            $histFiles.Add((Join-Path $prof 'AppData\Roaming\Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt'))
            $histFiles.Add((Join-Path $prof '.bash_history'))
        }
        foreach ($hf in $histFiles) {
            if (-not (Test-Path -LiteralPath $hf)) { continue }
            $text = ''
            try { $text = Get-Content -LiteralPath $hf -Raw -ErrorAction Stop } catch { continue }
            $hits = Get-WfxRedactedHits $text
            if ($hits.Count -gt 0) { & $add 'SecretInHistory' $hf 'credential(s) typed on the command line' $false $false @($hits.Redacted) }
        }
    } | Out-Null

    # ── 10. Optional: secrets in common config files (bounded; redacted immediately) ──
    if ($IncludeFileScan) {
        Invoke-WfxStep 'expo:configfiles' {
            $names = @('.env', '.env.local', 'web.config', 'appsettings.json', 'appsettings.Development.json', 'secrets.json', 'config.json', 'settings.py', 'application.properties', 'credentials.json', '.env.production')
            $scanned = 0
            foreach ($prof in (Get-WfxUserProfilePath)) {
                if ($scanned -ge 400) { break }
                Get-ChildItem -LiteralPath $prof -Recurse -File -Depth 4 -Include $names -ErrorAction SilentlyContinue |
                    Where-Object { $_.Length -le 262144 } | Select-Object -First 100 | ForEach-Object {
                        if ($scanned -ge 400) { return }
                        $scanned++
                        $text = ''
                        try { $text = Get-Content -LiteralPath $_.FullName -Raw -ErrorAction Stop } catch { return }
                        $hits = Get-WfxRedactedHits $text
                        if ($hits.Count -gt 0) {
                            $ai = @($hits | Where-Object { $_.Type -in $script:WfxAiKeyTypes })
                            if ($ai.Count -gt 0) { & $add 'AiKey' $_.FullName ($ai[0].Type) $false $false @($ai.Redacted) }
                            $other = @($hits | Where-Object { $_.Type -notin $script:WfxAiKeyTypes })
                            if ($other.Count -gt 0) { & $add 'SecretInFile' $_.FullName (($other[0].Type)) $false $false @($other.Redacted) }
                        }
                    }
            }
        } | Out-Null
    }

    $out.ToArray()
}


# ===== Collectors/Files.ps1 =====
# File collector — scans a bounded set of high-signal locations (web roots, user drop folders) and
# produces the normalized file records the File/Ransomware analyzers consume:
#   { Path, Directory, Extension, Length, LastWriteUtc, CreatedUtc, Content, Entropy, SignatureStatus, Zone, InWebRoot, SHA256 }
# Everything is bounded (file count, file size, read size, total content budget) so a triage never walks an
# entire disk or produces a huge bundle. Content is kept only for web-served scripts (for web-shell matching)
# and is secret-scrubbed before it enters the bundle. Reading files may update NTFS last-access times on
# volumes where that is enabled — a documented limitation of any live triage.

$script:WfxWebRoots = @(
    "$env:SystemDrive\inetpub\wwwroot"
    "$env:SystemDrive\inetpub\ftproot"
    "$env:SystemDrive\xampp\htdocs"
    "$env:SystemDrive\wamp\www"
    "$env:SystemDrive\wamp64\www"
    "$env:SystemDrive\Apache24\htdocs"
    "$env:SystemDrive\nginx\html"
    "$env:ProgramFiles\Apache Software Foundation"
    "$env:SystemDrive\laragon\www"
    "$env:ProgramFiles\Microsoft\Exchange Server\V15\FrontEnd\HttpProxy"
    "$env:ProgramFiles\Microsoft\Exchange Server\V15\ClientAccess"
)
$script:WfxWebScriptExt = @('.php', '.php3', '.php4', '.php5', '.php7', '.phtml', '.asp', '.aspx', '.ashx', '.asmx', '.jsp', '.jspx', '.cfm', '.cgi', '.pl')

function Get-WfxZoneId {
    <# Reads the Mark-of-the-Web Zone.Identifier stream. Returns @{ Zone; HostUrl; ReferrerUrl } (empty when none). #>
    param([string]$Path)
    $r = @{ Zone = ''; HostUrl = ''; ReferrerUrl = '' }
    if (-not (Test-WfxWindows)) { return $r }
    try {
        $z = (Get-Content -LiteralPath $Path -Stream 'Zone.Identifier' -ErrorAction Stop) -join "`n"
        $m = [regex]::Match($z, '(?im)^ZoneId\s*=\s*(\d)'); if ($m.Success) { $r.Zone = $m.Groups[1].Value }
        $m = [regex]::Match($z, '(?im)^HostUrl\s*=\s*(\S+)'); if ($m.Success) { $r.HostUrl = Protect-WfxText $m.Groups[1].Value }
        $m = [regex]::Match($z, '(?im)^ReferrerUrl\s*=\s*(\S+)'); if ($m.Success) { $r.ReferrerUrl = Protect-WfxText $m.Groups[1].Value }
    } catch {}
    return $r
}

function Get-WfxFileBytesEntropy {
    <# Shannon entropy over the first $Max bytes of a file (bounded read). 0 on failure. #>
    param([string]$Path, [int]$Max = 262144)
    try {
        $fs = [System.IO.File]::Open($Path, 'Open', 'Read', 'ReadWrite')
        try {
            $len = [int][Math]::Min([int64]$Max, $fs.Length)
            if ($len -le 0) { return 0.0 }
            $buf = New-Object byte[] $len
            $read = $fs.Read($buf, 0, $len)
            if ($read -lt $len) { $buf = $buf[0..($read - 1)] }
            return (Get-WfxEntropy ([byte[]]$buf))
        } finally { $fs.Dispose() }
    } catch { return 0.0 }
}

function Get-WfxFileHash256 {
    param([string]$Path)
    try { return (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash } catch { return '' }
}

function Get-WfxFileData {
    <#
    .SYNOPSIS Collects file records from web roots and user drop folders for the File analyzer.
    .PARAMETER ExtraPath     Additional folders to scan (e.g. a mounted image or a custom web root).
    .PARAMETER MaxFiles      Hard cap on files examined (default 4000) so a triage stays fast.
    .PARAMETER MaxReadKB     Max bytes read for content/entropy of a single file.
    .PARAMETER MaxContentMB  Total budget of web-script content kept in the bundle (default 32 MB).
    .PARAMETER Hours         Only files modified within this window are considered "recent drops" (default 168 = 7d).
    #>
    param([string[]]$ExtraPath = @(), [int]$MaxFiles = 4000, [int]$MaxReadKB = 256, [int]$MaxContentMB = 32, [int]$Hours = 168)
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $budget = [ref]$MaxFiles
    $contentBudget = [ref]([int64]$MaxContentMB * 1MB)
    $cutoff = (Get-Date).AddHours(-[Math]::Abs($Hours))

    $emit = {
        param($Item, [bool]$InWeb, [bool]$ReadContent)
        if ($budget.Value -le 0) { return }
        $p = $Item.FullName
        if ($seen.ContainsKey($p)) { return }
        $seen[$p] = $true
        $budget.Value--
        $ext = $Item.Extension.ToLowerInvariant()
        $content = ''
        $entropy = 0.0
        $isExe = $ext -in @('.exe', '.dll', '.scr', '.com', '.sys', '.ocx', '.cpl', '.pif')
        if ($ReadContent -and $Item.Length -le ($MaxReadKB * 1024)) {
            if ($contentBudget.Value -ge $Item.Length) {
                try { $content = Get-Content -LiteralPath $p -Raw -ErrorAction Stop } catch { $content = '' }
                # Scrub secrets (e.g. connection strings) before the content enters the bundle.
                if ($content) { $content = Protect-WfxText $content; $contentBudget.Value -= $Item.Length }
            } elseif ($contentBudget.Value -ge 0) {
                Add-WfxGap -Source 'files:webroots' -Reason "Web-script content budget ($MaxContentMB MB) reached; remaining web scripts were hashed but not content-scanned." -Fix 'Re-run Get-WfxFileData with a larger -MaxContentMB on that server.'
                $contentBudget.Value = -1
            }
        }
        if ($isExe) { $entropy = Get-WfxFileBytesEntropy $p (($MaxReadKB * 1024)) }
        $motw = Get-WfxZoneId $p
        $sha = ''
        # Hash only the small set of files most likely to matter (executables / MOTW / web scripts).
        if ($isExe -or $motw.Zone -match '^[34]$' -or $InWeb) { $sha = Get-WfxFileHash256 $p }
        $out.Add([pscustomobject]@{
                Path            = $p
                Directory       = $Item.DirectoryName
                Extension       = $ext
                Length          = $Item.Length
                LastWrite       = ConvertTo-WfxUtcString $Item.LastWriteTimeUtc
                Created         = ConvertTo-WfxUtcString $Item.CreationTimeUtc
                Content         = $content
                Entropy         = $entropy
                SignatureStatus = if ($isExe) { Get-WfxSignature $p } else { '' }
                Zone            = $motw.Zone
                HostUrl         = $motw.HostUrl
                ReferrerUrl     = $motw.ReferrerUrl
                InWebRoot       = $InWeb
                SHA256          = $sha
            })
    }

    # ── Web roots: scan served scripts for web shells ──
    Invoke-WfxStep 'files:webroots' {
        foreach ($root in (@($script:WfxWebRoots) + @($ExtraPath))) {
            if ($budget.Value -le 0) { break }
            if (-not $root -or -not (Test-Path -LiteralPath $root)) { continue }
            Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Extension.ToLowerInvariant() -in $script:WfxWebScriptExt } |
                Select-Object -First ([Math]::Max(0, $budget.Value)) |
                ForEach-Object { & $emit $_ $true $true }
        }
    } | Out-Null

    # ── User drop folders: recently written executables/scripts (download/exec staging) ──
    Invoke-WfxStep 'files:userdrops' {
        $dirs = New-Object System.Collections.Generic.List[string]
        $dirs.Add("$env:ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp")
        $dirs.Add("$env:PUBLIC\Downloads")
        $dirs.Add("$env:PUBLIC\Documents")
        $dirs.Add("$env:SystemRoot\Temp")
        $dirs.Add("$env:ProgramData")
        foreach ($prof in (Get-WfxUserProfilePath)) {
            foreach ($sub in @('Downloads', 'Desktop', 'Documents', 'AppData\Local\Temp', 'AppData\Roaming')) { $dirs.Add((Join-Path $prof $sub)) }
        }
        $dropExt = @('.exe', '.dll', '.scr', '.com', '.pif', '.cpl', '.ps1', '.bat', '.cmd', '.vbs', '.vbe', '.js', '.jse', '.wsf', '.hta', '.jar', '.lnk', '.iso', '.img', '.vhd', '.vhdx', '.msi', '.one', '.xll')
        foreach ($d in ($dirs | Sort-Object -Unique)) {
            if ($budget.Value -le 0) { break }
            if (-not (Test-Path -LiteralPath $d)) { continue }
            # NOTE: -Depth always implies recursion. Roaming / ProgramData: files directly inside an app folder (depth 1);
            # other folders: two levels down.
            $depth = if ($d -match '(?i)\\AppData\\Roaming$|^[a-z]:\\ProgramData$') { 1 } else { 2 }
            Get-ChildItem -LiteralPath $d -File -Depth $depth -ErrorAction SilentlyContinue |
                Where-Object { $_.Extension.ToLowerInvariant() -in $dropExt -and ($_.LastWriteTime -ge $cutoff -or $_.Extension -in @('.exe', '.scr', '.hta')) } |
                Select-Object -First ([Math]::Max(0, $budget.Value)) |
                ForEach-Object { & $emit $_ $false $false }
        }
        if ($budget.Value -le 0) { Add-WfxGap -Source 'files' -Reason "File cap ($MaxFiles) reached; remaining files were not examined." }
    } | Out-Null

    $out.ToArray()
}

function Get-WfxRansomwareData {
    <#
    .SYNOPSIS Collects ransom-note candidates and recently written encrypted-looking files.
    A note candidate is a small text/html file whose NAME looks like a ransom note, or whose identical name was
    dropped into many folders recently (how ransomware leaves notes). Only one copy per name is read; content is
    secret-scrubbed and truncated. Ordinary recent documents are never read.
    Returns .Note (Path, Name, Copies, Content) and .RecentFile (Path, Extension, Entropy, LastWrite).
    .PARAMETER Hours  Window for "recent" (default 48).
    #>
    param([int]$Hours = 48, [int]$MaxNotes = 50, [int]$MaxRecent = 4000, [int]$MaxScan = 60000, [int]$NoteMinCopies = 5)
    $notes = New-Object System.Collections.Generic.List[object]
    $recent = New-Object System.Collections.Generic.List[object]
    if (-not (Test-WfxWindows)) { return [pscustomobject]@{ Note = @(); RecentFile = @() } }
    $cutoff = (Get-Date).AddHours(-[Math]::Abs($Hours))
    $noteNameRx = '(?i)(?:read[\s_\-]?me|how[\s_\-]?to[\s_\-]?(?:decrypt|recover|restore)|decrypt|recover[\s_\-]?(?:files|instruction)|restore[\s_\-]?(?:my[\s_\-]?)?files|your[\s_\-]?files|unlock|ransom|_readme|help_decrypt|!!!)'
    $roots = @(@("$env:PUBLIC") + @(Get-WfxUserProfilePath)) | Where-Object { $_ } | Sort-Object -Unique

    Invoke-WfxStep 'files:ransomnotes' {
        $byName = @{}
        $scanned = 0
        foreach ($r in $roots) {
            if (-not (Test-Path -LiteralPath $r)) { continue }
            foreach ($f in (Get-ChildItem -LiteralPath $r -Recurse -File -Depth 4 -Include '*.txt', '*.html', '*.htm', '*.hta' -ErrorAction SilentlyContinue)) {
                if (++$scanned -gt $MaxScan) { break }
                if ($f.Length -gt 65536) { continue }
                $named = Test-WfxRxMatch $noteNameRx $f.BaseName
                if (-not $named -and $f.LastWriteTime -lt $cutoff) { continue }
                $k = $f.Name.ToLowerInvariant()
                if (-not $byName.ContainsKey($k)) { $byName[$k] = [pscustomobject]@{ Named = $named; Files = New-Object System.Collections.Generic.List[string] } }
                $byName[$k].Files.Add($f.FullName)
            }
        }
        $cands = @($byName.GetEnumerator() | Where-Object { $_.Value.Named -or $_.Value.Files.Count -ge $NoteMinCopies } |
                Sort-Object { $_.Value.Files.Count } -Descending | Select-Object -First $MaxNotes)
        foreach ($c in $cands) {
            $first = $c.Value.Files[0]
            $txt = ''
            try { $txt = Get-Content -LiteralPath $first -Raw -ErrorAction Stop } catch {}
            if ($txt) {
                if ($txt.Length -gt 16384) { $txt = $txt.Substring(0, 16384) }
                $notes.Add([pscustomobject]@{ Path = $first; Name = $c.Key; Copies = $c.Value.Files.Count; Content = (Protect-WfxText $txt) })
            }
        }
    } | Out-Null

    Invoke-WfxStep 'files:recentencrypted' {
        $count = 0; $scanned = 0
        foreach ($r in $roots) {
            if ($count -ge $MaxRecent -or $scanned -ge $MaxScan) { break }
            if (-not (Test-Path -LiteralPath $r)) { continue }
            foreach ($f in (Get-ChildItem -LiteralPath $r -Recurse -File -Depth 5 -ErrorAction SilentlyContinue)) {
                if (++$scanned -gt $MaxScan) { Add-WfxGap -Source 'files:recentencrypted' -Reason "Scan cap ($MaxScan files) reached."; break }
                if ($f.LastWriteTime -lt $cutoff -or $f.Length -lt 1024 -or $f.Length -gt 52428800) { continue }
                if ($count -ge $MaxRecent) { break }
                $count++
                $e = Get-WfxFileBytesEntropy $f.FullName 65536
                if ($e -ge 7.3) {
                    $recent.Add([pscustomobject]@{ Path = $f.FullName; Directory = $f.DirectoryName; Extension = $f.Extension; Entropy = $e; LastWrite = (ConvertTo-WfxUtcString $f.LastWriteTimeUtc) })
                }
            }
        }
    } | Out-Null

    [pscustomobject]@{ Note = @($notes.ToArray()); RecentFile = @($recent.ToArray()) }
}


# ===== Collectors/Persistence.ps1 =====
# Persistence collector — enumerates autostart locations into normalized records.
# Covers Run keys, Startup folders, scheduled tasks, WMI subscriptions, Winlogon, AppInit,
# Image File Execution Options, LSA packages, BootExecute and (as evidence, not persistence) the Run-dialog
# history (RunMRU) where ClickFix lures leave the pasted command. Services/drivers come from System.ps1.
# Only LOADED user hives are visible (logged-on users); unloaded NTUSER.DAT files are a recorded limitation.

function Get-WfxPersistenceData {
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]

    $add = {
        param($Kind, $Name, $Command, $Location, $User = '')
        $path = if ($Kind -eq 'RunMRU') { '' } else { Get-WfxImagePath $Command }
        # Store a secret-scrubbed command (a task action or WMI script text can embed credentials); the
        # image path above is taken from the raw value first so analysis is unaffected.
        $out.Add([pscustomobject]@{ Kind = $Kind; Name = $Name; Command = (Protect-WfxText ([string]$Command)); Path = $path; Location = $Location
                User = $User; Enabled = $true; SignatureStatus = (Get-WfxSignature $path) })
    }

    # ── Run / RunOnce keys (HKLM + all user hives) ──
    Invoke-WfxStep 'persist:runkeys' {
        $runPaths = @(
            'HKLM:\Software\Microsoft\Windows\CurrentVersion\Run'
            'HKLM:\Software\Microsoft\Windows\CurrentVersion\RunOnce'
            'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Run'
            'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run'
        )
        foreach ($u in (Get-WfxUserHives)) {
            $runPaths += "$u\Software\Microsoft\Windows\CurrentVersion\Run"
            $runPaths += "$u\Software\Microsoft\Windows\CurrentVersion\RunOnce"
        }
        foreach ($rp in $runPaths) {
            if (-not (Test-Path $rp)) { continue }
            $k = Get-Item $rp -ErrorAction SilentlyContinue
            foreach ($v in $k.GetValueNames()) {
                & $add 'RunKey' $(if ($v) { $v } else { '(Default)' }) ($k.GetValue($v)) $rp
            }
        }
    }

    # ── Run-dialog history (ClickFix / fake-CAPTCHA lures land here) ──
    Invoke-WfxStep 'persist:runmru' {
        foreach ($u in (Get-WfxUserHives)) {
            $mru = "$u\Software\Microsoft\Windows\CurrentVersion\Explorer\RunMRU"
            if (-not (Test-Path $mru)) { continue }
            $k = Get-Item $mru -ErrorAction SilentlyContinue
            foreach ($v in @($k.GetValueNames() | Where-Object { $_ -match '^[a-z]$' })) {
                & $add 'RunMRU' "RunMRU:$v" (([string]$k.GetValue($v)) -replace '\\1$', '') $mru
            }
        }
    }

    # ── Startup folders ──
    Invoke-WfxStep 'persist:startup' {
        $folders = @("$env:ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp")
        foreach ($prof in (Get-WfxUserProfilePath)) { $folders += "$prof\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup" }
        foreach ($f in $folders) {
            if (-not (Test-Path $f)) { continue }
            Get-ChildItem -LiteralPath $f -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' } | ForEach-Object { & $add 'Startup' $_.Name $_.FullName $f }
        }
    }

    # ── Scheduled tasks ──
    Invoke-WfxStep 'persist:tasks' {
        Get-ScheduledTask -ErrorAction Stop | ForEach-Object {
            $t = $_
            foreach ($a in @($t.Actions)) {
                $cmd = ''
                if ($a.Execute) { $cmd = $a.Execute; if ($a.Arguments) { $cmd += ' ' + $a.Arguments } }
                elseif ($a.PSObject.Properties['ClassId'] -and $a.ClassId) { $cmd = "COM-handler $($a.ClassId) $($a.Data)" }
                if (-not $cmd) { continue }
                & $add 'ScheduledTask' ($t.TaskPath + $t.TaskName) $cmd ('Task:' + $t.State) ($t.Principal.UserId)
            }
        }
    }

    # ── WMI event subscriptions (classic persistence) ──
    Invoke-WfxStep 'persist:wmi' {
        $consumers = Get-CimInstance -Namespace root\subscription -ClassName __EventConsumer -ErrorAction SilentlyContinue
        foreach ($c in $consumers) {
            $cmd = ''
            if ($c.CommandLineTemplate) { $cmd = $c.CommandLineTemplate }
            elseif ($c.ScriptText) { $cmd = $c.ScriptText }
            elseif ($c.ScriptFileName) { $cmd = $c.ScriptFileName }
            if ($cmd) { & $add 'WmiSubscription' ($c.Name) $cmd 'root\subscription' }
        }
    }

    # ── Winlogon (Shell / Userinit / Taskman / VmApplet) ──
    Invoke-WfxStep 'persist:winlogon' {
        $wl = 'HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Winlogon'
        if (Test-Path $wl) {
            $k = Get-Item $wl
            foreach ($v in @('Shell', 'Userinit', 'Taskman', 'VmApplet')) {
                $val = $k.GetValue($v)
                if ($val -and $val -notin @('explorer.exe', 'C:\Windows\system32\userinit.exe,')) { & $add 'Winlogon' $v $val $wl }
            }
        }
    }

    # ── AppInit_DLLs ──
    Invoke-WfxStep 'persist:appinit' {
        foreach ($p in @('HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Windows', 'HKLM:\Software\Wow6432Node\Microsoft\Windows NT\CurrentVersion\Windows')) {
            if (-not (Test-Path $p)) { continue }
            $v = (Get-ItemProperty $p -ErrorAction SilentlyContinue).AppInit_DLLs
            if ($v) { & $add 'AppInit' 'AppInit_DLLs' $v $p }
        }
    }

    # ── Image File Execution Options debuggers ──
    Invoke-WfxStep 'persist:ifeo' {
        $ifeo = 'HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Image File Execution Options'
        if (Test-Path $ifeo) {
            Get-ChildItem $ifeo -ErrorAction SilentlyContinue | ForEach-Object {
                $dbg = (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).Debugger
                if ($dbg) { & $add 'ImageFileExecution' ($_.PSChildName) $dbg $ifeo }
            }
        }
    }

    # ── LSA security/authentication packages ──
    Invoke-WfxStep 'persist:lsa' {
        $lsa = 'HKLM:\System\CurrentControlSet\Control\Lsa'
        if (Test-Path $lsa) {
            $k = Get-ItemProperty $lsa -ErrorAction SilentlyContinue
            foreach ($v in @('Security Packages', 'Authentication Packages', 'Notification Packages')) {
                $known = @('kerberos', 'msv1_0', 'schannel', 'wdigest', 'tspkg', 'pku2u', 'cloudap', 'negoexts', 'livessp', '""', 'scecli', 'rassfm')
                foreach ($pkg in @($k.$v | Where-Object { $_ })) {
                    if ($pkg.ToLower().Trim('"') -notin $known) { & $add 'LsaProvider' "$v`:$pkg" $pkg $lsa }
                }
            }
        }
    }

    # ── BootExecute ──
    Invoke-WfxStep 'persist:bootexec' {
        $sm = 'HKLM:\System\CurrentControlSet\Control\Session Manager'
        if (Test-Path $sm) {
            foreach ($be in @((Get-ItemProperty $sm -ErrorAction SilentlyContinue).BootExecute | Where-Object { $_ })) {
                if ($be -notmatch '^autocheck\s+autochk') { & $add 'BootExecute' $be $be $sm }
            }
        }
    }

    $out.ToArray()
}

function Get-WfxUserHives {
    <# Returns registry paths for all loaded user hives (Registry::HKEY_USERS\<sid>). #>
    # HKCU is the same hive as HKEY_USERS\<current SID>; listing both duplicated every per-user entry.
    $hives = @()
    try {
        Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-|^S-1-12-1-' -and $_.PSChildName -notmatch '_Classes$' } | ForEach-Object {
            $hives += "Registry::HKEY_USERS\$($_.PSChildName)"
        }
    } catch {}
    if (-not $hives.Count) { $hives = @('HKCU:') }
    $hives
}


# ===== Collectors/Security.ps1 =====
# Security-posture collector — gathers the host's defensive configuration so the triage can tell the
# difference between "nothing found" and "nothing could be seen". Read-only. Produces one posture
# object the Posture analyzer turns into visibility/hardening findings, plus an AI-tooling inventory.

function Get-WfxRegValue {
    param([string]$Path, [string]$Name)
    try { $p = Get-ItemProperty -Path $Path -Name $Name -ErrorAction Stop; return $p.$Name } catch { return $null }
}

function Get-WfxSecurityData {
    if (-not (Test-WfxWindows)) {
        return [pscustomobject]@{ Defender = $null; ThirdPartyAV = @(); Firewall = $null; Audit = $null; BitLocker = $null; Lsa = $null; Rdp = $null; AiTools = @() }
    }

    # ── Microsoft Defender ──
    $defender = Invoke-WfxStep 'posture:defender' {
        $st = $null; $pf = $null
        try { $st = Get-MpComputerStatus -ErrorAction Stop } catch {}
        try { $pf = Get-MpPreference -ErrorAction Stop } catch {}
        if (-not $st -and -not $pf) { throw 'Defender cmdlets unavailable' }
        $exReadable = [bool]$pf -and -not (@($pf.ExclusionPath) -match '^N/A')
        if ($pf -and -not $exReadable) { Add-WfxGap -Source 'posture:defender:exclusions' -Reason 'Defender exclusions are only visible to administrators.' -Fix 'Run elevated.' }
        $sigAge = $null
        if ($st -and $st.AntivirusSignatureLastUpdated) { try { $sigAge = [int]((Get-Date) - $st.AntivirusSignatureLastUpdated).TotalDays } catch {} }
        [pscustomobject]@{
            Installed                 = $true
            AntivirusEnabled          = if ($st) { [bool]$st.AntivirusEnabled } else { $null }
            RealTimeProtectionEnabled = if ($st) { [bool]$st.RealTimeProtectionEnabled } else { $null }
            TamperProtectionEnabled   = if ($st) { [bool]$st.IsTamperProtected } else { $null }
            BehaviorMonitorEnabled    = if ($st) { [bool]$st.BehaviorMonitorEnabled } else { $null }
            SignatureAgeDays          = $sigAge
            EngineVersion             = if ($st) { [string]$st.AMEngineVersion } else { '' }
            # Non-admins get the placeholder "N/A: Must be an administrator to view exclusions" — that is
            # "unknown", not "no exclusions".
            ExclusionsReadable        = $exReadable
            ExclusionPath             = if ($pf -and $exReadable) { @($pf.ExclusionPath | Where-Object { $_ }) } else { @() }
            ExclusionProcess          = if ($pf -and $exReadable) { @($pf.ExclusionProcess | Where-Object { $_ }) } else { @() }
            ExclusionExtension        = if ($pf -and $exReadable) { @($pf.ExclusionExtension | Where-Object { $_ }) } else { @() }
            DisableRealtimeMonitoring = if ($pf) { [bool]$pf.DisableRealtimeMonitoring } else { $null }
        }
    } $null

    # ── Registered AV products (SecurityCenter2) — tells us if a 3rd-party AV is the active engine ──
    $thirdParty = Invoke-WfxStep 'posture:securitycenter' {
        @(Get-CimInstance -Namespace 'root\SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop |
            Where-Object { $_.displayName -and $_.displayName -notmatch '(?i)windows defender|microsoft defender' } |
            ForEach-Object { $_.displayName })
    } @()

    # ── Firewall profiles ──
    $firewall = Invoke-WfxStep 'posture:firewall' {
        $fw = @{}
        Get-NetFirewallProfile -ErrorAction Stop | ForEach-Object { $fw[[string]$_.Name] = [bool]$_.Enabled }
        [pscustomobject]$fw
    } $null

    # ── Audit / logging visibility ──
    $audit = Invoke-WfxStep 'posture:audit' {
        # Tri-state: $true / $false / $null (unknown). auditpol needs admin and prints localized text, so a
        # failure or unrecognised output must be "unknown", never "auditing is off".
        $procAudit = $null
        try {
            # Subcategory GUID for "Process Creation" (language-independent).
            $ap = @(auditpol /get /subcategory:'{0CCE922B-69AE-11D9-BED3-505054503030}' /r 2>$null)
            if ($LASTEXITCODE -eq 0 -and $ap.Count -ge 2) {
                $row = ($ap | Where-Object { $_ -match '0CCE922B' } | Select-Object -First 1)
                if ($row -match '(?i),\s*(?:Success|Failure|Success and Failure)\s*,') { $procAudit = $true }
                elseif ($row -match '(?i),\s*No Auditing\s*,') { $procAudit = $false }
            }
        } catch {}
        if ($null -eq $procAudit) { Add-WfxGap -Source 'posture:audit:process-creation' -Reason 'Could not determine whether process-creation auditing is enabled (needs admin; output may be localized).' -Fix 'Run elevated, or check: auditpol /get /subcategory:"Process Creation"' }
        $sysmonSvc = [bool]((Get-Service -Name 'Sysmon', 'Sysmon64' -ErrorAction SilentlyContinue) | Where-Object { $_.Status -eq 'Running' })
        # The service binary can be renamed; the driver key and the event channel are more stable indicators.
        $sysmonDrv = Test-Path 'HKLM:\SYSTEM\CurrentControlSet\Services\SysmonDrv'
        $sysmonLog = $false; try { $sysmonLog = [bool](Get-WinEvent -ListLog 'Microsoft-Windows-Sysmon/Operational' -ErrorAction Stop).IsEnabled } catch {}
        [pscustomobject]@{
            ProcessCreation             = $procAudit
            CommandLineInProcessCreation = ((Get-WfxRegValue 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\Audit' 'ProcessCreationIncludeCmdLine_Enabled') -eq 1)
            ScriptBlockLogging          = ((Get-WfxRegValue 'HKLM:\Software\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging' 'EnableScriptBlockLogging') -eq 1)
            ModuleLogging               = ((Get-WfxRegValue 'HKLM:\Software\Policies\Microsoft\Windows\PowerShell\ModuleLogging' 'EnableModuleLogging') -eq 1)
            Transcription               = ((Get-WfxRegValue 'HKLM:\Software\Policies\Microsoft\Windows\PowerShell\Transcription' 'EnableTranscripting') -eq 1)
            SysmonInstalled             = ($sysmonSvc -or ($sysmonDrv -and $sysmonLog))
        }
    } $null

    # ── LSASS protection / Credential Guard ──
    $lsa = Invoke-WfxStep 'posture:lsa' {
        $cg = $null
        try { $dg = Get-CimInstance -Namespace 'root\Microsoft\Windows\DeviceGuard' -ClassName Win32_DeviceGuard -ErrorAction Stop; $cg = (@($dg.SecurityServicesRunning) -contains 1) } catch {}
        [pscustomobject]@{
            RunAsPPL        = ((Get-WfxRegValue 'HKLM:\System\CurrentControlSet\Control\Lsa' 'RunAsPPL') -in @(1, 2))
            CredentialGuard = $cg
        }
    } $null

    # ── RDP exposure ──
    $rdp = Invoke-WfxStep 'posture:rdp' {
        $deny = Get-WfxRegValue 'HKLM:\System\CurrentControlSet\Control\Terminal Server' 'fDenyTSConnections'
        $nla = Get-WfxRegValue 'HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' 'UserAuthentication'
        $nlaPolicy = Get-WfxRegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services' 'UserAuthentication'
        $denyPolicy = Get-WfxRegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services' 'fDenyTSConnections'
        if ($null -ne $denyPolicy) { $deny = $denyPolicy }
        if ($null -ne $nlaPolicy) { $nla = $nlaPolicy }
        [pscustomobject]@{ Enabled = ($deny -eq 0); NlaEnabled = ($nla -eq 1) }
    } $null

    # ── BitLocker (system drive) ──
    $bitlocker = Invoke-WfxStep 'posture:bitlocker' {
        $v = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop
        [pscustomobject]@{ SystemDriveProtection = [string]$v.ProtectionStatus; Encryption = [string]$v.VolumeStatus }
    } $null

    # ── AI tooling inventory (installed runtimes / assistant CLIs) — context, not a finding by itself ──
    $aiTools = Invoke-WfxStep 'posture:aitools' {
        $found = New-Object System.Collections.Generic.List[object]
        $dirs = @(
            @{ N = 'Ollama'; P = "$env:LOCALAPPDATA\Programs\Ollama" }
            @{ N = 'LM Studio'; P = "$env:LOCALAPPDATA\LM-Studio" }
            @{ N = 'Jan'; P = "$env:LOCALAPPDATA\Programs\Jan" }
            @{ N = 'GPT4All'; P = "$env:LOCALAPPDATA\nomic.ai\GPT4All" }
            @{ N = 'Open WebUI'; P = "$env:LOCALAPPDATA\open-webui" }
        )
        foreach ($d in $dirs) { if (Test-Path -LiteralPath $d.P) { $found.Add([pscustomobject]@{ Name = $d.N; Path = $d.P; Kind = 'runtime' }) } }
        foreach ($cli in @('ollama', 'llm', 'claude', 'openai', 'aider', 'gh-copilot')) {
            $c = Get-Command $cli -ErrorAction SilentlyContinue
            if ($c) { $found.Add([pscustomobject]@{ Name = $cli; Path = $c.Source; Kind = 'cli' }) }
        }
        @($found.ToArray())
    } @()

    [pscustomobject]@{
        Defender     = $defender
        ThirdPartyAV = @($thirdParty)
        Firewall     = $firewall
        Audit        = $audit
        Lsa          = $lsa
        Rdp          = $rdp
        BitLocker    = $bitlocker
        AiTools      = @($aiTools)
    }
}


# ===== Collectors/System.ps1 =====
# Windows collectors — gather live data into the normalized shapes the analyzers consume.
# Every collector: returns [] on non-Windows or on error (recorded as a gap), never throws, never makes
# network requests, and degrades gracefully without administrator rights. Timestamps are stored as UTC.

$script:WfxSigCache = @{}

function Get-WfxUserProfilePath {
    <# Real user-profile folders from the registry ProfileList (works when profiles are not on C:\Users). #>
    $paths = New-Object System.Collections.Generic.List[string]
    if (-not (Test-WfxWindows)) { return , $paths.ToArray() }
    try {
        Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList' -ErrorAction Stop | ForEach-Object {
            if ($_.PSChildName -match '^S-1-5-21-|^S-1-12-1-') {
                $p = [Environment]::ExpandEnvironmentVariables([string]$_.GetValue('ProfileImagePath'))
                if ($p -and (Test-Path -LiteralPath $p) -and -not $paths.Contains($p)) { $paths.Add($p) }
            }
        }
    } catch {}
    if ($paths.Count -eq 0) {
        $root = Join-Path $env:SystemDrive 'Users'
        Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin @('Public', 'Default', 'Default User', 'All Users') } | ForEach-Object { $paths.Add($_.FullName) }
    }
    $paths.ToArray()
}

function Get-WfxHostInfo {
    if (-not (Test-WfxWindows)) {
        return [pscustomobject]@{ HostName = [Environment]::MachineName; Os = 'Non-Windows (collectors limited)'; Collected = (Get-WfxUtcNow); Admin = $false }
    }
    $os = Invoke-WfxStep 'hostinfo:os' { Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } $null
    $cs = Invoke-WfxStep 'hostinfo:cs' { Get-CimInstance Win32_ComputerSystem -ErrorAction Stop } $null
    $tz = $null; try { $tz = Get-TimeZone -ErrorAction Stop } catch {}
    [pscustomobject]@{
        HostName     = [Environment]::MachineName
        Domain       = if ($cs) { $cs.Domain } else { '' }
        Os           = if ($os) { "$($os.Caption) $($os.Version) (build $($os.BuildNumber))" } else { '' }
        Architecture = if ($os) { [string]$os.OSArchitecture } else { '' }
        Is64BitProcess = [Environment]::Is64BitProcess
        BootUtc      = if ($os) { ConvertTo-WfxUtcString $os.LastBootUpTime } else { '' }
        InstallUtc   = if ($os) { ConvertTo-WfxUtcString $os.InstallDate } else { '' }
        Manufacturer = if ($cs) { "$($cs.Manufacturer) $($cs.Model)" } else { '' }
        Collected    = (Get-WfxUtcNow)
        TimeZone     = if ($tz) { $tz.Id } else { '' }
        UtcOffsetMinutes = if ($tz) { [int]$tz.GetUtcOffset((Get-Date)).TotalMinutes } else { $null }
        Admin        = (Test-WfxAdmin)
        Operator     = [Environment]::UserName
        PSVersion    = $PSVersionTable.PSVersion.ToString()
        # Own unicast addresses (read from the network stack; nothing is sent), so other hosts' logon
        # records can be matched to this one in a fleet report.
        Addresses    = @(try {
                [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces() | Where-Object { $_.OperationalStatus -eq 'Up' -and $_.NetworkInterfaceType -ne 'Loopback' } |
                    ForEach-Object { $_.GetIPProperties().UnicastAddresses } | ForEach-Object { $_.Address } | Where-Object { -not $_.IsIPv6LinkLocal -and -not [System.Net.IPAddress]::IsLoopback($_) } | ForEach-Object { $_.ToString() }
            } catch { })
    }
}

function Get-WfxSignature {
    <# Authenticode status, cached per path for the duration of a collection (services share binaries). #>
    param([string]$Path)
    if (-not $Path -or -not (Test-WfxWindows)) { return '' }
    $k = $Path.ToLowerInvariant()
    if ($script:WfxSigCache.ContainsKey($k)) { return $script:WfxSigCache[$k] }
    $s = ''
    if (Test-Path -LiteralPath $Path -PathType Leaf -ErrorAction SilentlyContinue) {
        try { $s = [string](Get-AuthenticodeSignature -LiteralPath $Path -ErrorAction Stop).Status } catch { $s = 'Unknown' }
    }
    $script:WfxSigCache[$k] = $s
    return $s
}

function Get-WfxProcessData {
    <# Normalized process list with parent linkage, signature status and owner.
       -Skip: hashtable of "pid:name" keys to leave out (used by the live monitor to enrich only new processes). #>
    param([hashtable]$Skip = @{})
    if (-not (Test-WfxWindows)) { return @() }
    $raw = Invoke-WfxStep 'process:list' { Get-CimInstance Win32_Process -ErrorAction Stop } @()
    if (-not $raw) { return @() }
    $byPid = @{}
    foreach ($p in $raw) { $byPid[[string]$p.ProcessId] = $p }
    # Owners: one bulk call when elevated (fast); per-process CIM GetOwner otherwise (only own processes resolve).
    $owners = @{}
    if (Test-WfxAdmin) { try { Get-Process -IncludeUserName -ErrorAction Stop | ForEach-Object { if ($_.UserName) { $owners[[string]$_.Id] = $_.UserName } } } catch {} }
    $companyCache = @{}
    $out = foreach ($p in $raw) {
        if ($Skip.Count -and $Skip.ContainsKey("$($p.ProcessId):$($p.Name)")) { continue }
        $path = $p.ExecutablePath
        if (-not $path) { $path = Get-WfxImagePath $p.CommandLine }
        $sig = Get-WfxSignature $path
        $company = ''
        if ($path -and $sig) {
            if (-not $companyCache.ContainsKey($path)) { try { $companyCache[$path] = (Get-Item -LiteralPath $path -ErrorAction Stop).VersionInfo.CompanyName } catch { $companyCache[$path] = '' } }
            $company = $companyCache[$path]
        }
        $parent = $byPid[[string]$p.ParentProcessId]
        $owner = [string]$owners[[string]$p.ProcessId]
        if (-not $owner -and $owners.Count -eq 0 -and [int]$p.SessionId -ne 0) {
            try { $o = Invoke-CimMethod -InputObject $p -MethodName GetOwner -ErrorAction SilentlyContinue; if ($o.User) { $owner = if ($o.Domain) { "$($o.Domain)\$($o.User)" } else { $o.User } } } catch { $owner = '' }
        }
        [pscustomobject]@{
            Pid               = [int]$p.ProcessId
            Ppid              = [int]$p.ParentProcessId
            Name              = $p.Name
            Path              = $path
            # Scrub secrets out of command lines at collection time, so the raw bundle is safe to persist
            # and ship. Tool/command structure is preserved; only embedded secret values are redacted.
            CommandLine       = (Protect-WfxText $p.CommandLine)
            ParentName        = if ($parent) { $parent.Name } else { '' }
            ParentPath        = if ($parent) { $parent.ExecutablePath } else { '' }
            ParentCommandLine = if ($parent) { Protect-WfxText $parent.CommandLine } else { '' }
            ParentCreateTime  = if ($parent) { ConvertTo-WfxUtcString $parent.CreationDate } else { '' }
            SignatureStatus   = $sig
            Company           = $company
            CreateTime        = ConvertTo-WfxUtcString $p.CreationDate
            User              = $owner
            SessionId         = [int]$p.SessionId
        }
    }
    $out
}

function Get-WfxNetworkData {
    <# TCP connections/listeners and UDP endpoints. No name resolution is performed here — endpoints are
       named later from the DNS cache, so the tool sends no packets from the host under investigation. #>
    if (-not (Test-WfxWindows)) { return @() }
    $procNames = @{}
    try { Get-Process -ErrorAction SilentlyContinue | ForEach-Object { $procNames[[string]$_.Id] = $_.ProcessName } } catch {}
    $out = New-Object System.Collections.Generic.List[object]
    $tcp = Invoke-WfxStep 'network:tcp' { Get-NetTCPConnection -ErrorAction Stop } $null
    if ($tcp) {
        foreach ($c in $tcp) {
            $out.Add([pscustomobject]@{
                    Protocol = 'TCP'; LocalAddress = $c.LocalAddress; LocalPort = [int]$c.LocalPort
                    RemoteAddress = $c.RemoteAddress; RemotePort = [int]$c.RemotePort; State = [string]$c.State
                    Pid = [int]$c.OwningProcess; Process = $procNames[[string]$c.OwningProcess]; RemoteHost = ''
                    CreatedUtc = ConvertTo-WfxUtcString $c.CreationTime
                })
        }
        $udp = Invoke-WfxStep 'network:udp' { Get-NetUDPEndpoint -ErrorAction Stop } $null
        foreach ($u in @($udp | Where-Object { $_ })) {
            $out.Add([pscustomobject]@{ Protocol = 'UDP'; LocalAddress = $u.LocalAddress; LocalPort = [int]$u.LocalPort; RemoteAddress = ''; RemotePort = 0
                    State = 'Bound'; Pid = [int]$u.OwningProcess; Process = $procNames[[string]$u.OwningProcess]; RemoteHost = ''; CreatedUtc = ConvertTo-WfxUtcString $u.CreationTime })
        }
    } else {
        # Fallback for very old hosts: parse netstat (state names may be localized; recorded as a gap).
        Add-WfxGap -Source 'network' -Reason 'Get-NetTCPConnection unavailable; used netstat fallback (state names may be localized).'
        $ns = Invoke-WfxStep 'network:netstat' { netstat -ano } @()
        foreach ($line in $ns) {
            if ($line -match '^\s*TCP\s+(\S+):(\d+)\s+(\S+):(\d+)\s+(\S+)\s+(\d+)\s*$') {
                $out.Add([pscustomobject]@{ Protocol = 'TCP'; LocalAddress = $Matches[1].Trim('[', ']'); LocalPort = [int]$Matches[2]
                        RemoteAddress = $Matches[3].Trim('[', ']'); RemotePort = [int]$Matches[4]; State = ($Matches[5] -replace '^LISTENING$', 'Listen' -replace '^ESTABLISHED$', 'Established')
                        Pid = [int]$Matches[6]; Process = $procNames[$Matches[6]]; RemoteHost = ''; CreatedUtc = '' })
            } elseif ($line -match '^\s*UDP\s+(\S+):(\d+)\s+\S+\s+(\d+)\s*$') {
                $out.Add([pscustomobject]@{ Protocol = 'UDP'; LocalAddress = $Matches[1].Trim('[', ']'); LocalPort = [int]$Matches[2]; RemoteAddress = ''; RemotePort = 0
                        State = 'Bound'; Pid = [int]$Matches[3]; Process = $procNames[$Matches[3]]; RemoteHost = ''; CreatedUtc = '' })
            }
        }
    }
    $out.ToArray()
}

function Get-WfxDnsData {
    if (-not (Test-WfxWindows)) { return @() }
    $raw = Invoke-WfxStep 'dns:cache' { Get-DnsClientCache -ErrorAction Stop } $null
    if ($null -eq $raw) {
        # Fallback: ipconfig /displaydns parsing (English output only; recorded as a gap).
        Add-WfxGap -Source 'dns' -Reason 'Get-DnsClientCache unavailable; used ipconfig /displaydns fallback (English output only).'
        $out = New-Object System.Collections.Generic.List[object]
        $dns = Invoke-WfxStep 'dns:ipconfig' { ipconfig /displaydns } @()
        $cur = ''
        foreach ($line in $dns) {
            if ($line -match 'Record Name[.\s]*:\s*(\S+)') { $cur = $Matches[1] }
            elseif ($line -match '(?:A \(Host\)|AAAA) Record[.\s]*:\s*(\S+)' -and $cur) { $out.Add([pscustomobject]@{ Name = $cur; Type = 'A'; Data = $Matches[1] }) }
        }
        return $out.ToArray()
    }
    $raw | ForEach-Object { [pscustomobject]@{ Name = $_.Entry; RecordName = $_.Name; Type = [string]$_.Type; Data = [string]$_.Data; TTL = $_.TimeToLive } } | Where-Object { $_.Name }
}

function Get-WfxServiceAndDriver {
    <# Services and kernel drivers → autostart records (Kind Service / Driver). #>
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $svc = Invoke-WfxStep 'persist:services' { Get-CimInstance Win32_Service -ErrorAction Stop } @()
    foreach ($s in $svc) {
        $img = Get-WfxImagePath $s.PathName
        $out.Add([pscustomobject]@{ Kind = 'Service'; Name = $s.Name; DisplayName = $s.DisplayName; Command = (Protect-WfxText $s.PathName); Path = $img
                Location = "Service:$($s.StartMode)"; State = [string]$s.State; User = $s.StartName; Enabled = ($s.StartMode -ne 'Disabled'); SignatureStatus = (Get-WfxSignature $img) })
    }
    $drv = Invoke-WfxStep 'persist:drivers' { Get-CimInstance Win32_SystemDriver -ErrorAction Stop } @()
    foreach ($d in $drv) {
        if ($d.State -ne 'Running' -and $d.StartMode -eq 'Disabled') { continue }
        $img = Get-WfxImagePath $d.PathName
        $out.Add([pscustomobject]@{ Kind = 'Driver'; Name = $d.Name; DisplayName = $d.DisplayName; Command = (Protect-WfxText $d.PathName); Path = $img
                Location = "Driver:$($d.StartMode)"; State = [string]$d.State; Enabled = ($d.StartMode -ne 'Disabled'); SignatureStatus = (Get-WfxSignature $img) })
    }
    $out.ToArray()
}


# ===== Report/Guide.ps1 =====
function New-WfxGuide {
    <#
    .SYNOPSIS Writes a self-contained HTML usage guide (how to use, commands, outputs, limitations, safety),
              in the same look as the case report.
    .PARAMETER Path  Output .html path.
    .OUTPUTS The output path.
    #>
    [CmdletBinding()]
    param([string]$Path = (Join-Path ([IO.Path]::GetTempPath()) 'WinForensicX-guide.html'))
    $h = Get-WfxHelpModel
    $enc = { param($s) [System.Net.WebUtility]::HtmlEncode([string]$s) }

    $cmdHtml = foreach ($c in $h.Commands) {
        $ex = if (@($c.Examples).Count) { "<pre class='ex'>" + ((@($c.Examples) | ForEach-Object { & $enc $_ }) -join "`n") + "</pre>" } else { '' }
        $pr = if (@($c.Params).Count) { "<ul class='params'>" + ((@($c.Params) | ForEach-Object { "<li class='mono'>$(& $enc $_)</li>" }) -join '') + "</ul>" } else { '' }
        @"
<div class="cmd">
  <h3 class="mono">$(& $enc $c.Name)</h3><p>$(& $enc $c.Summary)</p>
  $pr$ex
</div>
"@
    }
    $outRows = ($h.Outputs | ForEach-Object { "<li class='mono'>$(& $enc $_)</li>" }) -join ''
    $limRows = ($h.Limits | ForEach-Object { "<li>$(& $enc $_)</li>" }) -join ''
    $safeRows = ($h.Safety | ForEach-Object { "<li>$(& $enc $_)</li>" }) -join ''

    $html = @"
<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'">
<title>WinForensicX $(& $enc $h.Version) help</title>
<style>
$(Get-WfxThemeCss)
.wrap{max-width:960px;margin:0 auto;padding:8px 24px 80px}
h2{font-size:19px;margin:36px 0 12px;padding-bottom:6px;border-bottom:1px solid var(--line)}
.cmd{padding:14px 0 16px;border-bottom:1px solid var(--line2)}
.cmd h3{font-size:14.5px;color:var(--ink)}
.cmd p{margin:4px 0 8px;color:var(--ink2)}
ul.params{margin:0 0 8px;padding-left:18px;color:var(--ink2)}
ul.params li{margin:2px 0}
pre.ex{font:12.5px/1.5 var(--mono);background:var(--alt);border:1px solid var(--line2);padding:8px 11px;margin:6px 0 0;overflow-x:auto;white-space:pre-wrap;overflow-wrap:anywhere}
ul.list{margin:0;padding-left:20px}
ul.list li{margin:6px 0}
.req{font-family:var(--mono);font-size:12.5px;color:var(--ink2);border:1px solid var(--line);background:var(--alt);padding:10px 13px}
.foot{margin-top:36px;border-top:1px solid var(--line);padding-top:14px;color:var(--ink3);font-size:12.5px}
@media (max-width:640px){.mast .in,.wrap{padding-left:16px;padding-right:16px}.mast h1{font-size:24px}}
</style></head><body>
<header class="mast"><div class="in">
  <div class="brandrow">$(Get-WfxMarkSvg)<b>WinForensicX</b><span>Help</span><span class="tools"><button class="mbtn" id="themebtn" type="button">Dark</button></span></div>
  <h1>WinForensicX $(& $enc $h.Version)</h1>
  <p>$(& $enc $h.Tagline)</p>
</div></header>
<main class="wrap">
  <h2>Commands</h2>$($cmdHtml -join "`n")
  <h2>What a run produces</h2><ul class="list">$outRows</ul>
  <h2>Safety</h2><ul class="list">$safeRows</ul>
  <h2>Limitations</h2><ul class="list">$limRows</ul>
  <h2>Requirements</h2><div class="req">$(& $enc $h.Requires)</div>
  <div class="foot">WinForensicX $(& $enc $h.Version). Generated $((Get-Date).ToUniversalTime().ToString('yyyy-MM-dd HH:mm')) UTC. Self-contained and offline.</div>
</main>
<script>
(function(){var r=document.documentElement,b=document.getElementById('themebtn');
function lbl(){var c=r.getAttribute('data-theme');var d=c?c==='dark':matchMedia('(prefers-color-scheme: dark)').matches;b.textContent=d?'Light':'Dark';}
try{var s=localStorage.getItem('wfx-theme');if(s==='dark'||s==='light')r.setAttribute('data-theme',s);}catch(e){}
lbl();b.onclick=function(){var n=b.textContent==='Dark'?'dark':'light';r.setAttribute('data-theme',n);try{localStorage.setItem('wfx-theme',n);}catch(e){}lbl();};})();
</script>
</body></html>
"@
    [IO.File]::WriteAllText($Path, $html, (New-Object Text.UTF8Encoding($false)))
    return $Path
}


# ===== Report/Report.ps1 =====
function New-WfxReport {
    <#
    .SYNOPSIS
        Renders a self-contained (no external assets, works offline) HTML case report from an
        Invoke-WfxAnalyze result: verdict, a chart of when it happened, incidents, the attack path, each
        finding as a case file (what happened, when, how we know, what to do), indicators, a merged timeline,
        execution evidence, ATT&CK coverage, what could not be seen, and chain of custody. Times are UTC.
        Embeds only already-redacted data — never raw secret values.
    .PARAMETER Result  The result object from Invoke-WfxAnalyze.
    .PARAMETER Path    Output .html path.
    .OUTPUTS The output path.
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)]$Result, [Parameter(Mandatory)][string]$Path)

    $help = Get-WfxHelpModel
    $data = [ordered]@{
        tool          = "WinForensicX $($script:WfxVersion)"
        generated     = (Get-WfxUtcNow)
        hostName      = [string](Get-WfxValue $Result 'HostName' '')
        host          = (Get-WfxValue $Result 'Host' $null)
        risk          = (Get-WfxValue $Result 'Risk' $null)
        posture       = (Get-WfxValue $Result 'Posture' $null)
        collected     = (ConvertTo-WfxUtcString (Get-WfxValue $Result 'Collected' ''))
        case          = (Get-WfxValue $Result 'Case' $null)
        suppressed    = @(Get-WfxValue $Result 'Suppressed' @())
        summary       = (Get-WfxValue $Result 'Summary' $null)
        findings      = @(Get-WfxValue $Result 'Findings' @())
        activity      = @(Get-WfxValue $Result 'Activity' @())
        activityTotal = (ConvertTo-WfxInt (Get-WfxValue $Result 'ActivityTotal' 0))
        coverage      = @(Get-WfxValue $Result 'AttackCoverage' @())
        incidents     = @(Get-WfxValue $Result 'Incidents' @())
        artifacts     = @(@(Get-WfxValue $Result 'Artifacts' @()) | Select-Object -First 3000 | ForEach-Object { [ordered]@{ Artifact = $_.Artifact; Time = $_.Time; TimeKind = $_.TimeKind; Evidence = $_.Evidence; Path = $_.Path; User = $_.User; Sha1 = $_.Sha1; Detail = $_.Detail } })
        artifactTotal = (ConvertTo-WfxInt (Get-WfxValue $Result 'ArtifactTotal' 0))
        gaps          = @(Get-WfxValue $Result 'Gaps' @())
        limits        = @($help.Limits)
    }
    $json = ConvertTo-Json -InputObject $data -Depth 12
    # Neutralise markup-significant characters inside the JSON island; JSON.parse restores them as text.
    $bs = [string][char]0x5C
    $json = $json.Replace('&', "${bs}u0026").Replace('<', "${bs}u003c").Replace('>', "${bs}u003e").Replace([string][char]0x2028, "${bs}u2028").Replace([string][char]0x2029, "${bs}u2029")

    # Template placeholders first, data LAST, so collected text can never fill a placeholder.
    $html = $script:WfxReportTemplate
    $html = $html.Replace('__WFX_HOST__', [System.Net.WebUtility]::HtmlEncode($data.hostName))
    $html = $html.Replace('/*__WFX_DATA__*/', $json)
    [IO.File]::WriteAllText($Path, $html, (New-Object Text.UTF8Encoding($false)))
    return $Path
}

$script:WfxReportTemplate = @'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light dark">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:">
<title>Case report: __WFX_HOST__</title>
<style>
:root {
  --page: #FFFFFF; --alt: #F5F6F8; --alt2: #ECEEF1; --ink: #17202C; --ink2: #4E5967; --ink3: #7B8591;
  --line: #D3D8DE; --line2: #E6E9ED; --link: #0B57A4; --sel: #E7EEF7;
  --band: #14233A; --band2: #1C2E48; --band-ink: #F1F4F8; --band-dim: #A9B6C6;
  --crit: #9B1C1C; --high: #C2410C; --med: #A16207; --low: #2B6CB0; --info: #6B7280;
  --mark: .028;
  --sans: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  --mono: "Cascadia Mono", "Cascadia Code", Consolas, "SF Mono", Menlo, monospace;
}
@media (prefers-color-scheme: dark) { :root:not([data-theme=light]) {
  --page: #14181D; --alt: #1A1F25; --alt2: #222830; --ink: #E3E7EC; --ink2: #A4AEBA; --ink3: #7D8793;
  --line: #333B45; --line2: #262D35; --link: #7CB1EC; --sel: #1F2B3A; --band: #0D141D; --band2: #152131;
  --crit: #F07171; --high: #F59056; --med: #E2B04A; --low: #7FB0E6; --info: #9AA3AE; --mark: .04; } }
:root[data-theme=dark] {
  --page: #14181D; --alt: #1A1F25; --alt2: #222830; --ink: #E3E7EC; --ink2: #A4AEBA; --ink3: #7D8793;
  --line: #333B45; --line2: #262D35; --link: #7CB1EC; --sel: #1F2B3A; --band: #0D141D; --band2: #152131;
  --crit: #F07171; --high: #F59056; --med: #E2B04A; --low: #7FB0E6; --info: #9AA3AE; --mark: .04; }
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--page); color: var(--ink); font: 14px/1.5 var(--sans); font-variant-numeric: tabular-nums; }
*, *::before, *::after { font-variant-ligatures: none; font-feature-settings: "calt" 0, "liga" 0, "clig" 0; }
a { color: var(--link); text-decoration: none; } a:hover { text-decoration: underline; }
:focus-visible { outline: 2px solid var(--link); outline-offset: 2px; }
h1, h2, h3, h4 { margin: 0; font-weight: 600; }
h2 { font-size: 20px; line-height: 1.3; }
h3 { font-size: 14px; margin: 22px 0 8px; }
p { margin: 0 0 10px; }
code, .mono { font-family: var(--mono); font-size: 12.5px; }
.wrap { max-width: 1280px; margin: 0 auto; padding: 0 28px; }
.small { font-size: 12.5px; color: var(--ink2); }
.muted { color: var(--ink3); }
.btn { font: inherit; font-size: 13px; color: var(--ink); background: var(--page); border: 1px solid var(--line); border-radius: 3px; padding: 4px 10px; cursor: pointer; white-space: nowrap; }
.btn:hover { background: var(--alt); }
.btn[aria-pressed=true] { background: var(--alt2); }
.watermark { position: fixed; left: 50%; top: 55%; width: min(66vw, 520px); transform: translate(-50%, -50%) rotate(-12deg); color: var(--ink); opacity: var(--mark); pointer-events: none; z-index: 50; }
.watermark text { font: 700 7px var(--sans); }

/* masthead */
.mast { background: var(--band); color: var(--band-ink); }
.mast .wrap { padding-top: 16px; padding-bottom: 26px; }
.brandrow { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--band-dim); }
.brandrow svg { width: 22px; height: 22px; color: var(--band-ink); }
.brandrow b { color: var(--band-ink); font-weight: 600; font-size: 14px; }
.brandrow .tools { margin-left: auto; display: flex; gap: 6px; }
.mbtn { font: inherit; font-size: 12.5px; color: var(--band-ink); background: transparent; border: 1px solid rgba(255,255,255,.28); border-radius: 3px; padding: 3px 10px; cursor: pointer; }
.mbtn:hover { border-color: rgba(255,255,255,.6); }
.casehead { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-end; gap: 18px 40px; margin-top: 30px; }
.casehead h1 { font-size: 40px; line-height: 1.05; letter-spacing: -.02em; overflow-wrap: anywhere; }
.facts-line { display: flex; flex-wrap: wrap; gap: 4px 26px; margin-top: 12px; font-size: 13px; color: var(--band-dim); }
.facts-line span b { color: var(--band-ink); font-weight: 500; }
.verdictbox { text-align: left; }
.verdictbox .v { font-size: 21px; font-weight: 600; display: inline-flex; align-items: center; gap: 10px; }
.verdictbox .s { font-size: 13px; color: var(--band-dim); margin-top: 4px; }

/* sticky section bar */
.bar { position: sticky; top: 0; z-index: 10; background: var(--page); border-bottom: 1px solid var(--line); }
.nav { display: flex; overflow-x: auto; scrollbar-width: none; }
.nav::-webkit-scrollbar { display: none; }
.nav a { color: var(--ink2); padding: 12px 10px 11px; white-space: nowrap; border-bottom: 2px solid transparent; font-size: 13.5px; }
.nav a:first-child { padding-left: 0; }
.nav a:hover { color: var(--ink); text-decoration: none; }
.nav a.on { color: var(--ink); border-bottom-color: var(--ink); }
.nav a .n { color: var(--ink3); margin-left: 4px; font-size: 12px; }

/* sections */
section { padding: 34px 0 10px; border-bottom: 1px solid var(--line2); scroll-margin-top: 44px; }
section:last-of-type { border-bottom: 0; }
.desc { color: var(--ink2); max-width: 80ch; margin: 4px 0 16px; }
.head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; margin-bottom: 4px; }
.head .tools { display: flex; gap: 6px; }

/* summary */
.assess { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(0, 1fr); gap: 44px; }
.assess > *, .two > * { min-width: 0; }
.mono, .case .tech, .story, ol.todo a { overflow-wrap: anywhere; }
.story { font-size: 16px; line-height: 1.6; max-width: 68ch; margin-bottom: 6px; }
ol.todo { margin: 0; padding: 0; list-style: none; counter-reset: t; border-top: 1px solid var(--line); }
ol.todo li { counter-increment: t; display: grid; grid-template-columns: 26px 1fr; padding: 9px 0; border-bottom: 1px solid var(--line2); }
ol.todo li::before { content: counter(t) "."; color: var(--ink3); }
ol.todo span { display: block; color: var(--ink2); font-size: 13.5px; }
dl.facts { margin: 0; display: grid; align-content: start; grid-template-columns: auto 1fr; border-top: 1px solid var(--line); }
dl.facts dt, dl.facts dd { margin: 0; padding: 8px 0; border-bottom: 1px solid var(--line2); }
dl.facts dt { color: var(--ink2); padding-right: 18px; white-space: nowrap; }
dl.facts dd { text-align: right; overflow-wrap: anywhere; }
.sevcount { display: inline-flex; flex-wrap: wrap; gap: 4px 14px; justify-content: flex-end; }

/* severity: a shape plus the word, so it reads in greyscale print and for colour-blind readers */
.sev { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; font-weight: 600; font-size: 13px; }
.sev i { display: inline-block; width: 8px; height: 8px; background: currentColor; flex: none; }
.sev.Critical { color: var(--crit); } .sev.Critical i { transform: rotate(45deg); }
.sev.High { color: var(--high); } .sev.High i { width: 9px; clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.sev.Medium { color: var(--med); }
.sev.Low { color: var(--low); } .sev.Low i { border-radius: 50%; }
.sev.Info { color: var(--info); } .sev.Info i { border-radius: 50%; background: none; border: 1.5px solid currentColor; }
.sev.bare { font-weight: 400; }

/* when it happened (chart) */
.chart { border: 1px solid var(--line); padding: 14px 16px 10px; margin-top: 4px; }
.chart .ctl { display: flex; gap: 10px; align-items: center; font-size: 13px; color: var(--ink2); margin-bottom: 8px; flex-wrap: wrap; }
.chart select { font: inherit; font-size: 13px; padding: 3px 6px; border: 1px solid var(--line); border-radius: 3px; background: var(--page); color: var(--ink); }
.chart svg { display: block; width: 100%; height: auto; }
.chart .lane { font: 12px var(--sans); fill: var(--ink2); }
.chart .grid { stroke: var(--line2); }
.chart .day { stroke: var(--line); }
.chart .tick { font: 11px var(--sans); fill: var(--ink3); }
.chart .tick.d { fill: var(--ink2); font-weight: 600; }
.chart .band { fill: var(--ink); opacity: .055; }
.chart .bandl { font: 11px var(--sans); fill: var(--ink2); }
.chart .pt { cursor: pointer; }
.chart .pt:focus { outline: none; }
.chart .pt:hover .mk, .chart .pt:focus .mk, .chart .pt.on .mk { stroke: var(--ink); stroke-width: 1.6; }
.chart .legend { display: flex; flex-wrap: wrap; gap: 4px 16px; font-size: 12.5px; color: var(--ink2); border-top: 1px solid var(--line2); padding-top: 8px; margin-top: 4px; }

/* tables */
.tbl { width: 100%; overflow-x: auto; border: 1px solid var(--line); }
table { border-collapse: collapse; width: 100%; }
th { font-weight: 600; font-size: 12.5px; color: var(--ink2); text-align: left; padding: 7px 12px; background: var(--alt); border-bottom: 1px solid var(--line); white-space: nowrap; }
td { padding: 7px 12px; border-bottom: 1px solid var(--line2); vertical-align: top; }
tr:last-child > td { border-bottom: 0; }
td.t, td.nw { white-space: nowrap; } td.t { color: var(--ink2); }
td.m { font-family: var(--mono); font-size: 12.5px; overflow-wrap: anywhere; min-width: 16ch; }
td.num { text-align: right; }
tr.day td { background: var(--alt); font-weight: 600; color: var(--ink2); }
.kind { color: var(--ink2); white-space: nowrap; }
.tb { display: flex; flex-wrap: wrap; gap: 8px 14px; align-items: center; margin: 0 0 10px; }
.tb input[type=search] { font: inherit; padding: 5px 9px; border: 1px solid var(--line); border-radius: 3px; background: var(--page); color: var(--ink); min-width: 240px; flex: 1; max-width: 420px; }
.tb select { font: inherit; padding: 4px 6px; border: 1px solid var(--line); border-radius: 3px; background: var(--page); color: var(--ink); }
.tb label { display: inline-flex; align-items: center; gap: 5px; color: var(--ink2); white-space: nowrap; }
.count { color: var(--ink3); font-size: 12.5px; margin-top: 8px; }
.empty { padding: 16px; border: 1px solid var(--line2); background: var(--alt); color: var(--ink2); }

/* findings: list and case file */
.fwrap { display: grid; grid-template-columns: minmax(300px, 380px) minmax(0, 1fr); border: 1px solid var(--line); min-height: 560px; }
.flist { border-right: 1px solid var(--line); min-width: 0; display: flex; flex-direction: column; }
.flist .tb { padding: 10px; margin: 0; border-bottom: 1px solid var(--line); display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.flist .tb input[type=search] { grid-column: 1 / -1; max-width: none; min-width: 0; }
.flist .tb > *, .fwrap > * { min-width: 0; }
.flist .tb select { width: 100%; }
.fitems { overflow-y: auto; max-height: 860px; }
.fg { padding: 6px 12px; font-size: 12px; color: var(--ink2); background: var(--alt); border-bottom: 1px solid var(--line2); }
.fi { display: block; width: 100%; text-align: left; font: inherit; color: inherit; background: none; border: 0; border-bottom: 1px solid var(--line2); padding: 9px 12px 10px; cursor: pointer; }
.fi:hover { background: var(--alt); }
.fi[aria-selected=true] { background: var(--sel); }
.fi .t { display: block; font-weight: 500; line-height: 1.35; overflow-wrap: anywhere; }
.fi .m { display: flex; flex-wrap: wrap; gap: 2px 12px; margin-top: 3px; font-size: 12px; color: var(--ink3); }
.fcount { padding: 8px 12px; font-size: 12px; color: var(--ink3); border-top: 1px solid var(--line2); margin-top: auto; }
.case { padding: 22px 28px 28px; min-width: 0; }
.case .top { display: flex; flex-wrap: wrap; gap: 4px 18px; align-items: center; font-size: 13px; color: var(--ink2); }
.case .top .tools { margin-left: auto; display: flex; gap: 6px; }
.case h3.ft { font-size: 22px; line-height: 1.25; margin: 10px 0 4px; overflow-wrap: anywhere; letter-spacing: -.01em; }
.case .tech { font-size: 13px; color: var(--ink2); margin-bottom: 14px; }
.case .tech a { font-family: var(--mono); font-size: 12.5px; }
dl.cf { margin: 0; display: grid; grid-template-columns: 150px minmax(0, 1fr); border-top: 1px solid var(--line); }
dl.cf > dt { padding: 14px 16px 14px 0; border-bottom: 1px solid var(--line2); font-weight: 600; font-size: 13px; }
dl.cf > dd { margin: 0; padding: 14px 0; border-bottom: 1px solid var(--line2); min-width: 0; overflow-wrap: anywhere; }
dl.cf > dd > :last-child { margin-bottom: 0; }
.stamp { font-size: 17px; font-weight: 600; }
.sub { color: var(--ink2); font-size: 13px; }
.lbl { font-size: 12.5px; color: var(--ink2); margin: 12px 0 4px; }
pre.box { font-family: var(--mono); font-size: 12.5px; line-height: 1.55; background: var(--alt); border: 1px solid var(--line2); padding: 9px 12px; margin: 0 0 10px; white-space: pre-wrap; overflow-wrap: anywhere; }
pre.box mark { background: none; color: var(--high); font-weight: 700; text-decoration: underline; text-underline-offset: 2px; }
table.kv { border: 1px solid var(--line2); }
table.kv td { padding: 5px 10px; font-size: 12.5px; }
table.kv td.k { color: var(--ink2); white-space: nowrap; width: 1%; }
table.kv td.v { font-family: var(--mono); white-space: pre-wrap; overflow-wrap: anywhere; }
dl.cf table.kv { table-layout: fixed; width: 100%; }
dl.cf table.kv td.k { width: 28%; white-space: normal; overflow-wrap: anywhere; }
table.seq td { padding: 4px 10px; font-size: 13px; }
table.seq tr.self td { background: var(--sel); font-weight: 600; }
table.seq button { font: inherit; color: var(--link); background: none; border: 0; padding: 0; cursor: pointer; text-align: left; }

/* attack path, incidents, matrix */
td.stage { font-weight: 600; white-space: nowrap; }
.matrix { display: flex; border: 1px solid var(--line); overflow-x: auto; }
.mcol { border-right: 1px solid var(--line2); flex: 1 1 150px; min-width: 150px; }
.mcol.none { flex: 0 0 84px; min-width: 84px; }
.mcol:last-child { border-right: 0; }
.mcol h4 { padding: 8px 9px; font-size: 12px; background: var(--alt); border-bottom: 1px solid var(--line); min-height: 52px; overflow-wrap: break-word; hyphens: auto; }
.mcol h4 span { display: block; color: var(--ink3); font-weight: 400; }
.mcol.none h4 { color: var(--ink3); background: var(--page); }
.mt { display: block; padding: 7px 9px; border-bottom: 1px solid var(--line2); font-size: 12px; color: var(--ink); }
.mt:hover { background: var(--alt); text-decoration: none; }
.mt b { display: flex; align-items: center; gap: 6px; font-family: var(--mono); font-weight: 600; font-size: 11.5px; }
ul.list { margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--line2); }
ul.list li { padding: 9px 0; border-bottom: 1px solid var(--line2); overflow-wrap: anywhere; }
ul.list .fix { color: var(--ink2); margin-top: 2px; }
.two { display: grid; grid-template-columns: 1fr 1fr; gap: 36px; }
footer { padding: 26px 0 40px; color: var(--ink3); font-size: 12.5px; }
.toast { position: fixed; bottom: 18px; left: 50%; transform: translateX(-50%); background: var(--ink); color: var(--page); padding: 6px 14px; border-radius: 3px; font-size: 13px; opacity: 0; transition: opacity .15s; pointer-events: none; z-index: 60; }
.toast.on { opacity: 1; }
#printall, .pnote { display: none; }

@media (max-width: 1000px) {
  .assess, .two { grid-template-columns: 1fr; gap: 24px; }
  .fwrap { grid-template-columns: 1fr; }
  .flist { border-right: 0; border-bottom: 1px solid var(--line); }
  .fitems { max-height: 340px; }
}
@media (max-width: 640px) {
  .wrap { padding: 0 16px; }
  .casehead h1 { font-size: 30px; }
  .case { padding: 18px 14px; }
  dl.cf { grid-template-columns: 1fr; }
  dl.cf > dt { border-bottom: 0; padding-bottom: 2px; }
  dl.cf > dd { padding-top: 2px; }
  dl.facts { grid-template-columns: 1fr; } dl.facts dt { border-bottom: 0; padding-bottom: 0; } dl.facts dd { text-align: left; }
  .tb input[type=search] { min-width: 0; max-width: none; width: 100%; }
}
@media (prefers-reduced-motion: reduce) { .toast { transition: none; } }
@media print {
  @page { margin: 16mm 13mm 15mm; }
  html, body { -webkit-print-color-adjust: exact; print-color-adjust: exact; background: #fff; }
  body { font-size: 10pt; }
  .mast { background: #fff; color: #000; border-bottom: 2px solid #000; break-after: page; min-height: 55vh; }
  .mast .brandrow, .mast .brandrow b, .facts-line, .facts-line span b, .verdictbox .s { color: #000; }
  .brandrow svg { color: #000; }
  .bar, .tb, .btn, .mbtn, .toast, .chart .ctl, .flist, #case, .head .tools { display: none !important; }
  #printall { display: block; }
  #printall .case { padding: 14px 0 18px; border-bottom: 1px solid #999; }
  #printall dl.cf > dt, #printall dl.cf > dd { padding: 8px 0; }
  .fwrap { display: block; border: 0; min-height: 0; }
  #abox, #ebox, #tbox tr.chg { display: none; }
  .pnote { display: block; color: #555; margin: 4px 0 8px; }
  section { padding-top: 18px; break-inside: auto; }
  .chart, .assess { break-inside: avoid; }
  .tbl { overflow: visible; border: 0; }
  tr, .mt, dl.cf > dd { break-inside: avoid; }
  .matrix { flex-wrap: wrap; } .mcol.none { display: none; }
  a { color: inherit; }
}
</style>
</head>
<body>
<svg width="0" height="0" style="position:absolute" aria-hidden="true">
  <symbol id="wfx-mark" viewBox="0 0 64 64">
    <path d="M6 20V6h14M44 6h14v14M58 44v14H44M20 58H6V44" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="square"/>
    <path d="M20 20l24 24M44 20L20 44" fill="none" stroke="currentColor" stroke-width="6"/>
    <circle cx="32" cy="32" r="9" fill="var(--lens, #14233A)" stroke="currentColor" stroke-width="5"/>
    <circle cx="32" cy="32" r="3" fill="currentColor"/>
  </symbol>
</svg>
<svg class="watermark" viewBox="0 0 64 80" aria-hidden="true" style="--lens: transparent"><use href="#wfx-mark" width="64" height="64"/><text x="32" y="77" text-anchor="middle" fill="currentColor">WinForensicX</text></svg>

<header class="mast"><div class="wrap">
  <div class="brandrow"><svg viewBox="0 0 64 64" aria-hidden="true"><use href="#wfx-mark"/></svg><b>WinForensicX</b><span>Case report</span>
    <div class="tools"><button class="mbtn" id="theme" type="button">Dark</button><button class="mbtn" id="print" type="button">Print</button></div></div>
  <div class="casehead">
    <div><h1>__WFX_HOST__</h1><div class="facts-line" id="sub"></div></div>
    <div class="verdictbox"><div class="v" id="verdict"></div><div class="s" id="vsub"></div></div>
  </div>
</div></header>

<div class="bar"><div class="wrap"><nav class="nav" id="nav" aria-label="Sections">
  <a href="#summary">Summary</a><a href="#incidents">Incidents<span class="n" id="n-n"></span></a><a href="#path">Path<span class="n" id="n-p"></span></a><a href="#findings">Findings<span class="n" id="n-f"></span></a><a href="#iocs">Indicators<span class="n" id="n-i"></span></a><a href="#timeline">Timeline<span class="n" id="n-t"></span></a><a href="#activity">Changes<span class="n" id="n-a"></span></a><a href="#execution">Execution<span class="n" id="n-e"></span></a><a href="#attack">ATT&amp;CK<span class="n" id="n-x"></span></a><a href="#visibility">Gaps<span class="n" id="n-g"></span></a><a href="#custody">Custody</a>
</nav></div></div>

<main class="wrap">
<section id="summary">
  <div class="assess">
    <div>
      <h2>Summary</h2>
      <p class="story" id="lead"></p>
      <h3>Do first</h3>
      <ol class="todo" id="todo"></ol>
    </div>
    <dl class="facts" id="facts"></dl>
  </div>
  <h3 style="margin-top:30px">When it happened</h3>
  <p class="desc">Each time-stamped finding on its ATT&amp;CK stage. Grey bands are incidents. Select a point to open the finding.</p>
  <div class="chart" id="chart"><div class="ctl"><label for="zoom">Show</label><select id="zoom"></select><span id="notime"></span></div><div id="chartsvg"></div><div class="legend" id="legend"></div></div>
</section>

<section id="incidents">
  <h2>Incidents</h2>
  <p class="desc">Findings grouped because they share a file, account or address close in time, or are high-severity findings minutes apart. The last column says why they were grouped and which finding is the likely starting point.</p>
  <div id="nbox"></div>
</section>

<section id="path">
  <h2>Attack path</h2>
  <p class="desc">Findings placed on the attack lifecycle, earliest stage first, with the time each stage was first seen.</p>
  <div id="pathbox"></div>
</section>

<section id="findings">
  <div class="head"><div><h2>Findings</h2><p class="desc">Each finding answers four questions: what happened, when, how we know, and what to do.</p></div>
    <div class="tools"><button class="btn" id="fx-csv" type="button">Download CSV</button></div></div>
  <div class="fwrap">
    <div class="flist">
      <div class="tb">
        <input type="search" id="fq" placeholder="Search titles, paths, users, IPs, rule IDs" aria-label="Search findings">
        <select id="fsev" aria-label="Severity"></select>
        <select id="ftac" aria-label="Stage"></select>
        <select id="fcat" aria-label="Area"></select>
        <select id="ford" aria-label="Order"><option value="sev">Most severe first</option><option value="time">Oldest first</option><option value="inc">By incident</option></select>
      </div>
      <div class="fitems" id="fitems" role="listbox" aria-label="Findings"></div>
      <div class="fcount" id="fcount"></div>
    </div>
    <article class="case" id="case" aria-live="polite"></article>
    <div id="printall"></div>
  </div>
</section>

<section id="iocs">
  <div class="head"><div><h2>Indicators</h2><p class="desc">Addresses, domains, URLs, hashes, files, registry keys and accounts taken from the evidence of attacker-related findings. Extraction is automatic: check each value before blocking it.</p></div>
    <div class="tools"><button class="btn" id="i-copy" type="button">Copy values</button><button class="btn" id="i-csv" type="button">Download CSV</button></div></div>
  <div class="tb">
    <input type="search" id="iq" placeholder="Search indicators" aria-label="Search indicators">
    <select id="itype" aria-label="Type"></select>
    <label><input type="checkbox" id="idef"> Defang for sharing</label>
    <label><input type="checkbox" id="ipriv"> Include private addresses</label>
    <label><input type="checkbox" id="isys"> Include Windows binaries</label>
  </div>
  <div id="ibox"></div>
</section>

<section id="timeline">
  <div class="head"><div><h2>Timeline</h2><p class="desc">Findings and notable changes in one sequence. All times are UTC.</p></div>
    <div class="tools"><button class="btn" id="t-csv" type="button">Download CSV</button></div></div>
  <div class="tb">
    <input type="search" id="tq" placeholder="Search the timeline" aria-label="Search timeline">
    <label><input type="checkbox" id="tonly"> Findings only</label>
  </div>
  <p class="pnote">The printed copy lists findings only; every change is in the timeline CSV and raw/bundle.json.</p>
  <div id="tbox"></div>
</section>

<section id="activity">
  <h2>Recent changes</h2>
  <p class="desc" id="asub">What changed on the host in the look-back window: registry, files, software, services, tasks, accounts, security settings, executions and connections.</p>
  <div class="tb">
    <input type="search" id="aq" placeholder="Search changes" aria-label="Search changes">
    <select id="acat" aria-label="Area"></select>
  </div>
  <p class="pnote">Left out of the printed copy; see the timeline CSV or raw/bundle.json.</p>
  <div id="abox"></div>
</section>

<section id="execution">
  <div class="head"><div><h2>Evidence of execution and user activity</h2><p class="desc" id="esub">Programs that ran or existed (Amcache, ShimCache, Prefetch, BAM, UserAssist, PCA), what users opened (ShellBags, Jump Lists, shortcuts, Run box, searches), browser downloads and Defender's own logs. These records outlive the files they describe. A severity mark means a finding refers to that path.</p></div>
    <div class="tools"><button class="btn" id="e-csv" type="button">Download CSV</button></div></div>
  <div class="tb">
    <input type="search" id="eq" placeholder="Search paths, users, hashes" aria-label="Search execution evidence">
    <select id="eart" aria-label="Artifact"></select>
    <select id="eev" aria-label="Evidence type"></select>
    <label><input type="checkbox" id="eflag"> Flagged only</label>
  </div>
  <p class="pnote">Left out of the printed copy; see the CSV or raw/bundle.json.</p>
  <div id="ebox"></div>
</section>

<section id="attack">
  <div class="head"><div><h2>MITRE ATT&amp;CK</h2><p class="desc">Techniques behind the findings, by tactic. The mark shows the most severe finding for each technique.</p></div>
    <div class="tools"><button class="btn" id="x-layer" type="button">Download Navigator layer</button></div></div>
  <div id="xbox"></div>
</section>

<section id="visibility">
  <h2>What this report could not see</h2>
  <p class="desc">Collection limits. An empty finding list means nothing matched in what was visible, not that nothing happened.</p>
  <div class="two"><div><h3>Not visible or incomplete</h3><div id="gbox"></div></div><div><h3>Suppressed by the allowlist</h3><div id="sbox"></div></div></div>
</section>

<section id="custody">
  <h2>Case and custody</h2>
  <p class="desc">How and when this evidence was collected. Verify the case folder before relying on it.</p>
  <div class="two"><div id="cbox"></div><div><h3 style="margin-top:0">Verify this case</h3><p class="small">Re-hashes every file against manifest.json and reports anything changed, missing or added.</p><pre class="box" id="verify"></pre>
    <h3>Method and limits</h3><ul class="list" id="lbox"></ul></div></div>
</section>
<footer id="foot"></footer>
</main>
<div class="toast" id="toast" role="status" aria-live="polite"></div>

<script id="wfx-data" type="application/json">/*__WFX_DATA__*/</script>
<script>
(function () {
  'use strict';
  var D = JSON.parse(document.getElementById('wfx-data').textContent);
  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  var SEV = ['Critical', 'High', 'Medium', 'Low', 'Info'], RANK = { Critical: 0, High: 1, Medium: 2, Low: 3, Info: 4 };
  var TAC = ['Reconnaissance', 'Resource Development', 'Initial Access', 'Execution', 'Persistence', 'Privilege Escalation', 'Defense Evasion', 'Credential Access', 'Discovery', 'Lateral Movement', 'Collection', 'Command and Control', 'Exfiltration', 'Impact'];
  var TID = /^T\d{4}(?:\.\d{3})?$/;
  var sevOf = function (s) { return RANK[s] === undefined ? 'Info' : s; };
  var sevHtml = function (s, word) { s = sevOf(s); return '<span class="sev ' + s + '"><i></i>' + esc(word === undefined ? s : word) + '</span>'; };
  var dt = function (s) { if (s === null || s === undefined || s === '') return null; var d = new Date(s); return isNaN(d) ? null : d; };
  var pad = function (n) { return (n < 10 ? '0' : '') + n; };
  var fmtD = function (d) { return d ? d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) : ''; };
  var fmt = function (d) { return d ? fmtD(d) + ' ' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) : ''; };
  var fmtT = function (d) { return d ? pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':' + pad(d.getUTCSeconds()) : ''; };
  var utc = function (d) { return d ? d.toISOString().replace(/\.\d{3}Z$/, 'Z') : ''; };
  var span = function (ms) { var m = Math.round(Math.abs(ms) / 60000); if (m < 1) return 'under a minute'; if (m < 90) return m + ' minute' + (m === 1 ? '' : 's'); var h = Math.round(m / 6) / 10; if (h < 48) return h + ' hours'; return Math.round(h / 24) + ' days'; };
  var isAcct = function (v) { v = String(v || '').trim(); return !!v && v.length < 64 && !/[:\/]|\.[A-Za-z0-9]{2,4}$|^-$|^(SYSTEM|NT AUTHORITY\\(SYSTEM|LOCAL SERVICE|NETWORK SERVICE)|LOCAL SERVICE|NETWORK SERVICE|S-1-5-(18|19|20))$/i.test(v); };
  var toast = function (m) { var t = $('toast'); t.textContent = m; t.classList.add('on'); clearTimeout(t._h); t._h = setTimeout(function () { t.classList.remove('on'); }, 1600); };
  var download = function (name, text, type) {
    var b = new Blob([text], { type: type || 'text/plain' }), a = document.createElement('a');
    a.href = URL.createObjectURL(b); a.download = name; document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500); toast('Saved ' + name);
  };
  var csv = function (rows) { return rows.map(function (r) { return r.map(function (v) { v = String(v == null ? '' : v); if (/^[=+\-@\t\r]/.test(v)) v = "'" + v; return /[",\n\r]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }).join(','); }).join('\r\n'); };
  var copy = function (text) {
    if (navigator.clipboard && window.isSecureContext) { navigator.clipboard.writeText(text).then(function () { toast('Copied'); }); return; }
    var ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); toast('Copied'); } catch (e) { } ta.remove();
  };
  var reduceMotion = function () { return window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches; };

  /* theme and print */
  var setThemeLabel = function () { var cur = document.documentElement.getAttribute('data-theme'); var dark = cur ? cur === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches; $('theme').textContent = dark ? 'Light' : 'Dark'; };
  try { var saved = localStorage.getItem('wfx-theme'); if (saved === 'dark' || saved === 'light') document.documentElement.setAttribute('data-theme', saved); } catch (e) { }
  setThemeLabel();
  $('theme').onclick = function () { var cur = document.documentElement.getAttribute('data-theme'); var dark = cur ? cur === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches; var nx = dark ? 'light' : 'dark'; document.documentElement.setAttribute('data-theme', nx); try { localStorage.setItem('wfx-theme', nx); } catch (e) { } setThemeLabel(); };
  $('print').onclick = function () { window.print(); };

  /* data */
  var F = (D.findings || []).map(function (f, i) { f._i = i; f._d = dt(f.Time); return f; });
  var A = (D.activity || []).map(function (a) { a._d = dt(a.Time); return a; });
  var risk = D.risk || { Score: 0, Level: 'Low' }, pos = D.posture || { Score: 0, Level: 'Low' }, host = D.host || {}, cs = D.case || {};
  var techTac = {}, techName = {};
  (D.coverage || []).forEach(function (t) { techTac[t.Id] = t.Tactic; techName[t.Id] = t.Name; });
  var isHygiene = function (f) { return f.Category === 'Posture' || f.Category === 'Visibility'; };
  F.forEach(function (f) {
    var tacs = (f.Technique || []).map(function (t) { return techTac[t]; }).filter(Boolean);
    tacs.sort(function (a, b) { return TAC.indexOf(a) - TAC.indexOf(b); });
    f._tac = isHygiene(f) ? 'Hardening' : (tacs[0] || 'Other');
    f._late = isHygiene(f) ? 'Hardening' : (tacs[tacs.length - 1] || 'Other');
  });
  var attackF = F.filter(function (f) { return !isHygiene(f); });
  var N = D.incidents || [];
  var fIndex = {}; F.forEach(function (f) { fIndex[f.Id + '|' + f.Entity] = f._i; });
  N.forEach(function (n) { n._m = []; (n.Findings || []).forEach(function (x) { var i = fIndex[x.Id + '|' + x.Entity]; if (i !== undefined) { n._m.push(F[i]); F[i]._inc = n; } }); });
  var timed = attackF.filter(function (f) { return f._d; }).sort(function (a, b) { return a._d - b._d; });

  /* masthead */
  var collected = dt(D.collected);
  var subBits = [];
  if (host.Os || host.OS) subBits.push('<span>' + esc(host.Os || host.OS) + '</span>');
  if (host.Domain) subBits.push('<span>Domain <b>' + esc(host.Domain) + '</b></span>');
  if (collected) subBits.push('<span>Collected <b>' + esc(fmt(collected)) + ' UTC</b></span>');
  if (cs.Id) subBits.push('<span>Case <b class="mono">' + esc(String(cs.Id).slice(0, 8)) + '</b></span>');
  if (cs.Operator) subBits.push('<span>Analyst <b>' + esc(cs.Operator) + '</b></span>');
  $('sub').innerHTML = subBits.join('');
  var V = { Critical: ['Compromise indicated', 'Treat this host as compromised until proven otherwise: isolate it, preserve evidence and scope the intrusion.'],
    High: ['Compromise likely', 'Strong indicators of attacker activity. Investigate now and consider isolating the host.'],
    Elevated: ['Suspicious activity', 'Some findings need an analyst to confirm or rule out attacker activity.'],
    Low: ['No strong indicators', 'Nothing in what could be seen strongly indicates compromise.'] };
  var v = V[risk.Level] || V.Low, vs = risk.Level === 'Critical' ? 'Critical' : risk.Level === 'High' ? 'High' : risk.Level === 'Elevated' ? 'Medium' : 'Low';
  $('verdict').innerHTML = '<span class="sev ' + vs + '" style="font-size:21px"><i style="width:11px;height:11px"></i></span>' + esc(v[0]);
  $('vsub').textContent = 'Compromise risk ' + risk.Score + ' of 100, hardening gaps ' + pos.Score + ' of 100';

  /* summary */
  var hc = attackF.filter(function (f) { return RANK[f.Severity] <= 1; }).length;
  var stages = []; attackF.forEach(function (f) { if (TAC.indexOf(f._tac) >= 0 && stages.indexOf(f._tac) < 0) stages.push(f._tac); });
  stages.sort(function (a, b) { return TAC.indexOf(a) - TAC.indexOf(b); });
  var lead = esc(v[1]) + ' ' + attackF.length + ' attacker-related finding' + (attackF.length === 1 ? '' : 's') + (hc ? ', ' + hc + ' critical or high' : '') +
    (stages.length ? ', across ' + stages.length + ' stage' + (stages.length === 1 ? '' : 's') + ' of the attack lifecycle (' + esc(stages.join(', ')) + ').' : '.');
  if (timed.length > 1) { var a0 = timed[0], a1 = timed[timed.length - 1]; lead += ' The earliest is <a href="#f' + a0._i + '" data-open="' + a0._i + '">' + esc(a0.Title) + '</a> at ' + esc(fmt(a0._d)) + ' UTC; the latest, ' + esc(span(a1._d - a0._d)) + ' later, is <a href="#f' + a1._i + '" data-open="' + a1._i + '">' + esc(a1.Title) + '</a>.'; }
  if (N.length) lead += ' They form ' + N.length + ' incident' + (N.length === 1 ? '' : 's') + '.';
  if ((D.gaps || []).length) lead += ' Some sources were not visible; read <a href="#visibility">what this report could not see</a> before concluding.';
  $('lead').innerHTML = lead;
  var seenRule = {}; var top = attackF.slice().sort(function (a, b) { return RANK[a.Severity] - RANK[b.Severity] || b.Score - a.Score; }).filter(function (f) { var k = String(f.Id).replace(/-\d+$/, ''), tk = f.Title.replace(/\s*\(.*\)$/, ''); if (seenRule[k] || seenRule[tk]) return false; seenRule[k] = seenRule[tk] = 1; return true; }).slice(0, 5);
  if (!top.length) top = F.slice().sort(function (a, b) { return RANK[a.Severity] - RANK[b.Severity]; }).slice(0, 3);
  var firstSentence = function (s) { s = String(s || 'Review the evidence.'); var m = s.match(/^.*?[.;](\s|$)/); s = (m ? m[0] : s).trim().replace(/[;,:]$/, ''); return /[.!?]$/.test(s) ? s : s + '.'; };
  $('todo').innerHTML = top.length ? top.map(function (f) { return '<li><div><a href="#f' + f._i + '" data-open="' + f._i + '">' + esc(f.Title) + '</a><span>' + esc(firstSentence(f.Recommendation)) + '</span></div></li>'; }).join('')
    : '<li><div>Nothing to act on<span>Check what this report could not see before concluding the host is clean.</span></div></li>';
  var S = D.summary || {};
  var accounts = {};
  attackF.forEach(function (f) { var e = f.Evidence || {}; ['User', 'Users', 'Actor', 'Account', 'TargetUserName', 'SubjectUserName', 'MemberName'].forEach(function (k) { if (e[k]) String(e[k]).split(/,\s*/).forEach(function (u) { if (isAcct(u)) accounts[u.trim()] = 1; }); }); });
  var facts = [
    ['Findings', '<span class="sevcount">' + (SEV.filter(function (x) { return S[x]; }).map(function (x) { return sevHtml(x, S[x] + ' ' + x.toLowerCase()); }).join('') || 'none') + '</span>'],
    ['Suspicious activity', timed.length ? esc(fmt(timed[0]._d)) + (timed.length > 1 ? ' to ' + esc(fmt(timed[timed.length - 1]._d)) : '') + ' UTC' : '<span class="muted">no time-stamped findings</span>'],
    ['Incidents', N.length ? '<a href="#incidents">' + N.length + '</a>' : '0'],
    ['Accounts involved', Object.keys(accounts).length ? esc(Object.keys(accounts).slice(0, 4).join(', ')) + (Object.keys(accounts).length > 4 ? ' and ' + (Object.keys(accounts).length - 4) + ' more' : '') : '<span class="muted">none identified</span>'],
    ['External addresses', '<span id="f-ext">0</span>'],
    ['Changes recorded', esc(D.activityTotal || A.length || 0)],
    ['Execution artifacts', (D.artifactTotal || (D.artifacts || []).length) ? '<a href="#execution">' + esc(D.artifactTotal || D.artifacts.length) + '</a>' : '0'],
    ['Sources not visible', (D.gaps || []).length ? '<a href="#visibility">' + (D.gaps || []).length + '</a>' : '0']
  ];
  $('facts').innerHTML = facts.map(function (r) { return '<dt>' + r[0] + '</dt><dd>' + r[1] + '</dd>'; }).join('');

  /* when it happened: one lane per stage, incidents as bands */
  var current = null, zoomInc = null;
  var lanes = TAC.filter(function (t) { return timed.some(function (f) { return f._tac === t; }); });
  if (timed.some(function (f) { return TAC.indexOf(f._tac) < 0; })) lanes.push('Other');
  var laneOf = function (f) { return TAC.indexOf(f._tac) >= 0 ? f._tac : 'Other'; };
  var sortedN = N.filter(function (n) { return dt(n.Start); }).slice().sort(function (a, b) { return dt(a.Start) - dt(b.Start); });
  $('zoom').innerHTML = '<option value="">Whole case</option>' + sortedN.map(function (n) { return '<option value="' + esc(n.Id) + '">' + esc(n.Id) + ', ' + esc(fmt(dt(n.Start))) + ' UTC</option>'; }).join('');
  $('zoom').onchange = function () { var id = this.value; zoomInc = N.filter(function (n) { return n.Id === id; })[0] || null; drawChart(); };
  var nt = attackF.length - timed.length;
  $('notime').textContent = nt ? nt + ' finding' + (nt === 1 ? ' has' : 's have') + ' no time stamp (state seen at collection) and ' + (nt === 1 ? 'is' : 'are') + ' not plotted.' : '';
  var shape = function (s, x, y) {
    var r = { Critical: 6.5, High: 6, Medium: 5, Low: 4.5, Info: 4 }[s] || 4, st = ' class="mk" style="fill:var(--' + { Critical: 'crit', High: 'high', Medium: 'med', Low: 'low', Info: 'info' }[s] + ');stroke:var(--page);stroke-width:1.2"';
    if (s === 'Critical') return '<rect x="' + (x - r) + '" y="' + (y - r) + '" width="' + 2 * r + '" height="' + 2 * r + '" transform="rotate(45 ' + x + ' ' + y + ')"' + st + '/>';
    if (s === 'High') return '<path d="M' + x + ' ' + (y - r - 1) + 'L' + (x + r + 1) + ' ' + (y + r) + 'L' + (x - r - 1) + ' ' + (y + r) + 'Z"' + st + '/>';
    if (s === 'Medium') return '<rect x="' + (x - r) + '" y="' + (y - r) + '" width="' + 2 * r + '" height="' + 2 * r + '"' + st + '/>';
    return '<circle cx="' + x + '" cy="' + y + '" r="' + r + '"' + st + '/>';
  };
  var drawChart = function () {
    var box = $('chartsvg');
    if (!timed.length) { $('chart').hidden = true; return; }
    var W = Math.max(600, box.clientWidth || 1200), L = 160, R = 18, top0 = 26, lh = 30;
    var t0 = timed[0]._d.getTime(), t1 = timed[timed.length - 1]._d.getTime();
    if (zoomInc) { t0 = dt(zoomInc.Start).getTime(); t1 = (dt(zoomInc.End) || dt(zoomInc.Start)).getTime(); }
    var spanMs = Math.max(t1 - t0, zoomInc ? 20 * 60000 : 3600000);
    if (t1 - t0 < spanMs) { var mid = (t0 + t1) / 2; t0 = mid - spanMs / 2; t1 = mid + spanMs / 2; }
    t0 -= spanMs * .04; t1 += spanMs * .04; spanMs = t1 - t0;
    var x = function (t) { return L + (W - L - R) * (t - t0) / spanMs; };
    var H = top0 + lanes.length * lh + 18;
    var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Findings over time by attack stage">';
    var steps = [6e4, 5 * 6e4, 15 * 6e4, 36e5, 3 * 36e5, 6 * 36e5, 12 * 36e5, 864e5, 7 * 864e5], step = steps[steps.length - 1];
    for (var k = 0; k < steps.length; k++) { if (spanMs / steps[k] <= 14) { step = steps[k]; break; } }
    for (var g = Math.ceil(t0 / step) * step; g <= t1; g += step) {
      var d = new Date(g), midnight = d.getUTCHours() === 0 && d.getUTCMinutes() === 0;
      var lbl = midnight || step >= 864e5 ? fmtD(d) : pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes());
      s += '<line class="' + (midnight ? 'day' : 'grid') + '" x1="' + x(g) + '" x2="' + x(g) + '" y1="' + (top0 - 6) + '" y2="' + (H - 16) + '"/>';
      s += '<text class="tick' + (midnight ? ' d' : '') + '" x="' + (x(g) + 3) + '" y="' + (top0 - 11) + '">' + lbl + '</text>';
    }
    var lastL = -1e9;
    sortedN.forEach(function (n) {
      var a = dt(n.Start).getTime(), b = (dt(n.End) || dt(n.Start)).getTime(); if (b < t0 || a > t1) return;
      var xa = Math.max(L, x(a) - 6), xb = Math.min(W - R, Math.max(x(b) + 6, xa + 12));
      s += '<rect class="band" x="' + xa + '" y="' + (top0 - 4) + '" width="' + (xb - xa) + '" height="' + (lanes.length * lh + 2) + '"/>';
      if (xa - lastL > 44) { s += '<text class="bandl" x="' + xa + '" y="' + (H - 3) + '">' + esc(n.Id) + '</text>'; lastL = xa; }
    });
    lanes.forEach(function (ln, i) { var y = top0 + i * lh + lh / 2; s += '<line class="grid" x1="' + L + '" x2="' + (W - R) + '" y1="' + y + '" y2="' + y + '"/><text class="lane" x="0" y="' + (y + 4) + '">' + esc(ln) + '</text>'; });
    var used = {};
    timed.forEach(function (f) {
      var t = f._d.getTime(); if (t < t0 || t > t1) return;
      var li = lanes.indexOf(laneOf(f)), px = x(t), key = li + ':' + Math.round(px / 9), c = used[key] = (used[key] || 0) + 1;
      var py = top0 + li * lh + lh / 2 + (c === 1 ? 0 : (c % 2 ? 1 : -1) * Math.ceil((c - 1) / 2) * 6);
      s += '<g class="pt' + (current === f ? ' on' : '') + '" tabindex="0" role="button" data-open="' + f._i + '" aria-label="' + esc(f.Severity + ', ' + fmt(f._d) + ' UTC: ' + f.Title) + '"><title>' + esc(fmt(f._d) + ' UTC  ' + f.Title) + '</title>' + shape(sevOf(f.Severity), px, py) + '</g>';
    });
    box.innerHTML = s + '</svg>';
  };
  $('legend').innerHTML = SEV.filter(function (x) { return S[x]; }).map(function (x) { return sevHtml(x); }).join('') + '<span>Grey band: incident</span>';
  drawChart();
  var rt; window.addEventListener('resize', function () { clearTimeout(rt); rt = setTimeout(drawChart, 150); });
  document.addEventListener('keydown', function (e) { if ((e.key === 'Enter' || e.key === ' ') && e.target.classList && e.target.classList.contains('pt')) { e.preventDefault(); openFinding(+e.target.getAttribute('data-open'), true); } });

  /* indicator extraction */
  var IOC = [], seenI = {};
  var isPriv = function (ip) { var p = ip.split('.').map(Number); return p[0] === 10 || p[0] === 127 || p[0] === 0 || (p[0] === 172 && p[1] >= 16 && p[1] <= 31) || (p[0] === 192 && p[1] === 168) || (p[0] === 169 && p[1] === 254) || p[0] >= 224 || (p[0] === 100 && p[1] >= 64 && p[1] <= 127); };
  var FILEEXT = /^(exe|dll|sys|ps1|psm1|psd1|bat|cmd|vbs|vbe|js|jse|wsf|hta|lnk|scr|msi|iso|img|zip|rar|7z|txt|log|xml|json|csv|html?|docx?|docm|xlsx?|xlsm|pptx?|pdf|dat|tmp|ini|cfg|config|dmp|evtx|etl|pf|db|sqlite|jpg|png|gif|cpl|ocx|tlb|mui|manifest|ps|sh|py|dit|save|lockd|aspx?|php|jsp|sct|inf|reg|cer|crt|pem|key|pfx|bin)$/i;
  var addI = function (type, value, f) {
