'@

# ===== entry point =====
$script:WfxSingleFile = $true
$script:WfxSingleFilePath = $PSCommandPath
if (-not $NoAuto) {
    if ($Help) { Show-WfxHelp -Html }
    elseif ($RunTriage) { Invoke-WfxTriage -OutputPath $OutputPath }
    elseif ($Menu) { Show-WfxMenu -OutputPath $OutputPath }
    elseif ($MyInvocation.InvocationName -ne '.') { Show-WfxMenu -OutputPath $OutputPath }
}
